def random_match_intelligence_candidate(
    candidates: list[dict[str, Any]], status: dict[str, Any], tier: str,
) -> dict[str, Any] | None:
    """Choose an unpaid fixture without exposing the random result first."""
    public_rows = {
        str(row.get("fixture_id") or ""): row
        for row in status.get("candidates") or []
    }
    eligible = []
    for candidate in candidates:
        fixture_id = str(candidate.get("fixture_id") or "")
        row = public_rows.get(fixture_id) or {}
        tier_row = next((
            item for item in row.get("tiers") or []
            if str(item.get("key") or "") == tier
        ), None)
        if tier_row and not bool(tier_row.get("purchased")):
            eligible.append(dict(candidate))
    return secrets.choice(eligible) if eligible else None


def purchasable_match_intelligence_candidates(
    intelligence: dict[str, Any],
) -> list[dict[str, Any]]:
    """Return current fixtures that still have at least one unpaid tier."""
    return [
        item
        for item in intelligence.get("candidates") or []
        if not item.get("archived")
        and item.get("available") is not False
        and any(
            not bool(tier.get("purchased"))
            for tier in item.get("tiers") or []
            if isinstance(tier, dict)
        )
    ]


def current_match_intelligence_candidates(
    candidates: list[dict[str, Any]], market_matches: list[dict[str, Any]],
    game_date: str, game_minutes: int,
) -> list[dict[str, Any]]:
    """Keep only intelligence fixtures still present in the published market."""
    game_date = str(game_date or "")
    try:
        game_minutes = int(game_minutes)
    except (TypeError, ValueError):
        return []
    if not game_date or not 0 <= game_minutes < 24 * 60:
        return []

    eligible_candidates, _candidate_keys, _candidate_hints = (
        open_match_intelligence_targets(
            candidates, game_date, game_minutes,
        )
    )
    eligible_markets, _market_keys, _market_hints = open_match_intelligence_targets(
        market_matches, game_date, game_minutes,
    )

    def fixture_key(item: dict[str, Any]) -> tuple[str, int, int, int] | None:
        try:
            key = (
                str(item["fixture_date"]),
                int(item["competition_id"]),
                int(item["home"]["id"]),
                int(item["away"]["id"]),
            )
        except (KeyError, TypeError, ValueError):
            return None
        return key if key[0] and all(value > 0 for value in key[1:]) else None

    candidates_by_key = {
        key: dict(item)
        for item in eligible_candidates
        if (key := fixture_key(item)) is not None
    }
    rows: list[dict[str, Any]] = []
    seen: set[tuple[str, int, int, int]] = set()
    for market in eligible_markets:
        key = fixture_key(market)
        if key is None or key in seen:
            continue
        candidate = candidates_by_key.get(key)
        if candidate is None:
            continue
        seen.add(key)
        rows.append({
            **candidate,
            "fixture_id": "|".join(map(str, key)),
            "fixture_date": key[0],
            "kickoff_minutes": market.get("kickoff_minutes"),
            "kickoff_time": market.get("kickoff_time"),
            "competition_id": key[1],
            "competition_name": str(
                market.get("competition_name")
                or candidate.get("competition_name") or key[1]
            ),
            "home": dict(market.get("home") or candidate.get("home") or {}),
            "away": dict(market.get("away") or candidate.get("away") or {}),
        })
    return rows


TRAVEL_CHANGE_WINDOW_SECONDS = 10.0
