def canonical_money(value: Any) -> float:
    return from_minor(to_minor(value))


def scaled_money(value: Any, multiplier: Any) -> float:
    return from_minor(multiply_minor(to_minor(value), multiplier))




def owned_stadium_upgrade_cooldowns(
    ownership: dict[str, Any] | None, game_date: str,
) -> dict[str, dict[str, Any]]:
    saved = (
        ownership.get("stadium_upgrade_cooldowns")
        if isinstance(ownership, dict) else None
    )
    saved = saved if isinstance(saved, dict) else {}
    try:
        current = date.fromisoformat(str(game_date))
    except (TypeError, ValueError):
        current = None
    result: dict[str, dict[str, Any]] = {}
    for action in ("capacity", "expansion"):
        until = str(saved.get(action) or "")
        try:
            remaining = max(0, (date.fromisoformat(until) - current).days) if current else 0
        except (TypeError, ValueError):
            until = ""
            remaining = 0
        result[action] = {
            "active": remaining > 0,
            "until": until or None,
            "remaining_days": remaining,
        }
    return result


def owned_club_facility_upgrade_cooldowns(
    ownership: dict[str, Any] | None, game_date: str,
) -> dict[str, dict[str, Any]]:
    saved_cooldowns = (
        ownership.get("facility_upgrade_cooldowns")
        if isinstance(ownership, dict) else None
    )
    saved_cooldowns = saved_cooldowns if isinstance(saved_cooldowns, dict) else {}
    saved_plans = (
        ownership.get("facility_upgrade_plans")
        if isinstance(ownership, dict) else None
    )
    saved_plans = saved_plans if isinstance(saved_plans, dict) else {}
    try:
        current = date.fromisoformat(str(game_date))
    except (TypeError, ValueError):
        current = None
    result: dict[str, dict[str, Any]] = {}
    for facility in ("training", "youth", "junior", "recruitment"):
        plan = saved_plans.get(facility)
        plan = plan if isinstance(plan, dict) else None
        if plan and str(plan.get("status") or "active") == "active":
            next_due = str(plan.get("next_due_on") or "")
            try:
                remaining = max(
                    0, (date.fromisoformat(next_due) - current).days,
                ) if current else 0
            except (TypeError, ValueError):
                next_due = ""
                remaining = 0
            try:
                total = max(0, int(plan.get("total_levels") or 0))
                completed = max(
                    0, min(total, int(plan.get("completed_levels") or 0)),
                )
                start_level = int(plan.get("start_level") or 0)
                target_level = int(plan.get("target_level") or 0)
            except (TypeError, ValueError):
                total = completed = start_level = target_level = 0
            result[facility] = {
                "active": True,
                "status": "due" if current and not remaining else "scheduled",
                "until": next_due or None,
                "next_due_on": next_due or None,
                "remaining_days": remaining,
                "start_level": start_level,
                "target_level": target_level,
                "total_levels": total,
                "completed_levels": completed,
                "remaining_levels": max(0, total - completed),
            }
            if plan.get("last_error"):
                result[facility]["last_error"] = str(plan["last_error"])
            continue
        until = str(saved_cooldowns.get(facility) or "")
        try:
            remaining = max(0, (date.fromisoformat(until) - current).days) if current else 0
        except (TypeError, ValueError):
            until = ""
            remaining = 0
        result[facility] = {
            "active": remaining > 0,
            "status": "legacy_cooldown" if remaining > 0 else "idle",
            "until": until or None,
            "next_due_on": None,
            "remaining_days": remaining,
        }
    return result


def owned_stadium_action_quotes(
    stadium: dict[str, Any], *, ownership: dict[str, Any] | None = None,
    game_date: str = "",
) -> dict[str, Any]:
    try:
        capacity = int(stadium.get("capacity"))
        expansion = int(stadium.get("expansion_capacity"))
        state_raw = int(stadium.get("state_raw"))
    except (TypeError, ValueError):
        return {
            "rename_price": OWNED_STADIUM_RENAME_PRICE,
            "capacity": None, "expansion": None, "state": None,
            "pitch_type_price": OWNED_STADIUM_PITCH_TYPE_PRICE,
            "pitch_types": [
                {"value": value, "name": name}
                for value, name in PITCH_TYPE_NAMES.items()
            ],
            "pitch_condition": None,
            "cooldowns": owned_stadium_upgrade_cooldowns(ownership, game_date),
        }
    capacity_after = min(
        capacity + OWNED_STADIUM_CAPACITY_STEP, expansion, 500_000,
    )
    expansion_after = min(expansion + OWNED_STADIUM_CAPACITY_STEP, 500_000)
    capacity_quote = None
    if 0 < capacity < capacity_after:
        capacity_quote = {
            "before": capacity, "after": capacity_after,
            "step": capacity_after - capacity,
            "price": (
                OWNED_STADIUM_CAPACITY_BASE_PRICE
                + capacity // 10_000 * OWNED_STADIUM_CAPACITY_BAND_PRICE
            ),
        }
    expansion_quote = None
    if 0 < expansion < expansion_after:
        expansion_quote = {
            "before": expansion, "after": expansion_after,
            "step": expansion_after - expansion,
            "price": (
                OWNED_STADIUM_EXPANSION_BASE_PRICE
                + expansion // 10_000 * OWNED_STADIUM_EXPANSION_BAND_PRICE
            ),
        }
    state_quote = next(
        (
            {"before": state_raw, "after": after, "price": price, "after_name": name}
            for minimum, after, price, name in OWNED_STADIUM_STATE_STEPS
            if state_raw >= minimum
        ),
        None,
    )
    pitch_condition = stadium.get("pitch_condition")
    try:
        pitch_condition = int(pitch_condition)
    except (TypeError, ValueError):
        pitch_condition = None
    pitch_condition_quote = None
    if pitch_condition is not None and 0 <= pitch_condition < 200:
        pitch_condition_after = min(pitch_condition + 5, 200)
        pitch_condition_quote = {
            "before": pitch_condition,
            "after": pitch_condition_after,
            "step": pitch_condition_after - pitch_condition,
            "price": OWNED_STADIUM_PITCH_CONDITION_PRICE,
        }
    return {
        "rename_price": OWNED_STADIUM_RENAME_PRICE,
        "capacity": capacity_quote,
        "expansion": expansion_quote,
        "state": state_quote,
        "pitch_type_price": OWNED_STADIUM_PITCH_TYPE_PRICE,
        "pitch_types": [
            {"value": value, "name": name}
            for value, name in PITCH_TYPE_NAMES.items()
        ],
        "pitch_condition": pitch_condition_quote,
        "cooldowns": owned_stadium_upgrade_cooldowns(ownership, game_date),
    }


def owned_club_action_quotes(
    detail: dict[str, Any], ownership: dict[str, Any] | None = None,
    game_date: str = "",
) -> dict[str, Any]:
    information = detail.get("club_information") or {}
    facilities = information.get("facilities") or {}
    facility_levels = {
        "training": facilities.get("training"),
        "youth": facilities.get("youth"),
        "junior": facilities.get("junior_coaching"),
        "recruitment": facilities.get("youth_recruitment"),
    }
    facility_prices = {
        key: owned_club_facility_upgrade_price(level)
        for key, level in facility_levels.items()
    }
    facility_quotes: dict[str, Any] = {}
    for key, level in facility_levels.items():
        try:
            current = int(level)
        except (TypeError, ValueError):
            facility_quotes[key] = None
            continue
        facility_quotes[key] = {
            "current_level": current,
            "max_levels": max(0, 20 - current),
            "options": [
                owned_club_facility_upgrade_quote(current, levels)
                for levels in range(1, max(0, 20 - current) + 1)
            ],
        }
    facility_plans = owned_club_facility_upgrade_cooldowns(ownership, game_date)
    return {
        "rename_price": OWNED_CLUB_RENAME_PRICE,
        "manager_replace_price": OWNED_MANAGER_REPLACE_PRICE,
        "facility_upgrade_prices": facility_prices,
        "facility_upgrade_quotes": facility_quotes,
        "facility_upgrade_plans": facility_plans,
        # Preserve the response key for older embedded frontends.
        "facility_upgrade_cooldowns": facility_plans,
        "stadium": owned_stadium_action_quotes(
            information.get("stadium") or {},
            ownership=ownership, game_date=game_date,
        ),
    }


def public_purchase_quotes(value: Any, *, price_collection: bool = False) -> Any:
    """Localize only FMODD-owned quote prices, leaving game values untouched."""
    if isinstance(value, list):
        return [public_purchase_quotes(item, price_collection=price_collection) for item in value]
    if not isinstance(value, dict):
        return value
    result: dict[str, Any] = {}
    for key, item in value.items():
        nested_price_collection = key == "facility_upgrade_prices"
        is_price = (
            isinstance(item, (int, float))
            and not isinstance(item, bool)
            and (price_collection or key == "price" or key.endswith("_price"))
        )
        result[key] = (
            local_purchase_price(item)
            if is_price
            else public_purchase_quotes(
                item, price_collection=nested_price_collection,
            )
        )
    return result


def active_academy_son_assignment(
    scope_id: str, acquired_clubs: list[dict[str, Any]],
) -> dict[str, Any] | None:
    target = next(
        (
            row for row in active_youth_generation_plans(scope_id)
            if row.get("kind") == "academy_son"
        ),
        None,
    )
    if not target:
        return None
    team_id = int(target.get("team_id") or 0)
    club = next(
        (
            row for row in acquired_clubs
            if int(row.get("id") or 0) == team_id
        ),
        None,
    )
    return {
        "team_id": team_id,
        "team_name": str((club or {}).get("name") or f"俱乐部 {team_id}"),
    }


def account_acquired_clubs(
    scope_id: str, output: dict[str, Any], *, include_suspended: bool = False,
) -> list[dict[str, Any]]:
    rows = acquired_clubs_for_game_date(
        load_acquired_clubs(scope_id).get("clubs", []),
        str(output.get("game_date") or ""),
    )
    return rows if include_suspended else [
        row for row in rows if row.get("ownership_active") is not False
    ]


def owned_club_league_standing(
    output: dict[str, Any], team_id: int,
) -> dict[str, Any] | None:
    """Return a current league row; absence means the league is not loaded."""
    for competition in public_league_standings(output).get("competitions", []):
        teams = list(competition.get("teams") or [])
        for team in teams:
            if int(team.get("team_id") or 0) != int(team_id):
                continue
            position = int(team.get("position") or 0)
            if position <= 0:
                return None
            return {
                "competition_id": int(competition.get("competition_id") or 0),
                "competition_name": str(competition.get("competition_name") or ""),
                "league_position": position,
                "league_team_count": len(teams),
                "league_points": int(team.get("points") or 0),
            }
    return None


def owned_club_finance_available(
    standing: dict[str, Any] | None, balance: Any, transfer_budget: Any,
) -> bool:
    """Only explicit zero funds plus no rank indicate an unloaded league."""
    def explicit_zero(value: Any) -> bool:
        if value is None or value == "":
            return False
        try:
            return float(value) == 0
        except (TypeError, ValueError):
            return False

    return standing is not None or not (
        explicit_zero(balance) and explicit_zero(transfer_budget)
    )


def read_owned_club_fund(
    team_address: Any,
    team_id: int,
    field: str,
    standing: dict[str, Any] | None,
    operation: Any | None = None,
    *,
    allow_budget_scan: bool = True,
) -> dict[str, Any]:
    """Read the requested fund first and only probe the other field if needed."""
    operation_kwargs = {"operation": operation} if operation is not None else {}
    budget_scan_kwargs = {} if allow_budget_scan else {"allow_scan": False}
    if field == "transfer_budget":
        current = read_transfer_budget(
            team_address, team_id, force_scan=True,
            **budget_scan_kwargs, **operation_kwargs,
        )
        if standing is None and int(current.get("amount") or 0) == 0:
            balance = read_club_balance(
                team_address, team_id, **operation_kwargs,
            )
            if not owned_club_finance_available(
                standing, balance.get("amount"), current.get("amount"),
            ):
                raise ValueError("请开启此俱乐部联赛后再进行资金操作")
        return current

    current = read_club_balance(team_address, team_id, **operation_kwargs)
    if standing is None and int(current.get("amount") or 0) == 0:
        budget = read_transfer_budget(
            team_address, team_id, force_scan=True,
            **budget_scan_kwargs, **operation_kwargs,
        )
        if not owned_club_finance_available(
            standing, current.get("amount"), budget.get("amount"),
        ):
            raise ValueError("请开启此俱乐部联赛后再进行资金操作")
    return current


def managed_team_rows(payload: dict[str, Any]) -> list[dict[str, Any]]:
    return list(payload.get("managed_teams") or (
        [payload["managed_team"]] if payload.get("managed_team") else []
    ))


def managed_team_address(payload: dict[str, Any], team_type: str) -> int:
    for team in managed_team_rows(payload):
        if str(team.get("team_type") or "club") != team_type:
            continue
        try:
            address = int(str(team.get("address") or "0"), 0)
        except (TypeError, ValueError):
            address = 0
        if address:
            return address
    return 0


def world_club_team_address_hints(payload: dict[str, Any]) -> set[int]:
    hints: set[int] = set()
    for competition in payload.get("competition_formats") or []:
        for stage in competition.get("stages") or []:
            for team in stage.get("teams") or []:
                try:
                    address = int(str(team.get("address") or "0"), 0)
                except (TypeError, ValueError):
                    address = 0
                if address:
                    hints.add(address)
    for team in managed_team_rows(payload):
        try:
            address = int(str(team.get("address") or "0"), 0)
        except (TypeError, ValueError):
            address = 0
        if address:
            hints.add(address)
    return hints


def managed_acquired_club_ids(
    payload: dict[str, Any], acquired: list[dict[str, Any]],
) -> set[int]:
    managed_ids = {
        int(team.get("id") or 0)
        for team in managed_team_rows(payload)
        if str(team.get("team_type") or "club") == "club"
        and int(team.get("id") or 0) > 0
    }
    acquired_ids = {
        int(club.get("id") or 0)
        for club in acquired
        if int(club.get("id") or 0) > 0
    }
    return managed_ids & acquired_ids


def club_preload_targets(
    manager: dict[str, Any], managed_teams: list[dict[str, Any]],
    treatment_due: bool,
) -> list[dict[str, Any]]:
    if not treatment_due or int(manager.get("id") or 0) <= 0:
        return []
    return [team for team in managed_teams if int(team.get("id") or 0) > 0]


def should_refresh_club_profiles_after_refresh(
    manager: dict[str, Any], managed_teams: list[dict[str, Any]],
) -> bool:
    return bool(
        int(manager.get("id") or 0) > 0
        and any(int(team.get("id") or 0) > 0 for team in managed_teams)
    )


def managed_club_profiles_are_current(
    manager: dict[str, Any], managed_teams: list[dict[str, Any]],
    profiles: dict[int, dict[str, Any]] | None, game_date: str,
) -> bool:
    """Return whether a successful odds refresh can reuse club profiles.

    Profile reads are deliberately not repeated for every automatic odds
    refresh.  They hold the foreground memory lock while walking every player
    and staff object, so an unconditional warm-up makes unrelated UI actions
    (canteen, activities, etc.) queue behind a second full roster scan.
    """
    if not should_refresh_club_profiles_after_refresh(manager, managed_teams):
        return False
    manager_id = int(manager.get("id") or 0)
    expected_date = str(game_date or "")
    if manager_id <= 0 or not expected_date or not isinstance(profiles, dict):
        return False
    for team in managed_teams:
        team_id = int(team.get("id") or 0)
        if team_id <= 0:
            continue
        profile = profiles.get(team_id)
        if not isinstance(profile, dict):
            return False
        if str(profile.get("game_date") or "") != expected_date:
            return False
        if str(profile.get("profile_stage") or "complete") != "complete":
            return False
        profile_manager = int((profile.get("manager") or {}).get("id") or 0)
        profile_team = profile.get("team") or {}
        if profile_manager != manager_id or int(profile_team.get("id") or 0) != team_id:
            return False
        if not isinstance(profile.get("staff"), list):
            return False
    return True


def managed_team_identities(payload: dict[str, Any]) -> set[tuple[int, str]]:
    return {
        (int(team.get("id") or 0), str(team.get("team_type") or "club"))
        for team in managed_team_rows(payload)
        if int(team.get("id") or 0) > 0
    }


def managed_club_identities(payload: dict[str, Any]) -> set[int]:
    return {
        int(team.get("id") or 0)
        for team in managed_team_rows(payload)
        if str(team.get("team_type") or "club") == "club"
        and int(team.get("id") or 0) > 0
    }


def _selected_manager_identity(payload: dict[str, Any]) -> int:
    return int(
        payload.get("selected_manager_id")
        or (payload.get("manager") or {}).get("id")
        or 0
    )


def _manager_option_assignment_identities(
    payload: dict[str, Any],
) -> tuple[tuple[int, tuple[tuple[int, str], ...]], ...]:
    rows = []
    for item in payload.get("manager_options") or []:
        manager_id = int(item.get("id") or item.get("manager_id") or 0)
        if manager_id <= 0:
            continue
        refs = item.get("managed_team_refs") or item.get("teams") or []
        teams = tuple(sorted({
            (
                int(ref.get("team_id") or ref.get("id") or 0),
                str(ref.get("team_type") or "club"),
            )
            for ref in refs
            if int(ref.get("team_id") or ref.get("id") or 0) > 0
        }))
        rows.append((manager_id, teams))
    return tuple(sorted(rows))


def manager_assignment_context_changed(
    current: dict[str, Any], refreshed: dict[str, Any],
) -> bool:
    """Return whether the selected manager's club/national assignments changed."""
    current_manager = _selected_manager_identity(current)
    refreshed_manager = _selected_manager_identity(refreshed)
    return bool(
        current_manager > 0
        and current_manager == refreshed_manager
        and managed_team_identities(current) != managed_team_identities(refreshed)
    )


def manager_team_context_changed(
    current: dict[str, Any], refreshed: dict[str, Any],
) -> bool:
    """Return whether the same human manager changed managed clubs."""
    current_manager = _selected_manager_identity(current)
    refreshed_manager = _selected_manager_identity(refreshed)
    current_clubs = managed_club_identities(current)
    refreshed_clubs = managed_club_identities(refreshed)
    if (
        current_manager <= 0
        or current_manager != refreshed_manager
        or current_clubs == refreshed_clubs
    ):
        return False
    # A newly discovered club is positive evidence and can be accepted at once.
    if refreshed_clubs:
        return True
    # Removing the last club is authoritative only when the live manager read
    # still found another assignment (normally a national team) or explicitly
    # found the HumanManager root with no assignments at all.
    return bool(
        managed_team_rows(refreshed)
        or refreshed.get("unemployed_manager_detected")
    )


def manager_club_change_requires_confirmation(
    current: dict[str, Any], refreshed: dict[str, Any],
) -> bool:
    """Ask before replacing one verified managed club with another."""
    current_clubs = managed_club_identities(current)
    refreshed_clubs = managed_club_identities(refreshed)
    return bool(
        current_clubs
        and refreshed_clubs
        and current_clubs != refreshed_clubs
        and manager_team_context_changed(current, refreshed)
    )


def manager_club_change_confirmation_key(
    current: dict[str, Any], refreshed: dict[str, Any],
) -> tuple[Any, ...]:
    return (
        str(current.get("save_instance_id") or ""),
        _selected_manager_identity(current),
        tuple(sorted(managed_club_identities(current))),
        tuple(sorted(managed_club_identities(refreshed))),
    )


def manager_assignment_absence_requires_confirmation(
    current: dict[str, Any], refreshed: dict[str, Any],
) -> bool:
    """Debounce a live transition that removes all work or the last club."""
    current_assignments = managed_team_identities(current)
    refreshed_assignments = managed_team_identities(refreshed)
    return bool(
        manager_assignment_context_changed(current, refreshed)
        and (
            (current_assignments and not refreshed_assignments)
            or (
                managed_club_identities(current)
                and not managed_club_identities(refreshed)
            )
        )
    )


def manager_context_confirmation_key(
    payload: dict[str, Any],
) -> tuple[Any, ...]:
    return (
        _selected_manager_identity(payload),
        tuple(sorted(managed_team_identities(payload))),
        _manager_option_assignment_identities(payload),
        bool(payload.get("unemployed_manager_detected")),
    )


def same_account_manager_club_changed(
    current: dict[str, Any], refreshed: dict[str, Any],
) -> bool:
    current_save = str(current.get("save_instance_id") or "")
    refreshed_save = str(refreshed.get("save_instance_id") or "")
    return bool(
        current_save
        and current_save == refreshed_save
        and manager_team_context_changed(current, refreshed)
    )


def manager_options_changed(current: dict[str, Any], refreshed: dict[str, Any]) -> bool:
    return (
        _manager_option_assignment_identities(current)
        != _manager_option_assignment_identities(refreshed)
    )


def should_retain_cached_manager_context(
    cached: dict[str, Any], refreshed: dict[str, Any], *, same_save: bool,
) -> bool:
    """Retain only an unverified missing read, never an authoritative unemployment."""
    return bool(
        same_save
        and cached.get("manager")
        and (
            not refreshed.get("manager")
            or (
                _selected_manager_identity(refreshed)
                == _selected_manager_identity(cached)
                and not managed_team_rows(refreshed)
                and not refreshed.get("unemployed_manager_detected")
            )
        )
    )


def matching_manager_team_profile(
    profile: dict[str, Any] | None, manager_id: int, team_id: int,
) -> dict[str, Any] | None:
    if not profile or manager_id <= 0 or team_id <= 0:
        return None
    if (
        int((profile.get("manager") or {}).get("id") or 0) != manager_id
        or int((profile.get("team") or {}).get("id") or 0) != team_id
    ):
        return None
    return profile


def maximum_stake_for_profit(odds: float, maximum_profit: float) -> float:
    if not math.isfinite(odds) or odds <= 1:
        return 0.0
    return from_minor(
        maximum_minor_for_product(to_minor(maximum_profit), odds - 1),
    )


def configured_money(value: Any) -> str:
    settings = load_settings()
    amount = scaled_money(value or 0, settings.get("money_rate") or 1)
    digits = max(0, min(2, int(settings.get("money_decimal_digits", 2))))
    return f"{settings.get('money_symbol') or '£'}{amount:,.{digits}f}"


def assert_bet_profit_limit(mode: str, stake: float, odds: float, maximum_profit: float) -> None:
    potential_profit_minor = multiply_minor(to_minor(stake), odds - 1)
    if potential_profit_minor <= to_minor(maximum_profit):
        return
    maximum_stake = maximum_stake_for_profit(odds, maximum_profit)
    label = "串关" if mode == "parlay" else "单场"
    raise ValueError(
        f"{label}最大可赢额为 {configured_money(maximum_profit)}；"
        f"按当前赔率，最大下注额为 {configured_money(maximum_stake)}"
    )


def mail_path() -> Path:
    return save_data_root() / "notifications" / "fm_odds_mail.json"


def load_mail() -> list[dict[str, Any]]:
    payload = load_document("mail", [], legacy_path=mail_path())
    return payload if isinstance(payload, list) else []


def save_mail(records: list[dict[str, Any]]) -> None:
    save_document("mail", records, legacy_path=mail_path())


def archive_sponsorship_offer_mail(mail: dict[str, Any]) -> dict[str, Any] | None:
    """Persist one delayed sponsorship offer mail idempotently."""
    if not isinstance(mail, dict) or not str(mail.get("offer_id") or ""):
        return None
    records = load_mail()
    source_id = str(mail.get("source_id") or "")
    existing = next(
        (row for row in records if source_id and str(row.get("source_id") or "") == source_id),
        None,
    )
    if existing:
        return existing
    records.append(dict(mail))
    save_mail(records)
    return mail


def update_sponsorship_offer_mail(
    *, team_id: int, offer_id: str, action_state: str,
) -> list[dict[str, Any]]:
    records = load_mail()
    changed = False
    for row in records:
        if int(row.get("team_id") or 0) != int(team_id) or row.get("type") != "sponsorship_offer":
            continue
        matches = str(row.get("offer_id") or "") == str(offer_id)
        if action_state == "accepted":
            row["action_state"] = "accepted" if matches else "not_selected"
            row["closed"] = True
            changed = True
        elif matches:
            row["action_state"] = str(action_state)
            row["closed"] = action_state in {"closed", "not_selected"}
            changed = True
    if changed:
        save_mail(records)
    return records


def archive_sponsorship_contract_mail(
    contract: dict[str, Any], payment: dict[str, Any],
) -> list[dict[str, Any]]:
    if not isinstance(contract, dict):
        return []
    records = load_mail()
    known = {str(row.get("source_id") or "") for row in records}
    team_name = str(contract.get("team_name") or "已收购俱乐部")
    contract_id = str(contract.get("contract_id") or "")
    added: list[dict[str, Any]] = []
    source_id = f"sponsorship_contract:{contract_id}"
    if contract_id and source_id not in known:
        mail = {
            "id": str(uuid.uuid4()), "source_id": source_id,
            "type": "sponsorship_contract", "created_at": datetime.now().isoformat(timespec="seconds"),
            **mail_template_fields("sponsorship_contract", {
                "team": team_name,
                "industry": str(contract.get("sponsor_industry") or ""),
                "years": int(contract.get("contract_years") or 1),
                "amount": int(contract.get("annual_value") or 0),
            }),
            "game_date": contract.get("accepted_game_date"),
            "team_name": team_name,
            "team_id": int(contract.get("team_id") or 0),
            "title": f"{team_name}赞助合同已签署",
            "message": f"{team_name}已与一家{contract.get('sponsor_industry') or '企业'}签署 {contract.get('contract_years') or 1} 年合作，年度赞助费 {configured_money(contract.get('annual_value') or 0)}。",
        }
        records.append(mail); added.append(mail); known.add(source_id)
    payment_id = str(payment.get("payment_id") or "") if isinstance(payment, dict) else ""
    payment_source = f"sponsorship_payment:{payment_id}"
    if payment_id and payment_source not in known and str(payment.get("status") or "") == "paid":
        mail = {
            "id": str(uuid.uuid4()), "source_id": payment_source,
            "type": "sponsorship_payment", "created_at": datetime.now().isoformat(timespec="seconds"),
            **mail_template_fields("sponsorship_payment", {
                "team": team_name,
                "amount": int(payment.get("amount") or 0),
            }),
            "game_date": payment.get("game_date"), "amount": int(payment.get("amount") or 0),
            "team_name": team_name,
            "team_id": int(payment.get("team_id") or 0),
            "title": f"{team_name}赞助费已到账",
            "message": f"年度赞助费 {configured_money(payment.get('amount') or 0)} 已写入俱乐部 FM 结余。",
        }
        records.append(mail); added.append(mail)
    if added:
        save_mail(records)
    return added


def prune_expired_profit_mail(game_date: str) -> list[dict[str, Any]]:
    """Delete betting-profit notices after five game days; keep formal mail forever."""
    records = load_mail()
    try:
        current = date.fromisoformat(str(game_date))
    except ValueError:
        return records
    retained = []
    changed = False
    for item in records:
        profit_mail = (
            item.get("type") == "bet_profit"
            or (
                not item.get("type") and item.get("bet_id") is not None
                and item.get("amount") is not None
            )
        )
        try:
            sent = date.fromisoformat(str(item.get("game_date") or ""))
        except ValueError:
            sent = None
        if profit_mail and sent is not None and (current - sent).days >= 5:
            changed = True
            continue
        retained.append(item)
    if changed:
        save_mail(retained)
    return retained


def _mail_visible_on_game_date(mail: dict[str, Any], game_date: str) -> bool:
    available_after = str(mail.get("available_after_game_date") or "")
    if not available_after:
        return True
    try:
        return date.fromisoformat(str(game_date)) >= date.fromisoformat(available_after)
    except ValueError:
        return False


def visible_mail_records(game_date: str) -> list[dict[str, Any]]:
    records = prune_expired_profit_mail(game_date)
    _repair_pending_item_integrity_cash_penalties(records)
    return [
        row for row in records
        if _mail_visible_on_game_date(row, game_date)
    ]


def favorite_teams_path() -> Path:
    return save_data_root() / "favorites.json"


def _favorite_ids(values: Any) -> list[int]:
    if not isinstance(values, list):
        return []
    resolved: set[int] = set()
    for value in values:
        try:
            item_id = int(value)
        except (TypeError, ValueError):
            continue
        if item_id > 0:
            resolved.add(item_id)
    return sorted(resolved)


def _favorite_market_keys(values: Any) -> list[str]:
    if not isinstance(values, list):
        return []
    resolved = {
        str(value).strip() for value in values
        if 0 < len(str(value).strip()) <= 100
    }
    return sorted(resolved)


def _hidden_competitions(values: Any) -> list[dict[str, Any]]:
    if not isinstance(values, list):
        return []
    resolved: dict[int, dict[str, Any]] = {}
    for value in values:
        if isinstance(value, dict):
            raw_id = value.get("id")
            name = str(value.get("name") or "").strip()[:200]
        else:
            raw_id = value
            name = ""
        try:
            competition_id = int(raw_id)
        except (TypeError, ValueError):
            continue
        if competition_id <= 0:
            continue
        current = resolved.get(competition_id)
        if current is None or (not current["name"] and name):
            resolved[competition_id] = {"id": competition_id, "name": name}
    return [resolved[key] for key in sorted(resolved)]


def owned_club_dividend_projection(
    metrics: dict[str, Any], game_date: str, acquisition: dict[str, Any],
) -> dict[str, Any] | None:
    current_month = str(game_date or "")[:7]
    if len(current_month) != 7:
        return None
    acquired_month = str(acquisition.get("acquired_game_date") or "")[:7]
    baseline = acquired_month if len(acquired_month) == 7 else current_month
    return club_dividend_forecast(current_month, acquisition, metrics, baseline)


def load_favorites(default_team_ids: Any = None) -> dict[str, Any]:
    payload = load_document("favorites", {}, legacy_path=favorite_teams_path())
    if not isinstance(payload, dict):
        payload = {}
    favorites = {
        "team_ids": _favorite_ids(payload.get("team_ids")),
        "competition_ids": _favorite_ids(payload.get("competition_ids")),
        "hidden_competitions": _hidden_competitions(
            payload.get("hidden_competitions")
        ),
        "market_keys": _favorite_market_keys(payload.get("market_keys")),
        "market_keys_initialized": bool(payload.get("market_keys_initialized")),
        "managed_defaults_initialized": bool(payload.get("managed_defaults_initialized")),
    }
    if default_team_ids is not None and not favorites["managed_defaults_initialized"]:
        favorites["team_ids"] = sorted(set(favorites["team_ids"]) | set(_favorite_ids(default_team_ids)))
        favorites["managed_defaults_initialized"] = True
        _save_favorites(favorites)
    return favorites


def _public_favorites(
    *, account_ready: bool, default_team_ids: Any = None,
) -> dict[str, Any]:
    if account_ready:
        return load_favorites(default_team_ids)
    return {
        "team_ids": [], "competition_ids": [], "hidden_competitions": [],
        "market_keys": [],
        "market_keys_initialized": False,
        "managed_defaults_initialized": False,
    }


def _save_favorites(payload: dict[str, Any]) -> None:
    normalized = {
        "team_ids": _favorite_ids(payload.get("team_ids")),
        "competition_ids": _favorite_ids(payload.get("competition_ids")),
        "hidden_competitions": _hidden_competitions(
            payload.get("hidden_competitions")
        ),
        "market_keys": _favorite_market_keys(payload.get("market_keys")),
        "market_keys_initialized": bool(payload.get("market_keys_initialized")),
        "managed_defaults_initialized": bool(payload.get("managed_defaults_initialized")),
    }
    save_document("favorites", normalized, legacy_path=favorite_teams_path())


def load_favorite_team_ids() -> list[int]:
    return list(load_favorites()["team_ids"])


def load_favorite_competition_ids() -> list[int]:
    return list(load_favorites()["competition_ids"])


def load_hidden_competition_ids() -> list[int]:
    return [
        int(item["id"]) for item in load_favorites()["hidden_competitions"]
    ]


def save_favorite_team_ids(values: Any) -> list[int]:
    if not isinstance(values, list):
        raise ValueError("收藏球队数据无效")
    try:
        resolved = sorted({int(value) for value in values if int(value) > 0})
    except (TypeError, ValueError) as error:
        raise ValueError("收藏球队数据无效") from error
    payload = load_favorites()
    payload["team_ids"] = resolved
    payload["managed_defaults_initialized"] = True
    _save_favorites(payload)
    return resolved


def save_favorite_competition_ids(values: Any) -> list[int]:
    if not isinstance(values, list):
        raise ValueError("收藏赛事数据无效")
    try:
        resolved = sorted({int(value) for value in values if int(value) > 0})
    except (TypeError, ValueError) as error:
        raise ValueError("收藏赛事数据无效") from error
    payload = load_favorites()
    hidden_ids = {
        int(item["id"]) for item in payload["hidden_competitions"]
    }
    resolved = [value for value in resolved if value not in hidden_ids]
    payload["competition_ids"] = resolved
    _save_favorites(payload)
    return resolved


def save_hidden_competitions(
    values: Any,
) -> tuple[list[dict[str, Any]], list[int]]:
    if not isinstance(values, list):
        raise ValueError("隐藏赛事数据无效")
    hidden = _hidden_competitions(values)
    hidden_ids = {int(item["id"]) for item in hidden}
    payload = load_favorites()
    payload["hidden_competitions"] = hidden
    payload["competition_ids"] = [
        value for value in payload["competition_ids"]
        if int(value) not in hidden_ids
    ]
    _save_favorites(payload)
    return hidden, list(payload["competition_ids"])


def save_favorite_market_keys(values: Any) -> list[str]:
    if not isinstance(values, list):
        raise ValueError("收藏玩法数据无效")
    resolved = _favorite_market_keys(values)
    payload = load_favorites()
    payload["market_keys"] = resolved
    payload["market_keys_initialized"] = True
    _save_favorites(payload)
    return resolved


def _display_game_date(value: Any) -> str:
    try:
        parsed = datetime.strptime(str(value), "%Y-%m-%d")
        return f"{parsed.year}-{parsed.month}-{parsed.day}"
    except ValueError:
        return str(value or "-")


def manager_display_name(output: dict[str, Any]) -> str:
    manager = output.get("manager") or {}
    manager_id = int(output.get("selected_manager_id") or manager.get("id") or 0)
    option = next(
        (item for item in output.get("manager_options", []) if int(item.get("id") or 0) == manager_id),
        None,
    )
    return str((option or {}).get("name") or manager.get("name") or "经理")


def manager_memory_identity(output: dict[str, Any]) -> tuple[int, Any]:
    """Return the selected manager UID and the best revalidated address hint."""
    manager = output.get("manager") or {}
    manager_id = int(output.get("selected_manager_id") or manager.get("id") or 0)
    option = next(
        (
            item for item in output.get("manager_options", [])
            if int(item.get("id") or 0) == manager_id
        ),
        None,
    ) or {}
    managed_team = output.get("managed_team") or {}
    return manager_id, (
        option.get("manager_address")
        or managed_team.get("manager_address")
        or manager.get("manager_address")
    )


def _specific_manager_name(value: Any) -> str:
    name = str(value or "").strip()
    if not name or name in {"经理", "教练", "未知", "待读取"}:
        return ""
    if name.startswith("经理 ") and name[3:].isdigit():
        return ""
    return name


def _integrity_manager_name(record: dict[str, Any], fallback: str = "") -> str:
    return (
        _specific_manager_name(record.get("manager_name"))
        or _specific_manager_name(fallback)
        or "经理"
    )


def _integrity_referee_name(record: dict[str, Any]) -> str:
    name = str(record.get("referee_name") or "").strip()
    if name in {"", "裁判", "本场裁判", "未知裁判"}:
        return "当值主裁判"
    return name


def _repair_integrity_mail_correspondents(
    records: list[dict[str, Any]], output: dict[str, Any],
) -> bool:
    manager_name = _specific_manager_name(manager_display_name(output))
    if not manager_name:
        return False
    changed = False
    for mail in records:
        if mail.get("type") not in {
            "referee_debt", "referee_integrity", "referee_apology", "doping_integrity",
        }:
            continue
        if mail.get("manager_name") != manager_name:
            mail["manager_name"] = manager_name
            changed = True
        referee_name = _integrity_referee_name(mail)
        if mail.get("type") in {"referee_debt", "referee_apology"}:
            if mail.get("referee_name") != referee_name:
                mail["referee_name"] = referee_name
                changed = True
        semantic_fields = mail_template_fields(mail.get("type"), {
            **dict(mail.get("template_params") or {}),
            "manager": manager_name,
            "referee": referee_name,
        })
        for key, value in semantic_fields.items():
            if mail.get(key) != value:
                mail[key] = value
                changed = True
    return changed


def player_manager_for_team(
    output: dict[str, Any], team_id: int,
) -> dict[str, Any] | None:
    managed_teams = list(output.get("managed_teams") or [])
    if not managed_teams and output.get("managed_team"):
        managed_teams = [output["managed_team"]]
    if not any(
        int(team.get("id") or 0) == int(team_id)
        and str(team.get("team_type") or "club") == "club"
        for team in managed_teams
    ):
        return None
    manager = output.get("manager") or {}
    manager_id = int(output.get("selected_manager_id") or manager.get("id") or 0)
    if manager_id <= 0:
        return None
    return {
        "id": manager_id,
        "name": manager_display_name(output),
        "contract_start_date": manager.get("contract_start_date"),
    }


def archive_winning_mail(settled_records: list[dict[str, Any]]) -> list[dict[str, Any]]:
    records = load_mail()
    known_bets = {str(item.get("bet_id")) for item in records}
    added = []
    for item in settled_records:
        bet_id = str(item.get("bet_id") or "")
        if item.get("status") != "won" or not bet_id or bet_id in known_bets:
            continue
        if item.get("type") == "championship":
            source = f"{item.get('competition_name') or '赛事'}冠军投注"
        elif item.get("type") == "parlay":
            source = f"{item.get('legs', 0)}场串关投注"
        else:
            source = f"{item.get('home') or '-'} VS {item.get('away') or '-'}"
        profit = float(item.get("profit", 0))
        game_date = _display_game_date(item.get("game_date"))
        message = f"{game_date} 从{source}获得了 {configured_money(profit)}。"
        mail = {
            "id": str(uuid.uuid4()),
            "type": "bet_profit",
            **mail_template_fields("bet_profit", {
                "date": str(item.get("game_date") or ""),
                "amount": profit,
            }),
            "bet_id": bet_id,
            "created_at": datetime.now().isoformat(timespec="seconds"),
            "game_date": item.get("game_date"),
            "amount": profit,
            "message": message,
        }
        records.append(mail)
        added.append(mail)
        known_bets.add(bet_id)
    if added:
        save_mail(records)
    return added


def archive_salary_payment_mail(payments: list[dict[str, Any]]) -> list[dict[str, Any]]:
    if not payments:
        return []
    records = load_mail()
    known_sources = {str(item.get("source_id") or "") for item in records}
    added = []
    for payment in payments:
        payment_id = str(payment.get("id") or "")
        source_id = f"manager_salary:{payment_id}"
        if not payment_id or source_id in known_sources:
            continue
        game_date = str(payment.get("game_date") or "")
        amount = float(payment.get("net_amount") or 0)
        mail = {
            "id": str(uuid.uuid4()), "source_id": source_id,
            "type": "manager_salary", "created_at": datetime.now().isoformat(timespec="seconds"),
            **mail_template_fields("manager_salary", {
                "date": game_date, "amount": amount,
            }),
            "game_date": game_date, "amount": amount,
            "title": "工资已到账",
            "message": f"{game_date} 的税后工资 {configured_money(amount)} 已存入银行。",
        }
        records.append(mail)
        added.append(mail)
        known_sources.add(source_id)
    if added:
        save_mail(records)
    return added


def archive_club_dividend_mail(payments: list[dict[str, Any]]) -> list[dict[str, Any]]:
    if not payments:
        return []
    records = load_mail()
    known_sources = {str(item.get("source_id") or "") for item in records}
    added = []
    for payment in payments:
        payment_id = str(payment.get("id") or "")
        source_id = f"club_dividend:{payment_id}"
        if not payment_id or source_id in known_sources:
            continue
        team_name = str(payment.get("team_name") or "已收购俱乐部")
        dividend_month = str(payment.get("month") or "")
        paid_on = str(payment.get("paid_on") or "")
        amount = float(payment.get("amount") or 0)
        rate = float(payment.get("rate") or 0) * 100
        mail = {
            "id": str(uuid.uuid4()), "source_id": source_id,
            "type": "club_dividend", "created_at": datetime.now().isoformat(timespec="seconds"),
            **mail_template_fields("club_dividend", {
                "team": team_name, "month": dividend_month,
                "rate": rate, "date": paid_on, "amount": amount,
            }),
            "game_date": paid_on, "amount": amount,
            "team_id": int(payment.get("team_id") or 0),
            "team_name": team_name, "dividend_month": dividend_month, "rate": rate,
            "title": f"{team_name}分红已到账",
            "message": (
                f"{dividend_month} 月度利润的 {rate:.0f}% 分红 "
                f"{configured_money(amount)} 已于 {paid_on} 存入银行。"
            ),
        }
        records.append(mail)
        added.append(mail)
        known_sources.add(source_id)
    if added:
        save_mail(records)
    return added


def archive_schedule_refund_mail(refunded_records: list[dict[str, Any]]) -> list[dict[str, Any]]:
    records = load_mail()
    known_sources = {str(item.get("source_id") or "") for item in records}
    added = []
    for item in refunded_records:
        bet_id = str(item.get("bet_id") or "")
        source_id = f"bet_schedule_refund:{bet_id}"
        if not bet_id or source_id in known_sources:
            continue
        changes = item.get("refund_changes") or []
        postponed = any(change.get("reason") == "fixture_postponed" for change in changes)
        source = (
            f"{item.get('legs', 0)}场串关投注"
            if item.get("type") in {"parlay", "system_parlay"}
            else f"{item.get('home') or '-'} VS {item.get('away') or '-'}"
        )
        reason = "比赛延期" if postponed else "比赛取消或从赛程中消失"
        new_dates = sorted({
            str(change.get("new_date") or "") for change in changes
            if change.get("new_date")
        })
        changed_to = f"，新比赛日期为 {'、'.join(new_dates)}" if new_dates else ""
        mail = {
            "id": str(uuid.uuid4()),
            "source_id": source_id,
            "type": "bet_schedule_refund",
            **mail_template_fields("bet_schedule_refund", {
                "date": str(item.get("game_date") or ""),
                "amount": float(item.get("payout") or 0.0),
            }),
            "bet_id": bet_id,
            "created_at": datetime.now().isoformat(timespec="seconds"),
            "game_date": item.get("game_date"),
            "amount": float(item.get("payout") or 0.0),
            "title": f"{reason}，投注已自动退款",
            "message": (
                f"{source}{changed_to}；原注单已作废，"
                f"{configured_money(float(item.get('payout') or 0.0))} 已全额退回赌场钱包。"
            ),
        }
        records.append(mail)
        added.append(mail)
        known_sources.add(source_id)
    if added:
        save_mail(records)
    return added


