def _youth_plan_generated_names(
    kind: str, plan: dict[str, Any],
) -> list[str]:
    rows = (
        [dict(plan.get("ability_result") or {})]
        if kind == "academy_son"
        else list(plan.get("ability_results") or [])
    )
    names: list[str] = []
    seen: set[int] = set()
    for row in rows:
        player_id = int(row.get("player_id") or row.get("id") or 0)
        if player_id > 0 and player_id in seen:
            continue
        name = str(
            row.get("player_name") or row.get("name")
            or (f"球员 {player_id}" if player_id > 0 else "青训球员")
        ).strip()
        if name:
            names.append(name)
        if player_id > 0:
            seen.add(player_id)
    return names


def archive_youth_completion_mail(
    *, armed_at: str, kind: str, team_id: int, team_name: str,
    game_date: str, player_names: list[str],
) -> dict[str, Any] | None:
    if not str(armed_at or "").strip():
        return None
    source_id = f"youth_plan_completed:{armed_at}:{int(team_id)}:{kind}"
    records = load_mail()
    if any(str(item.get("source_id") or "") == source_id for item in records):
        return None
    names = [str(name or "").strip() for name in player_names if str(name or "").strip()]
    if kind == "academy_son":
        message = f"儿子 {names[0] if names else '青训球员'} 已生成"
    else:
        message = f"小妖 {'、'.join(names) if names else '青训球员'} 已生成"
    mail = {
        "id": str(uuid.uuid4()),
        "source_id": source_id,
        "type": "youth_plan_completed",
        **mail_template_fields("youth_plan_completed", {
            "names": ", ".join(names),
        }),
        "created_at": datetime.now().isoformat(timespec="seconds"),
        "game_date": game_date,
        "team_id": int(team_id),
        "kind": kind,
        "title": message,
        "message": message,
        "team_name": str(team_name or ""),
        "player_names": names,
    }
    records.append(mail)
    save_mail(records)
    return mail


def archive_notice_mail(notice_type: str, notice: dict[str, Any]) -> dict[str, Any]:
    source_id = f"{notice_type}:{notice.get('id')}"
    records = load_mail()
    existing = next((item for item in records if item.get("source_id") == source_id), None)
    if existing:
        changed = False
        if existing.get("notice") != notice:
            existing["notice"] = notice
            existing["title"] = str(notice.get("title") or existing.get("title") or "足协纪律处罚通知")
            existing["game_date"] = notice.get("game_date")
            changed = True
        if notice.get("acknowledged") and not existing.get("read"):
            existing["read"] = True
            existing["read_at"] = notice.get("acknowledged_at") or datetime.now().isoformat(timespec="seconds")
            changed = True
        if changed:
            save_mail(records)
        return existing
    if notice_type == "credit_default":
        names = "、".join(row.get("name") or "" for row in notice.get("affected_players", []) if row.get("name"))
        title = "贷款逾期处罚通知"
        message = f"贷款逾期处罚已执行，{names or '相关球员'}受到违约影响。"
    else:
        title = str(notice.get("title") or "足协纪律处罚通知")
        message = "异常投注处罚已执行，点击查看足协纪律委员会的完整决定。"
    mail = {
        "id": str(uuid.uuid4()), "source_id": source_id, "type": notice_type,
        **mail_template_fields(notice_type, {
            "names": names if notice_type == "credit_default" else "",
        }),
        "created_at": notice.get("acknowledged_at") or datetime.now().isoformat(timespec="seconds"),
        "game_date": notice.get("game_date"), "title": title, "message": message,
        "notice": notice, "read": bool(notice.get("acknowledged")),
    }
    records.append(mail)
    save_mail(records)
    return mail


