def _game_date_plus(value: str, days: int) -> str:
    try:
        return (date.fromisoformat(str(value)) + timedelta(days=days)).isoformat()
    except ValueError:
        return str(value or "")


def _archive_item_integrity_mail(
    item: dict[str, Any], *, source_id: str, mail_type: str, title: str,
    message: str, body: str, available_date: str, profit: float,
    bet_ids: list[str], penalty_kind: str, points: int = 0,
    reputation: int = 0, waiver_amount: float = 0.0,
    cash_penalty: dict[str, float] | None = None,
    template_params: dict[str, Any] | None = None,
) -> dict[str, Any]:
    records = load_mail()
    existing = next((row for row in records if row.get("source_id") == source_id), None)
    if existing:
        return existing
    notice = {
        "id": str(uuid.uuid4()), "title": title, "body": body,
        "game_date": available_date, "type": mail_type,
    }
    if waiver_amount > 0:
        deadline = _game_date_plus(available_date, 7)
        notice["penalty_waiver"] = {
            "available": True, "paid": False,
            "amount": canonical_money(waiver_amount),
            "deadline_game_date": deadline,
            "label": f"缴纳 {configured_money(waiver_amount)}，免除本次处罚",
        }
    mail = {
        "id": notice["id"], "source_id": source_id, "type": mail_type,
        **mail_template_fields(mail_type, {
            "manager": _integrity_manager_name(item),
            "referee": _integrity_referee_name(item),
            "amount": canonical_money(waiver_amount),
            "date": available_date,
            **dict(template_params or {}),
        }),
        "created_at": datetime.now().isoformat(timespec="seconds"),
        "game_date": available_date, "available_after_game_date": available_date,
        "title": title, "message": message, "body": body, "notice": notice,
        "penalty_kind": penalty_kind, "penalty_points": int(points),
        "penalty_reputation": int(reputation),
        "profit": canonical_money(profit),
        "bet_ids": list(bet_ids), "team_id": int(item.get("managed_team_id") or 0),
        "team_address": str(item.get("managed_team_address") or ""),
        "competition_id": int(item.get("competition_id") or 0),
        "competition_kind": str(item.get("competition_kind") or ""),
        "fixture_date": str(item.get("fixture_date") or ""),
        "fixture_name": str(item.get("fixture_name") or ""),
        "manager_name": _integrity_manager_name(item),
        "referee_name": _integrity_referee_name(item),
        "read": False, "closed": False, "penalty_applied": False,
    }
    if cash_penalty is not None:
        mail["cash_penalty"] = dict(cash_penalty)
    records.append(mail)
    save_mail(records)
    return mail


def _capped_integrity_cash_penalty(profit: float, stake: float) -> dict[str, float]:
    profit = canonical_money(max(0.0, float(profit)))
    stake = canonical_money(max(0.0, float(stake)))
    profit_component = scaled_money(profit, 0.5)
    stake_component = 0.0
    requested = canonical_money(profit_component + stake_component)
    return {
        "profit": profit, "stake": stake,
        "profit_component": profit_component,
        "stake_component": stake_component,
        "requested": requested,
        "amount": min(profit, requested),
    }


def _repair_pending_item_integrity_cash_penalties(
    records: list[dict[str, Any]],
) -> bool:
    pending = [
        mail for mail in records
        if mail.get("type") in {"referee_integrity", "doping_integrity"}
        and mail.get("penalty_kind") in {
            "direct_referee_investigation", "doping_investigation",
        }
        and mail.get("profit") is not None
        and bool(mail.get("bet_ids"))
        and not mail.get("penalty_applied")
        and not mail.get("penalty_waived")
    ]
    if not pending:
        return False
    bets_by_id = {
        str(record.get("bet_id") or ""): record
        for record in load_bets()
        if record.get("bet_id")
    }
    changed = False
    for mail in pending:
        notice = mail.get("notice")
        waiver = notice.get("penalty_waiver") if isinstance(notice, dict) else None
        if not isinstance(waiver, dict) or not waiver.get("available") or waiver.get("paid"):
            continue
        stake = canonical_money(sum(
            max(0.0, float(bets_by_id[bet_id].get("stake") or 0))
            for bet_id in {str(value) for value in mail.get("bet_ids") or []}
            if bet_id in bets_by_id
        ))
        cash_penalty = _capped_integrity_cash_penalty(
            float(mail.get("profit") or 0), stake,
        )
        amount = cash_penalty["amount"]
        if (
            canonical_money(waiver.get("amount") or 0) == amount
            and mail.get("cash_penalty") == cash_penalty
        ):
            continue
        old_amount = canonical_money(waiver.get("amount") or 0)
        waiver["amount"] = amount
        waiver["label"] = f"缴纳 {configured_money(amount)}，免除本次处罚"
        mail["cash_penalty"] = cash_penalty
        if old_amount != amount and int(mail.get("cash_penalty_notice_version") or 0) < 2:
            adjustment = (
                f"【金额调整】现金处罚已按净收益的50%重新计算，不再没收本金，"
                f"应缴金额调整为 {configured_money(amount)}，原金额作废。\n\n"
                "原纪律处罚的非现金部分保持不变。"
            )
            mail["body"] = adjustment
            notice["body"] = adjustment
            mail["cash_penalty_notice_version"] = 2
            notice["cash_penalty_notice_version"] = 2
            semantic_fields = mail_template_fields(mail.get("type"), {
                **dict(mail.get("template_params") or {}),
                "amount": amount,
            })
            mail.update(semantic_fields)
        changed = True
    if changed:
        save_mail(records)
    return changed


