def archive_paid_referee_leak_mails(
    debt_mail: dict[str, Any], payment_game_date: str, payment: dict[str, Any],
) -> tuple[dict[str, Any], dict[str, Any]]:
    available_date = _game_date_plus(payment_game_date, 7)
    item = {
        "managed_team_id": debt_mail.get("team_id"),
        "managed_team_address": debt_mail.get("team_address"),
        "competition_id": debt_mail.get("competition_id"),
        "competition_kind": debt_mail.get("competition_kind"),
        "fixture_date": debt_mail.get("fixture_date"),
        "fixture_name": debt_mail.get("fixture_name"),
        "manager_name": debt_mail.get("manager_name"),
        "referee_name": debt_mail.get("referee_name"),
    }
    manager_name = _integrity_manager_name(debt_mail)
    referee_name = _integrity_referee_name(debt_mail)
    league_penalty = str(debt_mail.get("competition_kind") or "") == "league"
    decision = (
        "现扣除联赛积分3分，俱乐部声望降低50点"
        if league_penalty else "现将俱乐部声望降低50点"
    )
    body = (
        f"尊敬的{manager_name}：\n\n"
        f"足协收到举报，并已确认贵俱乐部在{debt_mail.get('fixture_name') or '相关比赛'}中存在收买裁判行为。{decision}。\n\n"
        "本决定自送达之日起生效。\n\n"
        f"足协纪律委员会\n{available_date}"
    )
    report = _archive_item_integrity_mail(
        item, source_id=f"referee_integrity:paid_leak:{debt_mail.get('id')}",
        mail_type="referee_integrity", title="足协纪律委员会来信",
        message="足协称已收到关于收买裁判行为的举报。", body=body,
        available_date=available_date, profit=float(debt_mail.get("profit") or 0),
        bet_ids=list(debt_mail.get("bet_ids") or []),
        penalty_kind="paid_referee_leak",
        points=-3 if league_penalty else 0, reputation=-50,
    )
    records = load_mail()
    source_id = f"referee_apology:{debt_mail.get('id')}"
    apology = next((row for row in records if row.get("source_id") == source_id), None)
    if apology is None:
        refund_amount = scaled_money(debt_mail.get("profit") or 0, 0.3)
        paid_amount = max(float(debt_mail.get("amount") or 0), 0.01)
        ratio = min(1.0, refund_amount / paid_amount)
        bank_refund = min(
            refund_amount, scaled_money(payment.get("bank") or 0, ratio),
        )
        refund_payment = {
            "bank": bank_refund,
            "wallet": canonical_money(refund_amount - bank_refund),
        }
        apology = {
            "id": str(uuid.uuid4()), "source_id": source_id, "type": "referee_apology",
            **mail_template_fields("referee_apology", {
                "manager": manager_name, "referee": referee_name,
                "amount": refund_amount, "date": available_date,
            }),
            "created_at": datetime.now().isoformat(timespec="seconds"),
            "game_date": available_date, "available_after_game_date": available_date,
            "title": "裁判来信", "message": "这不是我希望看到的结果。",
            "body": (
                f"教练：{manager_name}\n\n秘密还是泄露了，很抱歉，这不是我想看到的结果。"
                f"作为补偿，我会归还你在那场比赛盈利的30%，共 {configured_money(refund_amount)}。\n\n"
                f"裁判：{referee_name}"
            ),
            "manager_name": manager_name, "referee_name": referee_name,
            "refund_amount": refund_amount, "refund_payment": refund_payment,
            "refunded": False, "read": False, "closed": False,
        }
        records.append(apology)
        save_mail(records)
    return report, apology


