def referee_debt_action(mail_id: str, action: str, current_game_date: str = "") -> dict[str, Any]:
    records = load_mail()
    mail = next((row for row in records if row.get("id") == str(mail_id) and row.get("type") == "referee_debt"), None)
    if not mail:
        raise NotFoundError(
            "裁判追债邮件不存在",
            message_key="referee_debt.mail_not_found",
        )
    action = str(action or "")
    if action == "close":
        mail["closed"] = True
        mail["read"] = True
        mail["read_at"] = mail.get("read_at") or datetime.now().isoformat(timespec="seconds")
    elif action == "read":
        mail["read"] = True
        mail["read_at"] = mail.get("read_at") or datetime.now().isoformat(timespec="seconds")
    elif action == "pay":
        if mail.get("enforced"):
            raise ValidationError(
                "裁判追债已逾期，处罚已经执行，无法再付款",
                code="referee_debt_payment_unavailable",
                phase="validate_state",
                message_key="referee_debt.payment_unavailable",
            )
        if (
            current_game_date and str(mail.get("deadline") or "")
            and str(current_game_date) > str(mail.get("deadline"))
        ):
            raise ValidationError(
                "裁判追债付款期限已过",
                code="referee_debt_payment_expired",
                phase="validate_state",
                message_key="referee_debt.payment_expired",
            )
        if not mail.get("paid"):
            amount = float(mail.get("amount") or 0)
            try:
                payment = charge_combined_funds(
                    amount, "referee_debt_payment", mail_id=str(mail_id),
                    competition_name=str(mail.get("competition_name") or ""),
                )
            except ValueError as error:
                if str(error) != "银行与钱包余额合计不足":
                    raise
                raise ValidationError(
                    str(error),
                    code="referee_debt_insufficient_funds",
                    phase="funding",
                    message_key="referee_debt.insufficient_funds",
                    message_params={"amount": configured_money(amount)},
                ) from error
            mail["paid"] = True
            mail["paid_at"] = datetime.now().isoformat(timespec="seconds")
            mail["payment"] = payment
            mail["payment_game_date"] = str(current_game_date or mail.get("game_date") or "")
            leak = not load_settings().get("disable_fa_penalties") and secrets.randbelow(100) < 2
            mail["paid_leak_triggered"] = leak
            relief = grant_bankruptcy_relief()
            if relief.get("granted"):
                mail["bankruptcy_relief"] = relief
            save_mail(records)
            if relief.get("granted"):
                archive_bankruptcy_relief_mail(relief, mail["payment_game_date"])
            if leak:
                archive_paid_referee_leak_mails(mail, mail["payment_game_date"], payment)
            return mail
    else:
        raise ValueError("裁判追债邮件操作无效")
    save_mail(records)
    return mail


def acknowledge_referee_integrity_mail(mail_id: str) -> dict[str, Any]:
    records = load_mail()
    mail = next((
        row for row in records
        if row.get("id") == str(mail_id)
        and row.get("type") in {"referee_integrity", "doping_integrity", "referee_apology"}
    ), None)
    if not mail:
        raise ValueError("足协处罚邮件不存在")
    timestamp = datetime.now().isoformat(timespec="seconds")
    mail["read"] = True
    mail["read_at"] = mail.get("read_at") or timestamp
    mail["closed"] = True
    mail["closed_at"] = mail.get("closed_at") or timestamp
    notice = mail.get("notice")
    if isinstance(notice, dict):
        notice["read"] = True
        notice["acknowledged"] = True
        notice["acknowledged_at"] = notice.get("acknowledged_at") or timestamp
    save_mail(records)
    return mail


def waive_item_integrity_penalty(mail_id: str, current_game_date: str) -> dict[str, Any]:
    records = load_mail()
    _repair_pending_item_integrity_cash_penalties(records)
    mail = next((
        row for row in records
        if row.get("id") == str(mail_id)
        and row.get("type") in {"referee_integrity", "doping_integrity"}
    ), None)
    if not mail:
        raise NotFoundError(
            "足协处罚邮件不存在",
            message_key="integrity.waiver.mail_not_found",
        )
    waiver = dict((mail.get("notice") or {}).get("penalty_waiver") or {})
    if not waiver.get("available") or waiver.get("paid") or mail.get("penalty_applied"):
        raise ValidationError(
            "该处罚已不能缴款豁免",
            code="integrity_waiver_unavailable",
            phase="validate_state",
            message_key="integrity.waiver.unavailable",
        )
    if str(current_game_date or "") < str(mail.get("available_after_game_date") or ""):
        raise ValidationError(
            "处罚来信尚未送达",
            code="integrity_waiver_not_delivered",
            phase="validate_state",
            message_key="integrity.waiver.not_delivered",
        )
    if str(current_game_date or "") > str(waiver.get("deadline_game_date") or ""):
        raise ValidationError(
            "缴款豁免期限已过",
            code="integrity_waiver_expired",
            phase="validate_state",
            message_key="integrity.waiver.expired",
        )
    amount = canonical_money(waiver.get("amount") or 0)
    try:
        payment = charge_combined_funds(
            amount, "item_integrity_penalty_waiver", mail_id=str(mail_id),
            penalty_kind=str(mail.get("penalty_kind") or ""),
        )
    except ValueError as error:
        if str(error) != "银行与钱包余额合计不足":
            raise
        raise ValidationError(
            str(error),
            code="integrity_waiver_insufficient_funds",
            phase="funding",
            message_key="integrity.waiver.insufficient_funds",
            message_params={"amount": configured_money(amount)},
        ) from error
    waiver.update({
        "available": False, "paid": True, "paid_amount": amount,
        "paid_game_date": str(current_game_date or ""),
    })
    mail["notice"]["penalty_waiver"] = waiver
    mail["penalty_waived"] = True
    mail["waiver_payment"] = payment
    relief = grant_bankruptcy_relief()
    if relief.get("granted"):
        mail["bankruptcy_relief"] = relief
    save_mail(records)
    if relief.get("granted"):
        archive_bankruptcy_relief_mail(relief, str(current_game_date or ""))
    return {"mail": mail, "payment": payment, "bankruptcy_relief": relief}


def priced_special_market_odds(
    probability: float, pricing_mode: str = "casino", *, divisor: float = EXACT_GOALS_ODDS_DIVISOR,
) -> float:
    raw_fair = 1 / probability if probability > 0 else 1.01
    if pricing_mode == "fair":
        return quote_decimal_odds(raw_fair)
    return quote_decimal_odds(raw_fair / divisor)


def result_payload(output: dict[str, Any]) -> list[dict[str, Any]]:
    merged: dict[tuple[str, int, int, int], dict[str, Any]] = {}
    for item in [*output.get("season_results", []), *output.get("settlement_results", [])]:
        payload = {
            "date": item["date"],
            "competition": {"id": item["competition_id"]},
            "home_team": item["home"],
            "away_team": item["away"],
            "home_goals": item["home_goals"],
            "away_goals": item["away_goals"],
        }
        if item.get("half_home_goals") is not None and item.get("half_away_goals") is not None:
            payload["half_home_goals"] = int(item["half_home_goals"])
            payload["half_away_goals"] = int(item["half_away_goals"])
        if item.get("first_scoring_team") in {"home", "away", "none"}:
            payload["first_scoring_team"] = item["first_scoring_team"]
        for field in (
            "after_extra_time_home_goals", "after_extra_time_away_goals",
            "penalty_shootout_home_goals", "penalty_shootout_away_goals",
            "home_outcome_code", "away_outcome_code", "winner_side", "decided_by",
            "advanced_side", "advanced_team", "advanced_team_id",
            "settlement_verified", "settlement_evidence", "settlement_sources",
            "result_source", "result_address", "fixture_address",
            "competition_stage_index", "competition_group_index",
            "kickoff_minutes", "kickoff_time",
        ):
            if item.get(field) is not None:
                payload[field] = item[field]
        key = (
            str(payload["date"]), int(payload["competition"]["id"]),
            int(payload["home_team"]["id"]), int(payload["away_team"]["id"]),
        )
        merged[key] = payload
    return list(merged.values())


def _historical_market_snapshot(match: dict[str, Any]) -> dict[str, Any]:
    """Freeze one published early market without retaining private team profiles."""
    snapshot = deepcopy(match)
    ensure_match_market_catalog(snapshot)
    for side in ("home", "away"):
        team = dict(snapshot.get(side) or {})
        profile = team.get("profile")
        if isinstance(profile, dict):
            team["profile"] = {
                "candidate_20_ca": profile.get("candidate_20_ca"),
            }
        snapshot[side] = team
    early_prices = (
        snapshot.get("early_casino_1x2")
        or snapshot.get("casino_1x2")
        or snapshot.get("fair_1x2")
    )
    if isinstance(early_prices, dict):
        snapshot["casino_1x2"] = dict(early_prices)
    snapshot["market_phase"] = "early"
    snapshot["odds_movement"] = {
        outcome: "flat" for outcome in ("home", "draw", "away")
    }
    return snapshot


def attach_historical_market_snapshots(
    output: dict[str, Any], previous_output: dict[str, Any] | None,
    archived_forecasts: dict[str, dict[str, Any]] | None = None,
) -> dict[str, Any]:
    """Carry the actual pre-match market into completed result rows.

    The current FM fixture list no longer prices a completed match.  Reusing
    the previously published match preserves the odds the user actually saw
    and avoids recalculating completed matches with post-match squad information.
    """
    previous = previous_output or {}
    archived_result_dates: set[str] = set()
    archived_results = list(output.get("season_results") or [])
    if archived_forecasts is None:
        try:
            current_game_date = date.fromisoformat(
                str(output.get("game_date") or "")
            )
        except ValueError:
            archived_results = []
        else:
            archived_results = [
                result for result in archived_results
                if str(result.get("date") or "") < current_game_date.isoformat()
            ]
    result_keys = {
        ":".join(map(str, (
            str(result.get("date") or ""),
            int(result.get("competition_id") or 0),
            int((result.get("home") or {}).get("id") or 0),
            int((result.get("away") or {}).get("id") or 0),
        )))
        for result in archived_results
    }
    archived = (
        archived_forecasts
        if archived_forecasts is not None
        else load_season_forecasts(output, result_keys)
    )
    if archived_forecasts is None:
        archived_result_dates = set(sorted(
            {
                str(result.get("date") or "")
                for result in archived_results
                if ":".join(map(str, (
                    str(result.get("date") or ""),
                    int(result.get("competition_id") or 0),
                    int((result.get("home") or {}).get("id") or 0),
                    int((result.get("away") or {}).get("id") or 0),
                ))) in archived
            },
            reverse=True,
        )[:HISTORICAL_MARKET_DATE_LIMIT])
    match_by_key = {
        (
            str(match.get("fixture_date") or ""),
            int(match.get("competition_id") or 0),
            int((match.get("home") or {}).get("id") or 0),
            int((match.get("away") or {}).get("id") or 0),
        ): match
        for match in [
            *(previous.get("matches") or []),
            *(output.get("matches") or []),
        ]
    }
    retained = {
        (
            str(result.get("date") or ""),
            int(result.get("competition_id") or 0),
            int((result.get("home") or {}).get("id") or 0),
            int((result.get("away") or {}).get("id") or 0),
        ): result.get("odds_snapshot")
        for result in previous.get("season_results") or []
        if isinstance(result.get("odds_snapshot"), dict)
    }
    for result in output.get("season_results") or []:
        key = (
            str(result.get("date") or ""),
            int(result.get("competition_id") or 0),
            int((result.get("home") or {}).get("id") or 0),
            int((result.get("away") or {}).get("id") or 0),
        )
        source = match_by_key.get(key)
        if source is not None:
            snapshot = _historical_market_snapshot(source)
            for field in ("kickoff_minutes", "kickoff_time"):
                if snapshot.get(field) is None and result.get(field) is not None:
                    snapshot[field] = result[field]
            result["odds_snapshot"] = snapshot
        elif isinstance(retained.get(key), dict):
            snapshot = deepcopy(retained[key])
            for field in ("kickoff_minutes", "kickoff_time"):
                if snapshot.get(field) is None and result.get(field) is not None:
                    snapshot[field] = result[field]
            result["odds_snapshot"] = snapshot
        else:
            forecast_key = ":".join(map(str, key))
            forecast = (
                archived.get(forecast_key)
                if archived_forecasts is not None or key[0] in archived_result_dates
                else None
            )
            if isinstance(forecast, dict):
                casino_prices = forecast.get("casino_1x2")
                archived_match = {
                    **deepcopy(forecast),
                    "fixture_date": key[0],
                    "kickoff_minutes": (
                        forecast.get("kickoff_minutes")
                        if forecast.get("kickoff_minutes") is not None
                        else result.get("kickoff_minutes")
                    ),
                    "kickoff_time": (
                        forecast.get("kickoff_time")
                        or result.get("kickoff_time")
                    ),
                    "competition_id": key[1],
                    "competition_name": str(
                        result.get("competition_name") or "未知赛事"
                    ),
                    "competition_kind": str(
                        result.get("competition_kind") or "league"
                    ),
                    "home": deepcopy(result.get("home") or {}),
                    "away": deepcopy(result.get("away") or {}),
                    "early_casino_1x2": (
                        deepcopy(casino_prices)
                        if isinstance(casino_prices, dict) else None
                    ),
                }
                result["odds_snapshot"] = _historical_market_snapshot(
                    archived_match
                )
    return output


def championship_market_dependency_signature(
    output: dict[str, Any], standings: dict[str, Any],
) -> str:
    """Hash only inputs that can change championship availability or prices."""
    match_fields = (
        "fixture_date", "kickoff_minutes", "competition_id", "competition_kind",
        "competition_reputation", "home", "away", "xg", "casino_1x2",
        "knockout", "competition_round", "competition_match_role", "competition_final",
    )
    payload = {
        "championship_model_version": CHAMPIONSHIP_MODEL_VERSION,
        "game_date": str(output.get("game_date") or ""),
        "game_time": str(output.get("game_time") or ""),
        "season_start": str(output.get("season_start") or ""),
        "season_end": str(output.get("season_end") or ""),
        "competition_season_starts": output.get("competition_season_starts") or {},
        "competitions": output.get("competitions") or [],
        "competition_formats": output.get("competition_formats") or [],
        "matches": [
            {key: match.get(key) for key in match_fields if key in match}
            for match in output.get("matches") or []
        ],
        "season_results": output.get("season_results") or [],
        "settlement_results": output.get("settlement_results") or [],
        "standings": standings,
    }
    encoded = json.dumps(
        payload, ensure_ascii=False, sort_keys=True, separators=(",", ":"), default=str,
    ).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()


def published_championship_markets(output: dict[str, Any]) -> dict[str, Any] | None:
    markets = output.get("championship_markets")
    if not isinstance(markets, dict):
        return None
    if str(markets.get("published_save_id") or "") != str(output.get("save_instance_id") or ""):
        return None
    if str(markets.get("published_game_date") or "") != str(output.get("game_date") or ""):
        return None
    return markets


def championship_refund_settlement_dates(
    markets: dict[str, Any] | None,
) -> dict[str, str]:
    return {
        str(item.get("season_key") or ""): str(
            item.get("settlement_date") or item.get("season_end") or ""
        )
        for item in [*((markets or {}).get("competitions") or []), *((markets or {}).get("settlement_competitions") or [])]
        if str(item.get("season_key") or "")
        and str(item.get("status") or "") != "open"
        and str(item.get("settlement_date") or item.get("season_end") or "")
    }


def publish_championship_markets(
    output: dict[str, Any], previous_output: dict[str, Any] | None = None,
) -> tuple[dict[str, Any], bool]:
    """Build once per dependency change and attach an atomic published snapshot."""
    started = monotonic()
    standings = public_league_standings(output)
    signature = championship_market_dependency_signature(output, standings)
    previous_markets = published_championship_markets(previous_output or {})
    cache_hit = bool(
        previous_markets
        and str(previous_markets.get("dependency_signature") or "") == signature
        and not any(
            str(item.get("status") or "") == "awaiting_result"
            for item in [*(previous_markets.get("competitions") or []), *(previous_markets.get("settlement_competitions") or [])]
        )
    )
    if cache_hit:
        markets = dict(previous_markets or {})
    else:
        markets = dict(build_championship_markets(output, standings))
    markets.update({
        "published_save_id": str(output.get("save_instance_id") or ""),
        "published_game_date": str(output.get("game_date") or ""),
        "dependency_signature": signature,
    })
    output["championship_markets"] = markets
    elapsed_ms = round((monotonic() - started) * 1000, 1)
    performance = output.setdefault("performance", {})
    performance["championship_markets_ms"] = elapsed_ms
    performance["championship_market_cache_hit"] = int(cache_hit)
    performance["total_ms"] = round(
        float(performance.get("total_ms") or 0) + elapsed_ms, 1,
    )
    return markets, cache_hit


def light_result_refresh_changed(
    date_changed: bool, changed_results: int,
    previous_match_count: int, current_match_count: int,
) -> bool:
    return bool(
        date_changed
        or changed_results
        or previous_match_count != current_match_count
    )


def preserve_previous_schedule_after_empty_read(
    previous: dict[str, Any], current: dict[str, Any],
) -> dict[str, Any]:
    """Keep a verified fixture list when a transient FM read returns zero rows."""
    if current.get("matches") or not previous.get("matches"):
        return current
    if str(previous.get("model_version") or "") != str(
        current.get("model_version") or ""
    ):
        return current
    same_context = bool(
        save_identity_matches(
            str(current.get("save_instance_id") or ""),
            str(previous.get("save_instance_id") or ""),
        )
        and str(current.get("game_date") or "")
        >= str(previous.get("game_date") or "")
        and str(current.get("odds_scope") or "")
        == str(previous.get("odds_scope") or "")
        and int(current.get("odds_days") or 0)
        == int(previous.get("odds_days") or 0)
        and _favorite_ids(current.get("hidden_competition_ids"))
        == _favorite_ids(previous.get("hidden_competition_ids"))
    )
    if not same_context:
        return current
    game_date = str(current.get("game_date") or "")
    retained = [
        dict(item) for item in previous.get("matches", [])
        if str(item.get("fixture_date") or "") >= game_date
    ]
    if not retained:
        return current
    copied = dict(current)
    copied["matches"] = retained
    copied["competitions"] = list(previous.get("competitions") or current.get("competitions") or [])
    copied["schedule_read_fallback"] = True
    return copied


def suspicious_empty_schedule_refresh(
    previous: dict[str, Any], current: dict[str, Any],
) -> bool:
    """Reject a same-context fast refresh that would publish an empty market."""
    if current.get("matches") or not previous.get("matches"):
        return False
    return bool(
        save_identity_matches(
            str(current.get("save_instance_id") or ""),
            str(previous.get("save_instance_id") or ""),
        )
        and str(current.get("odds_scope") or "")
        == str(previous.get("odds_scope") or "")
        and int(current.get("odds_days") or 0)
        == int(previous.get("odds_days") or 0)
        and _favorite_ids(current.get("hidden_competition_ids"))
        == _favorite_ids(previous.get("hidden_competition_ids"))
    )


def fast_refresh_crossed_save(
    previous: dict[str, Any], current: dict[str, Any],
) -> bool:
    previous_id = str(previous.get("save_instance_id") or "")
    current_id = str(current.get("save_instance_id") or "")
    return bool(
        previous_id
        and current_id
        and not save_identity_matches(previous_id, current_id)
    )


def suspicious_partial_schedule_refresh(
    previous: dict[str, Any], current: dict[str, Any],
) -> bool:
    """Detect a same-save snapshot missing known open or future fixtures."""
    if not previous.get("full_verified_at") or not current.get("matches"):
        return False
    same_context = bool(
        save_identity_matches(
            str(previous.get("save_instance_id") or ""),
            str(current.get("save_instance_id") or ""),
        )
        and str(previous.get("odds_scope") or "")
        == str(current.get("odds_scope") or "")
        and int(previous.get("odds_days") or 0)
        == int(current.get("odds_days") or 0)
        and _favorite_ids(current.get("hidden_competition_ids"))
        == _favorite_ids(previous.get("hidden_competition_ids"))
    )
    if not same_context:
        return False
    game_date = str(current.get("game_date") or "")
    try:
        hour, minute = str(current.get("game_time") or "").split(":", 1)
        game_minutes = int(hour) * 60 + int(minute)
    except (TypeError, ValueError):
        game_minutes = None

    def fixture_key(item: dict[str, Any]) -> tuple[str, int, int, int] | None:
        try:
            return (
                str(item["fixture_date"]), int(item["competition_id"]),
                int(item["home"]["id"]), int(item["away"]["id"]),
            )
        except (KeyError, TypeError, ValueError):
            return None

    current_keys = {
        key for item in current.get("matches", [])
        if (key := fixture_key(item)) is not None
    }
    required_previous_keys: set[tuple[str, int, int, int]] = set()
    for item in previous.get("matches", []):
        fixture_date = str(item.get("fixture_date") or "")
        if fixture_date < game_date:
            continue
        if fixture_date == game_date:
            try:
                kickoff = int(item.get("kickoff_minutes"))
            except (TypeError, ValueError):
                continue
            if game_minutes is None or kickoff < game_minutes:
                continue
        key = fixture_key(item)
        if key is not None:
            required_previous_keys.add(key)
    if not required_previous_keys.issubset(current_keys):
        return True

    # Retain a coarse fallback for old or incomplete snapshots whose fixture
    # rows predate stable competition/team identities.
    baseline_count = sum(
        1 for item in previous.get("matches", [])
        if str(item.get("fixture_date") or "") >= game_date
    )
    current_count = len(current.get("matches") or [])
    return bool(
        baseline_count >= 50
        and current_count * 100 < baseline_count * 65
    )


def detected_pending_schedule_changes(
    previous: dict[str, Any], current: dict[str, Any],
    completed_results: list[dict[str, Any]],
) -> dict[tuple[str, int, int, int], dict[str, Any]]:
    """Find verified fixture replacements or removals without treating live play as cancellation."""
    if (
        not previous.get("full_verified_at")
        or not current.get("matches")
        or str(current.get("fixture_scan_mode") or "") not in {"heap", "pool"}
        or not save_identity_matches(
            str(previous.get("save_instance_id") or ""),
            str(current.get("save_instance_id") or ""),
        )
        or str(previous.get("odds_scope") or "") != str(current.get("odds_scope") or "")
        or int(previous.get("odds_days") or 0) != int(current.get("odds_days") or 0)
        or _favorite_ids(previous.get("hidden_competition_ids"))
        != _favorite_ids(current.get("hidden_competition_ids"))
    ):
        return {}

    def match_key(item: dict[str, Any]) -> tuple[str, int, int, int] | None:
        try:
            return (
                str(item["fixture_date"]), int(item["competition_id"]),
                int(item["home"]["id"]), int(item["away"]["id"]),
            )
        except (KeyError, TypeError, ValueError):
            return None

    def kickoff_minutes(item: dict[str, Any]) -> int | None:
        try:
            value = int(item.get("kickoff_minutes"))
        except (TypeError, ValueError):
            return None
        return value if 0 <= value < 24 * 60 else None

    current_by_key = {
        key: item for item in current.get("matches") or []
        if (key := match_key(item)) is not None
    }
    current_by_matchup: dict[tuple[int, int, int], list[tuple[tuple[str, int, int, int], dict[str, Any]]]] = {}
    for key, item in current_by_key.items():
        current_by_matchup.setdefault(key[1:], []).append((key, item))
    result_keys = set()
    for item in completed_results:
        try:
            result_keys.add((
                str(item["date"]), int(item["competition"]["id"]),
                int(item["home_team"]["id"]), int(item["away_team"]["id"]),
            ))
        except (KeyError, TypeError, ValueError):
            continue
    game_date = str(current.get("game_date") or "")
    try:
        hour, minute = str(current.get("game_time") or "").split(":", 1)
        game_minutes = int(hour) * 60 + int(minute)
    except (TypeError, ValueError):
        game_minutes = None

    changes: dict[tuple[str, int, int, int], dict[str, Any]] = {}
    for previous_match in previous.get("matches") or []:
        key = match_key(previous_match)
        if key is None or key in result_keys:
            continue
        current_match = current_by_key.get(key)
        old_kickoff = kickoff_minutes(previous_match)
        if current_match is not None:
            new_kickoff = kickoff_minutes(current_match)
            if old_kickoff is None or new_kickoff is None or old_kickoff == new_kickoff:
                continue
            changes[key] = {
                "reason": "fixture_postponed",
                "original_date": key[0],
                "original_kickoff_minutes": old_kickoff,
                "new_date": key[0],
                "new_kickoff_minutes": new_kickoff,
            }
            continue

        replacements = sorted(
            current_by_matchup.get(key[1:], []), key=lambda row: row[0][0],
        )
        if replacements:
            replacement_key, replacement = replacements[0]
            changes[key] = {
                "reason": "fixture_postponed",
                "original_date": key[0],
                "original_kickoff_minutes": old_kickoff,
                "new_date": replacement_key[0],
                "new_kickoff_minutes": kickoff_minutes(replacement),
            }
            continue

        # A same-day fixture normally leaves the public schedule when play
        # starts. Wait for a result or the next game day instead of refunding
        # an in-progress match merely because its fixture row disappeared.
        if key[0] == game_date and (
            game_minutes is None or old_kickoff is None or game_minutes >= old_kickoff
        ):
            continue
        changes[key] = {
            "reason": "fixture_disappeared",
            "original_date": key[0],
            "original_kickoff_minutes": old_kickoff,
            "new_date": None,
            "new_kickoff_minutes": None,
        }
    return changes


def background_pool_reconcile_requires_heap(
    previous: dict[str, Any], current: dict[str, Any],
) -> bool:
    """Escalate a pool-first reconciliation when its snapshot is unsafe."""
    return bool(
        fast_refresh_crossed_save(previous, current)
        or suspicious_empty_schedule_refresh(previous, current)
        or suspicious_partial_schedule_refresh(previous, current)
    )


def disappeared_same_day_result_keys(
    previous: dict[str, Any], current: dict[str, Any], results: list[dict[str, Any]],
) -> set[tuple[str, int, int, int]]:
    """Confirm same-day completion only when a prior fixture vanished and has a result."""
    game_date = str(current.get("game_date") or "")
    previous_keys = {
        (
            str(item["fixture_date"]), int(item["competition_id"]),
            int(item["home"]["id"]), int(item["away"]["id"]),
        )
        for item in previous.get("matches", [])
        if str(item.get("fixture_date") or "") == game_date
    }
    current_keys = {
        (
            str(item["fixture_date"]), int(item["competition_id"]),
            int(item["home"]["id"]), int(item["away"]["id"]),
        )
        for item in current.get("matches", [])
    }
    result_keys = {
        (
            str(item["date"]), int(item["competition"]["id"]),
            int(item["home_team"]["id"]), int(item["away_team"]["id"]),
        )
        for item in results
    }
    return (previous_keys - current_keys) & result_keys


def settlement_keys_safe_for_engine_state(
    required_keys: set[tuple[str, int, int, int]],
    game_date: str,
    engine_state: dict[str, Any] | None,
) -> set[tuple[str, int, int, int]]:
    """Allow historical results, but require schedule evidence for same-day results.

    FM can expose a stable, completed-looking result object before a fixture is
    actually played. An inactive or unreadable match session does not prove that
    a same-day fixture is complete. Same-day settlement is therefore handled by
    the full-refresh path after the fixture disappears from the verified schedule.
    """
    return {key for key in required_keys if key[0] < game_date}


def missing_result_timeout_due(
    required_keys: set[tuple[str, int, int, int]], game_date: str,
) -> bool:
    """Return whether any missing result key has reached the three-day void rule."""
    try:
        current_date = date.fromisoformat(str(game_date))
    except ValueError:
        return False
    for key in required_keys:
        try:
            if (current_date - date.fromisoformat(key[0])).days >= RESULT_SEARCH_WAIT_DAYS:
                return True
        except (IndexError, TypeError, ValueError):
            continue
    return False


def captured_same_day_result_keys(
    due_keys: set[tuple[str, int, int, int]],
    game_date: str,
    save_id: str,
    engine_state: dict[str, Any] | None,
    match_seen_active: bool,
    captured_keys: set[tuple[Any, ...]],
) -> set[tuple[str, int, int, int]]:
    """Trust due captured results only after a known match has ended."""
    if (
        not match_seen_active
        or not engine_state
        or not engine_state.get("known")
        or engine_state.get("active")
    ):
        return set()
    return {
        key for key in due_keys
        if key[0] == str(game_date) and (str(save_id), *key) in captured_keys
    }


def recovered_result_required_key(
    item: dict[str, Any],
    required_keys: set[tuple[str, int, int, int]],
) -> tuple[str, int, int, int] | None:
    """Match a recovered result to one unambiguous pending fixture key."""
    try:
        item_key = (
            str(item["date"]), int(item["competition"]["id"]),
            int(item["home_team"]["id"]), int(item["away_team"]["id"]),
        )
    except (KeyError, TypeError, ValueError):
        return None
    if item_key in required_keys:
        return item_key
    try:
        result_date = date.fromisoformat(item_key[0])
    except ValueError:
        return None
    nearby = []
    for key in required_keys:
        if key[1:] != item_key[1:]:
            continue
        try:
            distance = abs((date.fromisoformat(key[0]) - result_date).days)
        except ValueError:
            continue
        if distance <= 1:
            nearby.append((distance, key))
    if not nearby:
        return None
    nearest_distance = min(distance for distance, _key in nearby)
    nearest = [key for distance, key in nearby if distance == nearest_distance]
    return nearest[0] if len(nearest) == 1 else None


def validate_bet_times(clock: dict[str, Any], legs: list[dict[str, Any]]) -> None:
    """Close a fixture only after kickoff using the verified game clock.

    Native match-engine flags are useful diagnostics, but they are not a stable
    betting authority across FM builds. The clock and fixture kickoff already
    provide the conservative boundary needed here.
    """
    current_date = str(clock["date"])
    current_minutes = int(clock["minutes"])
    for leg in legs:
        fixture_date = str(leg["fixture_date"])
        kickoff_minutes = leg.get("kickoff_minutes")
        if kickoff_minutes is None:
            raise ValueError(f"无法确认 {leg['home']} VS {leg['away']} 的开球时间")
        if current_date > fixture_date or (
            current_date == fixture_date and current_minutes > int(kickoff_minutes)
        ):
            raise ValueError(f"{leg['home']} VS {leg['away']} 已超过下注时间")


def validate_betting_clock_sync(
    confirmed_clock: dict[str, Any] | None,
    game_clock: dict[str, Any] | None,
    *,
    block_on_mismatch: bool = True,
) -> None:
    """Block only an active/spectating bet when the cached clock is stale."""
    try:
        confirmed_key = (
            str((confirmed_clock or {})["date"]),
            int((confirmed_clock or {})["minutes"]),
        )
    except (KeyError, TypeError, ValueError):
        if block_on_mismatch:
            raise ValueError("当前时钟尚未同步，请等待游戏时间刷新后再下注") from None
        return
    try:
        game_key = (
            str((game_clock or {})["date"]),
            int((game_clock or {})["minutes"]),
        )
    except (KeyError, TypeError, ValueError):
        if block_on_mismatch:
            raise ValueError("无法确认当前游戏时钟，请稍后重试") from None
        return
    if block_on_mismatch and confirmed_key != game_key:
        raise ValueError("检测到游戏时间已经变化，请等待当前时钟同步后再下注")


def validate_active_match_bet_times(clock: dict[str, Any], legs: list[dict[str, Any]]) -> None:
    """Block fixtures that may belong to a confirmed active match session."""
    current_date = str(clock["date"])
    current_minutes = int(clock["minutes"])
    for leg in legs:
        fixture_date = str(leg["fixture_date"])
        kickoff_minutes = leg.get("kickoff_minutes")
        if kickoff_minutes is None:
            raise ValueError(f"无法确认 {leg['home']} VS {leg['away']} 的开球时间")
        if (
            fixture_date == current_date
            and int(kickoff_minutes) == current_minutes
        ):
            raise ValueError(
                "当前时刻的比赛已经进入比赛引擎，只能投注之后开赛的比赛："
                f"{leg['home']} VS {leg['away']}"
            )


def fixture_betting_key(fixture: dict[str, Any]) -> tuple[str, int, int, int]:
    return (
        str(fixture.get("fixture_date") or ""),
        int(fixture.get("competition_id") or 0),
        int(fixture.get("home_id") or 0),
        int(fixture.get("away_id") or 0),
    )


def match_engine_restricted_legs(
    legs: list[dict[str, Any]],
    intelligence_unlocked_fixture_keys: set[tuple[str, int, int, int]],
) -> list[dict[str, Any]]:
    """Exclude fixtures with acquired intelligence from engine-view guards."""
    return [
        leg for leg in legs
        if fixture_betting_key(leg) not in intelligence_unlocked_fixture_keys
    ]


def validate_spectator_bet_times(
    clock: dict[str, Any], legs: list[dict[str, Any]],
    *, locked_fixture_keys: set[tuple[str, int, int, int]] | None = None,
) -> None:
    """Block fixtures near or permanently locked by a spectator session."""
    current_date = date.fromisoformat(str(clock["date"]))
    current_minutes = int(clock["minutes"])
    for leg in legs:
        fixture_key = fixture_betting_key(leg)
        if locked_fixture_keys and fixture_key in locked_fixture_keys:
            raise ValueError(
                "观战之后不允许下注："
                f"{leg['home']} VS {leg['away']}"
            )
        fixture_date = date.fromisoformat(str(leg["fixture_date"]))
        kickoff_minutes = leg.get("kickoff_minutes")
        if kickoff_minutes is None:
            raise ValueError(f"无法确认 {leg['home']} VS {leg['away']} 的开球时间")
        minutes_until_kickoff = (
            (fixture_date - current_date).days * 24 * 60
            + int(kickoff_minutes)
            - current_minutes
        )
        if 0 <= minutes_until_kickoff <= SPECTATOR_BETTING_LOCK_MINUTES:
            raise ValueError(
                "观赛期间不能投注的比赛："
                f"{leg['home']} VS {leg['away']}"
            )


def validate_permanent_spectator_locks(
    legs: list[dict[str, Any]],
    locked_fixture_keys: set[tuple[str, int, int, int]],
) -> None:
    for leg in legs:
        key = fixture_betting_key(leg)
        if key in locked_fixture_keys:
            raise ValueError(
                "观战之后不允许下注："
                f"{leg['home']} VS {leg['away']}"
            )


def fixture_at_game_clock(
    output: dict[str, Any], clock: dict[str, Any] | None,
) -> bool:
    """Return whether the verified snapshot has a fixture at this exact clock."""
    if not clock:
        return False
    current_date = str(clock.get("date") or "")
    try:
        current_minutes = int(clock["minutes"])
    except (KeyError, TypeError, ValueError):
        return False
    for match in output.get("matches") or []:
        try:
            if (
                str(match.get("fixture_date") or "") == current_date
                and int(match["kickoff_minutes"]) == current_minutes
            ):
                return True
        except (KeyError, TypeError, ValueError):
            continue
    return False


def fm24_spectator_session_from_native_state(
    output: dict[str, Any], engine_state: dict[str, Any],
) -> bool:
    """Accept the validated FM24 GAME_MATCH_SESSION viewer state."""
    return bool(
        str(output.get("game_layout") or "") == "fm24"
        and engine_state.get("known")
        and engine_state.get("active")
        and engine_state.get("spectator")
        and engine_state.get("detector") == "native_match_session_vector"
    )


def read_betting_match_engine_state(attempts: int = 2) -> dict[str, Any]:
    """Retry transient native-state misses before applying the betting fallback."""
    last_state: dict[str, Any] = {
        "active": False,
        "known": False,
        "phase": None,
        "mode": None,
        "reason": "match-engine state unavailable",
    }
    for _attempt in range(max(1, attempts)):
        try:
            state = read_match_engine_state()
        except Exception as error:
            last_state = {**last_state, "reason": str(error)}
            continue
        if not isinstance(state, dict):
            last_state = {**last_state, "reason": "invalid match-engine state"}
            continue
        last_state = state
        if state.get("known"):
            return state
    return last_state


def refund_settlement_fixture_kickoffs(
    output: dict[str, Any],
) -> dict[tuple[str, int, int, int], int]:
    kickoffs = {}
    for match in output.get("matches") or []:
        try:
            kickoff = int(match["kickoff_minutes"])
            key = (
                str(match["fixture_date"]), int(match["competition_id"]),
                int(match["home"]["id"]), int(match["away"]["id"]),
            )
        except (KeyError, TypeError, ValueError):
            continue
        if 0 <= kickoff < 24 * 60:
            kickoffs[key] = kickoff
    return kickoffs


def latest_snapshot() -> tuple[dict[str, Any], Path] | None:
    if not active_save_id():
        restore_active_save_id()
    if not active_save_id():
        return None
    directory = cache_data_root() / "odds" / "live"
    for path in sorted(directory.glob("fm26_all_odds_*.json"), key=lambda item: item.stat().st_mtime, reverse=True):
        try:
            output = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            continue
        if isinstance(output, dict) and isinstance(output.get("matches"), list):
            return output, path
    return None


def startup_cache_validation(
    output: dict[str, Any], current_identity: str | None,
    game_clock: dict[str, Any] | None, settings: dict[str, Any],
) -> tuple[bool, str]:
    """Validate the minimum state required before cached odds become writable."""
    if not isinstance(output.get("matches"), list) or not output.get("save_instance_id"):
        return False, "missing_snapshot"
    if str(output.get("game_layout") or "") in {"fm24", "fm26"}:
        valid_context, context_reason = manager_team_context_status(output)
        if not valid_context:
            return False, context_reason
    if not current_identity or not save_identity_matches(
        current_identity, str(output.get("save_instance_id") or ""),
    ):
        return False, "save_changed"
    current_date = str((game_clock or {}).get("date") or "")
    if not current_date or current_date != str(output.get("game_date") or ""):
        return False, "date_changed"
    if str(output.get("model_version") or "") != MODEL_VERSION:
        return False, "model_changed"
    if str(output.get("fixture_scan_mode") or "") not in {"heap", "pool"}:
        return False, "fixture_scan_unverified"
    if int(output.get("odds_days") or 0) != int(settings.get("odds_days") or 0):
        return False, "settings_changed"
    if str(output.get("odds_scope") or "") != str(settings.get("odds_scope") or ""):
        return False, "settings_changed"
    return True, "valid"


def startup_odds_refresh_mode(
    cache_valid: bool,
    cache_reason: str,
    cached_output: dict[str, Any],
    now: datetime | None = None,
) -> str:
    """Choose one startup odds pass instead of fast-then-full duplicate work."""
    fast_eligible = bool(cache_valid or cache_reason == "date_changed")
    if not fast_eligible or full_reconcile_due(cached_output, now):
        return "full"
    return "fast"


def manager_team_context_status(output: dict[str, Any]) -> tuple[bool, str]:
    """Validate the manager/team identity required for an FM24/FM26 connection."""
    manager = output.get("manager") or {}
    manager_id = int(output.get("selected_manager_id") or manager.get("id") or 0)
    if manager_id <= 0:
        return False, "manager_missing"
    teams = managed_team_rows(output)
    if not any(
        int(team.get("id") or 0) > 0 and str(team.get("name") or "").strip()
        for team in teams
    ):
        if (
            output.get("unemployed_manager_detected")
            and output.get("unemployed_confirmed")
        ):
            return True, "unemployed_confirmed"
        return False, "managed_team_missing"
    return True, "valid"


def full_reconcile_due(output: dict[str, Any], now: datetime | None = None) -> bool:
    value = str(output.get("full_verified_at") or "")
    if not value:
        return True
    try:
        verified_at = datetime.fromisoformat(value)
    except ValueError:
        return True
    current = now or datetime.now()
    return (current - verified_at).total_seconds() >= FULL_RECONCILE_INTERVAL_SECONDS


def advance_identity_change_confirmation(
    known_identity: str | None, current_identity: str | None,
    candidate: str | None, confirmations: int,
) -> tuple[str | None, int, bool]:
    if not known_identity:
        return None, 0, False
    if not current_identity:
        return candidate, confirmations, False
    if save_identity_matches(current_identity, known_identity):
        return None, 0, False
    if candidate and save_identity_matches(current_identity, candidate):
        confirmations += 1
    else:
        candidate = current_identity
        confirmations = 1
    return (
        candidate,
        confirmations,
        confirmations >= SAVE_IDENTITY_CHANGE_CONFIRMATIONS,
    )


def validate_identity_change_output(
    previous_identity: str | None,
    candidate_identity: str | None,
    observed_identity: str | None,
) -> None:
    """Accept an automatic save switch only after an independent full read."""
    if not candidate_identity:
        raise RuntimeError("存档身份候选已失效")
    if save_identity_matches(observed_identity, previous_identity):
        raise RuntimeError("完整读取仍属于当前存档，已忽略本次身份波动")
    if not save_identity_matches(observed_identity, candidate_identity):
        raise RuntimeError("完整读取结果与候选存档身份不一致")


def validate_bet_snapshot(
    payload: dict[str, Any], current_save_id: str, current_data_version: int,
) -> bool:
    """Return whether a same-save request must be repriced against the current snapshot."""
    try:
        requested_version = int(payload.get("data_version"))
    except (TypeError, ValueError):
        requested_version = -1
    requested_save_id = str(payload.get("save_instance_id") or "")
    if requested_save_id:
        if not save_identity_matches(requested_save_id, str(current_save_id or "")):
            raise ValueError("存档已变化，请等待当前存档盘口加载完成")
        return requested_version != int(current_data_version)
    # Older embedded pages did not send a save scope.  Reprice their stale
    # selections against the current verified snapshot instead of forcing the
    # user to remove and re-add every leg after an odds refresh.  The normal
    # fixture/market validation below still rejects missing or changed events.
    return requested_version != int(current_data_version)


def restore_preferred_game_layout() -> None:
    preferred = str(load_settings().get("preferred_game_version") or "")
    if preferred not in {"fm24", "fm26"}:
        return
    try:
        select_game_layout(preferred)
    except ValueError:
        pass


def remembered_account_scope_for_game(manager_id: int, game_key: str) -> str | None:
    remembered_scope = str(active_save_id() or restore_active_save_id() or "")
    for account in saved_account_scopes():
        if (
            str(account.get("scope_id") or "") == remembered_scope
            and int(account.get("manager_id") or 0) == int(manager_id or 0)
            and str(account.get("namespace") or "") == str(game_key or "")
        ):
            return remembered_scope
    return None


def _attach_optional_response_snapshot(
    response: dict[str, Any], field: str, loader: Callable[[], Any],
) -> dict[str, Any]:
    """Enrich a committed mutation without turning snapshot failure into failure."""
    try:
        response[field] = loader()
    except Exception:
        pass
    return response


class LocalOddsState:
    club_deferred_refresh_reasons = frozenset(CLUB_DEFERRED_REFRESH_REASONS)
    temporary_bank_cheat = TEMPORARY_BANK_CHEAT

    def _refresh_coordinator(self) -> RefreshCoordinator:
        service = self.__dict__.get("_refresh_coordinator_service")
        if service is None:
            service = RefreshCoordinator(self)
            self.__dict__["_refresh_coordinator_service"] = service
        return service

    def _account_application(self) -> AccountApplicationService:
        service = self.__dict__.get("_account_application_service")
        if service is None:
            service = AccountApplicationService(self._account_operation)
            self.__dict__["_account_application_service"] = service
        return service

    @contextmanager
    def _account_operation(self, requested_wallet_scope: str | None):
        """Bind and guard a complete account mutation and its response metadata."""
        with self.lock:
            scope_id = (
                self._bind_current_save() if requested_wallet_scope is None
                else self._bind_wallet_scope(requested_wallet_scope)
            )
            yield AccountOperation(
                scope_id=scope_id,
                game_date=str(self.output.get("game_date") or ""),
                weekly_salary=lambda: self._total_weekly_salary(self.club_contexts),
                temporary_bank_cheat=self.temporary_bank_cheat,
                state_patch=lambda response, patch: self._state_patch_response(
                    response, patch, scope_id=scope_id,
                ),
                economy_patch=lambda response, **kwargs: self._economy_patch_response(
                    response, scope_id=scope_id, **kwargs,
                ),
            )

    def _club_legacy_refresh(self) -> ClubLegacyRefreshCoordinator:
        with self.lock:
            service = self.__dict__.get("_club_legacy_refresh_service")
            if service is None:
                service = ClubLegacyRefreshCoordinator(self)
                self.__dict__["_club_legacy_refresh_service"] = service
            return service

    def _club_legacy_context_key(self) -> tuple:
        output = self.output
        return (
            self._data_scope_id(output) if output else "",
            str(output.get("save_instance_id") or ""),
            str(output.get("game_layout") or ""),
            int(getattr(self, "connection_process_pid", 0) or 0),
            int(getattr(self, "club_refresh_generation", 0)),
            _selected_manager_identity(output),
            tuple(int(team.get("id") or 0) for team in managed_team_rows(output)),
            str((getattr(self, "last_connection_clock", None) or {}).get("date")
                or output.get("game_date") or ""),
        )

    @staticmethod
    def _bind_service_account_scope(scope_id: str) -> None:
        set_active_save_id(scope_id)

    @staticmethod
    def _service_available_balance() -> float:
        return available_balance()

    def _warm_world_player_index_after_connect(
        self,
        selected_process: tuple[int, str, Any] | None = None,
    ) -> None:
        """Start session-scoped world-player indexing after connection publish."""
        def worker() -> None:
            try:
                warm_database_index(selected_process)
            except Exception:
                # Index warmup is an optional acceleration path.  Connection
                # state remains valid; a later world-player request can retry
                # through the normal session provider if setup was transient.
                pass

        threading.Thread(
            target=worker,
            name="FMODDWorldPlayerWarmup",
            daemon=True,
        ).start()

