    def _bind_request_scope(self) -> str | None:
        """Bind account storage for the current HTTP or worker thread."""
        with self.lock:
            if self._has_verified_save():
                scope_id = self._data_scope_id(self.output)
            elif (
                getattr(self, "wallet_ready", False)
                and getattr(self, "connection_scope_id", None)
            ):
                scope_id = str(self.connection_scope_id or "")
            else:
                scope_id = ""
        scope_id = str(scope_id or "").strip()
        if scope_id.casefold() == "unidentified":
            scope_id = ""
        set_active_save_id(scope_id or None)
        return scope_id or None

    def _bind_current_save(self) -> str:
        if self.output.get("save_identity_discovery_deferred"):
            raise ValueError("正在确认存档身份，请稍后重试")
        if getattr(self, "save_change_pending", False):
            raise ValueError("正在验证存档身份，请稍后重试")
        save_id = self.output.get("save_instance_id")
        if not save_id:
            raise ValueError("尚未识别当前存档")
        scope_id = self._data_scope_id(self.output)
        set_active_save_id(scope_id)
        recover_acquired_clubs_from_transactions(
            load_economy().get("transactions", []), scope_id,
        )
        self.canteen_plan = canteen_plan()
        return scope_id

    def _bind_wallet_scope(self, requested_scope_id: str | None = None) -> str:
        if self.output.get("save_identity_discovery_deferred"):
            raise ValueError("正在确认存档身份，请稍后重试")
        verified_scope_id = (
            self._data_scope_id(self.output) if self._has_verified_save() else ""
        )
        connection_scope_id = str(self.connection_scope_id or "")
        requested_scope_id = str(requested_scope_id or "").strip()
        allowed_scope_ids = {
            scope_id for scope_id in (verified_scope_id, connection_scope_id) if scope_id
        }
        if requested_scope_id:
            if requested_scope_id not in allowed_scope_ids:
                raise ValueError("钱包账户已变化，请刷新后重试")
            scope_id = requested_scope_id
        else:
            scope_id = verified_scope_id or connection_scope_id
        if not scope_id or (not verified_scope_id and not self.wallet_ready):
            raise ValueError("钱包尚未连接当前存档")
        set_active_save_id(scope_id)
        return scope_id

    def _activate_connection_wallet(self, save_id: str) -> str:
        if not save_id:
            raise ValueError("尚未识别当前存档")
        with self.lock:
            previous = dict(self.output)
        same_save = save_identity_matches(save_id, str(previous.get("save_instance_id") or ""))
        previous_manager_id = int(
            previous.get("selected_manager_id")
            or (previous.get("manager") or {}).get("id")
            or previous.get("account_scope_manager_id")
            or 0
        )
        manager_id = previous_manager_id if same_save else int(selected_manager_id(save_id) or 0)
        preferred_scope = self._data_scope_id(previous) if same_save else None
        remembered_scope = remembered_account_scope_for_game(
            manager_id, str(process_selection_status().get("selected") or ""),
        )
        scope_id = (
            remembered_scope if remembered_scope else resolve_account_scope(
                save_id, manager_id, preferred_scope=preferred_scope,
            ) or save_id
        )
        set_active_save_id(scope_id)
        with self.lock:
            self.connection_save_id = save_id
            self.connection_scope_id = scope_id
            self.wallet_ready = True
            self.connection_liveness_failures = 0
            self.connection_unavailable_since = None
            self.pending_save_identity = None
            self.save_change_pending = False
            self.status = "已识别当前存档，钱包已就绪，正在读取赛程和球队..."
        return scope_id

    @staticmethod
    def _data_scope_id(output: dict[str, Any]) -> str:
        manual_scope = str(output.get("manual_account_scope_id") or "")
        manual_context = str(output.get("manual_account_context_id") or "")
        save_id = str(output.get("save_instance_id") or "")
        if manual_scope and (
            not manual_context or save_identity_matches(save_id, manual_context)
        ):
            return manual_scope
        manager_id = int(
            output.get("selected_manager_id")
            or (output.get("manager") or {}).get("id")
            or output.get("account_scope_manager_id")
            or 0
        )
        explicit_scope = str(output.get("account_scope_id") or "")
        explicit_manager = int(output.get("account_scope_manager_id") or 0)
        if explicit_scope and (manager_id <= 0 or explicit_manager == manager_id):
            return explicit_scope
        return resolve_account_scope(save_id, manager_id, preferred_scope=explicit_scope) or save_id

    def _sync_owned_club_board_hook(
        self, output: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        current = output if output is not None else self.output
        scope_id = self._data_scope_id(current) if current else ""
        if scope_id:
            set_active_save_id(scope_id)
            recover_acquired_clubs_from_transactions(
                load_economy().get("transactions", []), scope_id,
            )
        controller = getattr(self, "board_listens_hook", None)
        if controller is None:
            return {"supported": True, "active": False, "error": None}
        acquired = account_acquired_clubs(scope_id, current) if scope_id else []
        target_ids = managed_acquired_club_ids(current, acquired)
        status = controller.sync(bool(target_ids))
        status["team_ids"] = sorted(target_ids)
        return status

    def _reconcile_owned_club_customizations(
        self, output: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        """Restore persisted owned-club names after a save is connected."""
        current = dict(output if output is not None else self.output)
        scope_id = self._data_scope_id(current) if current else ""
        report: dict[str, Any] = {
            "checked": 0,
            "chairmen_checked": 0,
            "club_names_repaired": 0,
            "stadium_names_repaired": 0,
            "missing": [],
            "errors": [],
        }
        if not scope_id:
            self.owned_customization_sync_status = report
            return report
        set_active_save_id(scope_id)
        acquired = account_acquired_clubs(scope_id, current)
        if not acquired:
            self.owned_customization_sync_status = report
            return report

        save_id = str(current.get("save_instance_id") or scope_id)
        team_ids = {
            int(row.get("id") or 0) for row in acquired
            if int(row.get("id") or 0) > 0
        }
        hints = world_club_team_address_hints(current)
        known_addresses: dict[int, str] = {}
        native = self._world_club_native_cache(save_id)
        for row in [*acquired, *((native or {}).get("clubs") or [])]:
            team_id = int(row.get("id") or 0)
            if team_id not in team_ids:
                continue
            try:
                address = int(str(row.get("address") or "0"), 16)
            except (TypeError, ValueError):
                address = 0
            if address:
                hints.add(address)
                known_addresses[team_id] = hex(address)
        try:
            addresses = resolve_native_team_addresses(
                team_ids, hints, scan_all_if_unresolved=True,
                known_addresses=known_addresses,
            )
        except Exception as error:
            report["errors"].append({"stage": "addresses", "error": str(error)})
            self.owned_customization_sync_status = report
            return report

        report["missing"] = sorted(team_ids.difference(addresses))
        with self.lock:
            self.owned_world_club_addresses = dict(addresses)
            self.owned_world_club_address_save_id = save_id
        manager_id, manager_address = manager_memory_identity(current)
        managed_ids = {
            int(row.get("id") or 0)
            for row in managed_team_rows(current)
            if str(row.get("team_type") or "club") == "club"
        }
        game_key = str(current.get("game_layout") or "").lower()
        game_date = str(current.get("game_date") or "")
        with self.lock:
            self.acquired_status_enforced = {
                key for key in self.acquired_status_enforced
                if len(key) == 3 and key[0] == save_id and key[2] == game_date
            }

        for ownership in acquired:
            team_id = int(ownership.get("id") or 0)
            address = addresses.get(team_id)
            if not address:
                continue
            report["checked"] += 1
            try:
                owner_name = str(
                    ownership.get("owner_name") or manager_display_name(current) or ""
                ).strip()
                try:
                    if enforce_acquired_club_chairman_status(
                        team_id, address, owner_name,
                        manager_id=manager_id, manager_address=manager_address,
                    ):
                        report["chairmen_checked"] += 1
                        self.acquired_status_enforced.add((save_id, team_id, game_date))
                except Exception as error:
                    report["errors"].append({
                        "stage": "chairman",
                        "team_id": team_id,
                        "team_name": str(ownership.get("name") or team_id),
                        "error": str(error),
                    })

                desired_name = (
                    str(ownership.get("renamed_name") or "").strip()
                    if ownership.get("renamed_name") else None
                )
                desired_short_name = (
                    str(
                        ownership.get("renamed_short_name")
                        or ownership.get("short_name")
                        or ""
                    ).strip()
                    if ownership.get("renamed_name")
                    or ownership.get("renamed_short_name") else None
                )
                desired_stadium_name = (
                    str(ownership.get("renamed_stadium_name") or "").strip()
                    if game_key == "fm26" and ownership.get("renamed_stadium_name")
                    else None
                )
                if not any((desired_name, desired_short_name, desired_stadium_name)):
                    continue

                target = {**ownership, "address": address}
                detail = read_native_world_club_snapshot(target)
                native_club = detail.get("club") or {}
                current_name = str(native_club.get("name") or "")
                current_short_name = str(native_club.get("short_name") or "")
                name_mismatch = bool(desired_name and desired_name != current_name)
                short_mismatch = bool(
                    desired_short_name and desired_short_name != current_short_name
                )
                if name_mismatch or short_mismatch:
                    rename_native_club(
                        team_id, address,
                        desired_name if name_mismatch else None,
                        new_short_name=(
                            desired_short_name if short_mismatch else None
                        ),
                        is_managed_club=team_id in managed_ids,
                    )
                    report["club_names_repaired"] += 1
                    for row in (native or {}).get("clubs", []):
                        if int(row.get("id") or 0) == team_id:
                            if desired_name:
                                row["name"] = desired_name
                            if desired_short_name:
                                row["short_name"] = desired_short_name
                            row["name_overridden"] = True
                            break

                stadium = ((detail.get("club_information") or {}).get("stadium") or {})
                current_stadium_name = str(stadium.get("name") or "").rstrip()
                if (
                    desired_stadium_name
                    and desired_stadium_name != current_stadium_name
                ):
                    update_native_stadium(
                        team_id, address, name=desired_stadium_name,
                        expected_name=current_stadium_name,
                    )
                    report["stadium_names_repaired"] += 1
            except Exception as error:
                report["errors"].append({
                    "stage": "names",
                    "team_id": team_id,
                    "team_name": str(ownership.get("name") or team_id),
                    "error": str(error),
                })

        with self.lock:
            self.world_club_cache = native
            self.world_club_cache_save_id = save_id
        self.owned_customization_sync_status = report
        return report

    @staticmethod
    def _club_vision_signature(item: dict[str, Any]) -> dict[str, int]:
        """Return the stable business fields used to replay a vision edit."""
        return {
            key: int(item.get(key) if item.get(key) is not None else -1)
            for key in (
                "type", "importance", "source_type", "value_raw",
                "reference_id", "reference_type",
            )
        }

    def _reconcile_owned_club_native_overrides(
        self, output: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        """Replay explicit native edits after FM reconstructs a save.

        Supported FM24/FM26 builds rebuild some scalar finance fields and
        in-place Club Culture edits from the save payload. The account-scoped
        override is therefore a recovery layer, not a substitute for the
        native write: it is applied only to clubs the user explicitly edited
        and only after the same object/UID checks used by the normal operation.
        """
        current = dict(output if output is not None else self.output)
        scope_id = self._data_scope_id(current) if current else ""
        report: dict[str, Any] = {
            "checked": 0,
            "recruitment_repaired": 0,
            "sugar_daddy_repaired": 0,
            "vision_repaired": 0,
            "missing": [],
            "errors": [],
        }
        if not scope_id:
            self.native_override_sync_status = report
            return report
        set_active_save_id(scope_id)
        acquired = account_acquired_clubs(scope_id, current)
        if not acquired:
            self.native_override_sync_status = report
            return report
        addresses = dict(
            self.owned_world_club_addresses
            if self.owned_world_club_address_save_id
            == str(current.get("save_instance_id") or scope_id)
            else {}
        )
        if not addresses:
            try:
                # This method is called from maintenance paths that already
                # hold ``memory_lock``.  Do the narrow resolver inline instead
                # of calling refresh_owned_world_clubs(), which would try to
                # acquire the same non-reentrant lock a second time.
                team_ids = {
                    int(row.get("id") or 0) for row in acquired
                    if int(row.get("id") or 0) > 0
                }
                native = self._world_club_native_cache(
                    str(current.get("save_instance_id") or scope_id),
                ) or {}
                hints = world_club_team_address_hints(current)
                known_addresses: dict[int, Any] = {}
                for row in [*acquired, *((native or {}).get("clubs") or [])]:
                    row_id = int(row.get("id") or 0)
                    if row_id not in team_ids:
                        continue
                    try:
                        address_value = int(str(row.get("address") or "0"), 16)
                    except (TypeError, ValueError):
                        address_value = 0
                    if address_value:
                        hints.add(address_value)
                        known_addresses[row_id] = hex(address_value)
                addresses = resolve_native_team_addresses(
                    team_ids, hints, scan_all_if_unresolved=False,
                    known_addresses=known_addresses,
                )
                unresolved = team_ids.difference(addresses)
                if unresolved:
                    addresses.update(resolve_native_team_addresses(
                        unresolved, hints, scan_all_if_unresolved=True,
                        known_addresses={
                            team_id: known_addresses[team_id]
                            for team_id in unresolved
                            if team_id in known_addresses
                        },
                    ))
                report["missing"] = sorted(team_ids.difference(addresses))
                save_id = str(current.get("save_instance_id") or scope_id)
                with self.lock:
                    self.owned_world_club_addresses = dict(addresses)
                    self.owned_world_club_address_save_id = save_id
            except Exception as error:
                report["errors"].append({"stage": "addresses", "error": str(error)})
                self.native_override_sync_status = report
                return report

        for ownership in acquired:
            team_id = int(ownership.get("id") or 0)
            if team_id <= 0:
                continue
            desired_sugar = ownership.get("sugar_daddy_override")
            vision_overrides = ownership.get("club_vision_overrides")
            saved_facility_floors = ownership.get("facility_level_floors")
            desired_recruitment = (
                saved_facility_floors.get("recruitment")
                if isinstance(saved_facility_floors, dict) else None
            )
            if (
                desired_recruitment is None
                and desired_sugar is None
                and not isinstance(vision_overrides, list)
            ):
                continue
            address = addresses.get(team_id)
            if not address:
                report["missing"].append(team_id)
                continue
            report["checked"] += 1
            try:
                detail = read_native_world_club_snapshot({**ownership, "address": address})
                info = detail.get("club_information") or {}
                if desired_recruitment is not None:
                    desired = int(desired_recruitment)
                    if not 1 <= desired <= 20:
                        raise RuntimeError("已保存的青训招募最低等级无效")
                    live_raw = (info.get("facilities") or {}).get("youth_recruitment")
                    if live_raw is None:
                        raise RuntimeError("当前俱乐部缺少青训招募等级字段")
                    live = int(live_raw)
                    if not 1 <= live <= 20:
                        raise RuntimeError("当前青训招募等级无效")
                    if live < desired:
                        set_native_club_facility_level(
                            team_id, address, "recruitment", desired,
                            expected_level=live,
                        )
                        report["recruitment_repaired"] += 1

                if desired_sugar is not None:
                    desired = int(desired_sugar)
                    if desired not in range(5):
                        raise RuntimeError("已保存的俱乐部资助类型无效")
                    current_finance = info.get("finances") or {}
                    live_raw = current_finance.get("sugar_daddy")
                    if live_raw is None:
                        raise RuntimeError("当前俱乐部财政缺少资助类型字段")
                    live = int(live_raw)
                    if live != desired:
                        with borrow_game_operation(write_memory=True) as operation:
                            update_native_club_sugar_daddy(
                                team_id, address, desired, expected=live,
                                operation=operation,
                            )
                        report["sugar_daddy_repaired"] += 1

                if isinstance(vision_overrides, list):
                    culture = info.get("culture") or []
                    for override in vision_overrides:
                        if not isinstance(override, dict):
                            continue
                        expected = override.get("expected")
                        updates = override.get("updates")
                        if not isinstance(expected, dict) or not isinstance(updates, dict):
                            continue
                        target = self._club_vision_signature(expected)
                        desired = dict(target)
                        for key in ("type", "importance", "source_type"):
                            if key in updates and updates[key] is not None:
                                desired[key] = int(updates[key])
                        if "value" in updates and updates["value"] is not None:
                            desired["value_raw"] = int(updates["value"])
                        match = next(
                            (
                                item for item in culture
                                if isinstance(item, dict)
                                and self._club_vision_signature(item) in (target, desired)
                            ),
                            None,
                        )
                        if not match:
                            report["errors"].append({
                                "stage": "vision", "team_id": team_id,
                                "error": "保存后的董事会目标找不到原记录，已跳过回放",
                            })
                            continue
                        if self._club_vision_signature(match) == target and target != desired:
                            update_club_vision_record(
                                address, team_id, match.get("address"),
                                expected=target, updates=updates,
                            )
                            report["vision_repaired"] += 1
            except Exception as error:
                report["errors"].append({
                    "stage": "native_override", "team_id": team_id,
                    "team_name": str(ownership.get("name") or team_id),
                    "error": str(error),
                })
        self.native_override_sync_status = report
        return report

    def _advance_owned_club_facility_plans(
        self, game_date: str, output: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        """Settle due paid facility plans while the caller owns memory_lock."""
        current = date.fromisoformat(str(game_date or ""))
        snapshot = dict(output if output is not None else self.output)
        snapshot["game_date"] = current.isoformat()
        scope_id = self._data_scope_id(snapshot) if snapshot else ""
        report: dict[str, Any] = {
            "checked": 0, "advanced": 0, "completed": 0, "errors": [],
        }
        if not scope_id:
            return report
        set_active_save_id(scope_id)
        facility_fields = {
            "training": "training",
            "youth": "youth",
            "junior": "junior_coaching",
            "recruitment": "youth_recruitment",
        }
        for ownership in account_acquired_clubs(scope_id, snapshot):
            team_id = int(ownership.get("id") or 0)
            saved_plans = ownership.get("facility_upgrade_plans")
            if team_id <= 0 or not isinstance(saved_plans, dict):
                continue
            for facility, saved_plan in list(saved_plans.items()):
                if facility not in facility_fields or not isinstance(saved_plan, dict):
                    continue
                if str(saved_plan.get("status") or "active") != "active":
                    continue
                report["checked"] += 1
                plan = dict(saved_plan)
                try:
                    start_level = int(plan.get("start_level") or 0)
                    target_level = int(plan.get("target_level") or 0)
                    total_levels = int(plan.get("total_levels") or 0)
                    completed_levels = int(plan.get("completed_levels") or 0)
                    persisted_completed_levels = completed_levels
                    started_on = date.fromisoformat(str(plan.get("started_on") or ""))
                    if (
                        not 1 <= start_level < target_level <= 20
                        or total_levels != target_level - start_level
                        or not 0 <= completed_levels <= total_levels
                    ):
                        raise RuntimeError("已保存的设施升级计划无效")
                    scheduled_levels = min(
                        total_levels,
                        max(0, (current - started_on).days)
                        // OWNED_CLUB_FACILITY_UPGRADE_DAYS,
                    )
                    if scheduled_levels <= completed_levels:
                        continue
                    _scope, _output, club = self._owned_world_club_target(team_id)
                    facilities = read_native_club_facility_levels(
                        team_id, club.get("address"),
                    )
                    live_level = int(facilities.get(facility))
                    if not 1 <= live_level <= 20:
                        raise RuntimeError("当前俱乐部设施等级无效")
                    achieved_levels = min(
                        total_levels, max(0, live_level - start_level),
                    )
                    completed_levels = max(completed_levels, achieved_levels)
                    due_level = min(target_level, start_level + scheduled_levels)

                    if completed_levels > persisted_completed_levels:
                        plans = dict(saved_plans)
                        updated_plan = dict(plan)
                        updated_plan.update({
                            "completed_levels": completed_levels,
                            "last_completed_on": current.isoformat(),
                            "next_due_on": (
                                started_on + timedelta(
                                    days=(completed_levels + 1)
                                    * OWNED_CLUB_FACILITY_UPGRADE_DAYS,
                                )
                            ).isoformat() if completed_levels < total_levels else None,
                        })
                        updated_plan.pop("last_error", None)
                        if completed_levels >= total_levels or live_level >= target_level:
                            plans.pop(facility, None)
                        else:
                            plans[facility] = updated_plan
                        progress_map_updates: dict[str, dict[str, Any]] = {
                            "facility_upgrade_plans": {
                                facility: None if facility not in plans else updated_plan,
                            },
                        }
                        if facility == "recruitment":
                            saved_floors = ownership.get("facility_level_floors")
                            floors = (
                                dict(saved_floors)
                                if isinstance(saved_floors, dict) else {}
                            )
                            floors["recruitment"] = max(
                                int(floors.get("recruitment") or 0), live_level,
                            )
                            progress_map_updates["facility_level_floors"] = {
                                "recruitment": floors["recruitment"],
                            }
                        ownership = update_acquired_club_map_entries(
                            team_id, progress_map_updates, scope_id,
                        )
                        saved_plans = plans
                        plan = updated_plan

                    while live_level < due_level:
                        native_result = upgrade_native_club_facility(
                            team_id, club.get("address"), facility,
                            expected_level=live_level,
                        )
                        before_level = int(native_result["before"])
                        live_level = int(native_result["after"])
                        completed_levels = max(
                            completed_levels,
                            min(total_levels, live_level - start_level),
                        )
                        plans = dict(saved_plans)
                        updated_plan = dict(plan)
                        updated_plan.update({
                            "completed_levels": completed_levels,
                            "last_completed_on": current.isoformat(),
                            "next_due_on": (
                                started_on + timedelta(
                                    days=(completed_levels + 1)
                                    * OWNED_CLUB_FACILITY_UPGRADE_DAYS,
                                )
                            ).isoformat() if completed_levels < total_levels else None,
                        })
                        updated_plan.pop("last_error", None)
                        if completed_levels >= total_levels or live_level >= target_level:
                            plans.pop(facility, None)
                        else:
                            plans[facility] = updated_plan
                        map_updates: dict[str, dict[str, Any]] = {
                            "facility_upgrade_plans": {
                                facility: None if facility not in plans else updated_plan,
                            },
                        }
                        if facility == "recruitment":
                            saved_floors = ownership.get("facility_level_floors")
                            floors = (
                                dict(saved_floors)
                                if isinstance(saved_floors, dict) else {}
                            )
                            floors["recruitment"] = max(
                                int(floors.get("recruitment") or 0), live_level,
                            )
                            map_updates["facility_level_floors"] = {
                                "recruitment": floors["recruitment"],
                            }
                        try:
                            ownership = update_acquired_club_map_entries(
                                team_id, map_updates, scope_id,
                            )
                        except Exception as persistence_error:
                            try:
                                set_native_club_facility_level(
                                    team_id, club.get("address"), facility,
                                    before_level, expected_level=live_level,
                                )
                            except Exception as rollback_error:
                                raise RuntimeError(
                                    "设施升级进度持久化失败，且游戏内存回滚失败"
                                ) from rollback_error
                            raise RuntimeError(
                                "设施升级进度持久化失败，已恢复游戏内存原值"
                            ) from persistence_error
                        saved_plans = plans
                        plan = updated_plan
                        report["advanced"] += 1

                    if live_level >= target_level and facility in saved_plans:
                        plans = dict(saved_plans)
                        plans.pop(facility, None)
                        update_acquired_club_map_entries(
                            team_id, {"facility_upgrade_plans": {facility: None}},
                            scope_id,
                        )
                        saved_plans = plans
                    if live_level >= target_level:
                        report["completed"] += 1
                except Exception as error:
                    report["errors"].append({
                        "team_id": team_id,
                        "team_name": str(ownership.get("name") or team_id),
                        "facility": facility,
                        "error": str(error),
                    })
                    try:
                        plans = dict(saved_plans)
                        failed_plan = dict(plan)
                        failed_plan["last_error"] = str(error)
                        plans[facility] = failed_plan
                        update_acquired_club_map_entries(
                            team_id, {
                                "facility_upgrade_plans": {facility: failed_plan},
                            }, scope_id,
                        )
                        saved_plans = plans
                    except Exception:
                        pass
        return report

    def _apply_unemployed_confirmation_state(
        self, output: dict[str, Any], previous_output: dict[str, Any] | None = None,
    ) -> None:
        """Carry an explicit unemployed confirmation only for the same manager/save."""
        manager_id = int(
            output.get("selected_manager_id")
            or (output.get("manager") or {}).get("id")
            or 0
        )
        if (
            str(output.get("game_layout") or "") not in {"fm24", "fm26"}
            or manager_id <= 0
            or managed_team_rows(output)
        ):
            output.pop("unemployed_confirmed", None)
            output.pop("unemployed_confirmation_required", None)
            output.pop("unemployed_manager_detected", None)
            return
        if not output.get("unemployed_manager_detected"):
            output.pop("unemployed_confirmed", None)
            output.pop("unemployed_confirmation_required", None)
            return

        candidates = [previous_output or {}]
        with self.lock:
            candidates.append(dict(self.output))
        save_id = str(output.get("save_instance_id") or "")
        confirmed = any(
            candidate.get("unemployed_confirmed")
            and int(
                candidate.get("selected_manager_id")
                or (candidate.get("manager") or {}).get("id")
                or 0
            ) == manager_id
            and save_identity_matches(
                save_id, str(candidate.get("save_instance_id") or ""),
            )
            for candidate in candidates
        )
        output["unemployed_manager_detected"] = True
        output["unemployed_confirmed"] = bool(confirmed)
        output["unemployed_confirmation_required"] = not confirmed

    @classmethod
    def _assign_account_scope(
        cls, output: dict[str, Any], previous_output: dict[str, Any] | None = None,
    ) -> str:
        save_id = str(output.get("save_instance_id") or "")
        manager_id = int(
            output.get("selected_manager_id") or (output.get("manager") or {}).get("id") or 0
        )
        previous = previous_output or {}
        output_manual_scope = str(output.get("manual_account_scope_id") or "")
        manual_scope = output_manual_scope or str(previous.get("manual_account_scope_id") or "")
        manual_context = str(
            output.get("manual_account_context_id")
            or (
                save_id if output_manual_scope
                else previous.get("manual_account_context_id")
                or previous.get("save_instance_id")
            )
            or ""
        )
        manual_matches = bool(
            manual_scope and save_id and save_identity_matches(save_id, manual_context)
        )
        manual_account = next((
            item for item in saved_account_scopes()
            if str(item.get("scope_id") or "") == manual_scope
        ), None) if manual_matches else None
        if manual_account is not None:
            output["manual_account_scope_id"] = manual_scope
            output["manual_account_context_id"] = save_id
            output["account_scope_id"] = manual_scope
            display_name = str(manual_account.get("save_name") or "").strip()
            if display_name:
                output["save_name"] = display_name
            return manual_scope
        output.pop("manual_account_scope_id", None)
        output.pop("manual_account_context_id", None)
        same_save = bool(save_id and save_identity_matches(
            save_id, str(previous.get("save_instance_id") or ""),
        ))
        previous_manager_id = int(
            previous.get("account_scope_manager_id")
            or previous.get("selected_manager_id")
            or (previous.get("manager") or {}).get("id")
            or 0
        )
        if same_save and previous_manager_id > 0:
            options = list(output.get("manager_options") or [])
            if not any(int(item.get("id") or 0) == previous_manager_id for item in options):
                previous_option = next((
                    dict(item) for item in (previous.get("manager_options") or [])
                    if int(item.get("id") or 0) == previous_manager_id
                ), None)
                previous_manager = previous.get("manager") or {}
                options.append(previous_option or {
                    "id": previous_manager_id,
                    "name": previous_manager.get("name") or f"经理 {previous_manager_id}",
                    "teams": [
                        {"id": int(team.get("id") or 0), "team_type": team.get("team_type")}
                        for team in (previous.get("managed_teams") or [])
                        if int(team.get("id") or 0) > 0
                    ],
                    "temporarily_unavailable": True,
                })
                output["manager_options"] = options
        preferred_scope = (
            str(previous.get("account_scope_id") or cls._data_scope_id(previous))
            if same_save and (manager_id <= 0 or manager_id == previous_manager_id)
            else None
        )
        effective_manager_id = manager_id or (previous_manager_id if same_save else 0)
        manager = output.get("manager") or {}
        manager_name = str(manager.get("name") or "").strip()
        if not manager_name and effective_manager_id > 0:
            manager_name = str(next((
                item.get("name")
                for item in (output.get("manager_options") or [])
                if int(item.get("id") or 0) == effective_manager_id
            ), "") or "").strip()
        managed_team = output.get("managed_team") or {}
        team_name = str(
            managed_team.get("name") or manager.get("team_name") or ""
        ).strip()
        scope_id = resolve_account_scope(
            save_id, effective_manager_id, preferred_scope=preferred_scope,
            manager_name=manager_name, team_name=team_name,
        ) or save_id
        output["account_scope_id"] = scope_id
        output["account_scope_manager_id"] = effective_manager_id or None
        display_name = (
            account_scope_display_name(scope_id)
            if manager_name and team_name else None
        )
        if display_name:
            output["save_name"] = display_name
        return scope_id

    def _remember_fixture_effect_status(
        self, doping: dict[str, Any], goalkeeper: dict[str, Any],
    ) -> None:
        self.fixture_item_effect_status = {
            "doping": {
                "active": int(doping.get("active") or 0),
                "tracked": int(doping.get("tracked") or 0),
                "maintained": int(doping.get("maintained") or 0),
                "effects": list(doping.get("effects") or []),
                "errors": list(doping.get("errors") or []),
            },
            "goalkeeper_bribe": {
                "active": int(goalkeeper.get("active") or 0),
                "tracked": int(goalkeeper.get("tracked") or 0),
                "maintained": int(goalkeeper.get("maintained") or 0),
                "effects": list(goalkeeper.get("effects") or []),
                "errors": list(goalkeeper.get("errors") or []),
            },
        }

    def _sync_fixture_items_for_clock(self, game_clock: dict[str, Any] | None) -> None:
        """Advance fixture items daily and maintain active memory effects.

        This intentionally does not depend on the much heavier odds refresh.
        Both FM24 and FM26 feed the same lightweight lifecycle, while each
        native effect controller keeps its existing version-specific branch.
        """
        scope_id = self._data_scope_id(self.output)
        game_date = str((game_clock or {}).get("date") or "")
        if not scope_id or not game_date:
            return
        sync_key = (scope_id, game_date)
        now = monotonic()
        if getattr(self, "fixture_item_sync_key", None) == sync_key:
            if now < float(getattr(self, "fixture_effect_maintenance_at", 0.0)):
                return
            self.fixture_effect_maintenance_at = (
                now + FIXTURE_EFFECT_MAINTENANCE_SECONDS
            )
            active_doping = active_doping_items()
            active_goalkeepers = active_goalkeeper_bribes()
            referee_candidate = (
                referee_hook_candidate(game_date) if REFEREE_EFFECT_ENABLED else None
            )
            if (
                not active_doping and not active_goalkeepers and not referee_candidate
                or not self.memory_lock.acquire(blocking=False)
            ):
                return
            try:
                doping_status = (
                    sync_doping_effects(active_doping)
                    if active_doping else {"active": 0, "tracked": 0, "maintained": 0, "effects": [], "errors": []}
                )
                goalkeeper_status = (
                    sync_goalkeeper_bribes(active_goalkeepers)
                    if active_goalkeepers else {"active": 0, "tracked": 0, "maintained": 0, "effects": [], "errors": []}
                )
                if active_goalkeepers:
                    hook_status = self.redbull_hook.sync(
                        active_player_ids(), goalkeeper_status.get("player_ids", []),
                    )
                    if hook_status.get("error"):
                        goalkeeper_status.setdefault("errors", []).append(
                            str(hook_status["error"]),
                        )
                referee_activation = self._sync_referee_fixture_hook(game_date)
                self._remember_fixture_effect_status(doping_status, goalkeeper_status)
            except Exception as error:
                self.fixture_item_sync_error = str(error)
            else:
                maintenance_errors = [
                    str(error)
                    for status in (doping_status, goalkeeper_status)
                    for error in status.get("errors", []) if error
                ]
                if referee_activation.get("state") == "pending":
                    maintenance_errors.append(str(
                        (referee_activation.get("hook") or {}).get("error")
                        or "黑哨 Hook 尚未完成激活"
                    ))
                self.fixture_item_sync_error = (
                    "; ".join(maintenance_errors) if maintenance_errors else None
                )
            finally:
                self.memory_lock.release()
            return
        if (
            getattr(self, "fixture_item_sync_retry_key", None) == sync_key
            and now < float(getattr(self, "fixture_item_sync_retry_at", 0.0))
        ):
            return
        if not self.memory_lock.acquire(blocking=False):
            return
        set_active_save_id(scope_id)
        try:
            reconcile_inventory(
                game_date, self._fixture_index(self.output), activate_referee=False,
            )
            self._sync_opponent_flu_items(game_date)
            doping_status = sync_doping_effects(active_doping_items())
            goalkeeper_status = sync_goalkeeper_bribes(active_goalkeeper_bribes())
            hook_status = self.redbull_hook.sync(
                active_player_ids(), goalkeeper_status.get("player_ids", []),
            )
            if goalkeeper_status.get("player_ids") and hook_status.get("error"):
                goalkeeper_status.setdefault("errors", []).append(str(hook_status["error"]))
            self._remember_fixture_effect_status(doping_status, goalkeeper_status)
            referee_activation = self._sync_referee_fixture_hook(game_date)
            errors = []
            errors.extend(str(error) for error in doping_status.get("errors", []) if error)
            errors.extend(str(error) for error in goalkeeper_status.get("errors", []) if error)
            for status in (
                self.redbull_hook.status(), self.referee_hook.status(),
            ):
                if status.get("error"):
                    errors.append(str(status["error"]))
            if referee_activation.get("state") == "pending" and not (
                (referee_activation.get("hook") or {}).get("error")
            ):
                errors.append("黑哨 Hook 尚未完成激活")
            if errors:
                self.fixture_item_sync_error = "; ".join(errors)
                self.fixture_item_sync_retry_key = sync_key
                self.fixture_item_sync_retry_at = now + FIXTURE_ITEM_SYNC_RETRY_SECONDS
                return
            self.fixture_item_sync_error = None
            self.fixture_item_sync_key = sync_key
            self.fixture_effect_maintenance_at = (
                now + FIXTURE_EFFECT_MAINTENANCE_SECONDS
            )
            self.fixture_item_sync_retry_key = None
            self.fixture_item_sync_retry_at = 0.0
        except Exception as error:
            self.fixture_item_sync_error = str(error)
            self.fixture_item_sync_retry_key = sync_key
            self.fixture_item_sync_retry_at = now + FIXTURE_ITEM_SYNC_RETRY_SECONDS
        finally:
            self.memory_lock.release()

    def _release_training_users_for_club_change(
        self, previous: dict[str, Any], refreshed: dict[str, Any],
    ) -> dict[str, int] | None:
        if not same_account_manager_club_changed(previous, refreshed):
            return None
        result = release_training_users(
            str(refreshed.get("game_date") or ""),
            reason="manager_club_change",
        )
        self.attribute_growth_hook.sync([])
        self.training_sync_key = None
        self.training_sync_status = None
        return result

    def _post_publish_maintenance_worker(
        self, output: dict[str, Any], *, reconcile_owned_customizations: bool,
    ) -> None:
        """Run slow save-bound maintenance without delaying market publication."""
        scope_id = self._data_scope_id(output)
        save_id = str(output.get("save_instance_id") or "")

        def snapshot_is_current() -> bool:
            with self.lock:
                return bool(
                    self.output is output
                    and self._data_scope_id(self.output) == scope_id
                    and str(self.output.get("save_instance_id") or "") == save_id
                )

        if not snapshot_is_current():
            return
        try:
            with self._timed_memory_lock("youth_generation_sync"):
                if not snapshot_is_current():
                    return
                self._sync_youth_generation_plans(scope_id, save_id)
        except Exception as error:
            self.youth_generation_hook.suspend(str(error))
        try:
            with self._timed_memory_lock("owned_facility_plan_sync"):
                if not snapshot_is_current():
                    return
                self._advance_owned_club_facility_plans(
                    str(output.get("game_date") or ""), output,
                )
        except Exception as error:
            with self.lock:
                self.last_operation_error = str(error).strip() or type(error).__name__
                self.last_operation_error_type = type(error).__name__
                self.last_operation_error_stage = "owned_facility_plan"
                self.last_operation_traceback = traceback.format_exc()[-6000:]
        if not reconcile_owned_customizations or not snapshot_is_current():
            return
        self._sync_owned_club_customizations(output, is_current=snapshot_is_current)

    def _sync_owned_club_customizations(
        self, output: dict[str, Any], *, is_current: Any = None,
    ) -> None:
        """Re-verify owned-club names and controller fields on the live save.

        Runs on connect, on account switches and after every club refresh, so a
        takeover that swaps in new controller objects is repaired without
        waiting for the next reconnect.  Never raises: a failure is published
        through ``owned_customization_sync_status`` only.
        """
        try:
            with self._timed_memory_lock("owned_customization_sync"):
                if is_current is not None and not is_current():
                    return
                self._reconcile_owned_club_customizations(output)
                self._reconcile_owned_club_native_overrides(output)
        except Exception as error:
            with self.lock:
                self.owned_customization_sync_status = {
                    "checked": 0,
                    "chairmen_checked": 0,
                    "club_names_repaired": 0,
                    "stadium_names_repaired": 0,
                    "missing": [],
                    "errors": [{"stage": "post_publish", "error": str(error)}],
                }

    def _start_post_publish_maintenance(
        self, output: dict[str, Any], *, reconcile_owned_customizations: bool,
    ) -> None:
        threading.Thread(
            target=self._post_publish_maintenance_worker,
            args=(output,),
            kwargs={
                "reconcile_owned_customizations": reconcile_owned_customizations,
            },
            daemon=True,
        ).start()

    def _schedule_idle_data_prewarm(self, delay: float = 5.0) -> None:
        """Warm club/world projections only after refresh work has settled."""
        with self.lock:
            timer = getattr(self, "club_prewarm_timer", None)
            if timer is not None and timer.is_alive():
                return
            timer = threading.Timer(
                max(0.5, float(delay)), self._run_idle_data_prewarm,
            )
            timer.daemon = True
            self.club_prewarm_timer = timer
            timer.start()

    def _run_idle_data_prewarm(self) -> None:
        with self.lock:
            self.club_prewarm_timer = None
            if (
                not self._has_verified_save()
                or self.refreshing or self.reconciling
                or self.save_change_pending
                or self.club_refreshing or self.world_club_scanning
            ):
                self._schedule_idle_data_prewarm(delay=5.0)
                return
            manager = dict(self.output.get("manager") or {})
            teams = managed_team_rows(self.output)
            profiles = dict(self.club_profiles)
            game_date = str(self.output.get("game_date") or "")
            if not manager.get("id") or not teams:
                self._schedule_world_data_prewarm()
                return
        if not managed_club_profiles_are_current(manager, teams, profiles, game_date):
            if self.refresh_club_async():
                threading.Thread(
                    target=self._wait_for_club_prewarm,
                    daemon=True,
                    name="fmodd-idle-club-prewarm-wait",
                ).start()
            return
        self._schedule_world_data_prewarm()

    def _wait_for_club_prewarm(self) -> None:
        for _ in range(180):
            with self.lock:
                active = bool(self.club_refreshing)
                blocked = bool(
                    self.refreshing or self.reconciling
                    or self.save_change_pending
                )
            if not active:
                if blocked:
                    self._schedule_idle_data_prewarm(delay=5.0)
                else:
                    self._schedule_world_data_prewarm()
                return
            sleep(1)

    def _schedule_world_data_prewarm(self, delay: float = 5.0) -> None:
        with self.lock:
            timer = getattr(self, "world_prewarm_timer", None)
            if timer is not None and timer.is_alive():
                return
            timer = threading.Timer(
                max(0.5, float(delay)), self._run_world_data_prewarm,
            )
            timer.daemon = True
            self.world_prewarm_timer = timer
            timer.start()

    def _run_world_data_prewarm(self) -> None:
        with self.lock:
            self.world_prewarm_timer = None
            if (
                not self._has_verified_save()
                or self.refreshing or self.reconciling
                or self.save_change_pending
                or self.club_refreshing or self.world_club_scanning
            ):
                self._schedule_world_data_prewarm(delay=5.0)
                return
            if getattr(self.memory_lock, "foreground_waiters", 0):
                self._schedule_world_data_prewarm(delay=5.0)
                return
            save_id = str(
                self.output.get("save_instance_id")
                or self._data_scope_id(self.output)
            )
            native = self._world_club_native_cache(save_id)
            if native and native.get("addresses_current"):
                return
        self.start_world_club_scan()

    def _sync_training_focuses(self, game_date: str) -> dict[str, Any]:
        focuses = active_training_focuses(game_date) if game_date else []
        due_focus_ids = {
            str(row.get("id") or "") for row in advance_training_focuses(game_date)
        } if game_date else set()
        if due_focus_ids:
            focuses = active_training_focuses(game_date)
        profiles = list(self.club_profiles.values()) or (
            [self.club_profile] if self.club_profile else []
        )
        managed_teams = [dict(row) for row in (self.output.get("managed_teams") or [])]
        if not managed_teams and self.output.get("managed_team"):
            managed_teams = [dict(self.output["managed_team"])]
        roster_index = TrainingRosterIndex(
            profiles,
            managed_teams,
            read_roster=read_team_roster,
            resolve_player_address=resolve_team_player_address,
            player_manager_candidate=self._player_manager_training_candidate,
            rebind_player=rebind_training_focus_player,
            rebind_staff=rebind_training_focus_staff,
        )
        sync_rows = roster_index.sync_rows(focuses)
        sync_key = (
            str(self.output.get("save_instance_id") or ""), game_date,
            tuple(sync_rows),
        )
        cached_sync_status = getattr(self, "training_sync_status", None)
        due_coaching_focuses = due_coaching_license_focuses(game_date)
        settlement_due = bool(due_focus_ids or due_coaching_focuses) or any(
            focus.get("focus_type") == "preferred_move"
            and str(focus.get("expires_on") or "") <= game_date
            for focus in focuses
        )
        if (
            not settlement_due
            and sync_key == getattr(self, "training_sync_key", None)
            and cached_sync_status is not None
        ):
            return {
                **cached_sync_status,
                "completed_habit_focus_ids": [],
                "completed_attribute_focus_ids": [],
                "advanced_attribute_focus_ids": [],
                "completed_position_focus_ids": [],
                "advanced_position_focus_ids": [],
                "completed_coaching_license_focus_ids": [],
            }
        coaching_errors: list[str] = []
        coaching_pending: list[int] = []
        completed_coaching: list[str] = []
        for focus in due_coaching_focuses:
            focus_id = str(focus.get("id") or "")
            staff_id = int(focus.get("staff_id") or 0)
            resolved_staff = roster_index.resolve_staff(focus)
            if not resolved_staff:
                coaching_pending.append(staff_id)
                continue
            profile, staff = resolved_staff
            team = profile.get("team") or {}
            current_address = roster_index.bind_staff_address(focus, staff)
            try:
                writer = (
                    upgrade_human_manager_coaching_license
                    if focus.get("subject_type") == "player_manager"
                    else upgrade_staff_coaching_license
                )
                result = writer(
                    staff_id, current_address,
                    int(team.get("id") or 0), team.get("address"),
                    int(focus.get("initial_license_code") or 0),
                    int(focus.get("target_license_code") or 0),
                )
                complete_coaching_license_focus(focus_id, game_date, result)
                code = int(result["after"])
                next_code = COACHING_LICENSE_NEXT.get(code)
                staff["coaching_license"] = {
                    "code": code, "name": COACHING_LICENSE_NAMES[code],
                    "next_code": next_code,
                    "next_name": COACHING_LICENSE_NAMES.get(next_code),
                    "maximum": next_code is None,
                }
                if focus.get("subject_type") == "player_manager":
                    output_manager = self.output.get("manager")
                    if isinstance(output_manager, dict):
                        output_manager["coaching_license"] = dict(
                            staff["coaching_license"]
                        )
                completed_coaching.append(focus_id)
            except Exception as error:
                coaching_errors.append(
                    f"{focus.get('staff_name') or staff_id}：{error}"
                )
        if completed_coaching:
            focuses = active_training_focuses(game_date)
        habit_errors: list[str] = []
        habit_pending: list[int] = []
        completed_habits: list[str] = []
        for focus in focuses:
            if focus.get("focus_type") != "preferred_move":
                continue
            try:
                due = date.fromisoformat(game_date) >= date.fromisoformat(str(focus["expires_on"]))
            except (KeyError, TypeError, ValueError):
                habit_errors.append(f"{focus.get('player_name') or focus.get('player_id')}的习惯训练日期无效")
                continue
            if not due:
                continue
            player_id = int(focus.get("player_id") or 0)
            player = roster_index.resolve_player(focus, force_live=True)
            if not player or not player.get("address"):
                habit_pending.append(player_id)
                continue
            try:
                transaction = commit_player_effect(
                    apply_effect=lambda: update_player_preferred_move(
                        player_id, player["address"],
                        int(focus.get("preferred_move_bit", -1)),
                        str(focus.get("operation") or ""),
                    ),
                    persist_effect=lambda result: complete_habit_training_focus(
                        str(focus["id"]), game_date, {
                            key: value for key, value in result.items()
                            if key != "_original_mask"
                        },
                    ),
                    rollback_effect=lambda result: restore_player_preferred_moves(
                        player_id, player["address"], result["_original_mask"],
                    ),
                )
                transaction.native.pop("_original_mask", None)
                completed_habits.append(str(focus["id"]))
            except Exception as error:
                already_applied = bool(getattr(error, "already_satisfied", False))
                if already_applied:
                    complete_habit_training_focus(
                        str(focus["id"]), game_date, {"already_satisfied": True},
                    )
                    completed_habits.append(str(focus["id"]))
                else:
                    habit_errors.append(f"{focus.get('player_name') or player_id}：{error}")
        if completed_habits:
            focuses = active_training_focuses(game_date)

        def resolve_targets(rows: list[dict[str, Any]]) -> tuple[list[dict[str, Any]], list[int]]:
            targets: list[dict[str, Any]] = []
            pending: list[int] = []
            for focus in rows:
                if focus.get("focus_type") not in {"attribute", "position"}:
                    continue
                player_id = int(focus.get("player_id") or 0)
                focus_id = str(focus.get("id") or "")
                player = roster_index.resolve_player(
                    focus, force_live=focus_id in due_focus_ids,
                )
                if not player or not player.get("address"):
                    pending.append(player_id)
                    continue
                address = roster_index.bind_player_address(focus, player)
                targets.append({**focus, "player_address": address})
            return targets, pending

        resolved_targets, pending = resolve_targets(focuses)
        targets = [
            row for row in resolved_targets
            if row.get("focus_type") == "attribute"
        ]
        position_targets = [
            row for row in resolved_targets
            if row.get("focus_type") == "position"
        ]
        pending = list(dict.fromkeys([*pending, *habit_pending]))
        progress_errors: list[str] = []
        completed_attribute_focuses: list[str] = []
        advanced_attribute_focuses: list[str] = []
        if targets:
            try:
                current_attributes = read_player_training_attributes(targets)
            except Exception as error:
                current_attributes = {}
                progress_errors.append(str(error))
            for target in targets:
                focus_id = str(target.get("id") or "")
                player_id = int(target.get("player_id") or 0)
                current = current_attributes.get(focus_id)
                if current is None:
                    if player_id not in pending:
                        pending.append(player_id)
                    continue
                expected = int(target.get("initial_attribute") or 0)
                direction = -1 if int(target.get("direction") or 1) < 0 else 1
                next_attribute = expected + direction
                already_satisfied = (
                    int(current) >= next_attribute if direction > 0
                    else int(current) <= next_attribute
                )
                if already_satisfied:
                    try:
                        settled = complete_attribute_training_focus(
                            focus_id, game_date,
                            {"attribute_after": int(current), "already_satisfied": True},
                        )
                        if settled.get("status") == "completed":
                            completed_attribute_focuses.append(focus_id)
                        else:
                            advanced_attribute_focuses.append(focus_id)
                    except Exception as error:
                        progress_errors.append(
                            f"{target.get('player_name') or player_id}：{error}"
                        )
                    continue
                if focus_id not in due_focus_ids:
                    continue
                if int(current) != expected:
                    try:
                        rebased = rebase_attribute_training_focus(
                            focus_id, game_date, int(current),
                        )
                        target["initial_attribute"] = int(rebased["initial_attribute"])
                        target["required_points"] = int(rebased["required_points"])
                        target["progress_points"] = int(rebased["progress_points"])
                        expected = int(target["initial_attribute"])
                        next_attribute = expected + direction
                    except Exception as error:
                        progress_errors.append(
                            f"{target.get('player_name') or player_id}属性基线重置失败：{error}"
                        )
                        continue
                    if int(target.get("progress_points") or 0) < int(target.get("required_points") or 0):
                        continue
                    continue
                try:
                    hidden_training = target.get("attribute_kind") == "hidden"
                    transaction = commit_player_effect(
                        apply_effect=(
                            (lambda: develop_player_hidden_attribute(
                                player_id, target.get("player_address"),
                                str(target.get("attribute_key") or ""),
                                int(current), direction,
                            ))
                            if hidden_training else
                            (lambda: develop_player(
                                player_id, target.get("player_address"),
                                str(target.get("attribute_key") or ""), int(current),
                                "training", 1,
                                allow_ca_over_pa=bool(target.get("allow_ca_over_pa")),
                            ))
                        ),
                        persist_effect=lambda result: complete_attribute_training_focus(
                            focus_id, game_date, {
                                key: value for key, value in result.items()
                                if not key.startswith("_")
                            },
                        ),
                        rollback_effect=(
                            (lambda result: restore_player_hidden_attribute(
                                player_id, target.get("player_address"),
                                str(target.get("attribute_key") or ""),
                                result["_original_raw"], result["_updated_raw"],
                            ))
                            if hidden_training else
                            (lambda result: restore_player_development(
                                player_id, target.get("player_address"),
                                result["_original_raw"], int(result["_original_ca"]),
                                int(result["_original_pa"]),
                            ))
                        ),
                    )
                    result = transaction.native
                    settled = transaction.persisted
                    result.pop("_original_raw", None)
                    result.pop("_original_ca", None)
                    result.pop("_original_pa", None)
                    result.pop("_updated_raw", None)
                    for profile in profiles:
                        for matching in profile.get("players", []):
                            if int(matching.get("id") or 0) == player_id:
                                if hidden_training:
                                    matching["hidden_attributes"] = result["hidden_attributes"]
                                else:
                                    matching["attributes"] = result["attributes"]
                                    matching["ca"] = result["ca"]
                                    matching["pa"] = result["pa"]
                                if result.get("training_ca") is not None:
                                    matching["training_ca"] = result["training_ca"]
                    if settled.get("status") == "completed":
                        completed_attribute_focuses.append(focus_id)
                    else:
                        advanced_attribute_focuses.append(focus_id)
                except Exception as error:
                    progress_errors.append(
                        f"{target.get('player_name') or player_id}：{error}"
                    )
        completed_position_focuses: list[str] = []
        advanced_position_focuses: list[str] = []
        if position_targets:
            try:
                current_positions = read_player_training_positions(position_targets)
            except Exception as error:
                current_positions = {}
                progress_errors.append(str(error))
            for target in position_targets:
                focus_id = str(target.get("id") or "")
                player_id = int(target.get("player_id") or 0)
                while True:
                    current_raw = current_positions.get(focus_id)
                    if current_raw is None:
                        if player_id not in pending:
                            pending.append(player_id)
                        break
                    current = max(1, int(current_raw))
                    expected = max(1, int(target.get("initial_position") or 1))
                    if current >= expected + 1:
                        target_position = min(
                            20,
                            max(
                                expected + 1,
                                int(target.get("target_position") or 20),
                            ),
                        )
                        # A position focus may only settle the one point it was
                        # scheduled for.  If FM has independently advanced the
                        # player by more than one point, rebase the remaining
                        # focus instead of recording that jump as one training
                        # write.  Reaching the requested target is the sole
                        # exception: the focus can finish without another write.
                        if current > expected + 1 and current < target_position:
                            try:
                                rebased = rebase_position_training_focus(
                                    focus_id, game_date, current,
                                )
                                target["initial_position"] = int(
                                    rebased["initial_position"]
                                )
                            except Exception as error:
                                progress_errors.append(
                                    f"{target.get('player_name') or player_id}位置基线重置失败：{error}"
                                )
                            break
                        try:
                            settled = complete_position_training_focus(
                                focus_id, game_date, {
                                    "position_after": int(current_raw),
                                    "already_satisfied": True,
                                },
                            )
                            if settled.get("status") == "completed":
                                completed_position_focuses.append(focus_id)
                                break
                            target.update({
                                key: settled[key]
                                for key in (
                                    "initial_position", "required_points",
                                    "progress_points",
                                )
                                if key in settled
                            })
                            current_positions[focus_id] = int(current_raw)
                            if int(settled.get("progress_points") or 0) < int(
                                settled.get("required_points") or 0
                            ):
                                advanced_position_focuses.append(focus_id)
                                break
                            continue
                        except Exception as error:
                            progress_errors.append(
                                f"{target.get('player_name') or player_id}：{error}"
                            )
                            break
                    if focus_id not in due_focus_ids:
                        break
                    if current != expected:
                        try:
                            rebased = rebase_position_training_focus(
                                focus_id, game_date, current,
                            )
                            target["initial_position"] = int(
                                rebased["initial_position"]
                            )
                        except Exception as error:
                            progress_errors.append(
                                f"{target.get('player_name') or player_id}位置基线重置失败：{error}"
                            )
                        break
                    try:
                        position_key = str(target.get("position_key") or "")
                        transaction = commit_player_effect(
                            apply_effect=lambda: develop_player_position(
                                player_id, target.get("player_address"),
                                position_key, current,
                            ),
                            persist_effect=lambda result: complete_position_training_focus(
                                focus_id, game_date, {
                                    key: value for key, value in result.items()
                                    if not key.startswith("_")
                                },
                            ),
                            rollback_effect=lambda result: restore_player_position(
                                player_id, target.get("player_address"), position_key,
                                result["_original_raw"], result["_updated_raw"],
                            ),
                        )
                        result = transaction.native
                        settled = transaction.persisted
                        result.pop("_original_raw", None)
                        result.pop("_updated_raw", None)
                        current_positions[focus_id] = int(result["position_after"])
                        for profile in profiles:
                            for matching in profile.get("players", []):
                                if int(matching.get("id") or 0) == player_id:
                                    matching["position_ratings"] = result["position_ratings"]
                                    matching["positions"] = result["positions"]
                                    matching["primary_positions"] = result["primary_positions"]
                        if settled.get("status") == "completed":
                            completed_position_focuses.append(focus_id)
                            break
                        target.update({
                            key: settled[key]
                            for key in (
                                "initial_position", "required_points",
                                "progress_points",
                            )
                            if key in settled
                        })
                        if int(settled.get("progress_points") or 0) < int(
                            settled.get("required_points") or 0
                        ):
                            advanced_position_focuses.append(focus_id)
                            break
                    except Exception as error:
                        progress_errors.append(
                            f"{target.get('player_name') or player_id}：{error}"
                        )
                        break
        status = self.attribute_growth_hook.sync([])
        result = {
            **status, "pending_player_ids": pending,
            "progress_error": "; ".join(progress_errors) or None,
            "habit_errors": habit_errors,
            "coaching_license_errors": coaching_errors,
            "pending_staff_ids": coaching_pending,
            "completed_habit_focus_ids": completed_habits,
            "completed_attribute_focus_ids": completed_attribute_focuses,
            "advanced_attribute_focus_ids": advanced_attribute_focuses,
            "completed_position_focus_ids": completed_position_focuses,
            "advanced_position_focus_ids": advanced_position_focuses,
            "completed_coaching_license_focus_ids": completed_coaching,
        }
        self.training_sync_key = sync_key
        self.training_sync_status = dict(result)
        return result

    @staticmethod
    def _sync_opponent_flu_items(game_date: str) -> None:
        for item in active_flu_items():
            if not OPPONENT_VIRUS_EFFECT_ENABLED:
                resolve_flu_item(
                    str(item["id"]), applied=False,
                    detail="病毒包裹因 FM 伤病对象生命周期尚未安全适配，已退回库存",
                )
                continue
            try:
                result = create_player_injury(
                    int(item.get("player_id") or 0),
                    item.get("player_address"),
                    game_date,
                    team_id=int(item.get("opponent_team_id") or 0),
                    team_address=item.get("opponent_team_address"),
                    injury_name="病毒感染",
                    duration_days=3,
                )
                resolve_flu_item(
                    str(item["id"]), applied=True,
                    detail=f"{result['injury']} · {result['duration_days']}天",
                )
            except Exception as error:
                failure_detail = str(error)
                resolve_flu_item(str(item["id"]), applied=False, detail=failure_detail)
                archive_virus_rejection_mail(item, game_date, failure_detail)

    def _has_verified_save(self) -> bool:
        save_id = str(self.output.get("save_instance_id") or "").strip()
        return bool(
            self.cache_verified
            and save_id
            and save_id.casefold() != "unidentified"
        )

    def _note_betting_match_engine_state(
        self,
        game_clock: dict[str, Any],
        engine_state: dict[str, Any],
        *,
        save_instance_id: str | None = None,
    ) -> dict[str, bool]:
        """Update current-time and confirmed-spectator betting restrictions."""
        game_date = str(game_clock.get("date") or "")
        try:
            game_minutes = int(game_clock["minutes"])
        except (KeyError, TypeError, ValueError):
            game_minutes = -1
        with self.lock:
            fm24_spectator = bool(
                self.cache_verified
                and fm24_spectator_session_from_native_state(
                    self.output, engine_state,
                )
            )
            if fm24_spectator:
                # Keep the native session detector intact and record the
                # product-layer evidence used to classify this FM24 session.
                engine_state["spectator"] = True
                engine_state["spectator_detector"] = (
                    "fm24_game_match_session_viewer_vector"
                )
            spectator = bool(engine_state.get("known") and engine_state.get("spectator"))
            scope_id = str(
                save_instance_id
                if save_instance_id is not None
                else self.output.get("save_instance_id")
                or self.connection_save_id
                or ""
            )
            current_key = (
                (scope_id, game_date, game_minutes)
                if scope_id and game_date and game_minutes >= 0 else None
            )
            locked_key = getattr(self, "match_engine_betting_lock", None)
            if locked_key is not None and locked_key != current_key:
                self.match_engine_betting_lock = None
                locked_key = None
            if current_key is not None:
                locks = getattr(self, "spectator_betting_locks", set())
                self.spectator_betting_locks = {
                    key for key in locks
                    if key[0] == current_key[0]
                }
            if spectator and current_key is not None:
                try:
                    current_date = date.fromisoformat(game_date)
                    for match in self.output.get("matches") or []:
                        fixture_date = date.fromisoformat(str(match["fixture_date"]))
                        kickoff = int(match["kickoff_minutes"])
                        minutes_until = (
                            (fixture_date - current_date).days * 24 * 60
                            + kickoff - game_minutes
                        )
                        if 0 <= minutes_until <= SPECTATOR_BETTING_LOCK_MINUTES:
                            self.spectator_betting_locks.add((
                                str(match["fixture_date"]),
                                int(match["competition_id"]),
                                int((match.get("home") or {}).get("id") or match.get("home_id") or 0),
                                int((match.get("away") or {}).get("id") or match.get("away_id") or 0),
                            ))
                except (KeyError, TypeError, ValueError):
                    pass
            if not engine_state.get("known"):
                self.match_engine_betting_lock = None
                locked_key = None
            elif (
                current_key is not None
                and engine_state.get("active")
            ):
                self.match_engine_betting_lock = current_key
                locked_key = current_key
            return {
                "current_time": bool(engine_state.get("known") and (
                    engine_state.get("active")
                    or (current_key is not None and locked_key == current_key)
                )),
                "spectator_day": bool(
                    spectator
                ),
            }

    def _note_connection_liveness(
        self, game_clock: dict[str, Any] | None, game_available: bool,
        *, probe_busy: bool = False,
    ) -> tuple[dict[str, Any] | None, bool]:
        """Keep a verified connection through isolated process-read failures."""
        valid_clock = bool(game_clock and game_clock.get("date"))
        with self.lock:
            # A readable clock is stronger live-process evidence than the
            # independent process-list probe, which can briefly return empty.
            if valid_clock:
                self.last_connection_clock = dict(game_clock)
                self.connection_liveness_failures = 0
                self.connection_live_confirmed = True
                self.connection_suspended = False
                self.connection_unavailable_since = None
                return dict(game_clock), True
            if self._has_verified_save() and (
                self.refreshing
                or self.reconciling
                or getattr(self, "world_club_scanning", False)
                or probe_busy
            ):
                # Long-running memory scans own or saturate the reader. Do not
                # reinterpret probe contention as a lost FM process.
                return (
                    dict(self.last_connection_clock) if self.last_connection_clock else None,
                    True,
                )
            if game_available:
                # FM can briefly stop exposing a readable clock while it
                # advances dates or changes screens. The process is still the
                # same supported target, so retain the verified connection and
                # let the background readers retry instead of disabling
                # settlement after three UI polls.
                self.connection_liveness_failures = 0
                self.connection_unavailable_since = None
                keep_alive = bool(
                    self.connection_live_confirmed and self.last_connection_clock
                )
                return (
                    dict(self.last_connection_clock) if keep_alive else None,
                    keep_alive,
                )
            if self.connection_requested or self._has_verified_save():
                self.connection_liveness_failures += 1
                now = monotonic()
                if getattr(self, "connection_unavailable_since", None) is None:
                    self.connection_unavailable_since = now
            else:
                now = monotonic()
            unavailable_for = (
                now - float(self.connection_unavailable_since)
                if getattr(self, "connection_unavailable_since", None) is not None
                else 0.0
            )
            keep_alive = bool(
                self.connection_live_confirmed
                and self.last_connection_clock
                and (
                    self.connection_liveness_failures < CONNECTION_LIVENESS_FAILURE_LIMIT
                    or unavailable_for < CONNECTION_LIVENESS_GRACE_SECONDS
                )
            )
            if (
                not game_available
                and self.connection_live_confirmed
                and self.connection_liveness_failures >= CONNECTION_LIVENESS_FAILURE_LIMIT
                and unavailable_for >= CONNECTION_LIVENESS_GRACE_SECONDS
            ):
                self.match_engine_runtime_state = {
                    "active": False, "known": False,
                }
                self.match_engine_betting_lock = None
                self.pending_save_identity = None
                self.save_change_pending = False
                # Preserve all verified save/player/account context.  Memory
                # operations still fail closed while the exact PID is absent,
                # but the UI does not lose player information or force an
                # automatic disconnect because of a temporary FM outage.
                self.status = "游戏进程暂时不可用，已保留存档与玩家信息"
                self.connection_suspended = True
            return (
                dict(self.last_connection_clock) if keep_alive else None,
                keep_alive,
            )

    def _connected_process_available(self, game_versions: dict[str, Any]) -> bool:
        """Keep a verified connection bound to the exact process it opened."""
        with self.lock:
            process_pid = int(getattr(self, "connection_process_pid", 0) or 0)
            game_key = str(getattr(self, "connection_game_key", "") or "")
        available = game_versions.get("available") or []
        if process_pid > 0:
            return fm_process_is_running(process_pid)
        if game_key:
            return any(str(row.get("key") or "") == game_key for row in available)
        return bool(available)

    def _betting_ready(self) -> bool:
        return bool(
            self._has_verified_save()
            and not self.save_change_pending
            and not getattr(self, "manager_context_absence_pending", False)
            and not getattr(self, "pending_manager_club_change", None)
            and not getattr(self, "connection_suspended", False)
            and not self.output.get("save_identity_discovery_deferred")
            and (
                str(self.output.get("game_layout") or "") not in {"fm24", "fm26"}
                or manager_team_context_status(self.output)[0]
            )
        )

    def _assert_betting_ready(self) -> None:
        if self._betting_ready():
            return
        if getattr(self, "manager_context_absence_pending", False):
            raise ValueError("正在确认当前经理的俱乐部任职变化，请稍后再下注")
        if getattr(self, "pending_manager_club_change", None):
            raise ValueError("请先确认检测到的执教俱乐部变化，再继续下注")
        valid_context, context_reason = manager_team_context_status(self.output)
        if context_reason == "managed_team_missing":
            raise ValueError("请先确认当前经理确实处于无业状态，再继续下注")
        if context_reason == "manager_missing":
            raise ValueError("尚未可靠识别当前人类经理，请重新连接存档")
        raise ValueError("当前存档连接尚未满足投注条件，请稍后再试")

    def _refresh_state(self) -> dict[str, Any]:
        return {
            "club_legacy_status": self._club_legacy_refresh().snapshot(
                self._data_scope_id(self.output) if self.output else "",
            ),
            "refreshing": self.refreshing,
            "reconciling": self.reconciling,
            "background_reconcile_ready": bool(
                getattr(self, "reconciling", False)
                and getattr(self, "cache_verified", False)
                and self._has_verified_save()
                and not getattr(self, "save_change_pending", False)
            ),
            "refresh_mode": self.refresh_mode,
            "cache_verified": self.cache_verified,
            "betting_ready": self._betting_ready(),
            "data_version": self.data_version,
            "save_change_pending": self.save_change_pending,
            "manager_club_change_confirmation": (
                self._public_manager_club_change_confirmation()
            ),
            "status": self.status,
            "error": self.error,
            "error_stage": getattr(self, "last_refresh_error_stage", None),
        }

    def _public_manager_club_change_confirmation(self) -> dict[str, Any] | None:
        pending = getattr(self, "pending_manager_club_change", None)
        if not pending:
            return None
        previous = pending.get("previous") or {}
        candidate = pending.get("candidate") or {}

        def clubs(payload: dict[str, Any]) -> list[dict[str, Any]]:
            return [
                {
                    "id": int(team.get("id") or 0),
                    "name": str(team.get("name") or f"俱乐部 {int(team.get('id') or 0)}"),
                }
                for team in managed_team_rows(payload)
                if str(team.get("team_type") or "club") == "club"
                and int(team.get("id") or 0) > 0
            ]

        return {
            "request_id": str(pending.get("request_id") or ""),
            "manager_id": _selected_manager_identity(candidate),
            "manager_name": str(
                (candidate.get("manager") or {}).get("name")
                or (previous.get("manager") or {}).get("name")
                or "当前经理"
            ),
            "previous_clubs": clubs(previous),
            "new_clubs": clubs(candidate),
        }

    def _start_refresh_trace(self, reason: str, mode: str, background: bool) -> None:
        now = perf_counter()
        with self.lock:
            self._refresh_trace_started_at = now
            self._refresh_stage_started_at = 0.0
            self.refresh_trace = {
                "reason": reason,
                "mode": mode,
                "background": bool(background),
                "stages_ms": {},
                "memory_lock_wait_ms": {},
                "memory_lock_held_ms": {},
            }
            self.refresh_progress = {
                "phase": "starting",
                "text": "正在准备刷新盘口",
            }
            self._refresh_progress_updated_at = now

    def _set_refresh_stage(self, stage: str) -> None:
        now = perf_counter()
        with self.lock:
            previous = getattr(self, "refresh_stage", None)
            stage_started_at = float(
                getattr(self, "_refresh_stage_started_at", 0.0) or 0.0
            )
            if previous and stage_started_at:
                trace = getattr(self, "refresh_trace", None)
                if not isinstance(trace, dict):
                    trace = {}
                    self.refresh_trace = trace
                stages = trace.get("stages_ms")
                if not isinstance(stages, dict):
                    stages = {}
                    trace["stages_ms"] = stages
                stages[previous] = round(
                    float(stages.get(previous) or 0)
                    + (now - stage_started_at) * 1000,
                    1,
                )
            self.refresh_stage = stage
            self._refresh_stage_started_at = now
            stage_labels = {
                "settle_before_refresh": "正在确认待结算比赛",
                "generate_odds": "正在读取赛程并生成盘口",
                "validate_snapshot": "正在校验盘口完整性",
                "settle_bets": "正在结算普通注单",
                "championship_markets": "正在生成并结算冠军盘",
                "club_context": "正在读取执教俱乐部资料",
                "effects_and_economy": "正在同步道具和俱乐部经济",
                "persist_snapshot": "正在保存盘口快照",
                "publish_snapshot": "正在发布新盘口",
            }
            self.refresh_progress = {
                "phase": stage,
                "text": stage_labels.get(stage, "正在刷新盘口"),
            }
            self._refresh_progress_updated_at = now

    def _publish_refresh_progress(self, progress: dict[str, Any]) -> None:
        """Publish best-effort live diagnostics without affecting refreshes."""
        now = perf_counter()
        payload = {
            "phase": str(progress.get("phase") or "generate_odds"),
            "text": str(progress.get("text") or "正在读取盘口"),
        }
        for key in ("completed", "total"):
            if progress.get(key) is not None:
                payload[key] = max(0, int(progress[key]))
        with self.lock:
            self.refresh_progress = payload
            self._refresh_progress_updated_at = now

    def _record_refresh_metric(self, group: str, key: str, elapsed_ms: float) -> None:
        with self.lock:
            trace = getattr(self, "refresh_trace", None)
            if not isinstance(trace, dict):
                trace = {}
                self.refresh_trace = trace
            metrics = trace.get(group)
            if not isinstance(metrics, dict):
                metrics = {}
                trace[group] = metrics
            metrics[key] = round(
                float(metrics.get(key) or 0) + float(elapsed_ms), 1,
            )

    @staticmethod
    def _refresh_trace_snapshot(trace: Any) -> dict[str, Any]:
        if not isinstance(trace, dict):
            return {}
        return {
            key: dict(value) if isinstance(value, dict) else value
            for key, value in trace.items()
        }

    @contextmanager
    def _timed_memory_lock(self, phase: str):
        memory_lock = getattr(self, "memory_lock", None)
        if memory_lock is None:
            yield
            return
        waiting_at = perf_counter()
        memory_lock.acquire()
        acquired_at = perf_counter()
        try:
            try:
                self._record_refresh_metric(
                    "memory_lock_wait_ms", phase, (acquired_at - waiting_at) * 1000,
                )
            except Exception:
                pass
            yield
        finally:
            released_at = perf_counter()
            memory_lock.release()
            try:
                self._record_refresh_metric(
                    "memory_lock_held_ms", phase, (released_at - acquired_at) * 1000,
                )
            except Exception:
                pass

    @contextmanager
    def _timed_user_memory_operation(self, operation: str):
        """Measure foreground memory transactions without changing lock semantics."""
        memory_lock = getattr(self, "memory_lock", None)
        started_at = perf_counter()
        acquired_at = started_at
        trace: dict[str, Any] = {"operation": str(operation), "succeeded": False}
        if memory_lock is not None:
            acquire_foreground = getattr(memory_lock, "acquire_foreground", None)
            if callable(acquire_foreground):
                acquire_foreground()
            else:
                memory_lock.acquire()
            acquired_at = perf_counter()
        trace["memory_lock_wait_ms"] = round(
            (acquired_at - started_at) * 1000, 1,
        )
        try:
            yield trace
            trace["succeeded"] = True
        except Exception as error:
            trace["error_type"] = type(error).__name__
            raise
        finally:
            released_at = perf_counter()
            if memory_lock is not None:
                memory_lock.release()
            trace["memory_lock_held_ms"] = round(
                (released_at - acquired_at) * 1000, 1,
            )
            trace["total_ms"] = round((released_at - started_at) * 1000, 1)
            state_lock = getattr(self, "lock", None)
            if state_lock is None:
                self.last_operation_performance = dict(trace)
            else:
                with state_lock:
                    self.last_operation_performance = dict(trace)

    def _run_memory_operation_if_idle(
        self, operation: Any, default: Any = None,
    ) -> Any:
        """Run optional polling work only when no FM transaction owns the lock."""
        memory_lock = getattr(self, "memory_lock", None)
        if memory_lock is None or not memory_lock.acquire(blocking=False):
            return default
        try:
            return operation()
        finally:
            memory_lock.release()

    def _record_background_probe_metric(
        self, name: str, started_at: float,
    ) -> None:
        elapsed_ms = round((perf_counter() - started_at) * 1000, 1)
        with self.lock:
            metrics = getattr(self, "background_probe_metrics", None)
            if not isinstance(metrics, dict):
                metrics = {}
                self.background_probe_metrics = metrics
            metrics[str(name)] = elapsed_ms

    def _invalidate_club_manager_record_cache(self) -> None:
        with self.lock:
            self.club_manager_record_cache_key = None
            self.club_manager_record_cache = {}

    def _invalidate_rebuildable_runtime_caches(self) -> None:
        """Invalidate every process-local cache affected by a full rebuild."""
        invalidate_runtime_cache()
        invalidate_club_profile_cache()
        invalidate_head_coach_search_cache()
        invalidate_world_club_runtime_cache()
        with self.lock:
            self.club_refresh_generation = int(getattr(self, "club_refresh_generation", 0)) + 1
            self.club_manager_record_cache_key = None
            self.club_manager_record_cache = {}
            self.world_club_cache = None
            self.world_club_cache_save_id = None
            self.world_club_directory_cache_key = None
            self.world_club_directory_cache = None
            self.world_club_projection_cache_key = None
            self.world_club_projection_cache = None
            self.owned_world_club_addresses = {}
            self.owned_world_club_address_save_id = None
            self.acquired_status_enforced = set()

    def _request_training_settlement(self, game_date: str) -> None:
        """Queue settlement independently of any open frontend page."""
        if not game_date:
            return
        with self.lock:
            save_id = str(self.output.get("save_instance_id") or "")
            scope_id = self._data_scope_id(self.output) if save_id else ""
            if not save_id or not scope_id:
                return
            self.training_settlement_requested = (
                save_id, scope_id, str(game_date),
            )
            if self.training_settlement_worker_active:
                return
            self.training_settlement_worker_active = True
        threading.Thread(
            target=self._training_settlement_worker, daemon=True,
        ).start()

    def _process_manager_salary_for_date(self, game_date: str) -> dict[str, Any]:
        """Settle salary on a date change without depending on odds refresh."""
        game_date = str(game_date or "").strip()
        with self.lock:
            if not game_date or not self._has_verified_save():
                return {"paid": 0, "amount": 0.0}
            scope_id = self._data_scope_id(self.output)
            gross_weekly = self._total_weekly_salary(self.club_contexts)
        if not scope_id or gross_weekly <= 0:
            return {"paid": 0, "amount": 0.0}
        set_active_save_id(scope_id)
        result = process_salary_payments(game_date, gross_weekly)
        archive_salary_payment_mail(result.get("new_payments", []))
        with self.lock:
            self.salary_last_processed_date = game_date
            if result.get("paid"):
                self.status += (
                    f"，工资存入银行 {configured_money(result['amount'])}"
                )
        return result

    def _process_club_dividends_for_date(self, game_date: str) -> dict[str, Any]:
        """Settle the previous month's owned-club profit on this month's first."""
        current = date.fromisoformat(str(game_date or ""))
        with self.lock:
            if not self._has_verified_save():
                return {"processed": False}
            scope_id = self._data_scope_id(self.output)
        if not scope_id:
            return {"processed": False}
        set_active_save_id(scope_id)
        current_month = current.strftime("%Y-%m")
        if str(load_economy().get("club_dividend_last_settlement_month") or "") == current_month:
            return {"processed": True, "already_settled": True}
        result = self.owned_world_club_metrics()
        return {"processed": True, **result}

    def _process_monthly_club_dividends_if_due(
        self, game_date: str,
    ) -> dict[str, Any]:
        """Settle once for the first valid date observed in each month."""
        game_date = str(game_date or "").strip()
        current_month = game_date[:7]
        if len(current_month) != 7:
            return {"processed": False, "invalid_date": True}
        with self.lock:
            if not self._has_verified_save():
                return {"processed": False}
            scope_id = self._data_scope_id(self.output)
        processed_key = (str(scope_id or ""), current_month)
        if not processed_key[0]:
            return {"processed": False}
        if processed_key == getattr(
            self, "monthly_income_last_processed_key", None,
        ):
            return {"processed": False}
        result = self._process_club_dividends_for_date(game_date)
        if result.get("processed"):
            with self.lock:
                self.monthly_income_last_processed_key = processed_key
                self.monthly_income_last_processed_month = current_month
                self.monthly_income_last_attempted_date = game_date
                # Dividend settlement mutates the bank, statement, mail and
                # forecast state outside a normal odds refresh. Publish that
                # change so the status poll schedules one authoritative state
                # read instead of waiting for the portfolio page to be opened.
                self.data_version = int(getattr(self, "data_version", 0)) + 1
        return result

    def _training_settlement_worker(self) -> None:
        """Wait for the FM transaction lock, then settle the latest due tasks."""
        while True:
            with self.lock:
                requested = self.training_settlement_requested
                self.training_settlement_requested = None
                if requested is None:
                    self.training_settlement_worker_active = False
                    return
            save_id, scope_id, game_date = requested
            refresh_roster = False
            with self.memory_lock:
                with self.lock:
                    current_save_id = str(self.output.get("save_instance_id") or "")
                    current_scope_id = (
                        self._data_scope_id(self.output) if current_save_id else ""
                    )
                    if current_save_id != save_id or current_scope_id != scope_id:
                        continue
                    set_active_save_id(scope_id)
                    try:
                        self.training_sync_status = self._sync_training_focuses(game_date)
                        pending_people = bool(
                            self.training_sync_status.get("pending_player_ids")
                            or self.training_sync_status.get("pending_staff_ids")
                        )
                        retry_key = (save_id, scope_id, game_date)
                        if (
                            pending_people
                            and getattr(
                                self, "training_settlement_roster_retry_key", None,
                            ) != retry_key
                        ):
                            self.training_settlement_roster_retry_key = retry_key
                            refresh_roster = True
                        elif not pending_people:
                            self.training_settlement_roster_retry_key = None
                    except Exception as error:
                        status = dict(
                            self.training_sync_status
                            or self.attribute_growth_hook.status()
                            or {}
                        )
                        status["progress_error"] = str(error)
                        self.training_sync_status = status
            if refresh_roster:
                try:
                    self.refresh_club_async()
                except Exception as error:
                    with self.lock:
                        status = dict(self.training_sync_status or {})
                        status["progress_error"] = str(error)
                        self.training_sync_status = status

    def _finish_refresh_trace(self, succeeded: bool, error: str | None = None) -> None:
        now = perf_counter()
        with self.lock:
            current = getattr(self, "refresh_stage", None)
            stage_started_at = float(
                getattr(self, "_refresh_stage_started_at", 0.0) or 0.0
            )
            trace = getattr(self, "refresh_trace", None)
            if not isinstance(trace, dict):
                trace = {}
                self.refresh_trace = trace
            if current and stage_started_at:
                stages = trace.get("stages_ms")
                if not isinstance(stages, dict):
                    stages = {}
                    trace["stages_ms"] = stages
                stages[current] = round(
                    float(stages.get(current) or 0)
                    + (now - stage_started_at) * 1000,
                    1,
                )
            trace_started_at = float(
                getattr(self, "_refresh_trace_started_at", 0.0) or 0.0
            )
            trace["total_ms"] = round(
                (now - trace_started_at) * 1000, 1,
            ) if trace_started_at else 0.0
            trace["succeeded"] = bool(succeeded)
            trace["error"] = str(error or "")
            self.last_refresh_trace = self._refresh_trace_snapshot(trace)
            self._refresh_stage_started_at = 0.0

    def _state_patch_response(
        self, response: dict[str, Any], patch: dict[str, Any],
        *, scope_id: str | None = None,
    ) -> dict[str, Any]:
        """Attach a save-scoped patch without changing existing response fields."""
        with self.lock:
            if scope_id is None:
                scope_id = (
                    self._data_scope_id(self.output)
                    if self._has_verified_save()
                    else str(self.connection_scope_id or "")
                )
            sync = {
                "data_version": self.data_version,
                "data_scope_id": scope_id,
            }
        return {**response, "state_patch": patch, "state_sync": sync}

    def _economy_patch_response(
        self, response: dict[str, Any], *, transient: tuple[str, ...] = (),
        scope_id: str | None = None,
    ) -> dict[str, Any]:
        economy = {
            key: value for key, value in response.items()
            if key not in {*transient, "state_patch", "state_sync"}
        }
        patch: dict[str, Any] = {"economy": economy}
        if "casino_balance" in economy:
            patch["balance"] = float(economy["casino_balance"])
        return self._state_patch_response(response, patch, scope_id=scope_id)

    def _capture_mutation_context(self) -> MutationContext:
        with self.lock:
            return MutationContext(self._public_state_context_key(), active_account_context())

    def _mutation_patch_response(
        self, response: dict[str, Any], *, origin: MutationContext | None = None,
    ) -> dict[str, Any]:
        """Attach fields already returned by a mutation as a scoped UI patch."""
        if not isinstance(response, dict) or response.get("state_patch") is not None:
            return response
        if origin is not None:
            with self.lock:
                if not origin.matches(self._public_state_context_key(), active_account_context()):
                    return response
        patch = mutation_patch_fields(response)
        if "mail" not in patch and (
            isinstance(response.get("mail"), dict) or isinstance(response.get("notice"), dict)
        ):
            with self.lock:
                game_date = str(
                    (self.last_connection_clock or {}).get("date")
                    or self.output.get("game_date") or ""
                )
            patch["mail"] = list(reversed(
                visible_mail_records(game_date)[-100:]
            ))
        if not patch:
            return response
        with self.lock:
            if origin is not None:
                if not origin.matches(self._public_state_context_key(), active_account_context()):
                    return response
                return self._state_patch_response(response, patch, scope_id=origin.account_binding[0])
            return self._state_patch_response(response, patch)

    def _mark_save_identity_candidate(self, candidate: str, confirmed: bool) -> bool:
        """Start blocking verification only for a confirmed identity change."""
        candidate = str(candidate or "")
        if not candidate or not confirmed:
            return False
        with self.lock:
            if self.refreshing or self.reconciling:
                return False
            self.pending_save_identity = candidate
            self.save_change_pending = True
        started = self.refresh_async("identity_change_full", full=True)
        if started:
            with self.lock:
                self.status = "已确认存档变化，正在验证完整数据..."
            return True
        with self.lock:
            if self.pending_save_identity == candidate:
                self.pending_save_identity = None
                self.save_change_pending = False
        return False

    def _read_save_identity_when_idle(self) -> tuple[bool, str | None]:
        """Never inspect save identity during a refresh or item memory transaction."""
        if not self.memory_lock.acquire(blocking=False):
            return False, None
        try:
            with self.lock:
                preferred_save_id = str(
                    self.output.get("save_instance_id") or ""
                ) or None
                preferred_manager_id = int(
                    self.output.get("selected_manager_id")
                    or (self.output.get("manager") or {}).get("id")
                    or 0
                ) or None
                manager_sessions = [
                    dict(item) for item in self.output.get("manager_options", [])
                    if isinstance(item, dict)
                ]
                known_manager_sessions = (
                    manager_sessions
                    if preferred_manager_id and manager_sessions else None
                )
            identity = read_save_identity(
                preferred_save_id=preferred_save_id,
                preferred_manager_id=preferred_manager_id,
                known_manager_sessions=known_manager_sessions,
            )
            return True, str(identity) if identity else None
        finally:
            self.memory_lock.release()

    def _enforce_referee_debts(self, output: dict[str, Any], game_date: str) -> None:
        if not game_date:
            return
        try:
            current = date.fromisoformat(game_date)
        except ValueError:
            return
        records = load_mail()
        changed = False
        for mail in records:
            if mail.get("type") != "referee_debt" or mail.get("paid") or mail.get("enforced"):
                continue
            try:
                deadline = date.fromisoformat(str(mail.get("deadline") or ""))
            except ValueError:
                continue
            if current <= deadline:
                continue
            mail["enforced"] = True
            mail["enforced_at"] = current.isoformat()
            mail["overdue_outcome"] = "expired_without_further_action"
            mail["message"] = "裁判要求的付款期限已过。"
            changed = True
        if changed:
            save_mail(records)

    def _enforce_referee_integrity_notices(
        self, output: dict[str, Any], game_date: str | None = None,
    ) -> None:
        penalties_disabled = bool(load_settings().get("disable_fa_penalties"))
        records = load_mail()
        game_date = str(game_date or output.get("game_date") or "")
        changed = _repair_integrity_mail_correspondents(records, output)
        for mail in records:
            mail_type = str(mail.get("type") or "")
            if mail_type == "referee_apology":
                if mail.get("refunded") or not _mail_visible_on_game_date(mail, game_date):
                    continue
                try:
                    refund = refund_combined_funds(
                        dict(mail.get("refund_payment") or {}),
                        "referee_apology_refund", mail_id=str(mail.get("id") or ""),
                    )
                except Exception:
                    continue
                mail["refunded"] = True
                mail["refunded_at_game_date"] = game_date
                mail["refund_result"] = refund
                changed = True
                continue
            if penalties_disabled:
                continue
            if mail_type not in {"referee_integrity", "doping_integrity"}:
                continue
            notice = mail.get("notice")
            if isinstance(notice, dict) and notice.pop("fourth_waiver", None) is not None:
                changed = True
            for field in ("waiver_amount", "waiver_deadline"):
                if mail.pop(field, None) is not None:
                    changed = True
            if mail.get("penalty_applied"):
                continue
            if not _mail_visible_on_game_date(mail, game_date):
                continue
            penalty_kind = str(mail.get("penalty_kind") or "")
            waiver = dict(notice.get("penalty_waiver") or {}) if isinstance(notice, dict) else {}
            if mail.get("penalty_waived") or waiver.get("paid"):
                continue
            if penalty_kind in {"direct_referee_investigation", "doping_investigation"}:
                deadline = str(waiver.get("deadline_game_date") or "")
                if not deadline or game_date <= deadline:
                    continue
                if isinstance(notice, dict) and isinstance(notice.get("penalty_waiver"), dict):
                    notice["penalty_waiver"]["available"] = False
                if penalty_kind == "doping_investigation":
                    mail["penalty_applied"] = True
                    mail["penalty_applied_game_date"] = game_date
                    mail["suspension_pending"] = True
                    mail["suspension_implemented"] = False
                    if isinstance(notice, dict):
                        notice["penalty_applied"] = True
                        notice["suspension_implemented"] = False
                    changed = True
                    continue
            if penalty_kind in {"direct_referee_investigation", "paid_referee_leak"}:
                points_delta = int(mail.get("penalty_points") or 0)
                reputation_delta = int(mail.get("penalty_reputation") or 0)
                points_applied = False
                reputation_result = None
                if reputation_delta and not mail.get("penalty_reputation_effect_applied"):
                    try:
                        reputation_result = apply_team_reputation_delta(
                            int(mail.get("team_id") or 0), mail.get("team_address"),
                            reputation_delta,
                        )
                        mail["penalty_reputation_effect_applied"] = True
                        mail["penalty_reputation_applied"] = int(
                            reputation_result.get("applied") or 0
                        )
                        save_mail(records)
                    except Exception:
                        if reputation_result and int(reputation_result.get("applied") or 0):
                            try:
                                apply_team_reputation_delta(
                                    int(mail.get("team_id") or 0), mail.get("team_address"),
                                    -int(reputation_result["applied"]),
                                )
                            except Exception:
                                pass
                        mail.pop("penalty_reputation_effect_applied", None)
                        mail.pop("penalty_reputation_applied", None)
                        continue
                try:
                    if points_delta and mail.get("competition_kind") == "league":
                        add_points_adjustment(output, {
                            "competition_id": int(mail.get("competition_id") or 0),
                            "team_id": int(mail.get("team_id") or 0),
                            "delta": points_delta,
                            "reason": "足协收买裁判处罚",
                            "source_id": f"referee_integrity:{mail.get('id')}:league_points",
                            "legacy_source_created_after": str(mail.get("created_at") or ""),
                            "legacy_source_game_date": str(
                                mail.get("available_after_game_date") or mail.get("game_date") or ""
                            ),
                        })
                        points_applied = True
                except Exception:
                    continue
                mail["penalty_applied"] = True
                mail["penalty_applied_game_date"] = game_date
                mail["penalty_points_applied"] = points_delta if points_applied else 0
                mail.setdefault("penalty_reputation_applied", 0)
                if isinstance(notice, dict):
                    notice["penalty_applied"] = True
                changed = True
                continue

            # Preserve enforcement for formal notices created by older versions.
            reputation_result = None
            fine_result = None
            try:
                fine_result = collect_match_integrity_penalty(
                    0.0, float(mail.get("amount") or 0),
                )
                reputation_result = apply_team_reputation_delta(
                    int(mail.get("team_id") or 0), mail.get("team_address"), -50,
                )
                if mail.get("competition_kind") == "league":
                    add_points_adjustment(output, {
                        "competition_id": int(mail.get("competition_id") or 0),
                        "team_id": int(mail.get("team_id") or 0),
                        "delta": -3, "reason": "足协收买裁判处罚",
                        "source_id": f"referee_integrity:{mail.get('id')}:league_points",
                        "legacy_source_created_after": str(mail.get("created_at") or ""),
                        "legacy_source_game_date": str(
                            mail.get("available_after_game_date") or mail.get("game_date") or ""
                        ),
                    })
            except Exception:
                if fine_result and float(fine_result.get("total_deducted") or 0) > 0:
                    try:
                        refund_combined_funds(
                            {"bank": fine_result.get("bank_used"), "wallet": fine_result.get("wallet_used")},
                            "referee_integrity_penalty_rollback", mail_id=str(mail.get("id") or ""),
                        )
                    except Exception:
                        pass
                if reputation_result and int(reputation_result.get("applied") or 0):
                    try:
                        apply_team_reputation_delta(int(mail.get("team_id") or 0), mail.get("team_address"), 50)
                    except Exception:
                        pass
                continue
            mail["penalty_applied"] = True
            mail["penalty_fine_requested"] = float(fine_result.get("standard_fine") or mail.get("amount") or 0)
            mail["penalty_fine_actual"] = float(fine_result.get("actual_fine") or 0)
            mail["penalty_reputation"] = -50
            mail["penalty_points"] = -3 if mail.get("competition_kind") == "league" else 0
            if isinstance(mail.get("notice"), dict):
                mail["notice"]["penalty_applied"] = True
            changed = True
        if changed:
            save_mail(records)

    def _public_state_context_key(self) -> tuple:
        """Fingerprint bound identity without resolving accounts or reading FM.

        Capture the output reference once; resolving `_data_scope_id` here
        would perform registry work on the snapshot-reuse fast path.
        """
        output = getattr(self, "output", None)
        current = output or {}
        manager = current.get("manager") or {}
        return (
            int(getattr(self, "data_version", 0)), id(output),
            tuple(current.get(field) for field in (
                "save_instance_id", "account_scope_id", "account_scope_manager_id",
                "selected_manager_id", "manual_account_scope_id",
                "manual_account_context_id", "game_layout",
            )),
            manager.get("id"),
            tuple((team.get("id"), team.get("team_type"), team.get("club_id"))
                  for team in managed_team_rows(current)),
            tuple(getattr(self, field, None) for field in (
                "connection_scope_id", "connection_save_id", "connection_process_pid",
                "connection_game_key", "connection_live_confirmed", "wallet_ready",
                "connection_requested", "connection_suspended",
                "save_change_pending", "cache_verified",
            )),
        )

    def public_state(self) -> dict[str, Any]:
        """Return a context-bound, short-lived snapshot for concurrent readers."""
        publisher = self.__dict__.get("_public_state_publisher")
        if publisher is None:
            # Also support isolated __new__ fixtures without invoking startup.
            publisher = self.__dict__.setdefault(
                "_public_state_publisher", CoalescedStatePublisher(),
            )
        return publisher.read(self._public_state_context_key, self._capture_public_state)

    def _build_public_state(self) -> dict[str, Any]:
        """Compatibility entry for callers needing an uncached public payload."""
        return self._capture_public_state().payload

    def _capture_public_state(self) -> PublicationCandidate:
        state_started_at = perf_counter()
        state_steps: dict[str, float] = {}
        step_started_at = state_started_at

        def record_step(name: str) -> None:
            nonlocal step_started_at
            now = perf_counter()
            state_steps[name] = round((now - step_started_at) * 1000, 1)
            step_started_at = now

        with self.lock:
            has_verified_save = self._has_verified_save()
            current_game_clock = (
                dict(self.last_connection_clock)
                if getattr(self, "last_connection_clock", None) else None
            )
            cached_versions = getattr(self, "last_process_selection_status", None)
            if (
                current_game_clock
                and getattr(self, "connection_live_confirmed", False)
                and (cached_versions or {}).get("available")
            ):
                game_versions = cached_versions or {"available": [], "selected": None}
                game_available = True
            else:
                game_versions = process_selection_status()
                self.last_process_selection_status = dict(game_versions)
                game_available = self._connected_process_available(game_versions)
            record_step("process_and_liveness")
            game_clock, connection_alive = self._note_connection_liveness(
                current_game_clock, game_available,
            )
            has_verified_save = self._has_verified_save()
            connection_scope_id = str(self.connection_scope_id or "")
            connection_wallet_ready = bool(
                self.wallet_ready and connection_scope_id and connection_alive
            )
            account_ready = bool(has_verified_save or connection_wallet_ready)
            settings = load_settings()
            championship_enabled = bool(
                settings.get("championship_enabled", True)
            )
            league_standings = None
            championship_markets = None
            if has_verified_save:
                scope_id = self._data_scope_id(self.output)
                set_active_save_id(scope_id)
                league_standings = public_league_standings(self.output)
                if championship_enabled:
                    championship_markets = published_championship_markets(self.output)
            elif connection_wallet_ready:
                set_active_save_id(connection_scope_id)
            record_step("standings_and_settings")
            manager_context_ready = bool(
                str(self.output.get("game_layout") or "") not in {"fm24", "fm26"}
                or manager_team_context_status(self.output)[0]
            )
            retained_connection = bool(
                has_verified_save
                and getattr(self, "connection_requested", False)
            )
            save_connected = bool(
                has_verified_save and manager_context_ready
                and (connection_alive or retained_connection)
            )
            connecting = bool(
                getattr(self, "connection_requested", False)
                and self.refreshing
                and not has_verified_save
            )
            # Keep this endpoint read-oriented. Memory writes and maintenance
            # are queued after the snapshot has been published.
            economy = (
                public_economy()
                if connection_wallet_ready and not has_verified_save else None
            )
            game_date = str((game_clock or {}).get("date") or self.output.get("game_date") or "")
            training_ground = (
                public_training_ground(game_date) if account_ready else None
            )
            record_step("training_ground")
            club_policies = None
            if has_verified_save:
                policy_context = self._club_policy_context()
                club_policies = public_club_policies(
                    game_date,
                    manager_id=policy_context["manager_id"],
                    team_id=policy_context["team_id"],
                    club_id=policy_context["club_id"],
                )
                club_policies["hook"] = self.club_policy_hooks.status()
            record_step("club_policies")
            training_growth_status = None
            if has_verified_save:
                training_growth_status = dict(
                    self.training_sync_status
                    or self.attribute_growth_hook.status()
                    or {}
                )
                if any(
                    row.get("status") == "active"
                    and row.get("focus_type") in {"attribute", "position"}
                    and int(row.get("required_points") or 0) > 0
                    and int(row.get("progress_points") or 0)
                    >= int(row.get("required_points") or 0)
                    for row in training_ground.get("focuses", [])
                ):
                    self._request_training_settlement(game_date)
            managed_teams = managed_team_rows(self.output)
            favorites = _public_favorites(
                account_ready=account_ready,
                default_team_ids=(
                    [team.get("id") for team in managed_teams]
                    if has_verified_save else None
                ),
            )
            record_step("favorites")
            if training_ground is not None:
                training_ground["club_policies"] = club_policies
                training_ground["growth_hook"] = training_growth_status
                training_ground["player_manager"] = (
                    self._player_manager_training_candidate()
                    if has_verified_save else None
                )
                try:
                    training_ground["preferred_moves"] = preferred_move_catalog_for_current_game()
                    training_ground["preferred_moves_error"] = None
                except Exception as error:
                    training_ground["preferred_moves"] = []
                    training_ground["preferred_moves_error"] = str(error)
            record_step("training_projection")
            fa_disabled = bool(settings.get("disable_fa_penalties"))
            integrity_status = (
                public_integrity_status(self.output)
                if has_verified_save and not fa_disabled else None
            )
            if integrity_status:
                integrity_status.pop("_mail_notices", None)
            record_step("integrity")
            if has_verified_save:
                economy = self._public_club_economy(
                    game_date, read_memory=False,
                )
            record_step("economy")
            mail_records = (
                visible_mail_records(str((game_clock or {}).get("date") or self.output.get("game_date") or ""))
                if has_verified_save else []
            )
            record_step("mail")
            market_source = dict(self.output)
            if "matches" in self.output:
                market_source["matches"] = [
                    dict(match) for match in self.output.get("matches", [])
                ]
            current_intelligence_candidates = current_match_intelligence_candidates(
                [
                    dict(item)
                    for item in getattr(self, "match_intelligence_results", [])
                ],
                market_source.get("matches", []),
                game_date,
                (game_clock or {}).get("minutes"),
            )
            welfare = (
                welfare_status(
                    match_intelligence_candidates=current_intelligence_candidates,
                )
                if has_verified_save else None
            )
            record_step("welfare")
            intelligence_notice = {
                "available": False,
                "candidate_count": 0,
            }
            if has_verified_save:
                intelligence = dict(
                    (welfare or {}).pop("_match_intelligence", {}) or {}
                )
                self.match_intelligence_public_cache = deepcopy(intelligence)
                self.match_intelligence_public_cache_scope_id = str(
                    self._data_scope_id(self.output) or ""
                )
                current_candidates = purchasable_match_intelligence_candidates(
                    intelligence
                )
                intelligence_notice = {
                    "available": bool(current_candidates),
                    "candidate_count": len(current_candidates),
                }
            if welfare is not None:
                welfare["club_policies"] = club_policies
            connection_error = str(self.error or "")
            if connecting:
                connection_message_code = "connecting"
            elif save_connected and connection_alive:
                connection_message_code = "connected"
            elif save_connected:
                connection_message_code = "retained"
            elif connection_error:
                if "尚未定位当前经理的执教球队" in connection_error:
                    connection_message_code = "managed_team_missing"
                elif "尚未定位当前人类经理对象" in connection_error:
                    connection_message_code = "manager_missing"
                else:
                    connection_message_code = "read_failed"
            elif game_available:
                connection_message_code = "game_detected"
            else:
                connection_message_code = "offline"
            payload = {
                "data_scope_id": (
                    self._data_scope_id(self.output) if has_verified_save
                    else connection_scope_id if connection_wallet_ready else ""
                ),
                "manual_account_scope_id": str(self.output.get("manual_account_scope_id") or ""),
                "saved_accounts": saved_account_scopes(),
                "output": None,
                "game_clock": game_clock,
                "balance": float((economy or {}).get("casino_balance") or 0.0),
                "economy": economy,
                "training_ground": training_ground,
                "welfare": welfare,
                "club_status": {
                    "ready": bool(self.club_profiles or self.club_profile),
                    "refreshing": self.club_refreshing or getattr(
                        self, "club_refresh_pending", False,
                    ),
                    "last_updated": self.club_last_updated,
                    "error": self.club_error,
                    "progress": self.club_progress,
                    "progress_text": self.club_progress_text,
                },
                "redbull_hook": self.redbull_hook.status(),
                "fixture_item_effects": dict(self.fixture_item_effect_status),
                "referee_hook": self.referee_hook.status(),
                "nuclear_effects": self._nuclear_status(),
                "bets": public_bet_history() if has_verified_save else [],
                "mail": list(reversed(mail_records[-100:])),
                "favorite_team_ids": favorites["team_ids"],
                "favorite_competition_ids": favorites["competition_ids"],
                "hidden_competitions": favorites["hidden_competitions"],
                "favorite_market_keys": favorites["market_keys"],
                "favorite_market_keys_initialized": favorites["market_keys_initialized"],
                "favorite_team_defaults_initialized": favorites["managed_defaults_initialized"],
                "match_integrity": integrity_status,
                "match_intelligence_notice": intelligence_notice,
                "league_standings": league_standings,
                "championship_markets": championship_markets,
                **self._refresh_state(),
                "result_refresh_date": self.last_result_refresh_date,
                "result_search_wait_days": RESULT_SEARCH_WAIT_DAYS,
                "live_settlement": dict(self.live_settlement_status),
                "last_background_settled": self.last_background_settled,
                "settings": settings,
                "game_versions": game_versions,
                "connection": {
                    "status": (
                        "connecting" if connecting else
                        "connected" if save_connected else
                        "game_running" if game_available else
                        "offline"
                    ),
                    "connected": save_connected,
                    "live": bool(connection_alive),
                    "retained": bool(save_connected and not connection_alive),
                    "wallet_ready": connection_wallet_ready or save_connected,
                    "game_available": game_available,
                    "message_code": connection_message_code,
                    "message": (
                        self.status if connecting else
                        "已连接当前存档" if save_connected and connection_alive else
                        "游戏暂时不可用，已保留存档与玩家信息" if save_connected else
                        self.error if self.error else
                        "已检测到游戏，请进入存档后连接" if game_available else
                        "请先启动 Football Manager"
                    ),
                },
                "app_version": APP_VERSION,
            }
            record_step("payload")
            publication_key = self._public_state_context_key()
        lock_released_at = perf_counter()
        market_started_at = perf_counter()
        public_output = market_output(market_source, game_clock)
        if isinstance(public_output, dict):
            season_results = public_output.pop("season_results", None) or []
            public_output["season_result_count"] = len(season_results)
        payload["output"] = public_output
        completed_at = perf_counter()
        state_metrics = {
            **state_steps,
            "locked_ms": round((lock_released_at - state_started_at) * 1000, 1),
            "market_output_ms": round((completed_at - market_started_at) * 1000, 1),
            "total_ms": round((completed_at - state_started_at) * 1000, 1),
        }
        with self.lock:
            self.last_public_state_metrics = state_metrics
            self.last_public_state_ms = state_metrics["total_ms"]
        return PublicationCandidate(publication_key, payload)

    def public_results(self) -> dict[str, Any]:
        """Return historical results only when the results UI needs them."""
        with self.lock:
            return {
                "data_version": int(self.data_version),
                "data_scope_id": (
                    self._data_scope_id(self.output)
                    if self._has_verified_save() else ""
                ),
                "season_results": deepcopy(self.output.get("season_results") or []),
            }

    def public_team_results(self, team_id: int, limit: int = 10) -> dict[str, Any]:
        """Return a team's latest completed matches from the full retained history."""
        team_id = int(team_id)
        limit = max(1, min(int(limit), 50))
        with self.lock:
            state_version = int(self.data_version)
            connection_clock = getattr(self, "last_connection_clock", None) or {}
            current_game_date = str(
                connection_clock.get("date") or self.output.get("game_date") or ""
            ).strip()[:10]
            save_id = str(self.output.get("save_instance_id") or "") or None
            cache_key = (save_id or "", state_version, current_game_date)
            if getattr(self, "team_results_cache_key", None) != cache_key:
                self.team_results_cache_key = cache_key
                self.team_results_cache = {}
            cached_rows = getattr(self, "team_results_cache", {}).get(team_id)
            if cached_rows is not None:
                return {
                    "data_version": state_version,
                    "team_results": deepcopy(cached_rows[:limit]),
                }
            current_rows = deepcopy(self.output.get("season_results") or [])

        # Result history may be a large compressed career ledger. Keep disk I/O,
        # decompression, and filtering outside the shared state lock.
        history = read_result_history(save_id) if save_id else []

        rows: dict[tuple[str, int, int, int], dict[str, Any]] = {}
        for item in [*history, *current_rows]:
            if not isinstance(item, dict):
                continue
            home = item.get("home") or item.get("home_team") or {}
            away = item.get("away") or item.get("away_team") or {}
            if not isinstance(home, dict) or not isinstance(away, dict):
                continue
            try:
                home_id = int(home.get("id") or item.get("home_team_id"))
                away_id = int(away.get("id") or item.get("away_team_id"))
                competition = item.get("competition") or {}
                competition_id = int(item.get("competition_id") or competition.get("id"))
                date_text = str(item.get("date") or "").strip()
                if not date_text or team_id not in {home_id, away_id}:
                    continue
                if current_game_date and date_text[:10] == current_game_date:
                    continue
                key = (date_text, competition_id, home_id, away_id)
                row = {
                    "date": date_text,
                    "competition_id": competition_id,
                    "competition_name": str(
                        item.get("competition_name")
                        or competition.get("short_name")
                        or competition.get("name")
                        or competition_id
                    ),
                    "competition_kind": str(item.get("competition_kind") or "cup"),
                    "home": dict(home),
                    "away": dict(away),
                    "home_goals": int(item.get("home_goals", 0)),
                    "away_goals": int(item.get("away_goals", 0)),
                }
                for field in (
                    "half_home_goals", "half_away_goals", "first_scoring_team",
                    "after_extra_time_home_goals", "after_extra_time_away_goals",
                    "penalty_shootout_home_goals", "penalty_shootout_away_goals",
                    "home_outcome_code", "away_outcome_code", "winner_side",
                    "decided_by", "advanced_side", "advanced_team", "advanced_team_id",
                ):
                    if item.get(field) is not None:
                        row[field] = item[field]
                if isinstance(item.get("goal_events"), list):
                    row["goal_events"] = deepcopy(item["goal_events"])
                rows[key] = row
            except (TypeError, ValueError):
                continue
        ordered = sorted(
            rows.values(),
            key=lambda item: (item["date"], item["competition_name"]),
            reverse=True,
        )[:50]
        with self.lock:
            live_clock = getattr(self, "last_connection_clock", None) or {}
            live_date = str(
                live_clock.get("date") or self.output.get("game_date") or ""
            ).strip()[:10]
            live_key = (
                str(self.output.get("save_instance_id") or ""),
                int(self.data_version),
                live_date,
            )
            if live_key == cache_key:
                if getattr(self, "team_results_cache_key", None) != cache_key:
                    self.team_results_cache_key = cache_key
                    self.team_results_cache = {}
                cache = getattr(self, "team_results_cache", {})
                if team_id not in cache and len(cache) >= 128:
                    cache.pop(next(iter(cache)))
                cache[team_id] = deepcopy(ordered)
                self.team_results_cache = cache
        return {
            "data_version": state_version,
            "team_results": ordered[:limit],
        }

    def select_saved_account(self, payload: dict[str, Any]) -> dict[str, Any]:
        requested = str(payload.get("scope_id") or "").strip()
        with self.lock:
            if self.refreshing or self.reconciling:
                raise ValueError("当前正在刷新，请完成后再切换账户")
            accounts = saved_account_scopes()
            if not self.output.get("save_instance_id"):
                raise ValueError("尚未识别当前存档")
            if not requested:
                self.output.pop("manual_account_scope_id", None)
                self.output.pop("manual_account_context_id", None)
                self.output.pop("account_scope_id", None)
                self.output.pop("account_scope_manager_id", None)
                scope_id = self._assign_account_scope(self.output)
            else:
                account = next((
                    item for item in accounts
                    if str(item.get("scope_id") or "") == requested
                ), None)
                if account is None:
                    raise ValueError("所选存档账户已不存在")
                scope_id = requested
                self.output["manual_account_scope_id"] = scope_id
                self.output["manual_account_context_id"] = str(
                    self.output.get("save_instance_id") or ""
                )
                self.output["account_scope_id"] = scope_id
                self.output["account_scope_manager_id"] = account.get("manager_id")
                if account.get("save_name"):
                    self.output["save_name"] = str(account["save_name"])
            remember_active_save_id(scope_id)
            self.fixture_item_sync_key = None
            self.fixture_effect_maintenance_at = 0.0
            self.fixture_item_effect_status = {
                "doping": {"active": 0, "effects": [], "errors": []},
                "goalkeeper_bribe": {"active": 0, "effects": [], "errors": []},
            }
            save_id = str(self.output.get("save_instance_id") or "")
        with self.memory_lock:
            self._sync_youth_generation_plans(scope_id, save_id)
            self._sync_owned_club_board_hook(self.output)
            self._reconcile_owned_club_customizations(self.output)
            self._reconcile_owned_club_native_overrides(self.output)
        return {
            "data_scope_id": scope_id,
            "manual_account_scope_id": str(self.output.get("manual_account_scope_id") or ""),
        }

    def merge_same_manager_accounts(self, payload: dict[str, Any]) -> dict[str, Any]:
        """Union all visible accounts for the current manager into a new account."""
        if str(payload.get("confirm") or "") != "merge_same_manager_accounts":
            raise ValueError("请确认后再合并同ID账户")
        with self.lock:
            if self.refreshing or self.reconciling or self.club_refreshing or self._club_legacy_refresh().busy():
                raise ValueError("当前正在刷新，请完成后再合并账户")
            career_id = str(self.output.get("save_instance_id") or "").strip()
            manager = self.output.get("manager") or {}
            manager_id = int(
                self.output.get("selected_manager_id") or manager.get("id") or 0
            )
            namespace = str(self.output.get("game_layout") or "").strip().lower()
            if not career_id or manager_id <= 0 or namespace not in {"fm24", "fm26"}:
                raise ValueError("请先连接到已识别经理的当前游戏存档")
            accounts = [
                item for item in saved_account_scopes()
                if int(item.get("manager_id") or 0) == manager_id
                and str(item.get("namespace") or "").strip().lower() == namespace
            ]
            source_ids = [str(item.get("scope_id") or "") for item in accounts if item.get("scope_id")]
            if len(source_ids) < 2:
                raise ValueError("当前代际没有两个可合并的同经理账户")
            manager_name = str(manager.get("name") or "").strip()
            team = self.output.get("managed_team") or {}
            team_name = str(team.get("name") or manager.get("team_name") or "").strip()
            merge = create_merged_account(
                career_id, manager_id, source_ids,
                manager_name=manager_name, team_name=team_name,
            )
            try:
                merge_account_containers(source_ids, str(merge["account_id"]))
            except Exception:
                rollback_merged_account(career_id, manager_id, merge)
                raise
            target = str(merge["account_id"])
            self.output["manual_account_scope_id"] = target
            self.output["manual_account_context_id"] = career_id
            self.output["account_scope_id"] = target
            self.output["account_scope_manager_id"] = manager_id
            display_name = account_scope_display_name(target)
            if display_name:
                self.output["save_name"] = display_name
            remember_active_save_id(target)
            self.fixture_item_sync_key = None
            self.fixture_effect_maintenance_at = 0.0
            self.fixture_item_effect_status = {
                "doping": {"active": 0, "effects": [], "errors": []},
                "goalkeeper_bribe": {"active": 0, "effects": [], "errors": []},
            }
            response = {
                "data_scope_id": target,
                "manual_account_scope_id": target,
                "merged_account_count": len(source_ids),
                "source_account_ids": source_ids,
                "cache_rebuild_required": True,
            }
            current_output = dict(self.output)
        with self.memory_lock:
            self._sync_youth_generation_plans(target, career_id)
            self._sync_owned_club_board_hook(current_output)
            self._reconcile_owned_club_customizations(current_output)
            self._reconcile_owned_club_native_overrides(current_output)
        return response

    def switch_game_version(self, payload: dict[str, Any]) -> dict[str, Any]:
        key = str(payload.get("key") or "")
        with self.memory_lock:
            with self.lock:
                if self.refreshing or self.reconciling or self.club_refreshing or self._club_legacy_refresh().busy():
                    raise ValueError("当前正在刷新，请稍候再切换游戏版本")
                scope_id = self._bind_request_scope()
            if scope_id:
                restore_all_doping_effects()
                restore_all_goalkeeper_bribes()
            self.redbull_hook.close()
            self.referee_hook.close()
            self.ca_growth_hook.close()
            self.attribute_growth_hook.close()
            self.team_nuclear_hooks.close()
            self.club_policy_hooks.close()
            self.board_listens_hook.close()
            self._close_youth_generation_hook()
            self.simple_effects.close()
            status = select_game_layout(key)
            set_preferred_game_version(key)
            set_active_save_id(None)
            with self.lock:
                self.output = {}
                self.output_path = None
                self.cache_verified = False
                self.data_version += 1
                self.club_context = None
                self.club_profile = None
                self.club_contexts = {}
                self.club_profiles = {}
                self.club_last_updated = None
                self.club_error = None
                self.fixture_item_sync_key = None
                self.fixture_item_sync_error = None
                self.fixture_item_sync_retry_key = None
                self.fixture_item_sync_retry_at = 0.0
                self.fixture_effect_maintenance_at = 0.0
                self.fixture_item_effect_status = {
                    "doping": {"active": 0, "effects": [], "errors": []},
                    "goalkeeper_bribe": {"active": 0, "effects": [], "errors": []},
                }
                self.connection_requested = False
                self.connection_save_id = None
                self.connection_scope_id = None
                self.connection_process_pid = None
                self.connection_game_key = None
                self.match_engine_betting_lock = None
                self.wallet_ready = False
                self.connection_liveness_failures = 0
                self.connection_live_confirmed = False
                self.last_connection_clock = None
                self.connection_unavailable_since = None
                self.pending_save_identity = None
                self.save_change_pending = False
                self.status = "游戏版本已切换，请进入存档后点击连接存档"
                self.redbull_hook = RedBullHookController()
                self.referee_hook = RefereeHookController()
                self.ca_growth_hook = CAGrowthHookController()
                self.attribute_growth_hook = AttributeGrowthHookController()
                self.team_nuclear_hooks = TeamNuclearHookController()
                self.club_policy_hooks = ClubPolicyHookController()
                self.board_listens_hook = BoardListensHookController()
                self.youth_generation_hook = YouthGenerationHookController()
                self.simple_effects = SimpleNuclearController()
        return {**status, "refresh_started": False}

    def clear_cache(self, confirmation: str) -> dict[str, Any]:
        if confirmation != "CLEAR_REBUILDABLE_CACHE":
            raise ValueError("未确认清除可重新生成的缓存")
        with self.memory_lock:
            with self.lock:
                if (
                    self.refreshing or self.reconciling or self.club_refreshing
                    or self.world_club_scanning
                    or self._club_legacy_refresh().busy()
                ):
                    raise ValueError("当前正在读取游戏数据，请等待刷新完成后再清理")
                scope_id = (
                    self._data_scope_id(self.output)
                    if self._has_verified_save()
                    else str(self.connection_scope_id or "")
                )
                if scope_id:
                    set_active_save_id(scope_id)
                    protected_paths = pending_snapshot_paths()
                else:
                    protected_paths = set()
                self.refreshing = True
                self.refresh_mode = "storage_clear"
                self.status = "正在清理可重新生成的缓存..."
            try:
                self._invalidate_rebuildable_runtime_caches()
                result = clear_cache_files(protected_paths=protected_paths)
                with self.lock:
                    # Keep the verified save/account identity for the refresh
                    # worker. A new thread does not inherit this request's
                    # ContextVar, so clearing the whole output here would make
                    # pre-generation account reads fall back to no scope.
                    self.output_path = None
                    self.cache_verified = False
                    self.data_version += 1
                    self.club_context = None
                    self.club_profile = None
                    self.club_contexts = {}
                    self.club_profiles = {}
                    self.club_last_updated = None
                    self.club_error = None
                    self.last_game_date = None
                    self.last_result_refresh_date = None
                    self.salary_last_processed_date = None
                    self.pending_save_identity = None
                    self.save_change_pending = False
                    self.error = None
                    self.status = "缓存已清理，正在重新读取当前存档..."
            finally:
                with self.lock:
                    self.refreshing = False
                    self.refresh_mode = None
        result["refresh_started"] = self.refresh_async("cache_cleared", full=True)
        return result

    def delete_other_saves(self, confirmation: str) -> dict[str, Any]:
        if confirmation != "DELETE_OTHER_SAVE_FILES":
            raise ValueError("未确认删除其他存档")
        with self.memory_lock:
            with self.lock:
                if self.refreshing or self.reconciling or self.club_refreshing or self._club_legacy_refresh().busy():
                    raise ValueError("当前正在读取游戏数据，请等待刷新完成后再删除")
                current_scope = (
                    self._data_scope_id(self.output)
                    if self._has_verified_save()
                    else str(self.connection_scope_id or "")
                )
            return delete_other_save_files(current_scope)

    def delete_current_save(self, confirmation: str) -> dict[str, Any]:
        if confirmation != "DELETE_CURRENT_SAVE_FILE":
            raise ValueError("未确认删除当前存档")
        with self.memory_lock:
            with self.lock:
                if self.refreshing or self.reconciling or self.club_refreshing or self._club_legacy_refresh().busy():
                    raise ValueError("当前正在读取游戏数据，请等待刷新完成后再删除")
                current_scope = (
                    self._data_scope_id(self.output)
                    if self._has_verified_save()
                    else str(self.connection_scope_id or "")
                )
            result = delete_current_save_file(current_scope)
        result["refresh_started"] = self.refresh_async("current_save_deleted", full=True)
        return result

    def configure_data_root(self, value: str) -> dict[str, str | bool | int]:
        with self.memory_lock:
            with self.lock:
                if (
                    self.refreshing or self.reconciling or self.club_refreshing
                    or self.world_club_scanning
                    or self._club_legacy_refresh().busy()
                ):
                    raise ValidationError(
                        "当前正在读取游戏数据，请等待刷新完成后再修改存储位置",
                        code="storage_migration_busy",
                        phase="migrate_storage_root",
                        message_key="storage.migration.busy",
                    )
                return configure_data_root(value)

    def refresh_async(
        self, reason: str = "manual", *, full: bool = False,
        cancel_on_clock_change: bool = False,
    ) -> bool:
        return self._refresh_coordinator().start(
            reason, full=full,
            cancel_on_clock_change=cancel_on_clock_change,
        )

    def connect_current_save(self) -> dict[str, Any]:
        connection_started_at = perf_counter()
        discovery_started_at = connection_started_at
        game_versions: dict[str, Any] = {}
        game_version_error: Exception | None = None
        for attempt in range(CONNECTION_READ_ATTEMPTS):
            try:
                game_versions = process_selection_status(include_internal=True)
            except Exception as error:
                game_version_error = error
                game_versions = {}
            if game_versions.get("available"):
                break
            if attempt + 1 < CONNECTION_READ_ATTEMPTS:
                sleep(CONNECTION_READ_RETRY_SECONDS)
        if not game_versions.get("available"):
            if game_version_error is not None:
                raise ValueError("未检测到支持的 Football Manager，请先启动游戏") from game_version_error
            raise ValueError("未检测到支持的 Football Manager，请先启动游戏")
        process_discovery_ms = round(
            (perf_counter() - discovery_started_at) * 1000, 1,
        )
        selected_context = game_versions.pop("_selected_process", None)
        if selected_context is not None:
            selected_context = resolve_selected_process_layout(selected_context)
        selected_key = str(game_versions.get("selected") or "")
        selected_process = next(
            (
                row for row in (game_versions.get("available") or [])
                if int(row.get("pid") or 0) == int(
                    game_versions.get("selected_pid") or 0
                )
            ),
            None,
        )
        if selected_process is None:
            selected_process = next(
                (
                    row for row in (game_versions.get("available") or [])
                    if str(row.get("key") or "") == selected_key
                ),
                None,
            )
        selected_pid = int((selected_process or {}).get("pid") or 0)
        if not selected_key or selected_pid <= 0:
            raise ValueError("未能锁定当前 Football Manager 进程，请重新连接")
        selection_started_at = perf_counter()
        if selected_context is not None:
            selection_changed = select_game_process(
                selected_key, selected_pid, selected=selected_context,
            )
        else:
            selection_changed = select_game_process(selected_key, selected_pid)
        selection_pin_ms = round(
            (perf_counter() - selection_started_at) * 1000, 1,
        )
        with self.lock:
            self.connection_requested = True
            self.connection_process_pid = selected_pid
            self.connection_game_key = selected_key or None
            self.last_process_selection_status = dict(game_versions)
        startup_kwargs: dict[str, Any] = {}
        if selected_context is not None:
            startup_kwargs = {
                "selected_process": selected_context,
                "connection_trace": {
                    "_started_at": connection_started_at,
                    "process_discovery_ms": process_discovery_ms,
                    "selection_pin_ms": selection_pin_ms,
                    "selection_changed": bool(selection_changed),
                },
            }
        started = self.startup_async(**startup_kwargs)
        with self.lock:
            wallet_ready = bool(self.wallet_ready and self.connection_scope_id)
            scope_id = str(self.connection_scope_id or "")
            refresh_mode = str(getattr(self, "refresh_mode", None) or "")
        if wallet_ready:
            set_active_save_id(scope_id)
        return {
            "started": started,
            "game_versions": game_versions,
            "data_scope_id": scope_id,
            "wallet_ready": wallet_ready,
            "refresh_mode": refresh_mode,
        }

    def startup_async(
        self, *, selected_process: tuple[int, str, Any] | None = None,
        connection_trace: dict[str, Any] | None = None,
    ) -> bool:
        with self.lock:
            if self.refreshing or self.reconciling:
                return False
            had_verified_save = self._has_verified_save()
            self.refreshing = True
            # Retained player context is not permission to read the old career
            # while a reconnect is identifying the game's newly loaded save.
            self.club_refresh_generation = int(getattr(self, "club_refresh_generation", 0)) + 1
            self.refresh_mode = "startup"
            self.refresh_reason = "startup"
            # A reconnect or transient retry must not hide an already verified
            # player context while the new read is in flight.
            if not had_verified_save:
                self.cache_verified = False
            self.error = None
            self.status = (
                "正在核对缓存盘口与当前存档..."
                if self.output else "正在首次读取当前存档..."
            )
            now = perf_counter()
            self.refresh_progress = {
                "phase": "connection_context",
                "text": "正在读取存档、经理和执教队伍",
            }
            self._refresh_progress_updated_at = now
            cancel_event = threading.Event()
            self.refresh_cancel_event = cancel_event
            self.refresh_cancel_on_clock_change = False
        threading.Thread(
            target=self._startup_worker,
            args=(cancel_event, selected_process, connection_trace), daemon=True,
        ).start()
        return True

    def _startup_worker(
        self, cancel_event: threading.Event,
        selected_process: tuple[int, str, Any] | None = None,
        connection_trace: dict[str, Any] | None = None,
    ) -> None:
        worker_started_at = perf_counter()
        performance = dict(connection_trace or {})
        connection_started_at = float(
            performance.pop("_started_at", worker_started_at) or worker_started_at
        )
        with self.lock:
            cached_output = dict(self.output)
            had_verified_save = self._has_verified_save()
        cached_manager = cached_output.get("manager") or {}
        preferred_manager_id = int(
            cached_output.get("selected_manager_id")
            or cached_manager.get("id")
            or 0
        )
        try:
            memory_wait_started_at = perf_counter()
            with self.memory_lock:
                memory_acquired_at = perf_counter()
                read_kwargs: dict[str, Any] = {
                    "preferred_save_id": (
                        str(cached_output.get("save_instance_id") or "") or None
                    ),
                    "preferred_manager_id": preferred_manager_id or None,
                    "known_manager_sessions": list(
                        cached_output.get("manager_options") or []
                    ),
                }
                if selected_process is not None:
                    read_kwargs["selected_process"] = selected_process
                context = read_connection_context(
                    **read_kwargs,
                )
                context_read_completed_at = perf_counter()
            reader_performance = dict(context.get("connection_performance") or {})
            context_read_ms = float(reader_performance.pop("total_ms", 0.0) or 0.0)
            context["connection_performance"] = {
                **performance,
                "memory_lock_wait_ms": round(
                    (memory_acquired_at - memory_wait_started_at) * 1000, 1,
                ),
                "context_read_ms": round(
                    context_read_ms or (
                        context_read_completed_at - memory_acquired_at
                    ) * 1000,
                    1,
                ),
                **reader_performance,
                "total_ms": round(
                    (context_read_completed_at - connection_started_at) * 1000, 1,
                ),
            }
            identity = str(context.get("save_instance_id") or "")
            game_clock = {
                "date": str(context.get("game_date") or ""),
                "time": str(context.get("game_time") or "00:00"),
                "minutes": (
                    int(str(context.get("game_time") or "00:00")[:2]) * 60
                    + int(str(context.get("game_time") or "00:00")[3:5])
                ),
            }
            if not identity or not game_clock["date"]:
                raise RuntimeError("当前存档连接上下文不完整")
            same_save = bool(
                cached_output.get("save_instance_id")
                and save_identity_matches(
                    identity, str(cached_output.get("save_instance_id") or ""),
                )
            )
            # A manager allocation may briefly disappear while FM changes
            # screens or reloads the same save. Keep the last validated player
            # context until a later read can replace it atomically.
            retain_manager_context = should_retain_cached_manager_context(
                cached_output, context, same_save=same_save,
            )
            if retain_manager_context:
                for key in (
                    "manager", "manager_options", "selected_manager_id",
                    "manager_selection_required", "managed_team", "managed_teams",
                ):
                    if key in cached_output:
                        context[key] = cached_output[key]
                context["manager_context_retained"] = True

            connection_output = dict(cached_output) if same_save else {
                "matches": [],
                "competitions": [],
                "competition_formats": [],
                "competition_goal_baselines": {},
                "season_results": [],
                "settlement_results": [],
                "model_cache": {},
                "odds_days": int(load_settings().get("odds_days") or 7),
                "odds_scope": str(load_settings().get("odds_scope") or "all"),
            }
            connection_output.update(context)
            self._apply_unemployed_confirmation_state(
                connection_output, cached_output if same_save else None,
            )
            scope_id = self._assign_account_scope(
                connection_output, cached_output if same_save else None,
            )
        except Exception as error:
            with self.lock:
                self.status = (
                    f"存档暂时不可读，已保留上次玩家信息：{error}"
                    if had_verified_save else
                    f"连接存档失败：{error}"
                )
                self.error = str(error)
                self.refreshing = False
                self.refresh_mode = None
                self.refresh_reason = None
                if self.refresh_cancel_event is cancel_event:
                    self.refresh_cancel_event = None
            return

        with self.lock:
            previous_manager_id = int(
                (cached_output.get("manager") or {}).get("id")
                or cached_output.get("selected_manager_id")
                or 0
            )
            current_manager_id = int(
                (connection_output.get("manager") or {}).get("id")
                or connection_output.get("selected_manager_id")
                or 0
            )
            previous_teams = managed_team_identities(cached_output)
            current_teams = managed_team_identities(connection_output)
            context_changed = bool(
                cached_output
                and (
                    not same_save
                    or previous_manager_id != current_manager_id
                    or previous_teams != current_teams
                )
            )
            self.output = connection_output
            self.manager_context_absence_pending = False
            if not same_save:
                self.output_path = None
            self.cache_verified = True
            self.connection_save_id = identity
            self.connection_scope_id = scope_id
            self.wallet_ready = True
            self.connection_live_confirmed = True
            self.connection_suspended = False
            self.connection_liveness_failures = 0
            self.connection_unavailable_since = None
            self.last_connection_clock = dict(game_clock)
            self.pending_save_identity = None
            self.save_change_pending = False
            self.data_version += 1
            self.status = "已连接当前存档，正在启动盘口刷新..."
            self.error = None
            if context_changed:
                self.club_profile = None
                self.club_profiles = {}
                self.club_context = None
                self.club_contexts = {}
                self.club_last_updated = None
        set_active_save_id(scope_id)
        remember_active_save_id(scope_id)
        warmup = getattr(self, "_warm_world_player_index_after_connect", None)
        if callable(warmup):
            warmup(selected_process)

        valid, reason = startup_cache_validation(
            cached_output, identity, game_clock, load_settings(),
        ) if same_save else (False, "save_changed")
        if valid:
            with self.lock:
                self.refreshing = False
                self.refresh_mode = None
                self.refresh_reason = None
                self.status = "已连接当前存档，已复用缓存盘口"
                self.refresh_progress = {
                    "phase": "connection_ready",
                    "text": "当前存档读取完成",
                }
                self._refresh_progress_updated_at = perf_counter()
                if self.refresh_cancel_event is cancel_event:
                    self.refresh_cancel_event = None
                    self.refresh_cancel_on_clock_change = False
            self._schedule_idle_data_prewarm()
            return
        mode = startup_odds_refresh_mode(valid, reason, cached_output)
        if (
            not had_verified_save
            and str(connection_output.get("game_layout") or "") == "fm24"
            and mode == "full"
        ):
            with self.lock:
                self.refreshing = False
                self.refresh_mode = None
                self.refresh_reason = None
                self.status = "已连接 FM24，正在优先读取俱乐部资料"
                self.deferred_memory_job_after_club = {
                    "kind": "refresh",
                    "reason": "startup_odds",
                    "full": mode == "full",
                    "cancel_on_clock_change": False,
                }
                if self.refresh_cancel_event is cancel_event:
                    self.refresh_cancel_event = None
                    self.refresh_cancel_on_clock_change = False
            self.refresh_club_async()
            return
        with self.lock:
            self.refresh_mode = mode
            self.refresh_reason = "startup_odds"
            self.status = (
                "已连接当前存档，正在快速刷新启动盘口..."
                if mode == "fast" else
                "已连接当前存档，正在完整刷新启动盘口..."
            )
        self._refresh_worker("startup_odds", mode, False, cancel_event)

    def refresh_status(self) -> dict[str, Any]:
        return self._refresh_coordinator().status()

    @staticmethod
    def _schedule_window_needs_refresh(output: dict[str, Any], game_date: str) -> bool:
        """Return whether the rolling odds window is still anchored to an older game day."""
        output_date = str(output.get("game_date") or "")
        if not output_date or not game_date:
            return False
        try:
            return datetime.fromisoformat(game_date).date() > datetime.fromisoformat(output_date).date()
        except ValueError:
            return game_date > output_date

    @staticmethod
    def _output_schedule_snapshot(
        output: dict[str, Any], game_date: str, game_minutes: int | None = None,
    ) -> dict[str, Any]:
        days = int(output.get("odds_days") or 7)
        try:
            start = datetime.fromisoformat(game_date).date()
        except ValueError:
            return {"fingerprint": "", "fixtures": []}
        end = start.fromordinal(start.toordinal() + days)
        rows = []
        for match in output.get("matches", []):
            try:
                fixture_date = datetime.fromisoformat(str(match["fixture_date"])).date()
                if not start <= fixture_date <= end:
                    continue
                kickoff_minutes = (
                    int(match["kickoff_minutes"])
                    if match.get("kickoff_minutes") is not None else -1
                )
                if (
                    fixture_date == start and game_minutes is not None
                    and kickoff_minutes >= 0 and kickoff_minutes < int(game_minutes)
                ):
                    continue
                rows.append((
                    fixture_date.isoformat(), int(match["competition_id"]),
                    int(match["home"]["id"]), int(match["away"]["id"]),
                    kickoff_minutes,
                ))
            except (KeyError, TypeError, ValueError):
                continue
        rows = sorted(set(rows))
        encoded = json.dumps(rows, ensure_ascii=True, separators=(",", ":")).encode("ascii")
        return {"fingerprint": hashlib.sha256(encoded).hexdigest(), "fixtures": rows}

    def _probe_schedule_change(self, clock_key: tuple[str, int]) -> str:
        """Confirm live schedule changes twice before refreshing the odds snapshot."""
        now = monotonic()
        with self.lock:
            if self.refreshing or self.reconciling or self.save_change_pending:
                return "skipped"
            if self.schedule_probe_clock != clock_key:
                self.schedule_probe_clock = clock_key
                self.schedule_probe_candidate = None
                self.schedule_probe_confirmations = 0
                self.schedule_probe_last_at = 0.0
            if (
                self.schedule_probe_completed_clock == clock_key
                and now - self.schedule_probe_last_at < SCHEDULE_STABLE_RECHECK_SECONDS
            ):
                return "stable"
            if now - self.schedule_probe_last_at < SCHEDULE_FINGERPRINT_POLL_SECONDS:
                return "pending" if self.schedule_probe_candidate else "skipped"
            output = dict(self.output)
            self.schedule_probe_last_at = now
        if not output.get("save_instance_id") or not output.get("matches"):
            return "skipped"
        if not self.memory_lock.acquire(blocking=False):
            return "skipped"
        try:
            visible_competitions = {
                int(item.get("competition_id") or 0) for item in output.get("matches", [])
            }
            managed_team_ids = {
                int(item.get("id") or 0) for item in output.get("managed_teams", [])
            }
            if str(output.get("odds_scope") or "") == "favorite_schedule":
                set_active_save_id(self._data_scope_id(output))
                managed_team_ids = set(load_favorite_team_ids())
            live = read_upcoming_fixture_snapshot(
                int(output.get("odds_days") or 7),
                competition_scope=str(output.get("odds_scope") or "all"),
                visible_competition_ids=visible_competitions,
                managed_team_ids=managed_team_ids,
                hidden_competition_ids=set(load_hidden_competition_ids()),
                game_minutes=clock_key[1],
            )
        except Exception:
            return "skipped"
        finally:
            self.memory_lock.release()
        if str(live.get("game_date") or "") != clock_key[0]:
            return "skipped"
        baseline = self._output_schedule_snapshot(output, clock_key[0], clock_key[1])
        if live["fingerprint"] == baseline["fingerprint"]:
            with self.lock:
                self.schedule_probe_candidate = None
                self.schedule_probe_confirmations = 0
                self.schedule_probe_completed_clock = clock_key
            return "stable"

        baseline_rows = {tuple(row) for row in baseline["fixtures"]}
        live_rows = {tuple(row) for row in live["fixtures"]}
        missing_rows = sorted(baseline_rows - live_rows)
        added_rows = sorted(live_rows - baseline_rows)
        signature = hashlib.sha256(json.dumps(
            {"missing": missing_rows, "added": added_rows},
            ensure_ascii=True, separators=(",", ":"),
        ).encode("ascii")).hexdigest()
        with self.lock:
            self.schedule_probe_completed_clock = None
            if self.schedule_probe_candidate == signature:
                self.schedule_probe_confirmations += 1
            else:
                self.schedule_probe_candidate = signature
                self.schedule_probe_confirmations = 1
            confirmations = self.schedule_probe_confirmations
        if confirmations < SCHEDULE_CHANGE_CONFIRMATIONS:
            return "pending"

        set_active_save_id(self._data_scope_id(output))
        started = self.refresh_async(
            "schedule_change", full=False, cancel_on_clock_change=True,
        )
        with self.lock:
            if started:
                self.status = "已连续确认赛程变化，正在更新盘口..."
            self.schedule_probe_candidate = None
            self.schedule_probe_confirmations = 0
            if started:
                self.schedule_probe_completed_clock = clock_key
        return "triggered" if started else "skipped"

    @staticmethod
    def _due_existing_result_keys(
        output: dict[str, Any], game_date: str, game_minutes: int,
        minimum_match_minutes: int = LIVE_SETTLEMENT_MINIMUM_MATCH_MINUTES,
    ) -> set[tuple[str, int, int, int]]:
        """Return cached fixtures whose conservative 105-minute end has passed."""
        keys: set[tuple[str, int, int, int]] = set()
        for match in output.get("matches", []):
            fixture_date = str(match.get("fixture_date") or "")
            kickoff = match.get("kickoff_minutes")
            if not fixture_date or kickoff is None:
                continue
            if fixture_date > game_date or (
                fixture_date == game_date and int(kickoff) + minimum_match_minutes > game_minutes
            ):
                continue
            keys.add((
                fixture_date, int(match["competition_id"]),
                int(match["home"]["id"]), int(match["away"]["id"]),
            ))
        return keys

    def _merge_light_results(
        self, output: dict[str, Any], results: list[dict[str, Any]],
    ) -> tuple[dict[str, Any], int]:
        """Add completed cached fixtures to the result list without rebuilding odds."""
        if not results:
            return output, 0
        copied = dict(output)
        match_index = {
            (
                str(item["fixture_date"]), int(item["competition_id"]),
                int(item["home"]["id"]), int(item["away"]["id"]),
            ): item
            for item in output.get("matches", [])
        }
        merged = {
            (
                str(item["date"]), int(item["competition_id"]),
                int(item["home"]["id"]), int(item["away"]["id"]),
            ): dict(item)
            for item in output.get("season_results", [])
        }
        changed = 0
        confirmed_keys: set[tuple[str, int, int, int]] = set()
        for result in results:
            key = self._live_result_key(result)
            match = match_index.get(key, {})
            row = {
                "date": key[0],
                "competition_id": key[1],
                "competition_name": match.get("competition_name") or result["competition"].get("name") or "未知赛事",
                "competition_kind": match.get("competition_kind") or "league",
                "home": dict(result["home_team"]),
                "away": dict(result["away_team"]),
                "home_goals": int(result["home_goals"]),
                "away_goals": int(result["away_goals"]),
            }
            if match:
                row["odds_snapshot"] = _historical_market_snapshot(match)
            elif isinstance((merged.get(key) or {}).get("odds_snapshot"), dict):
                row["odds_snapshot"] = deepcopy(merged[key]["odds_snapshot"])
            for field in (
                "competition_stage_index", "competition_group_index",
            ):
                value = match.get(field, result.get(field))
                if value is not None:
                    row[field] = int(value)
            if result.get("half_home_goals") is not None and result.get("half_away_goals") is not None:
                row["half_home_goals"] = int(result["half_home_goals"])
                row["half_away_goals"] = int(result["half_away_goals"])
            if result.get("first_scoring_team") in {"home", "away", "none"}:
                row["first_scoring_team"] = result["first_scoring_team"]
            for field in (
                "after_extra_time_home_goals", "after_extra_time_away_goals",
                "penalty_shootout_home_goals", "penalty_shootout_away_goals",
                "home_outcome_code", "away_outcome_code", "winner_side", "decided_by",
                "advanced_side", "advanced_team", "advanced_team_id",
            ):
                if result.get(field) is not None:
                    row[field] = result[field]
            if merged.get(key) != row:
                changed += 1
            merged[key] = row
            confirmed_keys.add(key)
        copied["season_results"] = sorted(
            merged.values(), key=lambda item: (str(item["date"]), str(item.get("competition_name") or "")),
            reverse=True,
        )
        copied["matches"] = [
            item for item in output.get("matches", [])
            if (
                str(item["fixture_date"]), int(item["competition_id"]),
                int(item["home"]["id"]), int(item["away"]["id"]),
            ) not in confirmed_keys
        ]
        save_instance_id = str(output.get("save_instance_id") or "") or None
        if save_instance_id:
            save_result_history(
                merge_result_history(results, save_instance_id),
                save_instance_id,
                str(copied.get("game_date") or "") or None,
                protected_result_keys=confirmed_keys,
            )
            self._invalidate_club_manager_record_cache()
        return copied, changed

    def _result_refresh_worker(
        self, cancel_event: threading.Event, reason: str = "game_clock_stable",
    ) -> None:
        """Lightweight clock-stop refresh: results and settlements, never odds."""
        succeeded = False
        try:
            championship_enabled = bool(
                load_settings().get("championship_enabled", True)
            )
            with self.memory_lock:
                clock = read_game_clock()
                with self.lock:
                    output = dict(self.output)
                if not output.get("save_instance_id"):
                    return
                set_active_save_id(self._data_scope_id(output))
                game_date = str(clock["date"])
                game_minutes = int(clock["minutes"])
                championship_required = championship_enabled or has_pending_championship_bets()
                required_keys = self._due_existing_result_keys(output, game_date, game_minutes)
                required_keys.update(pending_due_result_keys(game_date, game_minutes))
                required_keys.update(settled_missing_half_score_keys(game_date))
                championship_result_keys = (
                    pending_cup_final_result_keys(game_date)
                    if championship_required else set()
                )
                required_keys.update(championship_result_keys)
                if required_keys:
                    try:
                        engine_state = read_match_engine_state()
                    except Exception:
                        engine_state = None
                    if engine_state and engine_state.get("active"):
                        with self.lock:
                            self.live_match_seen_active = True
                    required_keys = settlement_keys_safe_for_engine_state(
                        required_keys, game_date, engine_state,
                    )
                    if not required_keys:
                        return
                fixture_hints = pending_result_fixture_hints(required_keys)
                first = probe_live_completed_results(
                    required_keys, fixture_hints=fixture_hints,
                )
                sleep(0.2)
                if cancel_event.is_set():
                    raise RuntimeError("refresh cancelled")
                second = probe_live_completed_results(
                    required_keys, fixture_hints=fixture_hints,
                )
                first_scores = {
                    self._live_result_key(item): (int(item["home_goals"]), int(item["away_goals"]))
                    for item in first.get("results", [])
                }
                stable_results = [
                    item for item in second.get("results", [])
                    if first_scores.get(self._live_result_key(item))
                    == (int(item["home_goals"]), int(item["away_goals"]))
                ]
                stable_by_key = {
                    self._live_result_key(item): item for item in stable_results
                }
                missing_previous_results = {
                    key for key in required_keys - set(stable_by_key)
                    if key[0] <= game_date
                }
                if missing_previous_results:
                    # FM24 may never create a short-lived FIXTURE_RESULT when
                    # the user skips a match. Its persistent BASIC_SCORELINE
                    # pool is slower, so query it only for unresolved matches
                    # after their fixture date has passed.
                    result_kwargs = {}
                    if str(output.get("game_layout") or "") == "fm24":
                        result_kwargs = {
                            "preferred_save_id": str(output.get("save_instance_id") or "") or None,
                            "preferred_manager_id": _selected_manager_identity(output) or None,
                            "known_manager_sessions": list(output.get("manager_options") or []),
                        }
                    for item in read_completed_results(
                        missing_previous_results,
                        fixture_hints=pending_result_fixture_hints(
                            missing_previous_results,
                        ),
                        **result_kwargs,
                    ):
                        key = self._live_result_key(item)
                        if key in missing_previous_results:
                            stable_by_key[key] = item
                stable_results = list(stable_by_key.values())
            trusted_keys = {self._live_result_key(item) for item in stable_results}
            settlement = settle_pending_bets(
                stable_results, game_date, game_minutes=game_minutes,
                trusted_same_day_keys=trusted_keys,
                void_missing_after_timeout=missing_result_timeout_due(
                    required_keys - championship_result_keys, game_date,
                ),
            )
            self._finalize_settlement(settlement, output)
            updated, added = self._merge_light_results(output, stable_results)
            date_changed = str(updated.get("game_date") or "") != game_date
            updated["game_date"] = game_date
            updated["game_time"] = str(clock.get("time") or f"{game_minutes // 60:02d}:{game_minutes % 60:02d}")
            if date_changed:
                attach_historical_market_snapshots(updated, output)
            if not championship_required:
                updated.pop("championship_markets", None)
            else:
                championship_markets, _championship_cache_hit = (
                    publish_championship_markets(updated, output)
                )
                championship_settlement = settle_championship_bets(
                    championship_markets,
                )
                championship_records = championship_settlement.get(
                    "settled_records", [],
                )
                if championship_records:
                    archive_winning_mail(championship_records)
                    settlement["settled_records"] = [
                        *settlement.get("settled_records", []),
                        *championship_records,
                    ]
                if championship_settlement.get("settled"):
                    settlement["settled"] += int(
                        championship_settlement["settled"]
                    )
                    settlement["returned"] = round(
                        float(settlement.get("returned", 0.0))
                        + float(championship_settlement.get("returned", 0.0)),
                        2,
                    )
            championship_changed = updated.get("championship_markets") != output.get("championship_markets")
            with self.lock:
                gross_weekly_salary = self._total_weekly_salary(self.club_contexts)
            salary_result = (
                process_salary_payments(game_date, gross_weekly_salary)
                if gross_weekly_salary > 0 else {"paid": 0, "amount": 0.0}
            )
            archive_salary_payment_mail(salary_result.get("new_payments", []))
            output_path = self.output_path
            if championship_changed or date_changed or added or len(updated.get("matches", [])) != len(output.get("matches", [])):
                stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
                output_path = cache_data_root() / "odds" / "live" / f"fm26_all_odds_{game_date}_{stamp}.json"
                save_odds(updated, output_path)
            with self.lock:
                self.output = updated
                self.output_path = output_path
                self.cache_verified = True
                if championship_changed or light_result_refresh_changed(
                    date_changed, added,
                    len(output.get("matches", [])),
                    len(updated.get("matches", [])),
                ):
                    self.data_version += 1
                self.last_game_date = game_date
                self.last_result_refresh_date = game_date
                self.salary_last_processed_date = game_date
                self.last_background_settled = int(settlement.get("settled", 0))
                self.status = f"赛果已更新 {added} 场，结算 {int(settlement.get('settled', 0))} 笔"
                if salary_result.get("paid"):
                    self.status += f"，工资存入银行 {configured_money(salary_result['amount'])}"
                self.error = None
            succeeded = True
        except Exception as error:
            with self.lock:
                if str(error) == "refresh cancelled":
                    self.status = (
                        "已暂停自动赛果刷新，优先读取俱乐部资料"
                        if getattr(self, "refresh_cancel_reason", None) == "club_priority"
                        else "游戏时间变化，已停止赛果刷新"
                    )
                    self.error = None
                else:
                    self.status = "赛果刷新失败"
                    self.error = str(error)
        finally:
            with self.lock:
                self.refreshing = False
                self.refresh_mode = None
                if self.refresh_cancel_event is cancel_event:
                    self.refresh_reason = None
                    self.refresh_cancel_event = None
                    self.refresh_cancel_on_clock_change = False
                    self.refresh_cancel_reason = None
        if succeeded and (
            reason == "travel_complete"
            or (
                reason == "startup_cached"
                and full_reconcile_due(self.output)
            )
        ):
            self._start_reconcile(cancel_on_clock_change=True)

    def _manager_context_worker(
        self, manager_id: int, previous_manager_id: int, save_id: str,
        refreshed_context: dict[str, Any] | None = None,
        refresh_schedule: bool = False,
        account_only: bool = False,
        release_training_users_on_club_change: bool = False,
    ) -> None:
        succeeded = False
        try:
            with self.memory_lock:
                with self.lock:
                    previous_output = dict(self.output)
                known_session = next(
                    (
                        dict(item)
                        for item in (previous_output.get("manager_options") or [])
                        if int(item.get("id") or 0) == manager_id
                    ),
                    None,
                )
                if known_session:
                    known_session["manager_id"] = manager_id
                    known_session["manager_name"] = known_session.get("name")
                    raw_team_refs = list(
                        known_session.get("managed_team_refs")
                        or known_session.get("teams")
                        or []
                    )
                    known_session["managed_team_refs"] = [
                        {
                            **ref,
                            "team_id": int(ref.get("team_id") or ref.get("id") or 0),
                        }
                        for ref in raw_team_refs
                        if int(ref.get("team_id") or ref.get("id") or 0) > 0
                    ]
                    known_session["manager_address"] = known_session.get("manager_address")
                refreshed = refreshed_context or read_manager_context(
                    manager_id, preferred_save_id=save_id, known_session=known_session,
                )
                if refreshed_context is None and known_session and previous_output.get("manager_options"):
                    refreshed["manager_options"] = list(previous_output["manager_options"])
                if str(refreshed.get("game_date") or "") != str(previous_output.get("game_date") or ""):
                    raise RuntimeError("游戏日期已变化，请等待自动刷新完成")
                output = {
                    **previous_output,
                    **{
                        key: refreshed[key]
                        for key in (
                            "manager", "manager_options", "selected_manager_id",
                            "manager_selection_required", "managed_team", "managed_teams",
                        )
                    },
                }
                for key in (
                    "unemployed_manager_detected", "unemployed_confirmed",
                    "unemployed_confirmation_required",
                ):
                    output.pop(key, None)
                    if key in refreshed:
                        output[key] = refreshed[key]
                self._apply_unemployed_confirmation_state(output, previous_output)
                if manager_id == previous_manager_id:
                    # A human manager changing clubs is still the same account.
                    # Keep the already verified scope instead of resolving it
                    # again from transient manager/team discovery state.
                    scope_id = self._data_scope_id(previous_output)
                    output["account_scope_id"] = scope_id
                    output["account_scope_manager_id"] = manager_id
                else:
                    scope_id = self._assign_account_scope(output, previous_output)
                remember_active_save_id(scope_id)
                if release_training_users_on_club_change:
                    self._release_training_users_for_club_change(
                        previous_output, output,
                    )
                manager = output.get("manager") or {}
                managed_team = output.get("managed_team") or {}
                managed_teams = output.get("managed_teams") or []
                club_names = [
                    str(team.get("name") or team.get("id"))
                    for team in managed_teams
                    if str(team.get("team_type") or "club") == "club"
                ]
                national_names = [
                    str(team.get("name") or team.get("id"))
                    for team in managed_teams
                    if str(team.get("team_type") or "club") == "national"
                ]
                assignment_parts = []
                if club_names:
                    assignment_parts.append(f"俱乐部 {'、'.join(club_names)}")
                if national_names:
                    assignment_parts.append(f"国家队 {'、'.join(national_names)}")
                assignment_label = " · ".join(assignment_parts)
                context_status = (
                    f"已更新经理任职 · {assignment_label}，沿用当前日期盘口"
                    if assignment_label else
                    "检测到当前经理暂无执教球队，等待确认无业状态"
                )
                if account_only:
                    with self.lock:
                        self.output = output
                        self.manager_context_absence_pending = False
                        self.club_context = None
                        self.club_contexts = {}
                        self.club_profile = None
                        self.club_profiles = {}
                        self.club_last_updated = None
                        self.club_error = None
                        self.status = context_status
                        self.error = None
                    try:
                        self._sync_youth_generation_plans(
                            self._data_scope_id(output),
                            str(output.get("save_instance_id") or save_id),
                        )
                    except Exception as error:
                        self.youth_generation_hook.suspend(str(error))
                    self._sync_owned_club_board_hook(output)
                    succeeded = True
                    return
                club_contexts: dict[int, dict[str, Any]] = {}
                for team in managed_teams:
                    team_id = int(team.get("id") or 0)
                    if not team_id:
                        continue
                    try:
                        context = read_club_context(
                            manager_id, team_id,
                            team_address=team.get("address"),
                            manager_address=team.get("manager_address") or manager.get("manager_address"),
                        )
                        context["team"]["team_type"] = team.get("team_type") or "club"
                        club_contexts[team_id] = context
                    except Exception:
                        continue
                club_context = club_contexts.get(int(managed_team.get("id") or 0))
                fixture_index = self._fixture_index(output)
                game_date = str(output.get("game_date") or "")
                reconcile_inventory(game_date, fixture_index, activate_referee=False)
                doping_status = sync_doping_effects(active_doping_items())
                goalkeeper_status = sync_goalkeeper_bribes(active_goalkeeper_bribes())
                hook_status = self.redbull_hook.sync(
                    active_player_ids(), goalkeeper_status.get("player_ids", []),
                )
                if goalkeeper_status.get("player_ids") and hook_status.get("error"):
                    goalkeeper_status.setdefault("errors", []).append(str(hook_status["error"]))
                self._remember_fixture_effect_status(doping_status, goalkeeper_status)
                if hook_status.get("error"):
                    refund_active_sku("red_bull", str(hook_status["error"]))
                    refund_active_sku("team_red_bull", str(hook_status["error"]))
                    self.redbull_hook.sync([], goalkeeper_status.get("player_ids", []))
                self._sync_referee_fixture_hook(game_date, club_contexts, output)
                effects = set(active_effect_skus())
                team_address = self._club_team_address(club_context)
                club_address = self._club_address(club_context)
                self.simple_effects.sync(effects)
                self._sync_owned_club_board_hook(output)
                self.canteen_plan = canteen_plan()
                self._sync_ca_growth_hook(
                    effects, team_address, club_address,
                    managed_team_address(output, "national"),
                )
                self.team_nuclear_hooks.sync(effects, team_address, club_address)
                roster_profile = None
                if effects & ROSTER_EFFECTS and manager.get("id") and managed_team.get("id"):
                    roster_profile = read_club_profile(
                        manager_id, int(managed_team["id"]),
                        team_address=managed_team.get("address"),
                        manager_address=managed_team.get("manager_address") or manager.get("manager_address"),
                    )
                self.roster_effect_errors = apply_roster_effects(roster_profile, effects)
                with self.lock:
                    self.output = output
                    self.manager_context_absence_pending = False
                    self.club_context = club_context
                    self.club_contexts = club_contexts
                    self.club_profile = None
                    self.club_profiles = {}
                    self.club_last_updated = None
                    self.club_error = None
                    self.status = context_status
                    self.error = None
                try:
                    self._sync_youth_generation_plans(
                        self._data_scope_id(output),
                        str(output.get("save_instance_id") or save_id),
                    )
                except Exception as error:
                    self.youth_generation_hook.suspend(str(error))
                succeeded = True
        except Exception as error:
            remember_selected_manager(save_id, previous_manager_id)
            with self.lock:
                self.status = "经理切换失败"
                self.error = str(error)
        finally:
            with self.lock:
                self.refreshing = False
                self.refresh_mode = None
                self.refresh_reason = None
        if succeeded and refresh_schedule:
            self.refresh_async(
                "manager_change_schedule", full=False, cancel_on_clock_change=True,
            )

    def _queue_manager_club_change_confirmation(
        self, current: dict[str, Any], candidate: dict[str, Any],
    ) -> bool:
        if not manager_club_change_requires_confirmation(current, candidate):
            return False
        key = manager_club_change_confirmation_key(current, candidate)
        request_id = "|".join((
            str(key[0]), str(key[1]),
            ",".join(str(item) for item in key[2]),
            ",".join(str(item) for item in key[3]),
        ))
        with self.lock:
            if key == getattr(self, "declined_manager_club_change_key", None):
                return True
            self.pending_manager_club_change = {
                "key": key,
                "request_id": request_id,
                "previous": deepcopy(current),
                "candidate": deepcopy(candidate),
            }
            self.manager_context_absence_pending = False
            self.status = "检测到玩家更换了执教俱乐部，等待确认是否切换"
            self.error = None
        return True

    def confirm_manager_club_change(self, payload: dict[str, Any]) -> dict[str, Any]:
        confirmed = payload.get("confirmed")
        if confirmed is not True and confirmed is not False:
            raise ValueError("请明确选择是否切换到新执教俱乐部")
        request_id = str(payload.get("request_id") or "")
        with self.lock:
            pending = getattr(self, "pending_manager_club_change", None)
            if not pending or request_id != str(pending.get("request_id") or ""):
                raise ValueError("执教俱乐部变化已失效，请等待重新检测")
            candidate = deepcopy(pending.get("candidate") or {})
            key = pending.get("key")
            if (
                str(self.output.get("save_instance_id") or "") != str(key[0])
                or _selected_manager_identity(self.output) != int(key[1])
            ):
                self.pending_manager_club_change = None
                raise ValueError("当前存档或经理已变化，请等待重新检测")
            self.pending_manager_club_change = None
            if not confirmed:
                self.declined_manager_club_change_key = key
                self.status = "已取消本次执教俱乐部切换，继续沿用当前俱乐部"
                self.error = None
                return {"confirmed": False, "started": False}
            self.declined_manager_club_change_key = None
        started = self._start_manager_team_context_refresh(candidate)
        if not started:
            with self.lock:
                if (
                    not getattr(self, "pending_manager_club_change", None)
                    and str(self.output.get("save_instance_id") or "") == str(key[0])
                    and _selected_manager_identity(self.output) == int(key[1])
                ):
                    self.pending_manager_club_change = pending
            raise ValueError("当前正在执行其他刷新，请稍后再次确认")
        return {"confirmed": True, "started": True}

    def _start_manager_team_context_refresh(
        self, refreshed: dict[str, Any],
    ) -> bool:
        manager_options_only = bool(refreshed.pop("_manager_options_only", False))
        manager_id = int(
            refreshed.get("selected_manager_id")
            or (refreshed.get("manager") or {}).get("id")
            or 0
        )
        with self.lock:
            save_id = str(self.output.get("save_instance_id") or "")
            previous_manager_id = int(
                self.output.get("selected_manager_id")
                or (self.output.get("manager") or {}).get("id")
                or 0
            )
            if (
                not save_id or manager_id <= 0 or manager_id != previous_manager_id
                or self.refreshing or self.reconciling or self.club_refreshing
                or self.save_change_pending
            ):
                return False
            self.refreshing = True
            self.refresh_mode = "manager"
            self.refresh_reason = "manager_team_context_change"
            self.club_profile = None
            self.club_context = None
            self.club_profiles = {}
            self.club_contexts = {}
            self.club_last_updated = None
            self.club_error = None
            self.error = None
            if manager_options_only:
                self.status = "检测到经理任职列表变化，正在更新经理列表..."
            elif not managed_club_identities(refreshed):
                self.status = "已确认当前经理离开俱乐部，正在更新执教状态..."
            else:
                self.status = "检测到经理任职变化，正在读取最新球队信息..."
        refresh_schedule = not manager_options_only and str(load_settings().get("odds_scope") or "all") in {
            "managed_schedule", "famous",
        }
        threading.Thread(
            target=self._manager_context_worker,
            args=(
                manager_id, previous_manager_id, save_id,
                dict(refreshed), refresh_schedule,
                False, not manager_options_only,
            ),
            daemon=True,
        ).start()
        return True

    def confirm_unemployed_manager(self, payload: dict[str, Any]) -> dict[str, Any]:
        if payload.get("confirmed") is not True:
            raise ValueError("请明确确认当前经理处于无业状态")
        with self.lock:
            if self.reconciling:
                raise ValueError("当前正在刷新，请完成后再确认经理状态")
            manager_id = int(
                self.output.get("selected_manager_id")
                or (self.output.get("manager") or {}).get("id")
                or 0
            )
            if manager_id <= 0:
                raise ValueError("尚未可靠识别当前人类经理")
            if managed_team_rows(self.output):
                raise ValueError("已经识别到当前经理的执教球队，无需确认无业")
            if not self.output.get("unemployed_manager_detected"):
                raise ValueError("当前读取结果不能确认经理处于无球队状态")
            self.output["unemployed_confirmed"] = True
            self.output["unemployed_confirmation_required"] = False
            self.status = "已确认当前经理无业，正在读取可用盘口..."
            should_start = not self.refreshing and not self.reconciling
        started = self.refresh_async(
            "unemployed_manager_confirmed", full=True,
        ) if should_start else False
        return {
            "confirmed": True,
            "manager_id": manager_id,
            "started": started,
        }

    def switch_manager(self, payload: dict[str, Any]) -> dict[str, Any]:
        manager_id = int(payload.get("manager_id") or 0)
        with self.lock:
            self.pending_manager_club_change = None
            self.declined_manager_club_change_key = None
            save_id = str(self.output.get("save_instance_id") or "")
            options = self.output.get("manager_options") or []
            resume_startup = bool(self.output.get("manager_selection_required"))
            allowed = {int(item.get("id") or 0) for item in options}
            if not save_id or manager_id not in allowed:
                raise ValueError("所选经理已失效，请重新读取存档")
            if self.refreshing or self.reconciling:
                raise ValueError("当前正在刷新，请完成后再切换经理")
            previous_manager_id = int(self.output.get("selected_manager_id") or 0)
            if manager_id == previous_manager_id and not resume_startup:
                return {"started": False, "manager_id": manager_id}
            option = next(item for item in options if int(item.get("id") or 0) == manager_id)
            previous_output = dict(self.output)
            refs = list(option.get("managed_team_refs") or option.get("teams") or [])
            known_teams: dict[int, dict[str, Any]] = {}
            for team in previous_output.get("managed_teams") or []:
                if int(team.get("id") or 0) > 0:
                    known_teams[int(team["id"])] = dict(team)
            for match in previous_output.get("matches") or []:
                for side in ("home", "away"):
                    team = match.get(side) or {}
                    if int(team.get("id") or 0) > 0:
                        known_teams.setdefault(int(team["id"]), dict(team))
            managed_teams = []
            for ref in refs:
                team_id = int(ref.get("team_id") or ref.get("id") or 0)
                if team_id <= 0:
                    continue
                known = known_teams.get(team_id, {})
                managed_teams.append({
                    **known,
                    **{key: value for key, value in ref.items() if value is not None},
                    "id": team_id,
                    "name": str(ref.get("name") or known.get("name") or f"球队 {team_id}"),
                    "team_type": str(ref.get("team_type") or known.get("team_type") or "club"),
                    "source": "cached_manager_switch",
                })
            managed_team = next(
                (team for team in managed_teams if team.get("team_type") == "club"),
                managed_teams[0] if managed_teams else None,
            )
            output = dict(previous_output)
            output.pop("manual_account_scope_id", None)
            output.update({
                "manager": {
                    "id": manager_id,
                    "name": option.get("name"),
                    "team_id": int((managed_team or {}).get("id") or 0) or None,
                    "team_name": (managed_team or {}).get("name"),
                    "team_type": (managed_team or {}).get("team_type"),
                    "manager_address": (
                        option.get("manager_address")
                        or (managed_team or {}).get("manager_address")
                    ),
                    "source": "cached_manager_switch",
                },
                "selected_manager_id": manager_id,
                "manager_selection_required": False,
                "unemployed_manager_detected": not bool(managed_teams),
                "managed_team": managed_team,
                "managed_teams": managed_teams,
            })
            self._apply_unemployed_confirmation_state(output, previous_output)
            scope_id = self._assign_account_scope(output, previous_output)
            remember_active_save_id(scope_id)
            self.output = output
            self.club_context = None
            self.club_contexts = {}
            self.club_profile = None
            self.club_profiles = {}
            self.club_last_updated = None
            self.club_error = None
            self.error = None
            self.status = (
                f"已切换经理账户 · {managed_team['name']}，沿用当前盘口"
                if managed_team else
                "已切换到无球队经理，等待确认无业状态"
            )
        remember_selected_manager(save_id, manager_id)
        if resume_startup:
            if getattr(self, "connection_requested", False):
                started = self.startup_async()
            else:
                started = bool(self.connect_current_save().get("started"))
            return {
                "started": started, "completed": False,
                "manager_id": manager_id, "mode": "startup_connection",
            }
        return {
            "started": False, "completed": True, "manager_id": manager_id,
            "mode": "cached_account_context",
        }

    def _start_reconcile(self, *, cancel_on_clock_change: bool = False) -> None:
        with self.lock:
            if self.refreshing or self.reconciling or self.save_change_pending:
                return
            if getattr(self, "club_refreshing", False):
                if getattr(self, "deferred_memory_job_after_club", None) is None:
                    self.deferred_memory_job_after_club = {
                        "kind": "reconcile",
                        "cancel_on_clock_change": bool(cancel_on_clock_change),
                    }
                return
            self.reconciling = True
            self.refresh_mode = "reconcile"
            self.refresh_reason = "background_reconcile"
            cancel_event = threading.Event()
            self.refresh_cancel_event = cancel_event
            self.refresh_cancel_on_clock_change = bool(cancel_on_clock_change)
            self.status += "，正在后台核对新赛程..."
        threading.Thread(
            target=self._refresh_worker,
            args=("background_reconcile", "full", True, cancel_event),
            daemon=True,
        ).start()

    def _settle_results_before_refresh(self) -> dict[str, Any]:
        """Prioritise stable completed results before rebuilding odds or schedules."""
        empty = {"settled": 0, "settled_records": [], "returned": 0.0}
        with self._timed_memory_lock("pre_refresh_result_read"):
            output = dict(getattr(self, "output", {}) or {})
            if not output.get("save_instance_id"):
                return empty
            try:
                clock = read_game_clock()
            except Exception:
                return empty
            try:
                game_date = str((clock or {})["date"])
                game_minutes = int((clock or {})["minutes"])
            except (KeyError, TypeError, ValueError):
                return empty
            if not game_date:
                return empty
            due_keys = pending_due_result_keys(game_date, game_minutes)
            if not due_keys:
                return empty
            try:
                engine_state = read_match_engine_state()
            except Exception:
                engine_state = None
            if engine_state and engine_state.get("active"):
                with self.lock:
                    self.live_match_seen_active = True
            due_keys = settlement_keys_safe_for_engine_state(
                due_keys, game_date, engine_state,
            )
            if not due_keys:
                return empty
            try:
                fixture_hints = pending_result_fixture_hints(due_keys)
                first = probe_live_completed_results(
                    due_keys, fixture_hints=fixture_hints,
                ) or {}
                sleep(0.2)
                second = probe_live_completed_results(
                    due_keys, fixture_hints=fixture_hints,
                ) or {}
            except Exception:
                return empty
            if not isinstance(first, dict) or not isinstance(second, dict):
                return empty
            first_scores = {}
            for item in first.get("results") or []:
                if not isinstance(item, dict):
                    continue
                try:
                    first_scores[self._live_result_key(item)] = (
                        int(item["home_goals"]), int(item["away_goals"]),
                    )
                except (KeyError, TypeError, ValueError):
                    continue
            stable_results = []
            for item in second.get("results") or []:
                if not isinstance(item, dict):
                    continue
                try:
                    key = self._live_result_key(item)
                    score = (int(item["home_goals"]), int(item["away_goals"]))
                except (KeyError, TypeError, ValueError):
                    continue
                if first_scores.get(key) == score:
                    stable_results.append(item)
        if not stable_results:
            return empty
        trusted_keys = {self._live_result_key(item) for item in stable_results}
        settlement = settle_pending_bets(
            stable_results, str(clock["date"]),
            game_minutes=int(clock["minutes"]),
            trusted_same_day_keys=trusted_keys,
        )
        self._finalize_settlement(settlement, output)
        return settlement

    def _recover_missing_live_results(
        self,
        due_keys: set[tuple[str, int, int, int]],
        observed_keys: set[tuple[str, int, int, int]],
    ) -> list[dict[str, Any]]:
        """Use validated persistent results after repeated live-read misses."""
        missing = set(due_keys) - set(observed_keys)
        now = monotonic()
        with self.lock:
            for key in list(self.live_settlement_recovery_attempts):
                if key not in missing:
                    self.live_settlement_recovery_attempts.pop(key, None)
            for key in missing:
                self.live_settlement_recovery_attempts[key] = (
                    int(self.live_settlement_recovery_attempts.get(key, 0)) + 1
                )
            attempts = max(
                (self.live_settlement_recovery_attempts.get(key, 0) for key in missing),
                default=0,
            )
            should_retry = bool(
                missing
                and attempts >= LIVE_SETTLEMENT_FALLBACK_AFTER_MISSES
                and now - float(self.live_settlement_recovery_last_at)
                >= LIVE_SETTLEMENT_FALLBACK_RETRY_SECONDS
            )
            if should_retry:
                self.live_settlement_recovery_last_at = now
                self.live_settlement_status["fallback_attempts"] = int(
                    self.live_settlement_status.get("fallback_attempts", 0)
                ) + 1
                self.live_settlement_status["missing_results"] = len(missing)
        if not should_retry:
            with self.lock:
                self.live_settlement_status["missing_results"] = len(missing)
            return []

        try:
            if not self.memory_lock.acquire(timeout=1.0):
                return []
            try:
                with self.lock:
                    result_context = dict(self.output)
                result_kwargs = {}
                if str(result_context.get("game_layout") or "") == "fm24":
                    result_kwargs = {
                        "preferred_save_id": str(result_context.get("save_instance_id") or "") or None,
                        "preferred_manager_id": _selected_manager_identity(result_context) or None,
                        "known_manager_sessions": list(result_context.get("manager_options") or []),
                    }
                recovered = read_completed_results(
                    missing,
                    fixture_hints=pending_result_fixture_hints(missing),
                    **result_kwargs,
                )
            finally:
                self.memory_lock.release()
        except Exception as error:
            with self.lock:
                self.live_settlement_status["error"] = str(error)
            return []

        matched = [
            (item, required_key)
            for item in recovered
            if (required_key := recovered_result_required_key(item, missing)) is not None
        ]
        valid = [item for item, _required_key in matched]
        with self.lock:
            self.live_settlement_status["fallback_recovered"] = int(
                self.live_settlement_status.get("fallback_recovered", 0)
            ) + len(valid)
            for _item, required_key in matched:
                self.live_settlement_recovery_attempts.pop(
                    required_key, None,
                )
        return valid

    def _finalize_settlement(self, settlement: dict[str, Any], output: dict[str, Any]) -> None:
        settled_records = settlement.get("settled_records", [])
        if not settled_records:
            return
        intelligence_refunds = reconcile_match_intelligence_refunds(
            settled_records, str(output.get("game_date") or ""),
        )
        if intelligence_refunds:
            settlement["intelligence_refunds"] = intelligence_refunds
        self._process_match_item_consequences(
            settled_records, str(output.get("game_date") or ""),
        )
        if not load_settings().get("disable_fa_penalties"):
            with self.lock:
                gross_weekly = self._total_weekly_salary(self.club_contexts)
            manager_name = manager_display_name(output)
            penalty = process_match_integrity(
                [str(item.get("bet_id") or "") for item in settled_records],
                output, manager_name, gross_weekly,
            )
            if penalty:
                settlement["integrity_penalty"] = penalty
                relief = grant_bankruptcy_relief()
                if relief.get("granted"):
                    archive_bankruptcy_relief_mail(relief, str(output.get("game_date") or ""))
                    settlement["bankruptcy_relief"] = relief
        archive_winning_mail(settled_records)

    @staticmethod
    def _process_match_item_consequences(
        settled_records: list[dict[str, Any]], game_date: str,
    ) -> list[dict[str, Any]]:
        settled_ids = {str(row.get("bet_id") or "") for row in settled_records if row.get("bet_id")}
        if not settled_ids:
            return []
        records = load_bets()

        def matches_fixture(record: dict[str, Any], identity: str, fixture_date: str) -> bool:
            legs = record.get("legs") or [record]
            return any(
                "|".join(map(str, (
                    leg.get("competition_id"), leg.get("home_id"), leg.get("away_id"),
                ))) == identity
                and str(leg.get("fixture_date") or "") == fixture_date
                for leg in legs
            )

        outcomes = []
        penalties_disabled = bool(load_settings().get("disable_fa_penalties"))
        for item in pending_match_item_consequences():
            item = dict(item)
            identity = str(item.get("fixture_identity") or "")
            fixture_date = str(item.get("fixture_date") or "")
            fixture_records = [
                record for record in records
                if matches_fixture(record, identity, fixture_date)
            ]
            recorded_manager_name = next((
                _specific_manager_name(record.get("integrity_manager_name"))
                for record in fixture_records
                if _specific_manager_name(record.get("integrity_manager_name"))
            ), "")
            if recorded_manager_name:
                item["manager_name"] = recorded_manager_name
            settled_now = [
                record for record in fixture_records
                if str(record.get("bet_id") or "") in settled_ids
            ]
            if not settled_now or any(
                record.get("status", "pending") == "pending" for record in fixture_records
            ):
                continue
            bet_ids = sorted({
                str(record.get("bet_id") or "") for record in fixture_records
                if record.get("bet_id")
            })
            profit = round(sum(
                float(record.get("payout") or 0) - float(record.get("stake") or 0)
                for record in fixture_records
            ), 2)
            stake = round(sum(
                max(0.0, float(record.get("stake") or 0))
                for record in fixture_records
            ), 2)
            sku = str(item.get("sku") or "")
            outcome = "none"
            if profit <= 0:
                outcome = "no_profit"
            elif penalties_disabled:
                outcome = "disabled"
            elif sku in {"referee", "referee_level2", "referee_level3"}:
                roll = secrets.randbelow(100)
                if roll < 20:
                    archive_referee_debt_mail(
                        item, item, game_date, profit=profit, bet_ids=bet_ids,
                    )
                    outcome = "referee_debt"
                elif roll < 30:
                    archive_direct_referee_investigation_mail(
                        item, profit, bet_ids, stake=stake,
                    )
                    outcome = "direct_referee_investigation"
            elif sku in {"doping", "team_doping"}:
                if secrets.randbelow(100) < 20:
                    if sku == "doping":
                        names = [str(item.get("player_name") or "相关球员")]
                    else:
                        candidates = [
                            str(row.get("player_name") or row.get("player_id") or "")
                            for row in item.get("player_targets") or []
                            if row.get("player_name") or row.get("player_id")
                        ]
                        names = secrets.SystemRandom().sample(candidates, min(3, len(candidates)))
                    archive_doping_investigation_mail(
                        item, profit, bet_ids, names, stake=stake,
                    )
                    outcome = "doping_investigation"
            marked = mark_match_item_consequence(
                str(item.get("id") or ""), outcome=outcome, profit=profit,
                bet_ids=bet_ids, game_date=game_date,
            )
            outcomes.append(marked)
        return outcomes

    def _refresh_worker(
        self, reason: str, mode: str, background: bool,
        cancel_event: threading.Event | None = None,
    ) -> None:
        succeeded = False
        failure_message: str | None = None
        discover_future_league_seasons = reason == "manual_standings"
        previous_output: dict[str, Any] = {}
        deferred_club_refresh = False
        committed_result = {
            "settled": 0,
            "returned": 0.0,
            "schedule_refunded": 0,
        }

        def remember_committed(
            *, settled: int = 0, returned: float = 0.0,
            schedule_refunded: int = 0,
        ) -> None:
            committed_result["settled"] += int(settled or 0)
            committed_result["returned"] = round(
                float(committed_result["returned"]) + float(returned or 0.0), 2,
            )
            committed_result["schedule_refunded"] += int(
                schedule_refunded or 0
            )
        if reason in {
            "identity_change_full", "save_change_full",
            "cache_cleared", "storage_cleared",
        }:
            self._invalidate_rebuildable_runtime_caches()
        with self.lock:
            self.last_refresh_partial_result = None
        self._start_refresh_trace(reason, mode, background)
        def yield_refresh_memory_lock() -> None:
            """Yield the native-read mutex between long result-link chunks."""
            self.memory_lock.release()
            self.memory_lock.acquire()
        try:
            self._set_refresh_stage("settle_before_refresh")
            with self.lock:
                previous_output = self.output
                expected_save_identity = str(
                    getattr(self, "pending_save_identity", None) or ""
                )
            previous_market_output = (
                previous_output
                if (
                    reason not in {"cache_cleared", "storage_cleared"}
                    and str(previous_output.get("model_version") or "") == MODEL_VERSION
                )
                else {}
            )
            if previous_output.get("save_instance_id"):
                set_active_save_id(self._data_scope_id(previous_output))
            priority_settlement = (
                {"settled": 0, "settled_records": [], "returned": 0.0}
                if reason == "identity_change_full"
                else self._settle_results_before_refresh()
            )
            remember_committed(
                settled=int(priority_settlement.get("settled") or 0),
                returned=float(priority_settlement.get("returned") or 0.0),
            )
            if cancel_event and cancel_event.is_set():
                raise RuntimeError("refresh cancelled")
            odds_settings = load_settings()
            championship_enabled = bool(
                odds_settings.get("championship_enabled", True)
            )
            scope_favorite_team_ids = (
                set(load_favorite_team_ids())
                if str(odds_settings.get("odds_scope") or "") == "favorite_schedule"
                else None
            )
            hidden_competition_ids = set(load_hidden_competition_ids())
            with self._timed_memory_lock("odds_read"):
                self._set_refresh_stage("generate_odds")
                output = generate_all_odds(
                    int(odds_settings["odds_days"]),
                    required_result_keys=(
                        pending_result_keys() | pending_cup_final_result_keys(
                            str(previous_market_output.get("game_date") or ""),
                        )
                        if mode == "full" and reason != "identity_change_full" else None
                    ),
                    refresh_mode=mode,
                    previous_snapshot=previous_market_output or None,
                    preferred_save_id=(
                        previous_output.get("save_instance_id")
                        if previous_output and reason not in {
                            "save_change_full", "identity_change_full", "storage_cleared",
                        }
                        else None
                    ),
                    preferred_manager=(
                        previous_output.get("manager")
                        if previous_output and reason != "identity_change_full" else None
                    ),
                    preferred_managed_teams=(
                        previous_output.get("managed_teams")
                        if previous_output and reason != "identity_change_full" else None
                    ),
                    preferred_manager_options=(
                        previous_output.get("manager_options")
                        if previous_output and reason != "identity_change_full" else None
                    ),
                    competition_scope=str(odds_settings["odds_scope"]),
                    favorite_team_ids=scope_favorite_team_ids,
                    hidden_competition_ids=hidden_competition_ids,
                    force_fixture_scan=reason in {
                        "manual_fast", "manual_standings",
                        "schedule_change", "schedule_rollover",
                        "travel_complete", "settings_changed", "startup_odds",
                    },
                    # The validated fixture pool is save-local and complete after
                    # its containing slabs are reconciled. Forcing a whole-heap
                    # pass here can saturate FM long enough to drop a network save.
                    # scan_fixture_and_result_addresses still falls back to the
                    # bounded heap scan when the current build exposes no pool.
                    force_fixture_heap_scan=False,
                    cancel_check=(cancel_event.is_set if cancel_event else None),
                    progress_callback=self._publish_refresh_progress,
                    championship_enabled=championship_enabled or has_pending_championship_bets(),
                    discover_future_league_seasons=(
                        discover_future_league_seasons
                    ),
                    connection_context_verified=bool(
                        reason == "startup_odds"
                        and previous_output.get("connection_context_verified")
                    ),
                    yield_memory_lock=yield_refresh_memory_lock,
                )
                if reason == "identity_change_full":
                    observed_identity = str(output.get("save_instance_id") or "")
                    previous_identity = str(previous_output.get("save_instance_id") or "")
                    validate_identity_change_output(
                        previous_identity, expected_save_identity, observed_identity,
                    )
                needs_cross_save_full = fast_refresh_crossed_save(
                    previous_output, output,
                )
                if needs_cross_save_full:
                    # Never reuse early prices, schedule fallbacks or market
                    # caches across two confirmed save identities.
                    previous_market_output = {}
                needs_partial_recovery = suspicious_partial_schedule_refresh(
                    previous_market_output, output,
                )
                if reason in {"manual_fast", "manual_standings"} and (
                    needs_cross_save_full or needs_partial_recovery
                ):
                    raise RuntimeError(
                        "快速刷新结果与当前盘口不一致，已保留原盘口；请使用全量刷新"
                    )
                pool_reconcile_needs_heap = bool(
                    background
                    and mode == "full"
                    and reason == "background_reconcile"
                    and background_pool_reconcile_requires_heap(
                        previous_market_output, output,
                    )
                )
                if (
                    mode == "fast"
                    and (needs_cross_save_full or needs_partial_recovery)
                ) or pool_reconcile_needs_heap:
                    mode = "full"
                    reason = (
                        "save_change_full"
                        if needs_cross_save_full else "partial_schedule_full"
                    )
                    with self.lock:
                        self.refresh_mode = "full"
                        self.refresh_reason = reason
                        self.refresh_trace["mode"] = "full"
                        self.refresh_trace["reason"] = reason
                        self.refresh_cancel_on_clock_change = False
                        self.status = (
                            "检测到存档切换，正在完整读取新存档..."
                            if needs_cross_save_full
                            else "检测到赛程读取不完整，正在执行完整内存核对..."
                        )
                    output = generate_all_odds(
                        int(odds_settings["odds_days"]),
                        required_result_keys=None,
                        refresh_mode="full",
                        previous_snapshot=(
                            None if needs_cross_save_full else previous_market_output or None
                        ),
                        preferred_save_id=(
                            None if needs_cross_save_full
                            else previous_output.get("save_instance_id")
                        ),
                        preferred_manager=(
                            None if needs_cross_save_full
                            else previous_output.get("manager")
                        ),
                        preferred_managed_teams=(
                            None if needs_cross_save_full
                            else previous_output.get("managed_teams")
                        ),
                        preferred_manager_options=(
                            None if needs_cross_save_full
                            else previous_output.get("manager_options")
                        ),
                        competition_scope=str(odds_settings["odds_scope"]),
                        favorite_team_ids=scope_favorite_team_ids,
                        hidden_competition_ids=hidden_competition_ids,
                        force_fixture_scan=True,
                        force_fixture_heap_scan=False,
                        cancel_check=(cancel_event.is_set if cancel_event else None),
                        progress_callback=self._publish_refresh_progress,
                        championship_enabled=championship_enabled or has_pending_championship_bets(),
                        discover_future_league_seasons=(
                            discover_future_league_seasons
                        ),
                        connection_context_verified=bool(
                            reason == "startup_odds"
                            and previous_output.get("connection_context_verified")
                        ),
                        yield_memory_lock=yield_refresh_memory_lock,
                    )
                self._set_refresh_stage("validate_snapshot")
                raw_output = output
                match_intelligence_results = list(
                    raw_output.pop("_match_intelligence_results", []) or []
                )
                if mode == "fast" and suspicious_empty_schedule_refresh(
                    previous_market_output, raw_output,
                ):
                    raise RuntimeError(
                        "盘口读取结果异常为空，已保留上次盘口，请稍后重试"
                    )
                output = preserve_previous_schedule_after_empty_read(
                    previous_market_output, raw_output,
                )
                self._apply_unemployed_confirmation_state(output, previous_output)
                if str(output.get("game_layout") or "") in {"fm24", "fm26"}:
                    context_valid, context_reason = manager_team_context_status(output)
                    if not context_valid:
                        detail = {
                            "manager_missing": "尚未定位当前人类经理对象",
                            "managed_team_missing": "尚未定位当前经理的执教球队",
                        }.get(context_reason, "经理与执教球队信息不完整")
                        raise RuntimeError(
                            f"已识别当前存档，但{detail}；请等待存档完全载入后重新连接"
                        )
                self._assign_account_scope(output, previous_output)
                prepare_early_market_prices(output, previous_market_output)
                attach_historical_market_snapshots(output, previous_market_output)
                if cancel_event and cancel_event.is_set():
                    raise RuntimeError("refresh cancelled")
                remember_active_save_id(self._data_scope_id(output))
                completed_results = result_payload(output)
                schedule_refund = {"refunded": 0, "returned": 0.0, "records": []}
                if mode == "full":
                    schedule_changes = detected_pending_schedule_changes(
                        previous_market_output, raw_output, completed_results,
                    )
                    schedule_refund = refund_pending_schedule_changes(schedule_changes)
                    remember_committed(
                        returned=float(schedule_refund.get("returned") or 0.0),
                        schedule_refunded=int(schedule_refund.get("refunded") or 0),
                    )
                    if schedule_refund.get("records"):
                        archive_schedule_refund_mail(schedule_refund["records"])
                same_day_keys: set[tuple[str, int, int, int]] = set()
                if getattr(self, "live_match_seen_active", False):
                    try:
                        if not read_match_engine_state().get("active"):
                            same_day_keys = disappeared_same_day_result_keys(
                                previous_market_output, raw_output, completed_results,
                            )
                    except Exception:
                        same_day_keys = set()
            self._set_refresh_stage("settle_bets")
            try:
                settlement_hour, settlement_minute = str(
                    output.get("game_time") or ""
                ).split(":", 1)
                settlement_game_minutes = (
                    int(settlement_hour) * 60 + int(settlement_minute)
                )
            except (TypeError, ValueError):
                settlement_game_minutes = None
            settlement = settle_pending_bets(
                completed_results, output["game_date"],
                game_minutes=settlement_game_minutes,
                trusted_same_day_keys=same_day_keys,
                void_missing_after_timeout=True,
            )
            remember_committed(
                settled=int(settlement.get("settled") or 0),
                returned=float(settlement.get("returned") or 0.0),
            )
            if same_day_keys:
                with self.lock:
                    self.live_match_seen_active = False
            self._finalize_settlement(settlement, output)
            if schedule_refund.get("refunded"):
                settlement["schedule_refunded"] = int(schedule_refund["refunded"])
                settlement["settled"] = int(settlement.get("settled") or 0) + int(
                    schedule_refund["refunded"]
                )
                settlement["returned"] = round(
                    float(settlement.get("returned") or 0.0)
                    + float(schedule_refund.get("returned") or 0.0), 2,
                )
            if priority_settlement.get("settled"):
                settlement["settled"] += int(priority_settlement["settled"])
                settlement["settled_records"] = [
                    *priority_settlement.get("settled_records", []),
                    *settlement.get("settled_records", []),
                ]
                settlement["returned"] = round(
                    float(priority_settlement.get("returned", 0.0))
                    + float(settlement.get("returned", 0.0)), 2,
                )
            if championship_enabled or has_pending_championship_bets():
                self._set_refresh_stage("championship_markets")
                championship_markets, _championship_cache_hit = (
                    publish_championship_markets(output, previous_market_output)
                )
                championship_settlement = settle_championship_bets(
                    championship_markets,
                )
                remember_committed(
                    settled=int(championship_settlement.get("settled") or 0),
                    returned=float(championship_settlement.get("returned") or 0.0),
                )
                championship_records = championship_settlement.get(
                    "settled_records", [],
                )
                if championship_records:
                    archive_winning_mail(championship_records)
                    settlement["settled_records"] = [
                        *settlement.get("settled_records", []),
                        *championship_records,
                    ]
                if championship_settlement.get("settled"):
                    settlement["settled"] += int(championship_settlement["settled"])
                    settlement["returned"] = round(
                        float(settlement.get("returned", 0.0))
                        + float(championship_settlement.get("returned", 0.0)), 2,
                    )
            else:
                output.pop("championship_markets", None)
            if cancel_event and cancel_event.is_set():
                raise RuntimeError("refresh cancelled")
            manager = output.get("manager") or {}
            with self._timed_memory_lock("club_effects"):
                self._set_refresh_stage("club_context")
                managed_team = output.get("managed_team") or {}
                managed_teams = managed_team_rows(output)
                club_contexts = {}
                if manager.get("id"):
                    for team in managed_teams:
                        if not team.get("id"):
                            continue
                        try:
                            context = read_club_context(
                                int(manager["id"]), int(team["id"]),
                                team_address=team.get("address"),
                                manager_address=team.get("manager_address") or manager.get("manager_address"),
                            )
                            context["team"]["team_type"] = team.get("team_type") or "club"
                            club_contexts[int(team["id"])] = context
                        except Exception:
                            continue
                club_context = club_contexts.get(int(managed_team.get("id") or 0))
                preloaded_profiles: dict[int, dict[str, Any]] = {}
                preload_errors: list[str] = []
                # Pre-V1.4 refresh behaviour: odds/results finish independently.
                # Full player, staff and contract profiles are loaded only when
                # the user opens My Team or explicitly refreshes that page.
                # A successful refresh should warm the managed-team profile
                # cache only when its manager/team/date contract is stale.
                # Re-reading a current profile after every automatic odds
                # refresh blocks unrelated foreground actions behind a full
                # player/staff scan and can create a visible refresh loop.
                with self.lock:
                    current_club_profiles = dict(self.club_profiles)
                deferred_club_refresh = (
                    should_refresh_club_profiles_after_refresh(
                        manager, managed_teams,
                    )
                    and not managed_club_profiles_are_current(
                        manager, managed_teams, current_club_profiles,
                        str(output.get("game_date") or ""),
                    )
                )
                salary_result = {"paid": 0, "amount": 0.0}
                gross_weekly_salary = self._total_weekly_salary(club_contexts)
                if gross_weekly_salary > 0:
                    salary_result = process_salary_payments(
                        output["game_date"], gross_weekly_salary,
                    )
                    archive_salary_payment_mail(salary_result.get("new_payments", []))
                    credit_result = process_credit_due(output["game_date"], gross_weekly_salary)
                    if credit_result.get("defaulted"):
                        penalty_profiles = list(self.club_profiles.values())
                        if not penalty_profiles and manager.get("id"):
                            for team in managed_teams:
                                try:
                                    penalty_profiles.append(read_club_profile(
                                        int(manager["id"]), int(team["id"]),
                                        team_address=team.get("address"),
                                        manager_address=team.get("manager_address") or manager.get("manager_address"),
                                    ))
                                except Exception:
                                    continue
                        penalty_players = [
                            player
                            for profile in penalty_profiles
                            for player in (profile.get("players") or [])
                        ]
                        try:
                            credit_result["penalty"] = apply_credit_default_penalty(
                                penalty_players,
                                float(credit_result.get("unpaid") or 0),
                                float(credit_result.get("loan_amount") or 0),
                            )
                            record_credit_default_notice(
                                credit_result["penalty"], output["game_date"],
                            )
                        except Exception as error:
                            credit_result["penalty_error"] = str(error)
                            preload_errors.append(f"违约处罚同步失败: {error}")
                else:
                    credit_result = {"due": False, "defaulted": False}
                legacy_integrity_penalty = (
                    audit_legacy_bets(output, manager_display_name(output), gross_weekly_salary)
                    if not load_settings().get("disable_fa_penalties") else None
                )
                if legacy_integrity_penalty:
                    settlement["integrity_penalty"] = legacy_integrity_penalty
                fixture_index = self._fixture_index(output)
                self._set_refresh_stage("effects_and_economy")
                reconcile_inventory(
                    output["game_date"], fixture_index, activate_referee=False,
                )
                doping_status = sync_doping_effects(active_doping_items())
                goalkeeper_status = sync_goalkeeper_bribes(active_goalkeeper_bribes())
                hook_status = self.redbull_hook.sync(
                    active_player_ids(), goalkeeper_status.get("player_ids", []),
                )
                if goalkeeper_status.get("player_ids") and hook_status.get("error"):
                    goalkeeper_status.setdefault("errors", []).append(str(hook_status["error"]))
                self._remember_fixture_effect_status(doping_status, goalkeeper_status)
                if hook_status.get("error"):
                    refund_active_sku("red_bull", str(hook_status["error"]))
                    refund_active_sku("team_red_bull", str(hook_status["error"]))
                    self.redbull_hook.sync([], goalkeeper_status.get("player_ids", []))
                team_address = self._club_team_address(club_context)
                club_address = self._club_address(club_context)
                self._sync_referee_fixture_hook(
                    str(output.get("game_date") or ""), club_contexts, output,
                )
                effects = set(active_effect_skus())
                self.simple_effects.sync(effects)
                self._sync_owned_club_board_hook(output)
                self.canteen_plan = canteen_plan()
                self._sync_ca_growth_hook(
                    effects, team_address, club_address,
                    managed_team_address(output, "national"),
                )
                self.team_nuclear_hooks.sync(effects, team_address, club_address)
                roster_profile = (
                    preloaded_profiles.get(int(managed_team.get("id") or 0))
                    or matching_manager_team_profile(
                        self.club_profile,
                        int(manager.get("id") or 0),
                        int(managed_team.get("id") or 0),
                    )
                )
                if (
                    effects & ROSTER_EFFECTS and roster_profile is None
                    and manager.get("id") and managed_team.get("id")
                ):
                    try:
                        roster_profile = read_club_profile(
                            int(manager["id"]), int(managed_team["id"]),
                            team_address=managed_team.get("address"),
                            manager_address=(
                                managed_team.get("manager_address")
                                or manager.get("manager_address")
                            ),
                        )
                    except Exception as error:
                        self.roster_effect_errors = {
                            sku: str(error) for sku in effects & ROSTER_EFFECTS
                        }
                        preload_errors.append(f"阵容效果同步失败: {error}")
                if roster_profile is not None or not (effects & ROSTER_EFFECTS):
                    self.roster_effect_errors = apply_roster_effects(roster_profile, effects)
                if mode == "full" and output.get("fixture_scan_mode") in {"heap", "pool"}:
                    output["full_verified_at"] = datetime.now().isoformat(timespec="seconds")
                elif previous_market_output.get("full_verified_at"):
                    output["full_verified_at"] = previous_market_output["full_verified_at"]
            if cancel_event and cancel_event.is_set():
                raise RuntimeError("refresh cancelled")
            stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
            self._set_refresh_stage("persist_snapshot")
            path = cache_data_root() / "odds" / "live" / f"fm26_all_odds_{output['game_date']}_{stamp}.json"
            save_odds(output, path)
            archive_season_output(output)
            retention = (
                apply_storage_retention(
                    output["game_date"], output.get("save_instance_id"), path,
                    protected_result_keys=pending_result_keys(),
                    protected_odds_paths=pending_snapshot_paths(),
                )
                if mode == "full" else {
                    "odds_files": 0,
                    "results": 0,
                    **enforce_storage_budget(
                        protected_paths={path, *pending_snapshot_paths()},
                    ),
                }
            )
            duration = float(output.get("performance", {}).get("total_ms", 0)) / 1000
            if background:
                old_keys = set(self._fixture_index(previous_output))
                new_keys = set(self._fixture_index(output))
                status = f"后台核对完成，新增 {len(new_keys - old_keys)} 场、移除 {len(old_keys - new_keys)} 场"
            else:
                status = f"{'完整' if mode == 'full' else '快速'}更新 {len(output['matches'])} 场"
            if duration:
                status += f"，耗时 {duration:.1f} 秒"
            if settlement["settled"]:
                status += f"，结算 {settlement['settled']} 笔"
            if salary_result.get("paid"):
                status += f"，工资存入银行 {configured_money(salary_result['amount'])}"
            if credit_result.get("defaulted"):
                status += "，花呗到期且余额不足"
            if retention["odds_files"] or retention["results"]:
                status += f"，清理 {retention['odds_files']} 份盘口、{retention['results']} 场旧赛果"
            save_label = output.get("save_name") or (
                f"存档 {output['save_instance_id']}" if output.get("save_instance_id") else None
            )
            if managed_team and save_label:
                status += f"，已确认 {save_label} · {managed_team['name']}"
            elif managed_team:
                status += f"，已确认执教队伍 · {managed_team['name']}"
            elif output.get("unemployed_confirmed"):
                status += f"，已确认 {manager.get('name') or '当前经理'} 处于无业状态"
            else:
                status += "，未确认当前存档的执教队伍"
            self._release_training_users_for_club_change(
                previous_output, output,
            )
            self._set_refresh_stage("publish_snapshot")
            with self.lock:
                current_team_ids = {int(item.get("id") or 0) for item in managed_teams}
                if self.club_profiles:
                    self.club_profiles = {
                        team_id: profile for team_id, profile in self.club_profiles.items()
                        if team_id in current_team_ids
                        and int((profile.get("manager") or {}).get("id") or 0) == int(manager.get("id") or 0)
                    }
                if self.club_profile:
                    profile_team = int((self.club_profile.get("team") or {}).get("id") or 0)
                    profile_manager = int((self.club_profile.get("manager") or {}).get("id") or 0)
                    if profile_team != int(managed_team.get("id") or 0) or profile_manager != int(manager.get("id") or 0):
                        self.club_profile = None
                        self.club_last_updated = None
                self.output = output
                self.match_intelligence_results = match_intelligence_results
                self.output_path = path
                self.cache_verified = True
                self.connection_save_id = str(output.get("save_instance_id") or "") or None
                self.connection_scope_id = self._data_scope_id(output) or None
                self.wallet_ready = bool(self.connection_scope_id)
                self.data_version += 1
                self.club_context = club_context
                self.club_contexts = club_contexts
                self.last_game_date = output["game_date"]
                if mode == "full":
                    self.last_result_refresh_date = output["game_date"]
                self.salary_last_processed_date = output["game_date"]
                if reason in {"startup", "save_change_full", "identity_change_full"}:
                    self.save_change_pending = False
                    self.pending_save_identity = None
                self.status = status
                self.error = None
                self.last_refresh_error_stage = None
                self.last_refresh_traceback = None
                self.last_refresh_partial_result = None
            succeeded = True
        except Exception as error:
            failure_message = str(error)
            error_traceback = traceback.format_exc()
            failed_stage = getattr(self, "refresh_stage", None)
            with self.lock:
                self.last_refresh_error_stage = failed_stage
                self.last_refresh_traceback = error_traceback[-6000:]
                if str(error) == "refresh cancelled":
                    self.status = (
                        "已暂停自动刷新，优先读取俱乐部资料"
                        if getattr(self, "refresh_cancel_reason", None) == "club_priority"
                        else "游戏时间变化，已停止刷新"
                    )
                    self.error = None
                    self.last_refresh_error_stage = None
                    self.last_refresh_traceback = None
                elif reason == "startup_odds":
                    # The save/player handshake completed before odds work.
                    # Keep that verified context and the last usable markets;
                    # only the startup odds refresh is considered failed.
                    self.cache_verified = bool(
                        previous_output.get("save_instance_id")
                    )
                    self.status = f"已连接当前存档，启动盘口刷新失败：{error}"
                    self.error = str(error)
                elif background:
                    self.status = f"快速更新已完成，后台核对失败：{error}"
                elif reason == "identity_change_full":
                    self.cache_verified = bool(previous_output.get("save_instance_id"))
                    self.save_change_pending = False
                    self.pending_save_identity = None
                    self.status = "存档身份验证未通过，已保留当前存档"
                    self.error = str(error)
                else:
                    startup_connection = reason in {"startup", "startup_cache_stale"}
                    stage_suffix = (
                        f"（阶段：{self.last_refresh_error_stage}）"
                        if self.last_refresh_error_stage else ""
                    )
                    self.error = (
                        f"无法读取当前存档，请确认 Football Manager 已进入存档后重试：{error}{stage_suffix}"
                        if startup_connection else str(error)
                    )
                    self.status = "连接存档失败" if startup_connection else "刷新失败"
                if (
                    int(committed_result["settled"])
                    or int(committed_result["schedule_refunded"])
                    or float(committed_result["returned"])
                ):
                    self.last_refresh_partial_result = {
                        **committed_result,
                        "failed_stage": failed_stage,
                        "snapshot_published": False,
                    }
                    completed_parts = []
                    if committed_result["settled"]:
                        completed_parts.append(
                            f"结算 {int(committed_result['settled'])} 笔"
                        )
                    if committed_result["schedule_refunded"]:
                        completed_parts.append(
                            f"赛程退款 {int(committed_result['schedule_refunded'])} 笔"
                        )
                    if not completed_parts and committed_result["returned"]:
                        completed_parts.append("账户金额变更")
                    self.status += "；刷新失败前已完成" + "、".join(completed_parts)
                else:
                    self.last_refresh_partial_result = None
        finally:
            try:
                self._finish_refresh_trace(succeeded, failure_message)
            except Exception:
                pass
            finally:
                with self.lock:
                    if background:
                        self.reconciling = False
                    else:
                        self.refreshing = False
                    self.refresh_mode = None
                    if self.refresh_cancel_event is cancel_event:
                        self.refresh_reason = None
                        self.refresh_cancel_event = None
                        self.refresh_cancel_on_clock_change = False
                    self.refresh_cancel_reason = None
                    self.refresh_stage = None
        with self.lock:
            pending_club_refresh = bool(
                getattr(self, "club_refresh_pending", False)
                and not self.club_refreshing
            )
            if pending_club_refresh:
                self.club_refresh_pending = False
        if pending_club_refresh:
            try:
                self.refresh_club_async()
            except Exception as error:
                with self.lock:
                    self.club_error = f"连接完成，但当前执教队伍资料读取失败：{error}"
        if succeeded:
            self._start_post_publish_maintenance(
                output,
                reconcile_owned_customizations=reason in {
                    "startup", "startup_odds", "startup_cache_stale",
                    "connect_save", "save_change_full", "identity_change_full",
                },
            )
        immediate_reconcile_reasons = {
            "schedule_change", "schedule_rollover", "travel_complete",
            "settings_changed", "startup_cache_stale",
        }
        should_reconcile = bool(
            succeeded and mode == "fast" and not background
            and reason not in {"manager_change_schedule", "manual_fast"}
            and reason in immediate_reconcile_reasons
        )
        if should_reconcile:
            self._start_reconcile(cancel_on_clock_change=True)
        if succeeded and (deferred_club_refresh or not should_reconcile):
            # Let the refresh transaction and any immediate reconcile finish
            # before starting the optional club/world data warm-up.
            self._schedule_idle_data_prewarm()

    def watch_game_date(self) -> None:
        identity_checks = 0
        identity_candidate: str | None = None
        identity_confirmations = 0
        manager_context_candidate_key: tuple[Any, ...] | None = None
        manager_context_confirmations = 0
        last_clock: tuple[str, int] | None = None
        stable_since = monotonic()
        forward_changes: list[float] = []
        traveling = False
        rollback_candidate: tuple[tuple[str, int], tuple[str, int]] | None = None
        while True:
            with self.lock:
                connection_ready = bool(
                    self.connection_requested and self._has_verified_save()
                )
                discover_player_match = fixture_at_game_clock(
                    self.output, getattr(self, "last_connection_clock", None),
                )
            if not connection_ready:
                sleep(1)
                continue
            try:
                runtime_probe_started_at = perf_counter()
                runtime_state = self._run_memory_operation_if_idle(
                    lambda: read_game_runtime_state(
                        discover_match_playback=True,
                        discover_large_match_playback=discover_player_match,
                    ),
                )
                self._record_background_probe_metric(
                    "runtime_state_ms", runtime_probe_started_at,
                )
                if runtime_state is None:
                    # Clock reads have priority over long-running read-only scans.
                    # Reading the packed date value is intentionally allowed to
                    # bypass memory_lock; all wider runtime/identity work still
                    # waits for the owning transaction to finish.
                    game_clock = read_game_clock()
                    clock_key = (
                        str(game_clock["date"]), int(game_clock["minutes"]),
                    )
                    self._note_connection_liveness(game_clock, True)
                    # Keep fixture-bound memory effects in sync even while the
                    # wider runtime probe is temporarily unavailable.  This
                    # includes restoring expired doping snapshots after the
                    # game advances to the next date.
                    self._sync_fixture_items_for_clock(game_clock)
                    if last_clock is None:
                        last_clock = clock_key
                        stable_since = monotonic()
                        self.last_auto_refresh_clock = clock_key
                    elif clock_key != last_clock:
                        with self.lock:
                            if (
                                self.refresh_cancel_on_clock_change
                                and self.refresh_cancel_event
                            ):
                                self.refresh_cancel_event.set()
                                self.status = "游戏时间变化，正在停止本次刷新..."
                    # Keep last_clock unchanged after a busy-period change. Once
                    # the scan releases memory_lock, the normal path observes the
                    # transition and runs all date-change lifecycle work exactly
                    # once against the latest clock.
                    sleep(1)
                    continue
                game_clock, engine_state = runtime_state
                clock_key = (str(game_clock["date"]), int(game_clock["minutes"]))
                now = monotonic()
                self._note_connection_liveness(game_clock, True)
                # The clock watcher is the lightweight lifecycle owner for
                # fixture items; full odds refreshes are not guaranteed to run
                # after every match or game-day transition.
                self._sync_fixture_items_for_clock(game_clock)
                self._note_betting_match_engine_state(game_clock, engine_state)
                with self.lock:
                    self.match_engine_runtime_state = dict(engine_state)
                    if engine_state.get("active"):
                        self.live_match_seen_active = True
                if engine_state.get("known") and engine_state.get("active"):
                    last_clock = clock_key
                    stable_since = now
                    forward_changes.clear()
                    traveling = False
                    rollback_candidate = None
                    sleep(1)
                    continue
                try:
                    self._process_monthly_club_dividends_if_due(clock_key[0])
                except Exception as error:
                    with self.lock:
                        self.last_operation_error = str(error).strip() or type(error).__name__
                        self.last_operation_error_type = type(error).__name__
                        self.last_operation_error_stage = "club_dividend"
                        self.last_operation_traceback = traceback.format_exc()[-6000:]
                auto_refresh_seconds = int(getattr(self, "odds_auto_refresh_seconds", 8))
                clock_changed = last_clock is not None and clock_key != last_clock
                if last_clock is None:
                    last_clock = clock_key
                    stable_since = now
                    self.last_auto_refresh_clock = clock_key
                elif clock_changed:
                    previous_clock = last_clock
                    last_clock = clock_key
                    stable_since = now
                    self._reconcile_youth_generation_if_due(now, force=True)
                    if clock_key[0] != previous_clock[0]:
                        try:
                            with self._timed_memory_lock("owned_facility_plan_sync"):
                                self._advance_owned_club_facility_plans(clock_key[0])
                        except Exception as error:
                            with self.lock:
                                self.last_operation_error = str(error).strip() or type(error).__name__
                                self.last_operation_error_type = type(error).__name__
                                self.last_operation_error_stage = "owned_facility_plan"
                                self.last_operation_traceback = traceback.format_exc()[-6000:]
                        try:
                            self._process_manager_salary_for_date(clock_key[0])
                        except Exception as error:
                            with self.lock:
                                self.last_operation_error = str(error).strip() or type(error).__name__
                                self.last_operation_error_type = type(error).__name__
                                self.last_operation_error_stage = "manager_salary"
                                self.last_operation_traceback = traceback.format_exc()[-6000:]
                        self._request_training_settlement(clock_key[0])
                    try:
                        previous_value = (
                            datetime.fromisoformat(previous_clock[0]).toordinal() * 24 * 60
                            + int(previous_clock[1])
                        )
                        current_value = (
                            datetime.fromisoformat(clock_key[0]).toordinal() * 24 * 60
                            + int(clock_key[1])
                        )
                    except (TypeError, ValueError):
                        previous_value = current_value = 0
                    if current_value > previous_value:
                        rollback_candidate = None
                        forward_changes = [
                            changed_at for changed_at in forward_changes
                            if now - changed_at <= TRAVEL_CHANGE_WINDOW_SECONDS
                        ]
                        forward_changes.append(now)
                        if len(forward_changes) >= TRAVEL_CHANGE_THRESHOLD:
                            traveling = True
                    else:
                        forward_changes.clear()
                        if current_value < previous_value:
                            rollback_candidate = (previous_clock, clock_key)
                    with self.lock:
                        if self.refresh_cancel_on_clock_change and self.refresh_cancel_event:
                            self.refresh_cancel_event.set()
                            self.status = "游戏时间变化，正在停止本次刷新..."
                        if traveling:
                            self.status = "检测到连续旅行，等待游戏时间稳定..."
                elif not traveling:
                    forward_changes = [
                        changed_at for changed_at in forward_changes
                        if now - changed_at <= TRAVEL_CHANGE_WINDOW_SECONDS
                    ]
                self._reconcile_youth_generation_if_due(now)
                if (
                    rollback_candidate
                    and clock_key == rollback_candidate[1]
                    and now - stable_since >= 0.8
                ):
                    previous_clock, rollback_clock = rollback_candidate
                    rollback_candidate = None
                    self._reapply_rewound_transfer_budget(previous_clock, rollback_clock)
                    with self.memory_lock:
                        self._sync_owned_club_board_hook(self.output)
                with self.lock:
                    known_identity = self.output.get("save_instance_id")
                identity_checks += 1
                identity_changed = False
                refreshed_manager_context = None
                if identity_checks >= 10:
                    identity_checks = 0
                    identity_probe_started_at = perf_counter()
                    identity_read, current_identity = self._read_save_identity_when_idle()
                    self._record_background_probe_metric(
                        "save_identity_ms", identity_probe_started_at,
                    )
                    if not identity_read:
                        identity_checks = 9
                    else:
                        (
                            identity_candidate,
                            identity_confirmations,
                            identity_changed,
                        ) = advance_identity_change_confirmation(
                            str(known_identity) if known_identity else None,
                            str(current_identity) if current_identity else None,
                            identity_candidate,
                            identity_confirmations,
                        )
                        if identity_candidate:
                            identity_verification_started = self._mark_save_identity_candidate(
                                identity_candidate, identity_changed,
                            )
                        else:
                            identity_verification_started = False
                    if identity_read and not identity_changed and not identity_candidate:
                        with self.lock:
                            current_output = dict(self.output)
                            manager_id = int(
                                current_output.get("selected_manager_id")
                                or (current_output.get("manager") or {}).get("id")
                                or 0
                            )
                            save_id = str(current_output.get("save_instance_id") or "")
                            busy = bool(
                                self.refreshing or self.reconciling or self.club_refreshing
                                or self.save_change_pending
                            )
                        if (
                            manager_id > 0 and save_id and not busy
                            and self.memory_lock.acquire(blocking=False)
                        ):
                            try:
                                known_session = next((
                                    dict(item)
                                    for item in current_output.get("manager_options", [])
                                    if int(item.get("id") or 0) == manager_id
                                ), None)
                                manager_probe_started_at = perf_counter()
                                candidate = read_manager_context(
                                    manager_id, preferred_save_id=save_id,
                                    known_session=known_session,
                                    known_manager_sessions=list(
                                        current_output.get("manager_options") or []
                                    ),
                                )
                                self._record_background_probe_metric(
                                    "manager_context_ms", manager_probe_started_at,
                                )
                                assignments_changed = manager_assignment_context_changed(
                                    current_output, candidate,
                                )
                                options_changed = manager_options_changed(current_output, candidate)
                                authoritative_assignments = bool(
                                    managed_team_identities(candidate)
                                    or candidate.get("unemployed_manager_detected")
                                )
                                if assignments_changed and not authoritative_assignments:
                                    manager_context_candidate_key = None
                                    manager_context_confirmations = 0
                                elif assignments_changed or options_changed:
                                    needs_confirmation = manager_assignment_absence_requires_confirmation(
                                        current_output, candidate,
                                    )
                                    candidate_key = manager_context_confirmation_key(candidate)
                                    if needs_confirmation:
                                        if candidate_key == manager_context_candidate_key:
                                            manager_context_confirmations += 1
                                        else:
                                            manager_context_candidate_key = candidate_key
                                            manager_context_confirmations = 1
                                        with self.lock:
                                            self.manager_context_absence_pending = True
                                            self.status = "检测到经理可能离开当前任职，正在再次确认..."
                                        if (
                                            manager_context_confirmations
                                            >= MANAGER_ASSIGNMENT_ABSENCE_CONFIRMATIONS
                                        ):
                                            candidate["_manager_options_only"] = False
                                            refreshed_manager_context = candidate
                                            manager_context_candidate_key = None
                                            manager_context_confirmations = 0
                                    else:
                                        manager_context_candidate_key = None
                                        manager_context_confirmations = 0
                                        with self.lock:
                                            self.manager_context_absence_pending = False
                                        if manager_club_change_requires_confirmation(
                                            current_output, candidate,
                                        ):
                                            self._queue_manager_club_change_confirmation(
                                                current_output, candidate,
                                            )
                                        else:
                                            candidate["_manager_options_only"] = (
                                                options_changed and not assignments_changed
                                            )
                                            refreshed_manager_context = candidate
                                else:
                                    manager_context_candidate_key = None
                                    manager_context_confirmations = 0
                                    with self.lock:
                                        self.pending_manager_club_change = None
                                        self.declined_manager_club_change_key = None
                                        if self.manager_context_absence_pending:
                                            self.manager_context_absence_pending = False
                                            self.status = "经理任职读取已恢复，继续沿用当前盘口"
                            except Exception:
                                refreshed_manager_context = None
                            finally:
                                self.memory_lock.release()
                if identity_changed:
                    with self.lock:
                        self.pending_manager_club_change = None
                        self.declined_manager_club_change_key = None
                    if identity_verification_started:
                        self.last_auto_refresh_clock = None
                        identity_candidate = None
                        identity_confirmations = 0
                elif refreshed_manager_context is not None:
                    if self._start_manager_team_context_refresh(refreshed_manager_context):
                        self.last_auto_refresh_clock = None
                elif (
                    auto_refresh_seconds > 0
                    and traveling
                    and not self.save_change_pending
                    and now - stable_since >= auto_refresh_seconds
                ):
                    schedule_probe = self._probe_schedule_change(clock_key)
                    if schedule_probe == "pending":
                        sleep(1)
                        continue
                    if schedule_probe == "triggered":
                        traveling = False
                        forward_changes.clear()
                        self.last_auto_refresh_clock = clock_key
                        sleep(1)
                        continue
                    with self.lock:
                        schedule_rollover = self._schedule_window_needs_refresh(
                            self.output, clock_key[0],
                        )
                    if self.refresh_async(
                        "schedule_rollover" if schedule_rollover else "travel_complete",
                        full=False,
                        cancel_on_clock_change=True,
                    ):
                        traveling = False
                        forward_changes.clear()
                        self.last_auto_refresh_clock = clock_key
                elif (
                    auto_refresh_seconds > 0
                    and not traveling
                    and not self.save_change_pending
                    and now - stable_since >= auto_refresh_seconds
                ):
                    with self.lock:
                        schedule_rollover = self._schedule_window_needs_refresh(
                            self.output, clock_key[0],
                        )
                    if self.last_auto_refresh_clock != clock_key or schedule_rollover:
                        schedule_probe = self._probe_schedule_change(clock_key)
                        if schedule_probe in {"pending", "triggered"}:
                            sleep(1)
                            continue
                        if self.refresh_async(
                            "schedule_rollover" if schedule_rollover else "game_clock_stable",
                            full=False,
                            cancel_on_clock_change=True,
                        ):
                            self.last_auto_refresh_clock = clock_key
            except Exception:
                try:
                    game_versions = process_selection_status()
                    with self.lock:
                        self.last_process_selection_status = dict(game_versions)
                    self._note_connection_liveness(
                        None, self._connected_process_available(game_versions),
                    )
                except Exception:
                    pass
            sleep(1)

    @staticmethod
    def _live_result_key(item: dict[str, Any]) -> tuple[str, int, int, int]:
        return (
            str(item["date"]), int(item["competition"]["id"]),
            int(item["home_team"]["id"]), int(item["away_team"]["id"]),
        )

    def watch_live_settlement(self) -> None:
        """Settle stable completed results after their scheduled match-ending time."""
        while True:
            sleep(LIVE_SETTLEMENT_POLL_SECONDS)
            try:
                with self.lock:
                    if not self.connection_requested:
                        continue
                    output = dict(self.output)
                    busy = bool(self.refreshing or self.reconciling or self.save_change_pending)
                if busy:
                    continue
                save_id = output.get("save_instance_id")
                if not save_id:
                    continue
                set_active_save_id(self._data_scope_id(output))
                clock = read_game_clock()
                pending_keys = pending_result_keys()
                due_keys = pending_due_result_keys(str(clock["date"]), int(clock["minutes"]))
                try:
                    engine_state = read_match_engine_state()
                except Exception:
                    engine_state = None
                if engine_state and engine_state.get("active"):
                    with self.lock:
                        self.live_match_seen_active = True
                        self.live_settlement_status["settlement_paused_for_match"] = True
                    continue
                with self.lock:
                    self.live_settlement_status["settlement_paused_for_match"] = False
                    match_seen_active = bool(self.live_match_seen_active)
                    captured_keys = set(self.live_captured_result_keys)
                historical_due_keys = settlement_keys_safe_for_engine_state(
                    due_keys, str(clock["date"]), engine_state,
                )
                captured_same_day_keys = captured_same_day_result_keys(
                    due_keys,
                    str(clock["date"]),
                    str(save_id),
                    engine_state,
                    match_seen_active,
                    captured_keys,
                )
                due_keys = historical_due_keys | captured_same_day_keys
                with self.lock:
                    self.live_settlement_status.update({
                        "monitoring": bool(pending_keys),
                        "due_matches": len(due_keys),
                        "error": None,
                    })
                if not due_keys:
                    with self.lock:
                        self.live_settlement_status["missing_results"] = 0
                        self.live_settlement_recovery_attempts.clear()
                    continue
                if not self.memory_lock.acquire(timeout=1.0):
                    continue
                try:
                    probe = probe_live_completed_results(
                        due_keys,
                        fixture_hints=pending_result_fixture_hints(due_keys),
                    )
                finally:
                    self.memory_lock.release()
                confirmed_results = []
                for result in probe.get("results", []):
                    key = self._live_result_key(result)
                    signature = (int(result["home_goals"]), int(result["away_goals"]))
                    previous = self.live_settlement_candidates.get(key)
                    confirmations = (
                        int(previous.get("confirmations", 0)) + 1
                        if previous and previous.get("signature") == signature else 1
                    )
                    candidate = {
                        "signature": signature,
                        "confirmations": confirmations,
                        "result": result,
                    }
                    self.live_settlement_candidates[key] = candidate
                    if confirmations >= LIVE_SETTLEMENT_CONFIRMATIONS:
                        confirmed_results.append(result)
                observed_keys = {
                    self._live_result_key(item) for item in probe.get("results", [])
                    if item.get("settlement_verified") is True
                }
                recovered_results = self._recover_missing_live_results(
                    due_keys, observed_keys,
                )
                if recovered_results:
                    confirmed_results.extend(recovered_results)
                confirmed_by_key = {
                    self._live_result_key(item): item for item in confirmed_results
                }
                confirmed_results = list(confirmed_by_key.values())
                settlement = {"settled": 0, "settled_records": [], "returned": 0.0}
                if confirmed_results:
                    trusted_keys = {self._live_result_key(item) for item in confirmed_results}
                    settlement = settle_pending_bets(
                        confirmed_results, str(clock["date"]),
                        game_minutes=int(clock["minutes"]),
                        trusted_same_day_keys=trusted_keys,
                    )
                    self._finalize_settlement(settlement, output)
                with self.lock:
                    if settlement.get("settled"):
                        self.last_background_settled = int(settlement["settled"])
                        self.live_settlement_status["confirmed_count"] = int(
                            self.live_settlement_status.get("confirmed_count", 0)
                        ) + int(settlement["settled"])
                        self.live_settlement_status["last_confirmed"] = {
                            "settled": int(settlement["settled"]),
                            "returned": float(settlement.get("returned", 0.0)),
                            "confirmed_at": datetime.now().isoformat(timespec="seconds"),
                        }
                    self.live_settlement_status.update({
                        "last_checked": datetime.now().isoformat(timespec="seconds"),
                        "region_count": int(probe.get("region_count", 0)),
                        "bytes_scanned": int(probe.get("bytes_scanned", 0)),
                        "changed_objects": int(probe.get("changed_objects", 0)),
                        "error": None,
                    })
            except Exception as error:
                with self.lock:
                    self.live_settlement_status["error"] = str(error)

    def watch_live_result_capture(self) -> None:
        """Persist short-lived FM result details before its pool is reused.

        FM24 can discard goal events shortly after a background-simulated
        fixture.  Poll only while a pending leg is close to kickoff, scan the
        already discovered result slab, and persist any internally consistent
        half-time details immediately.  Settlement remains in the slower,
        double-confirmed worker above.
        """
        reader_context = None
        reader = None
        reader_layout = None
        reader_save_id = ""
        poll_seconds = LIVE_RESULT_CAPTURE_IDLE_POLL_SECONDS
        while True:
            sleep(poll_seconds)
            poll_seconds = LIVE_RESULT_CAPTURE_IDLE_POLL_SECONDS
            try:
                with self.lock:
                    if not self.connection_requested:
                        continue
                    output = dict(self.output)
                    game_clock = (
                        dict(self.last_connection_clock)
                        if self.last_connection_clock else None
                    )
                    engine_state = dict(self.match_engine_runtime_state)
                save_id = str(output.get("save_instance_id") or "")
                if not save_id or not game_clock:
                    if reader_context is not None:
                        reader_context.__exit__(None, None, None)
                        reader_context = reader = reader_layout = None
                        reader_save_id = ""
                    continue
                match_active = bool(
                    engine_state.get("known") and engine_state.get("active")
                )
                set_active_save_id(self._data_scope_id(output))
                capture_keys = pending_detail_capture_keys(
                    str(game_clock["date"]), int(game_clock["minutes"]),
                    lead_minutes=LIVE_RESULT_CAPTURE_LEAD_MINUTES,
                    tail_minutes=LIVE_RESULT_CAPTURE_TAIL_MINUTES,
                )
                if not capture_keys:
                    if reader_context is not None:
                        reader_context.__exit__(None, None, None)
                        reader_context = reader = reader_layout = None
                        reader_save_id = ""
                    with self.lock:
                        self.live_settlement_status.update({
                            "capture_matches": 0,
                            "capture_paused_for_match": False,
                        })
                    continue
                poll_seconds = LIVE_RESULT_CAPTURE_POLL_SECONDS
                expected_version = str(output.get("game_version") or "")
                if (
                    reader_context is None
                    or reader_save_id != save_id
                    or (
                        expected_version
                        and reader_layout is not None
                        and str(reader_layout.display_name) != expected_version
                    )
                ):
                    if reader_context is not None:
                        reader_context.__exit__(None, None, None)
                    reader_context = open_supported_reader()
                    _path, reader_layout, _module, reader = reader_context.__enter__()
                    reader_save_id = save_id
                    if expected_version and str(reader_layout.display_name) != expected_version:
                        reader_context.__exit__(None, None, None)
                        reader_context = reader = reader_layout = None
                        reader_save_id = ""
                        continue
                if not self.memory_lock.acquire(blocking=False):
                    with self.lock:
                        self.live_settlement_status["capture_matches"] = len(capture_keys)
                    continue
                try:
                    probe = probe_live_completed_results_with_reader(
                        reader, capture_keys, allow_expensive_rescan=False,
                        fixture_hints=pending_result_fixture_hints(capture_keys),
                    )
                finally:
                    self.memory_lock.release()
                captured = []
                captured_signatures: set[tuple[Any, ...]] = set()
                captured_keys: set[tuple[Any, ...]] = set()
                detailed_count = 0
                for item in probe.get("results", []):
                    try:
                        key = self._live_result_key(item)
                        home_goals = int(item["home_goals"])
                        away_goals = int(item["away_goals"])
                    except (KeyError, TypeError, ValueError):
                        continue
                    half_home = item.get("half_home_goals")
                    half_away = item.get("half_away_goals")
                    first_side = item.get("first_scoring_team")
                    signature = (
                        *key,
                        home_goals, away_goals,
                        int(half_home) if half_home is not None else None,
                        int(half_away) if half_away is not None else None,
                        str(first_side) if first_side in {"home", "away", "none"} else None,
                    )
                    if signature in self.live_captured_result_details:
                        continue
                    captured.append(item)
                    captured_signatures.add(signature)
                    captured_keys.add((save_id, *key))
                    detailed_count += int(
                        half_home is not None
                        or half_away is not None
                        or first_side in {"home", "away", "none"}
                    )
                if captured:
                    merged = merge_result_history(captured, save_id)
                    save_result_history(
                        merged, save_id, str(game_clock["date"]),
                        protected_result_keys=capture_keys,
                    )
                    self._invalidate_club_manager_record_cache()
                with self.lock:
                    self.live_captured_result_details.update(captured_signatures)
                    self.live_captured_result_keys.update(captured_keys)
                    previous_results = int(
                        self.live_settlement_status.get("captured_results", 0)
                    )
                    previous_details = int(
                        self.live_settlement_status.get("captured_details", 0)
                    )
                    self.live_settlement_status.update({
                        "capture_matches": len(capture_keys),
                        "capture_paused_for_match": False,
                        "capture_match_active": match_active,
                        "captured_results": previous_results + len(captured),
                        "captured_details": previous_details + detailed_count,
                        "last_captured": (
                            {
                                "count": len(captured),
                                "at": datetime.now().isoformat(timespec="seconds"),
                            }
                            if captured else self.live_settlement_status.get("last_captured")
                        ),
                    })
            except Exception as error:
                if reader_context is not None:
                    reader_context.__exit__(None, None, None)
                    reader_context = reader = reader_layout = None
                    reader_save_id = ""
                with self.lock:
                    self.live_settlement_status["error"] = str(error)

    def public_club(self, *, compact: bool = False) -> dict[str, Any]:
        with self.lock:
            output = dict(self.output)
            data_version = int(getattr(self, "data_version", 0) or 0)
            club_busy = bool(
                self.club_refreshing
                or getattr(self, "club_refresh_pending", False)
            )
            visible_profiles = dict(self.club_profiles)
            if club_busy:
                visible_profiles.update(
                    getattr(self, "club_loading_profiles", {})
                )
            profiles = [dict(profile) for profile in visible_profiles.values()]
            primary_team_id = int((output.get("managed_team") or {}).get("id") or 0)
            primary_profile = (
                visible_profiles.get(primary_team_id)
                or self.club_profile
                or (next(iter(visible_profiles.values())) if visible_profiles else None)
            )
            profile = dict(primary_profile) if primary_profile else None
            result = {
                "profile": profile,
                "profiles": profiles,
                "data_version": data_version,
                "ready": bool(visible_profiles or self.club_profile),
                "refreshing": club_busy,
                "last_updated": self.club_last_updated,
                "error": self.club_error,
                "progress": self.club_progress,
                "progress_text": self.club_progress_text,
                "medical_auto_treatment": self.club_medical_auto_result,
            }
        scope_id = self._data_scope_id(output) if output else ""
        if scope_id:
            set_active_save_id(scope_id)
        result["data_scope_id"] = scope_id

        def compact_result_payload() -> None:
            player_cache: dict[int, dict[str, Any]] = {}

            def compact_player(player: dict[str, Any]) -> dict[str, Any]:
                cache_id = id(player)
                if cache_id not in player_cache:
                    player_cache[cache_id] = {
                        key: value for key, value in player.items()
                        if key != "training_ca"
                    }
                return player_cache[cache_id]

            def compact_profile(current: dict[str, Any]) -> dict[str, Any]:
                reduced = dict(current)
                reduced["players"] = [
                    compact_player(player)
                    for player in current.get("players") or []
                ]
                reduced["squads"] = [
                    {
                        **squad,
                        "players": [
                            compact_player(player)
                            for player in squad.get("players") or []
                        ],
                    }
                    for squad in current.get("squads") or []
                ]
                return reduced

            result["profiles"] = [
                compact_profile(current) for current in result["profiles"]
            ]
            # ``profiles`` is authoritative in the browser. Omitting the
            # duplicated primary profile cuts another full roster from JSON.
            result["profile"] = None

        if result["refreshing"]:
            # Progress polling must remain independent of account and welfare
            # reads, which can be waiting on the same game-memory operation.
            result["economy"] = None
            result["welfare"] = None
            if compact:
                compact_result_payload()
            return result
        cache_key = (
            scope_id, data_version, str(result.get("last_updated") or ""),
            tuple(sorted(
                int((current.get("team") or {}).get("id") or 0)
                for current in result["profiles"]
            )),
            "compact" if compact else "full",
        )
        with self.lock:
            cache_hit = (
                getattr(self, "club_manager_record_cache_key", None) == cache_key
            )
            cached_records = (
                deepcopy(getattr(self, "club_manager_record_cache", {}))
                if cache_hit else {}
            )
        save_id = str(output.get("save_instance_id") or "") or None
        if cache_hit:
            manager_results = []
        elif compact:
            # The browser only needs newly captured season results here.  The
            # persisted manager record already owns older counted results, so
            # parsing the full (potentially very large) result archive would
            # unnecessarily block save-state polling and the coaching page.
            manager_results = list(output.get("season_results") or [])
        else:
            try:
                history = read_result_history(save_id) if save_id else []
            except Exception:
                history = []
            manager_results = [*history, *(output.get("season_results") or [])]

        def enrich_manager_record(current: dict[str, Any]) -> dict[str, Any]:
            team = current.get("team") or {}
            manager = current.get("manager") or {}
            contract = current.get("contract") or {}
            if str(team.get("team_type") or "club") == "club":
                team_id = int(team.get("id") or 0)
                if cache_hit:
                    current["manager_record"] = deepcopy(
                        cached_records.get(team_id)
                    )
                else:
                    try:
                        current["manager_record"] = sync_player_manager_record(
                            int(manager.get("id") or 0), team_id,
                            contract.get("joined_club_date") or contract.get("start_date"),
                            manager_results, scope_id,
                        )
                    except Exception:
                        current["manager_record"] = None
            return current

        enriched_profiles = [
            enrich_manager_record(current) for current in result["profiles"]
        ]
        result["profiles"] = enriched_profiles
        if result["profile"]:
            profile_team_id = int((result["profile"].get("team") or {}).get("id") or 0)
            matching_profile = next(
                (
                    current for current in enriched_profiles
                    if int((current.get("team") or {}).get("id") or 0) == profile_team_id
                ),
                None,
            )
            result["profile"] = matching_profile or enrich_manager_record(result["profile"])
        if not cache_hit:
            records = {
                int((current.get("team") or {}).get("id") or 0): deepcopy(
                    current.get("manager_record")
                )
                for current in [*result["profiles"], result.get("profile")]
                if current
                and str((current.get("team") or {}).get("team_type") or "club") == "club"
            }
            with self.lock:
                self.club_manager_record_cache_key = cache_key
                self.club_manager_record_cache = records
        result["economy"] = public_economy() if scope_id else None
        result["welfare"] = welfare_status() if scope_id else None
        if compact:
            compact_result_payload()
        return result

    def relations_scopes(self) -> dict[str, Any]:
        """Return cheap relationship scope metadata without relationship RPM."""
        with self.lock:
            output = dict(self.output)
            visible_profiles = dict(self.club_profiles)
            if getattr(self, "club_refreshing", False):
                visible_profiles.update(
                    getattr(self, "club_loading_profiles", {})
                )
            profiles = [deepcopy(row) for row in visible_profiles.values()]
            data_version = int(getattr(self, "data_version", 0) or 0)
        scope_id = self._data_scope_id(output) if output else ""
        acquired = account_acquired_clubs(scope_id, output) if scope_id else []
        return relationship_scopes(
            profiles, acquired, data_version=data_version,
        )

    def _relationship_profile(self, payload: dict[str, Any]) -> dict[str, Any]:
        team_id = int(payload.get("team_id") or 0)
        if team_id <= 0:
            raise ValueError("未指定关系范围球队")
        requested_version = payload.get("data_version")
        with self.lock:
            current_version = int(getattr(self, "data_version", 0) or 0)
            profile = deepcopy(
                self.club_profiles.get(team_id)
                or (
                    getattr(self, "club_loading_profiles", {}).get(team_id)
                    if getattr(self, "club_refreshing", False) else None
                )
            )
        if requested_version is not None and int(requested_version) != current_version:
            raise ValueError("球队数据已刷新，请重新加载关系范围")
        if profile is not None:
            return profile
        if str(payload.get("scope_kind") or "") != "acquired":
            raise ValueError("未找到所选执教球队关系范围")
        # Acquired clubs are loaded only after the user selects one.
        detail = self.world_club_detail(team_id)
        team = dict(detail.get("team") or detail.get("club") or {})
        if not team:
            team = {"id": team_id, "name": detail.get("name") or str(team_id)}
        team.setdefault("id", team_id)
        return {
            "team": team,
            "players": list(detail.get("players") or []),
            "staff": list(detail.get("staff") or []),
            "squads": list(detail.get("squads") or []),
        }

    def relations_people(self, payload: dict[str, Any]) -> dict[str, Any]:
        return page_relationship_people(self._relationship_profile(payload), payload)

    def relations_network(self, payload: dict[str, Any]) -> dict[str, Any]:
        page = self.relations_people(payload)
        background = str(payload.get("background") or "").strip().lower() in {
            "1", "true", "yes", "on",
        }
        memory_lock = getattr(self, "memory_lock", None)
        memory_context = (
            memory_lock
            if background and memory_lock is not None
            else nullcontext()
        )
        with memory_context:
            with borrow_game_operation() as operation:
                result = enrich_relationship_page(operation.reader, page)
        with self.lock:
            result["data_version"] = int(getattr(self, "data_version", 0) or 0)
        return result

    def relations_pair(self, payload: dict[str, Any]) -> dict[str, Any]:
        with borrow_game_operation() as operation:
            return relationship_pair(
                operation.reader, payload.get("person_a"), payload.get("person_b"),
            )

    def relations_entities(self, payload: dict[str, Any]) -> dict[str, Any]:
        keys = payload.get("person_keys") or payload.get("keys") or []
        if not isinstance(keys, list):
            raise ValueError("人物地址列表无效")
        background = str(payload.get("background") or "").strip().lower() in {
            "1", "true", "yes", "on",
        }
        memory_lock = getattr(self, "memory_lock", None)
        memory_context = (
            memory_lock
            if background and memory_lock is not None
            else nullcontext()
        )
        with memory_context:
            with borrow_game_operation() as operation:
                return resolve_relationship_entities(
                    operation.reader, keys,
                    include_relationships=bool(payload.get("include_relationships")),
                )

