    def relations_timeline(self, payload: dict[str, Any]) -> dict[str, Any]:
        with self.lock:
            scope_id = self._data_scope_id(self.output)
            profiles_by_team = dict(self.club_profiles)
            profiles_by_team.update(getattr(self, "club_loading_profiles", {}) or {})
            profiles = list(profiles_by_team.values())
            manager = dict(self.output.get("manager") or {})
            manager_id = int(
                self.output.get("selected_manager_id") or manager.get("id") or 0
            )
        if not scope_id:
            raise ValueError("尚未识别当前账户")
        result = relationship_timeline(payload, scope_id)
        staff_groups = (
            ("球队高层", {66, 70, 4, 8, 6}),
            ("主管团队", {10, 88, 64, 86}),
            ("教练团队", {16, 20, 2, 26, 34, 22}),
            ("分析团队", {62, 60, 58}),
            ("招募团队", {44, 14}),
            ("医疗团队", {38, 46, 50, 12}),
            ("运动科学团队", {40, 48}),
        )

        def timeline_category(person: dict[str, Any]) -> dict[str, Any]:
            kind = str(person.get("kind") or person.get("person_kind") or "")
            if kind == "staff":
                if person.get("is_player_manager"):
                    return {"key": "教练团队", "label": "教练团队", "order": 2}
                job_type = int(person.get("job_type") or 0)
                for order, (label, job_types) in enumerate(staff_groups):
                    if job_type in job_types:
                        return {"key": label, "label": label, "order": order}
                return {"key": "其他职员", "label": "其他职员", "order": len(staff_groups)}
            if kind == "player":
                primary = list(person.get("primary_positions") or [])
                if not primary:
                    ratings = person.get("position_ratings") or {}
                    primary = [key for key, _value in sorted(
                        ratings.items(), key=lambda item: -int(item[1] or 0),
                    )]
                if not primary:
                    primary = list(person.get("positions") or [])
                position = str(primary[0] if primary else "").upper()
                if position == "GK":
                    return {"key": "goalkeepers", "label": "门将", "order": 3}
                if position in {"ST", "AML", "AMC", "AMR"}:
                    return {"key": "forwards", "label": "前场", "order": 0}
                if position in {"DM", "ML", "MC", "MR"}:
                    return {"key": "midfielders", "label": "中场", "order": 1}
                if position in {"DL", "DC", "DR", "WBL", "WBR", "SW"}:
                    return {"key": "defenders", "label": "后场", "order": 2}
                return {"key": "unclassified", "label": "未识别位置", "order": 4}
            return {"key": "unclassified", "label": "未识别人员", "order": 99}

        live_people: dict[tuple[str, int], dict[str, Any]] = {}
        live_by_id: dict[int, dict[str, Any]] = {}

        def register(kind: str, source: dict[str, Any], team: dict[str, Any], **extra: Any) -> None:
            person_id = int(source.get("id") or 0)
            if not person_id:
                return
            row = {
                **source, **extra, "id": person_id, "kind": kind,
                "person_kind": kind,
                "club": source.get("club") or team.get("name"),
                "team_name": source.get("team_name") or team.get("name"),
                "team_id": source.get("team_id") or team.get("id"),
                "team_type": source.get("team_type") or team.get("team_type") or "club",
            }
            live_people[(kind, person_id)] = row
            live_by_id.setdefault(person_id, row)

        for profile in profiles:
            team = dict(profile.get("team") or {})
            for player in profile.get("players") or []:
                register("player", dict(player), team)
            for squad in profile.get("squads") or []:
                for player in squad.get("players") or []:
                    person_id = int(player.get("id") or 0)
                    if person_id and ("player", person_id) not in live_people:
                        register(
                            "player", dict(player), team,
                            squad_label=squad.get("label") or squad.get("type"),
                            squad_team_id=squad.get("team_id"),
                        )
            for staff in profile.get("staff") or []:
                register("staff", dict(staff), team)
        if manager_id:
            manager_team = dict((profiles[0].get("team") if profiles else {}) or {})
            manager_row = {
                **manager, "id": manager_id, "kind": "staff",
                "person_kind": "staff", "role": "玩家经理",
                "is_player_manager": True,
                "club": manager.get("club") or manager_team.get("name"),
                "team_name": manager.get("team_name") or manager_team.get("name"),
                "team_id": manager.get("team_id") or manager_team.get("id"),
                "team_type": manager.get("team_type") or manager_team.get("team_type") or "club",
            }
            live_people[("staff", manager_id)] = manager_row
            live_by_id[manager_id] = manager_row
        for event in result.get("events") or []:
            for field in ("person_a", "person_b"):
                archived = dict(event.get(field) or {})
                person_id = int(archived.get("id") or 0)
                kind = str(archived.get("kind") or archived.get("person_kind") or "")
                live = live_people.get((kind, person_id)) or live_by_id.get(person_id, {})
                event_role = str(archived.get("event_role") or archived.get("role") or "")
                event_role_label = str(
                    archived.get("event_role_label") or archived.get("role_label") or "参与者"
                )
                employment_role = live.get("role") or live.get("job_type_name")
                merged = {**archived, **live}
                resolved_kind = str(live.get("kind") or kind)
                merged.update({
                    "id": person_id, "kind": resolved_kind,
                    "person_kind": resolved_kind,
                    "event_role": event_role, "event_role_label": event_role_label,
                })
                if employment_role:
                    merged["role"] = employment_role
                category = timeline_category(merged)
                merged["timeline_category_key"] = category["key"]
                merged["timeline_category_label"] = category["label"]
                merged["timeline_category_order"] = category["order"]
                event[field] = merged
        return result

    def relationship_training_rooms_state(
        self, _payload: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        with self.lock:
            scope_id = self._bind_request_scope()
            game_date = str(self.output.get("game_date") or "")
        if not scope_id:
            raise ValueError("尚未识别当前存档账户")
        ground = public_training_ground(game_date)
        floor = next((
            row for row in ground.get("floors") or []
            if row.get("scene") == "relationship_8f"
        ), None)
        return {**relationship_training_catalog(), "floor": floor}

    @staticmethod
    def _relationship_training_people(
        profile: dict[str, Any] | None, kind: str,
    ) -> list[dict[str, Any]]:
        if not profile:
            return []
        if kind == "staff":
            return list(profile.get("staff") or [])
        players: dict[int, dict[str, Any]] = {}
        for person in profile.get("players") or []:
            identifier = int(person.get("id") or 0)
            if identifier:
                players[identifier] = person
        for squad in profile.get("squads") or []:
            for source in squad.get("players") or []:
                identifier = int(source.get("id") or 0)
                if not identifier:
                    continue
                person = dict(source)
                if not int(person.get("squad_team_id") or 0):
                    person["squad_team_id"] = int(squad.get("team_id") or 0)
                if person.get("squad_type_code") is None:
                    person["squad_type_code"] = squad.get("type_code")
                if not str(person.get("squad_label") or "").strip():
                    person["squad_label"] = str(
                        squad.get("label") or squad.get("type") or ""
                    )
                players[identifier] = person
        return list(players.values())

    @staticmethod
    def _relationship_training_pairs(
        room_sku: str, participants: list[dict[str, Any]],
    ) -> list[tuple[dict[str, Any], dict[str, Any]]]:
        definition = RELATIONSHIP_TRAINING_ROOMS[str(room_sku)]
        beneficiary_roles = {
            str(row["key"]) for row in definition.get("roles") or []
            if row.get("kind") == "player"
        }
        if room_sku == "mentoring_room":
            beneficiary_roles.discard("mentor")
        beneficiaries = [
            row for row in participants if row.get("role") in beneficiary_roles
        ]
        guiders = [
            row for row in participants if row.get("role") not in beneficiary_roles
        ]
        pairs = [
            (guider, beneficiary)
            for guider in guiders for beneficiary in beneficiaries
        ]
        if room_sku == "mind_room":
            pairs.extend(
                (left, right)
                for index, left in enumerate(beneficiaries)
                for right in beneficiaries[index + 1:]
            )
        return pairs

    @staticmethod
    def _all_relationship_training_pairs(
        participants: list[dict[str, Any]],
    ) -> list[tuple[dict[str, Any], dict[str, Any]]]:
        return [
            (left, right)
            for index, left in enumerate(participants)
            for right in participants[index + 1:]
        ]

    def relationship_training_room_preview(
        self, payload: dict[str, Any],
    ) -> dict[str, Any]:
        room_id = str(payload.get("room_id") or "")
        submitted = payload.get("participants") or []
        selected_attributes = list(dict.fromkeys(
            str(value) for value in (payload.get("attributes") or []) if str(value)
        ))
        if not room_id or not isinstance(submitted, list):
            raise ValueError("缺少必要的房间或参与者信息")
        catalog = relationship_training_catalog()
        definition = next((
            definition for definition in catalog.get("rooms") or []
            if any(
                str(instance.get("id") or "") == room_id
                for instance in definition.get("instances") or []
            )
        ), None)
        if not definition:
            raise ValueError("房间实例不存在")
        room_sku = str(definition.get("sku") or "")
        scope = {
            str(row.get("key") or ""): dict(row)
            for row in definition.get("scope_attributes") or []
            if str(row.get("key") or "")
        }
        if set(selected_attributes) - set(scope):
            raise ValueError("训练属性不在当前房间作用域内")
        with self.lock:
            self._bind_current_save()
            profiles = [deepcopy(row) for row in self.club_profiles.values()]

        staged: list[tuple[str, int, int, str, dict[str, Any], dict[str, Any]]] = []
        for source in submitted:
            if not isinstance(source, dict):
                raise ValueError("参与者信息无效")
            kind = str(source.get("kind") or "")
            identifier = int(source.get("id") or 0)
            team_id = int(source.get("team_id") or 0)
            role = str(source.get("role") or "")
            if kind not in {"player", "staff"} or identifier <= 0 or team_id <= 0:
                raise ValueError("参与者身份信息不完整")
            profile = next((
                row for row in profiles
                if int((row.get("team") or {}).get("id") or 0) == team_id
            ), None)
            person = next((
                row for row in self._relationship_training_people(profile, kind)
                if int(row.get("id") or 0) == identifier
            ), None)
            if not profile or not person:
                raise ValueError("参与者已不属于当前执教球队，请刷新后重试")
            if kind == "staff":
                validate_relationship_training_staff(room_sku, role, person)
            staged.append((kind, identifier, team_id, role, profile, person))

        validate_relationship_training_guidance(room_sku, [
            {
                "role": role, "kind": kind, "id": identifier,
                "name": str(person.get("name") or identifier),
                "team_id": team_id,
                "team_type": str((profile.get("team") or {}).get("team_type") or "club"),
                "squad_team_id": int(person.get("squad_team_id") or team_id),
                "squad_type_code": int(person.get("squad_type_code") or 0),
                "squad_label": str(
                    person.get("squad_label") or person.get("squad_type")
                    or ("国家队" if str((profile.get("team") or {}).get("team_type") or "club") == "national" else "一线队")
                ),
            }
            for kind, identifier, team_id, role, profile, person in staged
        ])

        canonical: list[dict[str, Any]] = []
        live_people: dict[tuple[str, int], dict[str, Any]] = {}
        with borrow_game_operation() as operation:
            for kind, identifier, team_id, role, profile, person in staged:
                person_address = resolve_public_person_address(
                    operation.reader, person, kind,
                )
                canonical_person = {
                    "role": role, "kind": kind, "id": identifier,
                    "name": str(person.get("name") or identifier),
                    "ca": person.get("ca"), "pa": person.get("pa"),
                    "positions": deepcopy(person.get("positions") or []),
                    "primary_positions": deepcopy(person.get("primary_positions") or []),
                    "job_type": person.get("job_type"),
                    "job_type_name": person.get("job_type_name"),
                    "team_id": team_id,
                    "team_type": str((profile.get("team") or {}).get("team_type") or "club"),
                    "squad_team_id": int(person.get("squad_team_id") or team_id),
                    "squad_type_code": int(person.get("squad_type_code") or 0),
                    "squad_label": str(person.get("squad_label") or person.get("squad_type") or ""),
                    "person_address": person_address,
                }
                canonical.append(canonical_person)
                live_people[(kind, identifier)] = {
                    "source": person, "profile": profile,
                    "player_address": person.get("address"),
                    "person_address": person_address,
                }
            effect_pairs = {
                frozenset((
                    (str(left["kind"]), int(left["id"])),
                    (str(right["kind"]), int(right["id"])),
                ))
                for left, right in self._relationship_training_pairs(room_sku, canonical)
            }
            pairs = []
            pair_details: dict[tuple[str, int, str, int], dict[str, Any]] = {}
            negative = False
            for left, right in self._all_relationship_training_pairs(canonical):
                detail = read_relationship_pair(
                    operation.reader,
                    int(left["person_address"]), int(right["person_address"]),
                )
                left_key = (str(left["kind"]), int(left["id"]))
                right_key = (str(right["kind"]), int(right["id"]))
                pair_details[(*left_key, *right_key)] = detail
                pair_negative = any(
                    direction and int(direction.get("relation_type", 1)) != 1
                    for direction in (detail.get("a_to_b"), detail.get("b_to_a"))
                )
                negative = negative or pair_negative
                is_effect_pair = frozenset((left_key, right_key)) in effect_pairs
                pairs.append({
                    "person_a": {
                        key: left[key] for key in ("role", "kind", "id", "name", "team_id")
                    },
                    "person_b": {
                        key: right[key] for key in ("role", "kind", "id", "name", "team_id")
                    },
                    "a_to_b": detail.get("a_to_b"),
                    "b_to_a": detail.get("b_to_a"),
                    "negative": pair_negative,
                    "effect_pair": is_effect_pair,
                })

        selected_count = len(selected_attributes)
        scope_count = len(scope)
        focus = (
            max(0.5, 1.0 - 0.5 * (selected_count - 1) / max(1, scope_count - 1))
            if selected_count and scope_count > 1 else 1.0
        )
        base_daily_points = 3.0 * focus if selected_count else 0.0
        progress = relationship_training_progress()
        beneficiary_roles = {
            str(row.get("key") or "") for row in definition.get("roles") or []
            if row.get("kind") == "player"
        }
        if room_sku == "mentoring_room":
            beneficiary_roles.discard("mentor")
        beneficiaries = [
            row for row in canonical if str(row.get("role") or "") in beneficiary_roles
        ]
        mentor = next((row for row in canonical if row.get("role") == "mentor"), None)
        coach = next((row for row in canonical if row.get("role") == "coach"), None)
        mentor_source = live_people.get(("player", int((mentor or {}).get("id") or 0)), {}).get("source")
        coach_source = live_people.get(("staff", int((coach or {}).get("id") or 0)), {}).get("source")
        coach_multiplier = coach_composite_multiplier(
            int(((coach_source or {}).get("coaching_license") or {}).get("code") or -1),
            int((coach_source or {}).get("current_reputation") or 0),
        ) if coach_source else 1.0
        staff_bonus = 0.0
        if room_sku in {"video_analysis_room", "sports_science_room"} and canonical:
            team_id = int(canonical[0].get("team_id") or 0)
            profile = next((
                row for row in profiles
                if int((row.get("team") or {}).get("id") or 0) == team_id
            ), None)
            capabilities = compute_team_capabilities(list((profile or {}).get("staff") or []))
            staff_bonus = float(capabilities[
                "analysis" if room_sku == "video_analysis_room" else "sports_science"
            ]["bonus"])
        staff_multiplier = 1.0 + staff_bonus

        def pair_detail(left: dict[str, Any], right: dict[str, Any]) -> dict[str, Any]:
            left_key = (str(left["kind"]), int(left["id"]))
            right_key = (str(right["kind"]), int(right["id"]))
            direct = pair_details.get((*left_key, *right_key))
            if direct is not None:
                return direct
            reverse = pair_details.get((*right_key, *left_key), {})
            return {
                "a_to_b": reverse.get("b_to_a"),
                "b_to_a": reverse.get("a_to_b"),
            }

        def partner_bonus(beneficiary: dict[str, Any]) -> float:
            identity = (str(beneficiary["kind"]), int(beneficiary["id"]))
            total = 0.0
            for left, right in self._relationship_training_pairs(room_sku, canonical):
                detail = pair_detail(left, right)
                if identity == (str(left["kind"]), int(left["id"])):
                    total += relationship_intimacy_bonus(detail.get("a_to_b"))
                elif identity == (str(right["kind"]), int(right["id"])):
                    total += relationship_intimacy_bonus(detail.get("b_to_a"))
            return total

        read_targets: list[dict[str, Any]] = []
        value_people = list(beneficiaries)
        if mentor:
            value_people.append(mentor)
        for participant in value_people:
            live = live_people.get(("player", int(participant["id"])), {})
            for key in selected_attributes:
                attribute = scope[key]
                if str(attribute.get("kind") or "") == "height":
                    continue
                read_targets.append({
                    "id": f"{int(participant['id'])}:{key}",
                    "player_id": int(participant["id"]),
                    "player_address": live.get("player_address"),
                    "attribute_key": key,
                    "attribute_id": int(VISIBLE_ATTRIBUTE_IDS.get(key) or -1),
                    "attribute_kind": str(attribute.get("kind") or "visible"),
                })
        current_values = read_player_training_attributes(read_targets) if read_targets else {}

        def coach_can_teach(attribute_key: str) -> bool:
            if coach_source is None:
                return True
            name = attribute_key.partition(":")[2]
            abilities = coach_source.get("abilities") or {}
            hidden = coach_source.get("hidden_attributes") or {}
            values = {
                "适应性": [abilities.get("适应能力"), hidden.get("适应性")],
                "雄心": [hidden.get("雄心")],
                "忠诚": [hidden.get("忠诚")],
                "职业素养": [abilities.get("人员管理"), abilities.get("激励")],
                "稳定性": [abilities.get("战术知识")],
                "大赛发挥": [abilities.get("激励"), abilities.get("意志力")],
                "多面性": [abilities.get("战术训练")],
            }.get(name, [])
            valid = [int(value) for value in values if value is not None]
            return bool(valid) and sum(valid) / len(valid) >= 15

        def attribute_room_multiplier(beneficiary: dict[str, Any], key: str, current: int) -> tuple[float, str]:
            if mentor_source is not None:
                student = live_people[("player", int(beneficiary["id"]))]["source"]
                multiplier = 1.0 + abs(
                    estimate_player_status_tier(mentor_source)
                    - estimate_player_status_tier(student)
                ) * 0.5
                return multiplier, "导师层级"
            if room_sku == "video_analysis_room":
                return staff_multiplier, "分析团队"
            if room_sku == "sports_science_room":
                source = live_people[("player", int(beneficiary["id"]))]["source"]
                sharpness = float(source.get("sharpness") or 0)
                sharpness_raw = sharpness * 100 if sharpness <= 100 else sharpness
                fatigue = float(source.get("fatigue") or 0)
                if key == "精神:勇敢":
                    return (1.5 if sharpness_raw < 5000 else 1.0), "比赛状态"
                if key == "身体:体质":
                    return (0.5 if fatigue > 5000 else 1.0) * staff_multiplier, "疲劳与运动科学团队"
                if key == "hidden:受伤倾向":
                    return max(0.0, 1.0 + (float(current) - 10.0) * 0.1) * (1.0 - staff_bonus), "受伤倾向与运动科学团队"
                return staff_multiplier, "运动科学团队"
            if room_sku == "tactical_room":
                return coach_multiplier, "教练证书与声望"
            return 1.0, "房间基础"

        effects: list[dict[str, Any]] = []
        for beneficiary in beneficiaries:
            player_id = int(beneficiary["id"])
            source = live_people[("player", player_id)]["source"]
            relation_bonus = partner_bonus(beneficiary)
            for key in selected_attributes:
                attribute = scope[key]
                direction = -1 if attribute.get("direction") == "dec" else 1
                is_height = str(attribute.get("kind") or "") == "height"
                current = int(
                    source.get("height_cm") or source.get("height") or 0
                ) if is_height else int(current_values.get(f"{player_id}:{key}") or 0)
                eligible = current > 0 and 1 <= current + direction <= 20
                unavailable_reason = (
                    "" if eligible else
                    "属性已达到可训练边界" if current > 0 else
                    "无法读取当前属性"
                )
                mentor_value = None
                if eligible and mentor:
                    mentor_id = int(mentor["id"])
                    mentor_value = int(current_values.get(f"{mentor_id}:{key}") or 0)
                    threshold_ok = mentor_value >= 15 if direction > 0 else 0 < mentor_value <= 10
                    eligible = threshold_ok and (
                        mentor_value > current if direction > 0 else mentor_value < current
                    )
                    if not eligible:
                        unavailable_reason = "导师属性未达到门槛或不优于学员"
                if eligible and not coach_can_teach(key):
                    eligible = False
                    unavailable_reason = "教练对应指导能力不足 15"
                room_multiplier, multiplier_label = attribute_room_multiplier(
                    beneficiary, key, current,
                )
                daily_points = base_daily_points * (1.0 + relation_bonus) * room_multiplier
                row = {
                    "participant": {
                        key_name: beneficiary[key_name]
                        for key_name in ("id", "name", "kind", "role", "team_id")
                    },
                    "attribute_key": key,
                    "attribute_label": str(attribute.get("label") or key.partition(":")[2] or key),
                    "direction": direction, "current": current,
                    "target": current + direction if eligible else current,
                    "eligible": eligible, "unavailable_reason": unavailable_reason,
                    "base_daily_points": round(base_daily_points, 4),
                    "daily_points": round(daily_points, 4),
                    "focus_coefficient": round(focus, 4),
                    "relationship_bonus": round(relation_bonus, 4),
                    "room_multiplier": round(room_multiplier, 4),
                    "room_multiplier_label": multiplier_label,
                    "mentor_value": mentor_value,
                }
                if is_height:
                    probability = sports_science_height_probability(
                        int(source.get("age") or 0), current,
                        staff_bonus, relation_bonus,
                    ) if eligible else 0.0
                    row.update({
                        "height_probability": round(probability, 6),
                        "estimated_days": None, "stored_points": 0.0,
                        "required_points": None, "remaining_points": None,
                    })
                else:
                    progress_key = attribute_progress_key(room_sku, beneficiary, key)
                    stored = float(progress["attribute_progress"].get(progress_key, 0.0))
                    required = training_points_required_for_direction(current, direction) if eligible else None
                    remaining = max(0.0, float(required) - stored) if required is not None else None
                    estimated = math.ceil(remaining / daily_points) if eligible and daily_points > 0 else None
                    row.update({
                        "stored_points": round(stored, 4),
                        "required_points": required,
                        "remaining_points": round(remaining, 4) if remaining is not None else None,
                        "estimated_days": estimated,
                    })
                effects.append(row)

        pair_by_key = {
            frozenset(((str(row["person_a"]["kind"]), int(row["person_a"]["id"])),
                       (str(row["person_b"]["kind"]), int(row["person_b"]["id"])))): row
            for row in pairs if row.get("effect_pair")
        }
        for left, right in self._relationship_training_pairs(room_sku, canonical):
            row = pair_by_key.get(frozenset((
                (str(left["kind"]), int(left["id"])),
                (str(right["kind"]), int(right["id"])),
            )))
            if not row:
                continue
            detail = pair_detail(left, right)
            pair_multiplier = staff_multiplier if room_sku in {
                "video_analysis_room", "sports_science_room"
            } else coach_multiplier
            if mentor_source is not None:
                student = right if right.get("role") == "student" else left
                pair_multiplier = 1.0 + abs(
                    estimate_player_status_tier(mentor_source)
                    - estimate_player_status_tier(
                        live_people[("player", int(student["id"]))]["source"]
                    )
                ) * 0.5
            row_a_identity = (
                str(row["person_a"]["kind"]), int(row["person_a"]["id"]),
            )
            for from_person, to_person, detail_key in (
                (left, right, "a_to_b"),
                (right, left, "b_to_a"),
            ):
                relation = detail.get(detail_key)
                daily = INTIMACY_PER_DAY * (
                    1.0 + relationship_intimacy_bonus(relation)
                ) * pair_multiplier
                stored = float(progress["intimacy_progress"].get(
                    directed_progress_key(from_person, to_person), 0.0,
                ))
                effect_key = (
                    "a_to_b_effect"
                    if (str(from_person["kind"]), int(from_person["id"])) == row_a_identity
                    else "b_to_a_effect"
                )
                row[effect_key] = {
                    "daily": round(daily, 4), "stored": round(stored, 4),
                    "estimated_days_to_next": math.ceil(max(0.0, 1.0 - stored) / daily)
                    if daily > 0 else None,
                    "room_multiplier": round(pair_multiplier, 4),
                    "relationship_bonus": round(relationship_intimacy_bonus(relation), 4),
                }

        return {
            "pairs": pairs, "negative": negative, "effects": effects,
            "summary": {
                "selected_count": selected_count, "scope_count": scope_count,
                "focus_coefficient": round(focus, 4),
                "base_daily_points": round(base_daily_points, 4),
                "staff_team_bonus": round(staff_bonus, 4),
                "coach_multiplier": round(coach_multiplier, 4),
            },
        }

    def relationship_training_room_unlock(self, payload: dict[str, Any]) -> dict[str, Any]:
        if not self._bind_request_scope():
            raise ValueError("尚未识别当前存档账户")
        sku = str(payload.get("room_sku") or "")
        definition = RELATIONSHIP_TRAINING_ROOMS.get(sku)
        if not definition:
            raise ValueError("房间不存在")
        assert_training_floor_unlocked("relationship_8f")
        if not definition.get("available", False):
            raise ValueError(str(definition.get("unavailable_reason") or "该房间暂未开放"))
        with self.lock:
            profiles = [deepcopy(row) for row in self.club_profiles.values()]
        players = [row for profile in profiles for row in profile.get("players") or []]
        staff = [row for profile in profiles for row in profile.get("staff") or []]
        if sku == "mind_room" and not players:
            raise ValueError("解锁修心室需要队中至少一名球员")
        if sku == "mentoring_room":
            scope = list(definition.get("scope_attributes") or [])

            def value_of(person: dict[str, Any], attribute: dict[str, Any]) -> Any:
                key = str(attribute.get("key") or "")
                group, _, name = key.partition(":")
                if group == "hidden":
                    return (person.get("hidden_attributes") or {}).get(name)
                if group == "physical":
                    return person.get("height_cm") or person.get("height")
                return ((person.get("attributes") or {}).get(group) or {}).get(name)

            pair_available = any(
                mentor is not student and any(
                    value_of(mentor, attribute) is not None
                    and value_of(student, attribute) is not None
                    and (
                        value_of(mentor, attribute) < value_of(student, attribute)
                        if attribute.get("direction") == "dec"
                        else value_of(mentor, attribute) > value_of(student, attribute)
                    )
                    for attribute in scope
                )
                for mentor in players for student in players
            )
            if not pair_available:
                raise ValueError("解锁传习室需要至少一对导师与学员，且作用属性中至少一项导师更优")
        if sku == "tactical_room" and not any(
            int(row.get("job_type") or 0) in COACHING_JOB_TYPES
            and int((row.get("coaching_license") or {}).get("code") or 0) != 0
            for row in staff
        ):
            raise ValueError("解锁战术指导室需要队中至少一名持证教练")
        if sku == "video_analysis_room" and not any(
            int(row.get("job_type") or 0) in ANALYSIS_JOB_TYPES for row in staff
        ):
            raise ValueError("解锁视频分析室需要队中至少一名分析团队职员")
        if sku == "sports_science_room" and not any(
            int(row.get("job_type") or 0) in SPORTS_SCIENCE_JOB_TYPES for row in staff
        ):
            raise ValueError("解锁运动科学室需要队中至少一名运动科学团队职员")
        free = free_services_enabled()
        cost = local_purchase_price(float(definition.get("unlock_cost") or 0))
        payment = (
            {"bank": 0.0, "wallet": 0.0, "total": 0.0}
            if free else charge_combined_funds(
                cost, "relationship_training_room_unlock", room_sku=sku,
            )
        )
        try:
            room = unlock_relationship_training_room(sku)
        except Exception:
            if payment["total"]:
                refund_combined_funds(
                    payment, "relationship_training_room_unlock_rollback",
                    room_sku=sku,
                )
            raise
        return {
            "room": room, "payment": payment,
            "rooms": self.relationship_training_rooms_state(),
            "economy": public_economy(),
        }

    def relationship_training_room_enter(self, payload: dict[str, Any]) -> dict[str, Any]:
        room_id = str(payload.get("room_id") or "")
        submitted = payload.get("participants") or []
        attributes = payload.get("attributes") or []
        if not room_id or not isinstance(submitted, list) or not submitted:
            raise ValueError("缺少必要的房间或参与者信息")
        if not isinstance(attributes, list):
            raise ValueError("训练属性列表无效")
        assert_training_floor_unlocked("relationship_8f")
        catalog = relationship_training_catalog()
        room_sku = next((
            str(definition.get("sku") or "")
            for definition in catalog.get("rooms") or []
            for instance in definition.get("instances") or []
            if str(instance.get("id") or "") == room_id
        ), "")
        if not room_sku:
            raise ValueError("房间实例不存在")
        with self.lock:
            self._bind_current_save()
            game_date = str(self.output.get("game_date") or "")
            profiles = [deepcopy(row) for row in self.club_profiles.values()]
        if not game_date:
            raise ValueError("尚未读取游戏日期")

        staged: list[tuple[str, int, int, str, dict[str, Any], dict[str, Any]]] = []
        for source in submitted:
            if not isinstance(source, dict):
                raise ValueError("参与者信息无效")
            kind = str(source.get("kind") or "")
            identifier = int(source.get("id") or 0)
            team_id = int(source.get("team_id") or 0)
            if kind not in {"player", "staff"} or identifier <= 0 or team_id <= 0:
                raise ValueError("参与者身份信息不完整")
            profile = next((
                row for row in profiles
                if int((row.get("team") or {}).get("id") or 0) == team_id
            ), None)
            person = next((
                row for row in self._relationship_training_people(profile, kind)
                if int(row.get("id") or 0) == identifier
            ), None)
            if not profile or not person:
                raise ValueError("参与者已不属于当前执教球队，请刷新后重试")
            role = str(source.get("role") or "")
            if kind == "staff":
                validate_relationship_training_staff(room_sku, role, person)
            staged.append((kind, identifier, team_id, role, profile, person))

        validate_relationship_training_guidance(room_sku, [
            {
                "role": role, "kind": kind, "id": identifier,
                "name": str(person.get("name") or identifier),
                "team_id": team_id,
                "team_type": str((profile.get("team") or {}).get("team_type") or "club"),
                "squad_team_id": int(person.get("squad_team_id") or team_id),
                "squad_type_code": int(person.get("squad_type_code") or 0),
                "squad_label": str(
                    person.get("squad_label") or person.get("squad_type")
                    or ("国家队" if str((profile.get("team") or {}).get("team_type") or "club") == "national" else "一线队")
                ),
            }
            for kind, identifier, team_id, role, profile, person in staged
        ])

        canonical: list[dict[str, Any]] = []
        with borrow_game_operation() as operation:
            for kind, identifier, team_id, role, profile, person in staged:
                person_address = resolve_public_person_address(operation.reader, person, kind)
                team = dict(profile.get("team") or {})
                canonical.append({
                    "role": role, "kind": kind,
                    "id": identifier, "name": str(person.get("name") or identifier),
                    "address": person.get("address"), "person_key": hex(person_address),
                    "team_id": team_id, "team_name": str(team.get("name") or ""),
                    "team_type": str(team.get("team_type") or "club"),
                    "squad_team_id": int(person.get("squad_team_id") or team_id),
                    "squad_type_code": int(person.get("squad_type_code") or 0),
                    "squad_label": str(person.get("squad_label") or person.get("squad_type") or ""),
                })
            for left, right in self._all_relationship_training_pairs(canonical):
                if persons_relation_negative(
                    operation.reader,
                    int(str(left["person_key"]), 0),
                    int(str(right["person_key"]), 0),
                ):
                    raise ValueError(
                        f"{left['name']} 与 {right['name']} 存在负面关系，不能配对训练"
                    )
        room = enter_relationship_training_room(
            room_id, canonical, attributes, game_date,
            client_submission_id=str(payload.get("client_submission_id") or ""),
        )
        return {"room": room, "rooms": self.relationship_training_rooms_state()}

    def relationship_training_room_settle(self, payload: dict[str, Any]) -> dict[str, Any]:
        if FROZEN:
            raise PermissionError("8F 综训结算只在开发版开放")
        room_id = str(payload.get("room_id") or "")
        if not room_id:
            raise ValueError("缺少房间实例")
        assert_training_floor_unlocked("relationship_8f")
        with self.lock:
            self._bind_current_save()
            game_date = str(self.output.get("game_date") or "")
            scope_id = self._data_scope_id(self.output)
            profiles = [deepcopy(row) for row in self.club_profiles.values()]
        if not game_date or not scope_id:
            raise ValueError("尚未读取当前游戏日期或账户作用域")

        session = release_relationship_training_room(room_id, game_date)
        attribute_writes: list[dict[str, Any]] = []
        relationship_writes: list[dict[str, Any]] = []

        def rollback_native() -> None:
            for result in reversed(relationship_writes):
                rollback_bidirectional_intimacy(result)
            for item in reversed(attribute_writes):
                result = item["result"]
                if item["kind"] == "condition":
                    restore_player_training_condition(
                        int(item["player_id"]), item["player_address"],
                        result["_original"], result["_updated"],
                    )
                elif item["kind"] == "hidden":
                    restore_player_hidden_attribute(
                        int(item["player_id"]), item["player_address"],
                        str(item["attribute_key"]), result["_original_raw"],
                        result.get("_updated_raw"),
                    )
                else:
                    restore_player_development(
                        int(item["player_id"]), item["player_address"],
                        result["_original_raw"], int(result["_original_ca"]),
                        int(result["_original_pa"]),
                        attribute_keys=result.get("_restore_attribute_keys"),
                        restore_ca=bool(result.get("_restore_ca", True)),
                        restore_pa=bool(result.get("_restore_pa", True)),
                    )

        try:
            plan = relationship_training_effect_plan(session)
            stored_progress = relationship_training_progress()
            live_people: dict[tuple[str, int], dict[str, Any]] = {}
            pair_details: dict[tuple[str, int, str, int], dict[str, Any]] = {}
            with borrow_game_operation() as operation:
                for participant in session.get("participants") or []:
                    kind = str(participant.get("kind") or "")
                    identifier = int(participant.get("id") or 0)
                    team_id = int(participant.get("team_id") or 0)
                    profile = next((
                        row for row in profiles
                        if int((row.get("team") or {}).get("id") or 0) == team_id
                    ), None)
                    person = next((
                        row for row in self._relationship_training_people(profile, kind)
                        if int(row.get("id") or 0) == identifier
                    ), None)
                    if not person:
                        raise ValueError("综训参与者已不属于原球队，请刷新后重试")
                    person_address = resolve_public_person_address(
                        operation.reader, person, kind,
                    )
                    public_profile = read_person_public_profile(
                        operation.reader, person_address,
                    )
                    if int((public_profile or {}).get("uid") or 0) != identifier:
                        raise ValueError("综训参与者身份已变化，请刷新后重试")
                    live_people[(kind, identifier)] = {
                        "source": person, "player_address": person.get("address"),
                        "person_address": person_address,
                    }
                for pair in plan["pairs"]:
                    left = pair["person_a"]
                    right = pair["person_b"]
                    left_key = (str(left["kind"]), int(left["id"]))
                    right_key = (str(right["kind"]), int(right["id"]))
                    detail = read_relationship_pair(
                        operation.reader,
                        int(live_people[left_key]["person_address"]),
                        int(live_people[right_key]["person_address"]),
                    )
                    for direction in (detail.get("a_to_b"), detail.get("b_to_a")):
                        if direction and int(direction.get("relation_type", 1)) != 1:
                            raise ValueError(
                                f"{left.get('name')} 与 {right.get('name')} 已产生负面关系，训练自动终止"
                            )
                    pair_details[(*left_key, *right_key)] = detail

            definition = RELATIONSHIP_TRAINING_ROOMS[str(session["room_sku"])]
            if session["room_sku"] == "mentoring_room":
                mentor = next(
                    row for row in session["participants"] if row.get("role") == "mentor"
                )
                source = live_people[("player", int(mentor["id"]))]["source"]
                attributes = source.get("attributes") or {}
                credibility = (
                    int(source.get("ca") or 0) >= 140
                    or int(source.get("age") or 0) >= 28
                    or int((attributes.get("精神") or {}).get("领导力") or 0) >= 15
                    or max(
                        int(source.get("home_reputation") or 0),
                        int(source.get("current_reputation") or 0),
                        int(source.get("world_reputation") or 0),
                    ) >= 5000
                )
                if not credibility:
                    raise ValueError("导师的 CA、年龄、领导力或声望尚未达到传习资格")
            coach_source: dict[str, Any] | None = None
            coach_multiplier = 1.0
            if session["room_sku"] == "tactical_room":
                coach = next(
                    row for row in session["participants"] if row.get("role") == "coach"
                )
                coach_source = live_people[("staff", int(coach["id"]))]["source"]
                license_code = int((coach_source.get("coaching_license") or {}).get("code") or -1)
                if int(coach_source.get("job_type") or -1) not in {1, 16, 2, 34, 22, 26} or license_code not in range(1, 8):
                    raise ValueError("战术指导室需要教练岗位的持证教练")
                coach_multiplier = coach_composite_multiplier(
                    license_code, int(coach_source.get("current_reputation") or 0),
                )
            staff_team_bonus = 0.0
            staff_team_multiplier = 1.0
            if session["room_sku"] in {"video_analysis_room", "sports_science_room"}:
                staff_role = (
                    "analyst" if session["room_sku"] == "video_analysis_room" else "scientist"
                )
                staff_participant = next(
                    row for row in session["participants"] if row.get("role") == staff_role
                )
                team_id = int(staff_participant.get("team_id") or 0)
                staff_profile = next((
                    row for row in profiles
                    if int((row.get("team") or {}).get("id") or 0) == team_id
                ), None)
                capabilities = compute_team_capabilities(
                    list((staff_profile or {}).get("staff") or [])
                )
                if session["room_sku"] == "video_analysis_room":
                    staff_team_bonus = float(capabilities["analysis"]["bonus"])
                else:
                    staff_team_bonus = float(capabilities["sports_science"]["bonus"])
                staff_team_multiplier = 1.0 + staff_team_bonus

            def coach_can_teach(attribute_key: str) -> bool:
                if coach_source is None:
                    return True
                name = attribute_key.partition(":")[2]
                abilities = coach_source.get("abilities") or {}
                hidden = coach_source.get("hidden_attributes") or {}
                values = {
                    "适应性": [abilities.get("适应能力"), hidden.get("适应性")],
                    "雄心": [hidden.get("雄心")],
                    "忠诚": [hidden.get("忠诚")],
                    "职业素养": [abilities.get("人员管理"), abilities.get("激励")],
                    "稳定性": [abilities.get("战术知识")],
                    "大赛发挥": [abilities.get("激励"), abilities.get("意志力")],
                    "多面性": [abilities.get("战术训练")],
                }.get(name, [])
                valid = [int(value) for value in values if value is not None]
                return bool(valid) and sum(valid) / len(valid) >= 15

            read_targets: list[dict[str, Any]] = []
            for participant in session.get("participants") or []:
                if participant.get("kind") != "player":
                    continue
                live = live_people[("player", int(participant["id"]))]
                for attribute in plan["attributes"]:
                    if str(attribute.get("kind")) == "height":
                        continue
                    key = str(attribute["key"])
                    read_targets.append({
                        "id": f"{int(participant['id'])}:{key}",
                        "player_id": int(participant["id"]),
                        "player_address": live["player_address"],
                        "attribute_key": key,
                        "attribute_id": int(VISIBLE_ATTRIBUTE_IDS.get(key) or -1),
                        "attribute_kind": str(attribute.get("kind") or "visible"),
                    })
            current_values = read_player_training_attributes(read_targets)
            required_keys = {
                str(target["id"]) for target in read_targets
                if any(
                    int(row.get("id") or 0) == int(target["player_id"])
                    for row in plan["beneficiaries"]
                )
            }
            if set(current_values) < required_keys:
                raise ValueError("无法完整回读综训属性，请刷新后重试")

            mentor_id = next((
                int(row["id"]) for row in session.get("participants") or []
                if row.get("role") == "mentor"
            ), 0)
            mentor_source = (
                live_people[("player", mentor_id)]["source"] if mentor_id else None
            )
            attribute_changes: list[dict[str, Any]] = []
            attribute_progress_updates: dict[str, float] = {}

            def partner_bonus(beneficiary: dict[str, Any]) -> float:
                identity = (str(beneficiary["kind"]), int(beneficiary["id"]))
                total = 0.0
                for pair in plan["pairs"]:
                    left = pair["person_a"]
                    right = pair["person_b"]
                    left_key = (str(left["kind"]), int(left["id"]))
                    right_key = (str(right["kind"]), int(right["id"]))
                    detail = pair_details.get((*left_key, *right_key), {})
                    if identity == left_key:
                        total += relationship_intimacy_bonus(detail.get("a_to_b"))
                    elif identity == right_key:
                        total += relationship_intimacy_bonus(detail.get("b_to_a"))
                return total

            def room_multiplier(beneficiary: dict[str, Any], attribute_key: str) -> float:
                if mentor_source is not None:
                    student = live_people[("player", int(beneficiary["id"]))]["source"]
                    return 1.0 + abs(
                        estimate_player_status_tier(mentor_source)
                        - estimate_player_status_tier(student)
                    ) * 0.5
                if session["room_sku"] == "video_analysis_room":
                    return staff_team_multiplier
                if session["room_sku"] == "sports_science_room":
                    source = live_people[("player", int(beneficiary["id"]))]["source"]
                    sharpness = float(source.get("sharpness") or 0)
                    sharpness_raw = sharpness * 100 if sharpness <= 100 else sharpness
                    fatigue = float(source.get("fatigue") or 0)
                    if attribute_key == "精神:勇敢":
                        return 1.5 if sharpness_raw < 5000 else 1.0
                    if attribute_key == "身体:体质":
                        return (0.5 if fatigue > 5000 else 1.0) * staff_team_multiplier
                    if attribute_key == "hidden:受伤倾向":
                        return max(0.0, 1.0 + (
                            float(current_values.get(
                                f"{int(beneficiary['id'])}:hidden:受伤倾向", 10
                            )) - 10.0
                        ) * 0.1) * (1.0 - staff_team_bonus)
                    return staff_team_multiplier
                return coach_multiplier

            if int(plan["elapsed_days"]) > 0:
                for beneficiary in plan["beneficiaries"]:
                    player_id = int(beneficiary["id"])
                    live = live_people[("player", player_id)]
                    for attribute in plan["attributes"]:
                        key = str(attribute["key"])
                        direction = -1 if attribute.get("direction") == "dec" else 1
                        before = int(current_values[f"{player_id}:{key}"])
                        if mentor_id:
                            mentor_value = current_values.get(f"{mentor_id}:{key}")
                            threshold_ok = (
                                mentor_value is not None and (
                                    direction > 0 and int(mentor_value) >= 15
                                    or direction < 0 and int(mentor_value) <= 10
                                )
                            )
                            if not threshold_ok or (
                                direction > 0 and int(mentor_value) <= before
                            ) or (direction < 0 and int(mentor_value) >= before):
                                continue
                        if not coach_can_teach(key):
                            continue
                        progress_key = attribute_progress_key(
                            str(session["room_sku"]), beneficiary, key,
                        )
                        points = (
                            float(stored_progress["attribute_progress"].get(progress_key, 0.0))
                            + float(plan["attribute_points"])
                            * (1.0 + partner_bonus(beneficiary))
                            * room_multiplier(beneficiary, key)
                        )
                        after = before
                        while 1 <= after + direction <= 20:
                            if mentor_id and (
                                direction > 0 and after + direction > int(mentor_value)
                                or direction < 0 and after + direction < int(mentor_value)
                            ):
                                break
                            required = training_points_required_for_direction(after, direction)
                            if points < required:
                                break
                            points -= required
                            after += direction
                        attribute_progress_updates[progress_key] = points
                        amount = after - before
                        if not amount:
                            continue
                        if str(attribute.get("kind")) == "hidden":
                            current = before
                            for _ in range(abs(amount)):
                                result = develop_player_hidden_attribute(
                                    player_id, live["player_address"], key, current, direction,
                                )
                                attribute_writes.append({
                                    "kind": "hidden", "player_id": player_id,
                                    "player_address": live["player_address"],
                                    "attribute_key": key, "result": result,
                                })
                                current += direction
                        else:
                            result = develop_player(
                                player_id, live["player_address"], key, before,
                                "training", amount,
                            )
                            attribute_writes.append({
                                "kind": "visible", "player_id": player_id,
                                "player_address": live["player_address"],
                                "attribute_key": key, "result": result,
                            })
                        attribute_changes.append({
                            "participant_id": player_id,
                            "participant_name": str(beneficiary.get("name") or player_id),
                            "attribute": key, "before": before, "after": after,
                            "change": amount,
                        })

            height_baseline_updates: dict[str, int] = {}
            if (
                session["room_sku"] == "sports_science_room"
                and "physical:height" in {str(row["key"]) for row in plan["attributes"]}
                and int(plan["elapsed_days"]) > 0
            ):
                for beneficiary in plan["beneficiaries"]:
                    player_id = int(beneficiary["id"])
                    live = live_people[("player", player_id)]
                    source = live["source"]
                    height = int(source.get("height_cm") or 0)
                    age = int(source.get("age") or 0)
                    if not 100 <= height <= 250 or age <= 0:
                        raise ValueError("无法读取运动科学室球员的年龄或身高")
                    baseline_key = str(player_id)
                    baseline = int(
                        stored_progress.get("height_baselines", {}).get(baseline_key, height)
                    )
                    height_baseline_updates[baseline_key] = baseline
                    probability = sports_science_height_probability(
                        age, height, staff_team_bonus, partner_bonus(beneficiary),
                    )
                    if (
                        height >= sports_science_height_limit(baseline)
                        or deterministic_settlement_roll(
                            str(session["id"]), player_id, "height"
                        ) >= probability
                    ):
                        continue
                    result = develop_player_hidden_attribute(
                        player_id, live["player_address"], "physical:height", height, 1,
                    )
                    attribute_writes.append({
                        "kind": "hidden", "player_id": player_id,
                        "player_address": live["player_address"],
                        "attribute_key": "physical:height", "result": result,
                    })
                    attribute_changes.append({
                        "participant_id": player_id,
                        "participant_name": str(beneficiary.get("name") or player_id),
                        "attribute": "physical:height", "before": height,
                        "after": height + 1, "change": 1,
                        "probability": round(probability, 6),
                    })

            condition_changes: list[dict[str, Any]] = []
            if session["room_sku"] == "sports_science_room":
                for beneficiary in plan["beneficiaries"]:
                    player_id = int(beneficiary["id"])
                    live = live_people[("player", player_id)]
                    result = adjust_player_training_condition(
                        player_id, live["player_address"], staff_team_multiplier,
                    )
                    attribute_writes.append({
                        "kind": "condition", "player_id": player_id,
                        "player_address": live["player_address"], "result": result,
                    })
                    condition_changes.append({
                        "participant_id": player_id,
                        "participant_name": str(beneficiary.get("name") or player_id),
                        "before": result["before"], "after": result["after"],
                    })

            relationship_changes: list[dict[str, Any]] = []
            intimacy_progress_updates: dict[str, float] = {}
            active_pairs: list[dict[str, Any]] = []
            for pair in plan["pairs"]:
                left = pair["person_a"]
                right = pair["person_b"]
                left_key = (str(left["kind"]), int(left["id"]))
                right_key = (str(right["kind"]), int(right["id"]))
                detail = pair_details.get((*left_key, *right_key), {})
                pair_room_multiplier = (
                    staff_team_multiplier
                    if session["room_sku"] in {"video_analysis_room", "sports_science_room"}
                    else coach_multiplier
                )
                if mentor_source is not None:
                    student = right if right.get("role") == "student" else left
                    pair_room_multiplier = 1.0 + abs(
                        estimate_player_status_tier(mentor_source)
                        - estimate_player_status_tier(
                            live_people[("player", int(student["id"]))]["source"]
                        )
                    ) * 0.5
                a_key = directed_progress_key(left, right)
                b_key = directed_progress_key(right, left)
                a_accumulated = (
                    float(stored_progress["intimacy_progress"].get(a_key, 0.0))
                    + float(pair["base_increment"])
                    * (1.0 + relationship_intimacy_bonus(detail.get("a_to_b")))
                    * pair_room_multiplier
                )
                b_accumulated = (
                    float(stored_progress["intimacy_progress"].get(b_key, 0.0))
                    + float(pair["base_increment"])
                    * (1.0 + relationship_intimacy_bonus(detail.get("b_to_a")))
                    * pair_room_multiplier
                )
                points_a2b = int(a_accumulated)
                points_b2a = int(b_accumulated)
                intimacy_progress_updates[a_key] = a_accumulated - points_a2b
                intimacy_progress_updates[b_key] = b_accumulated - points_b2a
                if points_a2b or points_b2a:
                    active_pairs.append({
                        **pair, "points_a2b": points_a2b, "points_b2a": points_b2a,
                        "detail": detail,
                    })
            if active_pairs:
                with borrow_game_operation(write_memory=True) as operation:
                    try:
                        for pair in active_pairs:
                            left = pair["person_a"]; right = pair["person_b"]
                            left_live = live_people[(str(left["kind"]), int(left["id"]))]
                            right_live = live_people[(str(right["kind"]), int(right["id"]))]
                            result = write_bidirectional_intimacy(
                                int(left_live["person_address"]),
                                int(right_live["person_address"]),
                                reason_a2b=int(pair["reason_a2b"]),
                                reason_b2a=int(pair["reason_b2a"]),
                                points_a2b=int(pair["points_a2b"]),
                                points_b2a=int(pair["points_b2a"]), operation=operation,
                            )
                            relationship_writes.append(result)
                            before_a2b = pair["detail"].get("a_to_b") or {}
                            before_b2a = pair["detail"].get("b_to_a") or {}

                            def archive_direction(
                                before: dict[str, Any], after: dict[str, Any],
                            ) -> dict[str, Any]:
                                relation_type = int(before.get("relation_type", 1))
                                before_level = int(before.get("level") or 0)
                                after_level = int(after.get("after") or 0)
                                sign = 1 if relation_type == 1 else -1
                                return {
                                    "before": before_level, "after": after_level,
                                    "signed_before": sign * before_level,
                                    "signed_after": sign * after_level,
                                    "points": int(after.get("applied") or 0),
                                    "reason": int(after.get("reason") or 0),
                                    "relation_type": relation_type,
                                    "permanence": int(before.get("permanence") or 0),
                                    "new_record": bool(after.get("new_record")),
                                }

                            relationship_changes.append({
                                "person_a": {
                                    "id": int(left["id"]), "name": left.get("name"),
                                    "kind": left.get("kind"), "role": left.get("role"),
                                },
                                "person_b": {
                                    "id": int(right["id"]), "name": right.get("name"),
                                    "kind": right.get("kind"), "role": right.get("role"),
                                },
                                "a_to_b": archive_direction(before_a2b, result["a_to_b"]),
                                "b_to_a": archive_direction(before_b2a, result["b_to_a"]),
                                "reason_a2b": int(result["a_to_b"].get("reason") or 0),
                                "reason_b2a": int(result["b_to_a"].get("reason") or 0),
                            })
                    except Exception:
                        for result in reversed(relationship_writes):
                            rollback_bidirectional_intimacy(result, operation=operation)
                        relationship_writes.clear()
                        raise

            settlement = {
                "elapsed_days": int(plan["elapsed_days"]),
                "focus_coefficient": float(plan["focus_coefficient"]),
                "attribute_changes": attribute_changes,
                "condition_changes": condition_changes,
                "relationship_changes": relationship_changes,
            }
            committed = commit_relationship_training_settlement(
                room_id, str(session["id"]), settlement, scope_id=scope_id,
                attribute_progress=attribute_progress_updates,
                intimacy_progress=intimacy_progress_updates,
                height_baselines=height_baseline_updates,
            )
        except Exception as error:
            try:
                rollback_native()
            except Exception as rollback_error:
                raise PlayerEffectRollbackError(error, rollback_error) from error
            try:
                restore_relationship_training_room(room_id)
            except Exception as restore_error:
                raise RuntimeError(f"综训结算失败且房间状态恢复未完成：{restore_error}") from error
            raise

        invalidate_club_profile_cache()
        return {
            "ok": True, "settlement": committed["completed"],
            "archive": committed["archive"],
            "rooms": self.relationship_training_rooms_state(),
        }

    def public_club_legacy(self, team_id: int = 0) -> dict[str, Any]:
        with self.lock:
            output = dict(self.output)
            profiles = dict(self.club_profiles)
            if self.club_refreshing:
                profiles.update(self.club_loading_profiles)
        career_id = str(output.get("save_instance_id") or "")
        scope_id = self._data_scope_id(output) if output else ""
        if not career_id or not scope_id:
            raise ValueError("尚未识别当前存档和经理账户")
        active_season = club_legacy_season_identity(
            str(output.get("game_date") or ""),
            str(output.get("season_start") or ""),
            str(output.get("season_end") or ""),
        )
        requested_team_id = int(team_id or 0)
        if requested_team_id == 0:
            index = load_public_club_legacy_index(career_id, scope_id)
            current_club = next((
                team for team in (output.get("managed_teams") or [])
                if str(team.get("team_type") or "club") == "club"
            ), None)
            if current_club is None:
                candidate = output.get("managed_team") or {}
                current_club = candidate if str(candidate.get("team_type") or "club") == "club" else {}
            index["current_team_id"] = int((current_club or {}).get("id") or 0) or None
            index["active_season"] = active_season or None
            return index
        profile = profiles.get(requested_team_id)
        if profile and str((profile.get("team") or {}).get("team_type") or "club") == "national":
            raise ValueError("国家队不属于俱乐部名人堂范围")
        result = load_public_club_legacy(career_id, scope_id, requested_team_id)
        result["active_season"] = active_season or None
        return result

    def public_transfer_history(self) -> dict[str, Any]:
        """Project permanent transfer records across this manager's clubs."""
        with self.lock:
            output = dict(self.output)
        career_id = str(output.get("save_instance_id") or "")
        scope_id = self._data_scope_id(output) if output else ""
        if not career_id or not scope_id:
            raise ValueError("尚未识别当前存档和经理账户")
        manager = output.get("manager") or {}
        manager_id = int(
            output.get("selected_manager_id") or manager.get("id") or 0
        )
        current_club = next((
            team for team in (output.get("managed_teams") or [])
            if str(team.get("team_type") or "club") == "club"
        ), None)
        if current_club is None:
            candidate = output.get("managed_team") or {}
            current_club = (
                candidate
                if str(candidate.get("team_type") or "club") == "club" else {}
            )
        result = load_public_transfer_history(
            career_id, scope_id, manager_id=manager_id,
            current_team_id=int((current_club or {}).get("id") or 0),
        )
        native_team_ids = {
            int(row.get("id") or 0) for row in (result.get("clubs") or [])
            if isinstance(row, dict) and int(row.get("id") or 0) > 0
        }
        current_team_id = int((current_club or {}).get("id") or 0)
        if current_team_id > 0:
            native_team_ids.add(current_team_id)
        memory_lock = getattr(self, "memory_lock", None)
        if native_team_ids and memory_lock is not None:
            try:
                with memory_lock:
                    native = read_native_transfer_history(
                        native_team_ids, save_identity=career_id,
                    )
                result = merge_native_transfer_history(result, native)
            except (OSError, RuntimeError, TypeError, ValueError):
                # Unsupported builds and transient native-read failures keep
                # the durable FMODD projection intact.
                pass
        result["data_scope_id"] = scope_id
        return result

    def update_club_legacy_preference(self, payload: dict[str, Any]) -> dict[str, Any]:
        with self.lock:
            output = dict(self.output)
        career_id = str(output.get("save_instance_id") or "")
        scope_id = self._data_scope_id(output) if output else ""
        if not career_id or not scope_id:
            raise ValueError("尚未识别当前存档和经理账户")
        team_id = int(payload.get("team_id") or 0)
        player_id = int(payload.get("player_id") or 0)
        options: dict[str, Any] = {}
        for key in ("inducted", "favorite", "tier", "note", "career_record"):
            if key in payload:
                options[key] = payload[key]
        if not options:
            raise ValueError("没有需要保存的名人堂设置")
        if team_id == WORLD_WATCH_TEAM_ID and options.get("favorite") is True:
            with self._timed_user_memory_operation("club_legacy_world_follow"):
                player = read_world_player_profile(player_id)
                wrapper = {"players": [player]}
                apply_player_aliases(wrapper, scope_id)
                player = wrapper["players"][0]
            sync_world_watch_player(
                career_id, player,
                game_date=str(output.get("game_date") or ""),
                game_layout=str(output.get("game_layout") or ""),
            )
        return set_club_legacy_preference(
            career_id, scope_id, team_id, player_id, **options,
        )

    def update_club_legacy_best_team(self, payload: dict[str, Any]) -> dict[str, Any]:
        with self.lock:
            output = dict(self.output)
        career_id = str(output.get("save_instance_id") or "")
        scope_id = self._data_scope_id(output) if output else ""
        if not career_id or not scope_id:
            raise ValueError("尚未识别当前存档和经理账户")
        return set_club_legacy_best_team(
            career_id, scope_id, int(payload.get("team_id") or 0),
            lineup_kind=str(payload.get("lineup_kind") or ""),
            season_key=str(payload.get("season_key") or ""),
            formation=str(payload.get("formation") or ""),
            assignments=payload.get("assignments") or {},
        )

    def _refresh_world_watch_players(
        self, career_id: str, scope_id: str, game_date: str, game_layout: str,
        *, is_current: Callable[[], bool] | None = None,
    ) -> list[str]:
        """Re-observe followed world players without failing the club refresh."""
        watched = load_public_club_legacy(
            career_id, scope_id, WORLD_WATCH_TEAM_ID,
        )
        errors: list[str] = []
        for row in watched.get("players") or []:
            if is_current is not None and not is_current():
                break
            if not bool(row.get("favorite")):
                continue
            player_id = int(row.get("id") or 0)
            if player_id <= 0:
                continue
            try:
                if is_current is None:
                    player = read_world_player_profile(player_id)
                else:
                    with self.memory_lock:
                        if not is_current():
                            break
                        player = read_world_player_profile(player_id)
                    if not is_current():
                        break
                wrapper = {"players": [player]}
                apply_player_aliases(wrapper, scope_id)
                sync_world_watch_player(
                    career_id, wrapper["players"][0],
                    game_date=game_date, game_layout=game_layout,
                )
            except Exception as error:
                errors.append(f"世界关注球员 {player_id}: {error}")
        return errors

    def _sync_club_legacy_job(
        self, job: dict[str, Any], is_current: Callable[[], bool],
    ) -> list[str]:
        # Explicit binding also covers a job drained by an older club thread.
        set_active_save_id(job["scope_id"])
        errors = []
        for profile in job["profiles"].values():
            if not is_current():
                return errors
            if str((profile.get("team") or {}).get("team_type") or "club") != "club":
                continue
            try:
                sync_club_profile(
                    job["career_id"], profile, game_layout=job["game_layout"],
                    season_start=job["season_start"], season_end=job["season_end"],
                )
            except Exception as error:
                errors.append(str(error))
        if is_current():
            errors.extend(self._refresh_world_watch_players(
                job["career_id"], job["scope_id"], job["game_date"], job["game_layout"],
                is_current=is_current,
            ))
        return errors

    def add_club_legacy_match_moment(self, payload: dict[str, Any]) -> dict[str, Any]:
        with self.lock:
            output = dict(self.output)
        career_id = str(output.get("save_instance_id") or "")
        scope_id = self._data_scope_id(output) if output else ""
        if not career_id or not scope_id:
            raise ValueError("尚未识别当前存档和经理账户")
        team_id = int(payload.get("team_id") or 0)
        player_id = int(payload.get("player_id") or 0)
        moment = payload.get("moment")
        if not isinstance(moment, dict):
            moment = payload
        moment = dict(moment)
        # Native event vectors are process-memory evidence, not client input.
        # Resolve only the selected fixture here; reading every historical
        # result during odds refresh made large saves monopolize the service.
        moment.pop("goal_events", None)
        try:
            moment_key = (
                str(moment.get("game_date") or moment.get("date") or "")[:10],
                int(moment.get("competition_id") or 0),
                int((moment.get("home") or {}).get("id") or 0),
                int((moment.get("away") or {}).get("id") or 0),
            )
        except (AttributeError, TypeError, ValueError):
            moment_key = ("", 0, 0, 0)
        history = read_result_history(career_id)
        authoritative = None
        for item in [*history, *(output.get("season_results") or [])]:
            if not isinstance(item, dict):
                continue
            home = item.get("home") or item.get("home_team") or {}
            away = item.get("away") or item.get("away_team") or {}
            competition = item.get("competition") or {}
            try:
                item_key = (
                    str(item.get("date") or "")[:10],
                    int(item.get("competition_id") or competition.get("id") or 0),
                    int(home.get("id") or 0),
                    int(away.get("id") or 0),
                )
            except (AttributeError, TypeError, ValueError):
                continue
            if item_key == moment_key:
                authoritative = item
        tags = moment.get("tags") or []
        needs_late_goal_evidence = bool(
            "进球" in tags
            and moment.get("minute") not in (None, "")
            and int(moment.get("minute") or 0) >= 85
        )
        if authoritative is not None and needs_late_goal_evidence:
            try:
                with self.memory_lock:
                    events = read_result_goal_events(authoritative)
            except (OSError, RuntimeError, TypeError, ValueError):
                events = None
            if isinstance(events, list):
                moment["goal_events"] = events
        return add_club_legacy_match_moment(
            career_id, scope_id, team_id, player_id, moment,
        )

    def _settle_youth_plan_shortfall(
        self, scope_id: str, output: dict[str, Any], club: dict[str, Any],
        kind: str, result: dict[str, Any],
    ) -> dict[str, Any]:
        shortfall = max(0, int(result.get("shortfall") or 0))
        if shortfall <= 0:
            return {}
        team_id = int(club.get("id") or result.get("team_id") or 0)
        plan = youth_plans_for_team(scope_id, team_id).get(kind) or {}
        if plan.get("status") == "completed_with_refund":
            return {
                "refund": dict(plan.get("refund_result") or {}),
                "plan": plan,
                "mail": None,
                "already_settled": True,
            }
        if plan.get("roster_recovery_only"):
            raise RuntimeError("误判恢复计划已经在原结算中退款，不能重复退款")
        config = normalize_youth_plan_config(kind, plan.get("config"))
        expected_count = max(1, int(config["count"]))
        shortfall = min(expected_count, shortfall)
        payment = dict(plan.get("payment") or {})
        if float(payment.get("total") or 0) <= 0:
            raise RuntimeError("青训计划缺少原支付记录，已停止自动结算以避免错误退款")
        ratio = shortfall / expected_count
        refund_payment = {
            "bank": scaled_money(payment.get("bank") or 0, ratio),
            "wallet": scaled_money(payment.get("wallet") or 0, ratio),
            "transaction_id": str(
                payment.get("transaction_id")
                or f"youth-plan:{scope_id}:{team_id}:{kind}:{plan.get('armed_at') or ''}"
            ),
        }
        refund_payment["total"] = canonical_money(
            refund_payment["bank"] + refund_payment["wallet"]
        )
        fulfilled_count = max(0, expected_count - shortfall)
        refund = refund_combined_funds(
            refund_payment, f"world_club_{kind}_shortfall_refund",
            team_id=team_id, team_name=str(club.get("name") or ""),
            expected_count=expected_count, fulfilled_count=fulfilled_count,
            missing_count=shortfall,
        )
        mail = archive_youth_shortfall_refund_mail(
            armed_at=str(plan.get("armed_at") or ""), kind=kind,
            team_id=team_id, team_name=str(club.get("name") or ""),
            game_date=str(output.get("game_date") or ""),
            expected_count=expected_count, fulfilled_count=fulfilled_count,
            missing_count=shortfall, refund=refund,
        )
        settled_plan = complete_youth_plan_shortfall(
            scope_id, team_id, kind, shortfall=shortfall,
            eligible_count=max(0, int(result.get("eligible_count") or 0)),
            observed_count=max(0, int(result.get("observed_count") or 0)),
            refund=refund,
        )
        return {"refund": refund, "plan": settled_plan, "mail": mail}

    def _persist_youth_generation_progress(self) -> dict[str, Any]:
        status = self.youth_generation_hook.status()
        scope_id = str(getattr(self, "youth_generation_scope_id", None) or "")
        son_generation_completed = bool(
            int(status.get("son_applied_count") or 0) > 0
        )
        generation_active = bool(
            int((status.get("diagnostics") or {}).get("active_calls") or 0) > 0
        )
        if scope_id and (status.get("targets") or status.get("son_target")):
            record_youth_generation_progress(scope_id, status)
        plans = active_youth_generation_plans(scope_id) if scope_id else []
        son_target = status.get("son_target") or {}
        son_plan = next(
            (plan for plan in plans if plan.get("kind") == "academy_son"),
            None,
        )
        if scope_id and son_plan and generation_active:
            status["son_finalized"] = False
            status["son_finalize_reason"] = "原生青训生成仍在进行"
        if scope_id and son_plan and not generation_active:
            try:
                if int(status.get("son_applied_count") or 0) > 0:
                    quality_reconciliation = (
                        self.youth_generation_hook.reconcile_son_quality()
                    )
                    if quality_reconciliation.get("reconciled"):
                        status = self.youth_generation_hook.status()
                        son_target = status.get("son_target") or son_target
                    status["son_quality_reconciliation"] = quality_reconciliation
                team_id = int(son_plan.get("team_id") or 0)
                _scope_id, output, club = self._owned_world_club_target(
                    team_id, quick_rebind=True,
                )
                manager = output.get("manager") or {}
                manager_id = int(
                    output.get("selected_manager_id") or manager.get("id") or 0
                )
                manager_context = (
                    self.club_context
                    or next(iter(self.club_contexts.values()), None)
                    or {}
                )
                manager_team = (
                    manager_context.get("team") or output.get("managed_team") or {}
                )
                finalized = finalize_academy_son_attributes(
                    scope_id, team_id, club.get("address"),
                    str(output.get("game_date") or ""),
                    manager_id=manager_id,
                    manager_team_id=int(manager_team.get("id") or 0),
                    manager_team_address=manager_team.get("address"),
                    manager_address=(
                        manager_team.get("manager_address")
                        or manager.get("manager_address")
                    ),
                    allow_random_fallback=True,
                    fallback_requires_formed_at_club=False,
                    require_stable_cohort=True,
                )
                status["son_finalized"] = bool(finalized.get("finalized"))
                status["son_player"] = finalized.get("player")
                status["son_finalize_reason"] = finalized.get("reason")
                status["son_selection_mode"] = finalized.get("selection_mode")
                if finalized.get("finalized") and son_plan.get("armed_at"):
                    completed_plan = youth_plans_for_team(scope_id, team_id).get(
                        "academy_son"
                    ) or {}
                    try:
                        status["son_completion_mail"] = archive_youth_completion_mail(
                            armed_at=str(completed_plan.get("armed_at") or ""),
                            kind="academy_son", team_id=team_id,
                            team_name=str(club.get("name") or ""),
                            game_date=str(output.get("game_date") or ""),
                            player_names=_youth_plan_generated_names(
                                "academy_son", completed_plan,
                            ),
                        )
                    except Exception as error:
                        status["son_completion_mail_error"] = str(error)
                if int(finalized.get("shortfall") or 0) > 0:
                    status["son_shortfall_pending_manual_confirmation"] = {
                        key: max(0, int(finalized.get(key) or 0))
                        for key in ("eligible_count", "observed_count", "shortfall")
                    }
                    status["son_finalize_reason"] = (
                        "自动核验暂未找到足够的儿子候选；计划继续等待，"
                        "确认正式青训名单已经生成后可手动核验"
                    )
            except Exception as error:
                status["son_finalized"] = False
                status["son_finalize_error"] = str(error)
        roster_results = []
        if scope_id:
            for plan in active_youth_generation_plans(scope_id):
                if plan.get("kind") != "golden_generation":
                    continue
                team_id = int(plan.get("team_id") or 0)
                try:
                    if generation_active:
                        roster_results.append({
                            "team_id": team_id,
                            "finalized": False,
                            "reason": "原生青训生成仍在进行",
                        })
                        continue
                    pending_verification = dict(
                        plan.get("verification_result") or {}
                    )
                    pending_shortfall = max(
                        0, int(pending_verification.get("shortfall") or 0),
                    )
                    if (
                        pending_shortfall > 0
                        and pending_verification.get(
                            "shortfall_settlement_pending"
                        ) is True
                    ):
                        _scope_id, output, club = self._owned_world_club_target(
                            team_id, quick_rebind=True,
                        )
                        settlement = self._settle_youth_plan_shortfall(
                            scope_id, output, club, "golden_generation", {
                                "team_id": team_id,
                                "shortfall": pending_shortfall,
                                "eligible_count": max(
                                    0, int(pending_verification.get(
                                        "eligible_count"
                                    ) or 0),
                                ),
                                "observed_count": max(
                                    0, int(pending_verification.get(
                                        "observed_count"
                                    ) or 0),
                                ),
                            },
                        )
                        settled_plan = settlement.get("plan") or {}
                        roster_results.append({
                            "team_id": team_id,
                            "finalized": True,
                            "remaining": 0,
                            "status": "completed_with_refund",
                            "settlement": settlement,
                            "refund": settlement.get("refund"),
                            "mail": settlement.get("mail"),
                            "plan": settled_plan,
                            "reason": str(
                                settled_plan.get("last_result", {}).get("message")
                                or "已修正本批小妖；缺少名额的费用已退款"
                            ),
                        })
                        continue
                    son_plan = youth_plans_for_team(scope_id, team_id).get(
                        "academy_son"
                    ) or {}
                    son_ids = {
                        int(value)
                        for value in son_plan.get("processed_player_ids") or []
                        if int(value) > 0
                    }
                    son_result = son_plan.get("ability_result") or {}
                    if int(son_result.get("player_id") or 0) > 0:
                        son_ids.add(int(son_result["player_id"]))
                    if (
                        son_plan.get("status") in {"armed", "waiting"}
                        and not son_ids
                    ):
                        roster_results.append({
                            "team_id": team_id,
                            "finalized": False,
                            "reason": "等待同俱乐部儿子计划先完成",
                        })
                        continue
                    _scope_id, output, club = self._owned_world_club_target(
                        team_id, quick_rebind=True,
                    )
                    result = finalize_golden_generation_attributes(
                        scope_id, team_id, club.get("address"),
                        str(output.get("game_date") or ""),
                        excluded_player_ids=son_ids,
                        require_stable_cohort=True,
                    )
                    roster_result = {"team_id": team_id, **result}
                    if int(result.get("shortfall") or 0) > 0:
                        settlement = self._settle_youth_plan_shortfall(
                            scope_id, output, club, "golden_generation",
                            {"team_id": team_id, **result},
                        )
                        settled_plan = settlement.get("plan") or {}
                        roster_result.update({
                            "finalized": True,
                            "remaining": 0,
                            "status": "completed_with_refund",
                            "settlement": settlement,
                            "refund": settlement.get("refund"),
                            "mail": settlement.get("mail"),
                            "plan": settled_plan,
                            "reason": str(
                                settled_plan.get("last_result", {}).get("message")
                                or "已修正本批小妖；缺少名额的费用已退款"
                            ),
                        })
                    elif result.get("finalized") and plan.get("armed_at"):
                        completed_plan = youth_plans_for_team(scope_id, team_id).get(
                            "golden_generation"
                        ) or {}
                        try:
                            roster_result["completion_mail"] = (
                                archive_youth_completion_mail(
                                    armed_at=str(completed_plan.get("armed_at") or ""),
                                    kind="golden_generation", team_id=team_id,
                                    team_name=str(club.get("name") or ""),
                                    game_date=str(output.get("game_date") or ""),
                                    player_names=_youth_plan_generated_names(
                                        "golden_generation", completed_plan,
                                    ),
                                )
                            )
                        except Exception as error:
                            roster_result["completion_mail_error"] = str(error)
                    roster_results.append(roster_result)
                except Exception as error:
                    roster_results.append({
                        "team_id": team_id,
                        "finalized": False,
                        "error": str(error),
                    })
        if roster_results:
            status["roster_finalizations"] = roster_results
        if scope_id and (
            status.get("son_finalized")
            or son_generation_completed
            or any(
                result.get("finalized") or result.get("settlement")
                for result in roster_results
            )
        ):
            output = dict(getattr(self, "output", {}) or {})
            try:
                status["post_finalize_hook_sync"] = self._sync_youth_generation_plans(
                    scope_id,
                    str(
                        output.get("save_instance_id")
                        or self._data_scope_id(output)
                    ),
                )
            except Exception as error:
                status["post_finalize_hook_sync_error"] = str(error)
        return status

    def _reconcile_youth_generation_if_due(
        self, now: float | None = None, *, force: bool = False,
    ) -> dict[str, Any] | None:
        """Advance active youth plans without depending on a page request."""
        checked_at = monotonic() if now is None else float(now)
        scope_id = str(getattr(self, "youth_generation_scope_id", None) or "")
        if not scope_id:
            return None
        next_at = float(
            getattr(self, "youth_generation_reconcile_at", 0.0) or 0.0
        )
        if not force and checked_at < next_at:
            return None
        with self.lock:
            busy = bool(
                getattr(self, "refreshing", False)
                or getattr(self, "reconciling", False)
                or getattr(self, "club_refreshing", False)
                or getattr(self, "save_change_pending", False)
            )
        if busy:
            self.youth_generation_reconcile_at = (
                checked_at + YOUTH_GENERATION_RETRY_SECONDS
            )
            return None
        try:
            plans = active_youth_generation_plans(scope_id)
        except Exception as error:
            self.youth_generation_reconcile_error = str(error)
            self.youth_generation_reconcile_at = (
                checked_at + YOUTH_GENERATION_RECONCILE_SECONDS
            )
            return None
        self.youth_generation_reconcile_at = (
            checked_at + YOUTH_GENERATION_RECONCILE_SECONDS
        )
        if not plans:
            self.youth_generation_reconcile_error = None
            return None
        if not self.memory_lock.acquire(blocking=False):
            self.youth_generation_reconcile_at = (
                checked_at + YOUTH_GENERATION_RETRY_SECONDS
            )
            return None
        set_active_save_id(scope_id)
        try:
            status = self._persist_youth_generation_progress()
            self.youth_generation_reconcile_error = None
        except Exception as error:
            self.youth_generation_reconcile_error = str(error)
            failed = {"reconciled": False, "error": str(error)}
            self.youth_generation_reconcile_status = failed
            return failed
        finally:
            self.memory_lock.release()
        try:
            repair = self._repair_youth_generation_hook_if_needed()
            if repair is not None:
                status["hook_repair"] = repair
        except Exception as error:
            status["hook_repair_error"] = str(error)
        status["reconciled"] = True
        self.youth_generation_reconcile_status = status
        return status

    def public_youth_generation_status(self) -> dict[str, Any]:
        with self.lock:
            output = dict(self.output)
            scope_id = self._data_scope_id(output) if output else ""
        return {
            "generation_hook": self.youth_generation_hook.status(),
            "plans": active_youth_generation_plans(scope_id) if scope_id else [],
            "automatic_reconcile_error": getattr(
                self, "youth_generation_reconcile_error", None,
            ),
            "automatic_reconcile": getattr(
                self, "youth_generation_reconcile_status", None,
            ),
        }

    def _repair_youth_generation_hook_if_needed(self) -> dict[str, Any] | None:
        scope_id = str(getattr(self, "youth_generation_scope_id", None) or "")
        if not scope_id:
            return None
        plans = active_youth_generation_plans(scope_id)
        needs_hook = any(
            (
                plan.get("kind") == "academy_son"
                and not plan.get("roster_finalize_only")
                and not plan.get("generation_completed")
            )
            or (
                plan.get("kind") == "golden_generation"
                and int(plan.get("count") or 0) > 0
            )
            for plan in plans
        )
        current = self.youth_generation_hook.status()
        if not needs_hook:
            if not current.get("installed"):
                return current
            with self.lock:
                output = dict(self.output)
            save_id = str(
                output.get("save_instance_id") or self._data_scope_id(output)
            )
            try:
                with self.memory_lock:
                    return self._sync_youth_generation_plans(scope_id, save_id)
            except Exception as error:
                return self.youth_generation_hook.suspend(str(error))
        if current.get("installed"):
            return current
        now = monotonic()
        if now < float(getattr(self, "youth_generation_repair_at", 0.0) or 0.0):
            return current
        self.youth_generation_repair_at = now + 60.0
        with self.lock:
            output = dict(self.output)
        save_id = str(output.get("save_instance_id") or self._data_scope_id(output))
        try:
            with self.memory_lock:
                return self._sync_youth_generation_plans(scope_id, save_id)
        except Exception as error:
            return self.youth_generation_hook.suspend(str(error))

    def _close_youth_generation_hook(self) -> None:
        self._persist_youth_generation_progress()
        self.youth_generation_hook.close()
        self.youth_generation_scope_id = None
        self.youth_generation_reconcile_at = 0.0
        self.youth_generation_reconcile_error = None
        self.youth_generation_reconcile_status = None

    def _sync_youth_generation_plans(
        self, scope_id: str, save_id: str,
        native: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        previous_scope = str(getattr(self, "youth_generation_scope_id", None) or "")
        if previous_scope and previous_scope != scope_id:
            self._persist_youth_generation_progress()
        active_team_ids = {
            int(row.get("id") or 0)
            for row in account_acquired_clubs(scope_id, self.output)
            if int(row.get("id") or 0) > 0
        }
        plans = [
            plan for plan in active_youth_generation_plans(scope_id)
            if int(plan.get("team_id") or 0) in active_team_ids
        ]
        hook_plans = [
            plan for plan in plans
            if not plan.get("roster_finalize_only")
            and plan.get("execution_mode") != "roster_finalize"
            and not (
                plan.get("kind") == "academy_son"
                and plan.get("generation_completed")
            )
            and (
                plan.get("kind") != "golden_generation"
                or int(plan.get("count") or 0) > 0
            )
        ]
        if not hook_plans:
            status = self.youth_generation_hook.sync([])
            self.youth_generation_scope_id = scope_id
            return status
        plans = hook_plans
        team_ids = {
            int(plan.get("team_id") or 0)
            for plan in plans
            if int(plan.get("team_id") or 0) > 0
        }
        team_hints = world_club_team_address_hints(self.output)

        def recover_addresses() -> dict[int, Any]:
            addresses = resolve_native_team_addresses(team_ids, team_hints)
            if team_ids.issubset(addresses):
                return addresses
            payload = scan_native_world_clubs(
                save_id, team_hints=sorted(team_hints),
            )
            save_native_world_clubs(payload, save_id)
            payload["addresses_current"] = True
            with self.lock:
                self.world_club_cache = payload
                self.world_club_cache_save_id = save_id
            return {
                int(row.get("id") or 0): row.get("address")
                for row in payload.get("clubs") or []
                if int(row.get("id") or 0) > 0 and row.get("address")
            }

        def bind_addresses(addresses: dict[int, Any]) -> list[int]:
            missing = []
            for plan in plans:
                team_id = int(plan.get("team_id") or 0)
                if team_id not in addresses:
                    missing.append(team_id)
                    continue
                plan["team_address"] = addresses[team_id]
            return missing

        native = native if native is not None else self._world_club_native_cache(save_id)
        if native and native.get("addresses_current"):
            addresses = {
                int(row.get("id") or 0): row.get("address")
                for row in native.get("clubs") or []
                if int(row.get("id") or 0) > 0 and row.get("address")
            }
        else:
            addresses = resolve_native_team_addresses(
                team_ids, team_hints,
            )
        missing = bind_addresses(addresses)
        if missing:
            try:
                missing = bind_addresses(recover_addresses())
            except Exception as error:
                self.youth_generation_scope_id = scope_id
                return self.youth_generation_hook.suspend(
                    f"俱乐部地址自动扫描失败：{error}",
                )
            if missing:
                self.youth_generation_scope_id = scope_id
                return self.youth_generation_hook.suspend(
                    f"自动扫描后仍未找到俱乐部 {', '.join(map(str, missing))}",
                )
        status = self.youth_generation_hook.sync(plans)
        if "球队地址已失效" in str(status.get("error") or ""):
            try:
                missing = bind_addresses(recover_addresses())
                if missing:
                    raise RuntimeError(
                        f"仍未找到俱乐部 {', '.join(map(str, missing))}"
                    )
                status = self.youth_generation_hook.sync(plans)
            except Exception as error:
                status = self.youth_generation_hook.suspend(
                    f"俱乐部地址自动扫描失败：{error}",
                )
        self.youth_generation_scope_id = scope_id
        if status.get("installed"):
            self.youth_generation_repair_at = 0.0
        return status

    def _world_club_native_cache(self, save_id: str) -> dict[str, Any] | None:
        with self.lock:
            if self.world_club_cache_save_id == save_id:
                payload = self.world_club_cache
            else:
                payload = None
        if payload is not None:
            validity = native_world_club_cache_validity(payload, save_id)
            if not validity["matches_database"]:
                payload = None
            else:
                payload["addresses_current"] = validity["addresses_current"]
                return payload
        payload = load_native_world_clubs(save_id)
        with self.lock:
            self.world_club_cache = payload
            self.world_club_cache_save_id = save_id
        return payload

    def _world_club_directory(
        self, output: dict[str, Any], save_id: str,
        native: dict[str, Any] | None,
    ) -> dict[str, Any]:
        """Reuse the expensive base directory across searches and pages."""
        native_signature = (
            str((native or {}).get("generated_at") or ""),
            str((native or {}).get("game_key") or ""),
            bool((native or {}).get("addresses_current")),
            tuple(
                (
                    int(row.get("id") or 0), str(row.get("name") or ""),
                    str(row.get("short_name") or ""),
                    int(row.get("reputation") or 0),
                    str(row.get("address") or ""),
                )
                for row in (native or {}).get("clubs") or []
            ),
        )
        cache_key = (
            str(save_id), int(self.data_version),
            str(output.get("game_date") or ""), native_signature,
        )
        with self.lock:
            if (
                self.world_club_directory_cache_key == cache_key
                and self.world_club_directory_cache is not None
            ):
                return deepcopy(self.world_club_directory_cache)
        directory = build_world_clubs(output)
        if native:
            directory = merge_native_world_clubs(directory, native)
        directory = enrich_world_club_standings(
            directory, public_league_standings(output),
        )
        directory = enrich_world_club_reputation_ranks(directory)
        directory["_projection_source_key"] = cache_key
        with self.lock:
            self.world_club_directory_cache_key = cache_key
            self.world_club_directory_cache = deepcopy(directory)
        return directory

    def _owned_world_club_address_overrides(self, save_id: str) -> dict[int, str]:
        with self.lock:
            if self.owned_world_club_address_save_id != save_id:
                return {}
            return dict(self.owned_world_club_addresses)

    def _world_club_directory_projection(
        self, directory: dict[str, Any], save_id: str,
        acquired: list[dict[str, Any]],
    ) -> dict[str, Any]:
        """Reuse pure directory indexes across searches and page changes."""
        address_signature = tuple(sorted(
            self._owned_world_club_address_overrides(save_id).items(),
        ))
        name_signature = tuple(sorted(
            (
                int(row.get("id") or 0),
                str(row.get("renamed_name") or "").strip(),
                str(row.get("renamed_short_name") or "").strip(),
            )
            for row in acquired
            if int(row.get("id") or 0) > 0
            and (
                str(row.get("renamed_name") or "").strip()
                or str(row.get("renamed_short_name") or "").strip()
            )
        ))
        with self.lock:
            cache_key = (
                directory.get("_projection_source_key"),
                str(directory.get("generated_at") or ""),
                address_signature, name_signature,
            )
            if (
                self.world_club_projection_cache_key == cache_key
                and self.world_club_projection_cache is not None
            ):
                return self.world_club_projection_cache
        projection = build_world_club_directory_index(directory)
        with self.lock:
            self.world_club_projection_cache_key = cache_key
            self.world_club_projection_cache = projection
        return projection

    def _apply_owned_world_club_addresses(
        self, directory: dict[str, Any], save_id: str,
    ) -> dict[str, Any]:
        overrides = self._owned_world_club_address_overrides(save_id)
        if not overrides:
            return directory
        rows = []
        for source in directory.get("clubs") or []:
            row = dict(source)
            address = overrides.get(int(row.get("id") or 0))
            if address:
                row["address"] = address
                row["address_source"] = "owned_refresh"
            rows.append(row)
        return {**directory, "clubs": rows}

    def refresh_owned_world_clubs(self, payload: dict[str, Any] | None = None) -> dict[str, Any]:
        with self.lock:
            scope_id = self._bind_current_save()
            output = dict(self.output)
            save_id = str(output.get("save_instance_id") or self._data_scope_id(output))
            scope_id = self._data_scope_id(output)
            if self.world_club_scanning:
                raise ValueError("世界俱乐部正在扫描，请稍候")
        acquired = account_acquired_clubs(scope_id, output)
        team_ids = {
            int(row.get("id") or 0) for row in acquired
            if int(row.get("id") or 0) > 0
        }
        if not team_ids:
            return {"refreshed": 0, "requested": 0, "missing": []}

        native = self._world_club_native_cache(save_id)
        hints = world_club_team_address_hints(output)
        known_addresses: dict[int, Any] = {}
        for row in [*acquired, *((native or {}).get("clubs") or [])]:
            row_id = int(row.get("id") or 0)
            if row_id not in team_ids:
                continue
            try:
                address = int(str(row.get("address") or "0"), 16)
            except (TypeError, ValueError):
                address = 0
            if address:
                hints.add(address)
                known_addresses[row_id] = hex(address)
        with self.memory_lock:
            addresses = resolve_native_team_addresses(
                team_ids, hints, scan_all_if_unresolved=False,
                known_addresses=known_addresses,
            )
            unresolved = team_ids.difference(addresses)
            if unresolved:
                rebound = resolve_native_team_addresses(
                    unresolved, hints, scan_all_if_unresolved=True,
                    known_addresses={
                        team_id: known_addresses[team_id]
                        for team_id in unresolved
                        if team_id in known_addresses
                    },
                )
                addresses.update(rebound)
        missing = sorted(team_ids.difference(addresses))
        with self.lock:
            self.owned_world_club_addresses = dict(addresses)
            self.owned_world_club_address_save_id = save_id
        result = {
            "refreshed": len(addresses), "requested": len(team_ids),
            "missing": missing, "partial": bool(missing),
        }
        if (payload or {}).get("include_metrics"):
            result["metrics_snapshot"] = self.owned_world_club_metrics()
        return result

    def _world_club_scan_public(self, save_id: str) -> dict[str, Any]:
        native = self._world_club_native_cache(save_id)
        with self.lock:
            return {
                "ready": bool(native),
                "addresses_current": bool(native and native.get("addresses_current")),
                "club_count": len(native.get("clubs", [])) if native else 0,
                "generated_at": native.get("generated_at") if native else None,
                "game_key": native.get("game_key") if native else None,
                "scanning": self.world_club_scanning,
                "progress": self.world_club_scan_progress,
                "progress_text": self.world_club_scan_text,
                "error": self.world_club_scan_error,
            }

    def public_world_clubs(
        self, *, search: str = "", continent: str = "", nation: str = "",
        page: int = 1, page_size: int = 15,
    ) -> dict[str, Any]:
        with self.lock:
            if not self._has_verified_save():
                return {
                    "ready": False, "data_scope_id": "", "clubs": [], "acquired": [],
                    "pagination": {"page": 1, "page_size": 15, "page_count": 1, "total": 0, "from": 0, "to": 0},
                    "facets": [], "error": "请先连接当前存档",
                    "native_scan": {"ready": False, "scanning": False, "progress": 0},
                }
            output = dict(self.output)
            save_id = str(output.get("save_instance_id") or self._data_scope_id(output))
            scope_id = self._data_scope_id(output)
            set_active_save_id(scope_id)
        native = self._world_club_native_cache(save_id)
        # Keep the endpoint usable for lightweight test doubles and older
        # integrations that expose only the original state surface.  Real
        # LocalOddsState instances always use the cached directory builder.
        directory_builder = getattr(self, "_world_club_directory", None)
        if directory_builder is not None:
            directory = directory_builder(output, save_id, native)
        else:
            directory = build_world_clubs(output)
            if native:
                directory = merge_native_world_clubs(directory, native)
            directory = enrich_world_club_standings(
                directory, public_league_standings(output),
            )
            directory = enrich_world_club_reputation_ranks(directory)
        portfolio = load_acquired_clubs(scope_id)
        acquired = account_acquired_clubs(
            scope_id, output, include_suspended=True,
        )
        directory = self._apply_owned_world_club_addresses(directory, save_id)
        directory = apply_acquired_club_overrides(directory, acquired)
        projection_builder = getattr(
            self, "_world_club_directory_projection", None,
        )
        projection = (
            projection_builder(directory, save_id, acquired)
            if projection_builder is not None
            else build_world_club_directory_index(directory)
        )
        result = paginate_world_clubs(
            directory, search=search, continent=continent, nation=nation,
            page=page, page_size=page_size, directory_index=projection,
        )
        by_id = projection["clubs_by_id"]
        reputation_ranks = projection["reputation_ranks"]
        for row in acquired:
            if not row.get("owner_name"):
                row["owner_name"] = manager_display_name(output)
            source = by_id.get(int(row.get("id") or 0))
            if source:
                row.update({
                    "name": source.get("name"), "continent": source.get("continent"),
                    "nation": source.get("nation"), "competition": source.get("competition"),
                    "reputation": source.get("reputation"),
                    "reputation_rank": reputation_ranks.get(int(row.get("id") or 0)),
                    "competition_count": len(source.get("competitions") or []),
                    "competition_id": source.get("competition_id"),
                    "league_position": source.get("league_position"),
                    "league_team_count": source.get("league_team_count"),
                    "league_points": source.get("league_points"),
                    "competition_reputation_rank": source.get("competition_reputation_rank"),
                    "competition_reputation_total": source.get("competition_reputation_total"),
                    "nation_reputation_rank": source.get("nation_reputation_rank"),
                    "nation_reputation_total": source.get("nation_reputation_total"),
                })
                if source.get("recent_results"):
                    row["recent_results"] = source.get("recent_results")
        return {
            "ready": True, "data_scope_id": scope_id, **result, "acquired": acquired,
            "group_name": str(portfolio.get("group_name") or "我的集团"),
            "filters": {"search": search, "continent": continent, "nation": nation},
            "native_scan": self._world_club_scan_public(save_id),
        }

    def public_world_players(
        self, *, search: str = "", page: int = 1, page_size: int = 30,
        force_refresh: bool = False, sort_by: str = "pa", sort_order: str = "desc",
        gender: str = "all", live_summary: bool = True,
        background: bool = False,
        nationality_id: int = 0,
        min_age: int = 0, max_age: int = 0,
        min_ca: int = 0, max_ca: int = 0,
        min_pa: int = 0, max_pa: int = 0,
    ) -> dict[str, Any]:
        with self.lock:
            if not self._has_verified_save():
                return {
                    "ready": False, "data_scope_id": "", "players": [],
                    "pagination": {
                        "page": 1, "page_size": 30, "page_count": 1,
                        "total": 0, "from": 0, "to": 0,
                    },
                    "index": {"source": "session_person_cache", "player_count": 0},
                    "error": "请先连接当前存档。",
                }
            output = dict(self.output)
            scope_id = self._data_scope_id(output)
            set_active_save_id(scope_id)
        timed_operation = getattr(self, "_timed_user_memory_operation", None)
        memory_context = (
            self.memory_lock
            if background else (
                timed_operation("world_player_search")
                if callable(timed_operation) else self.memory_lock
            )
        )
        with memory_context:
            search_kwargs = {
                "page": page, "page_size": page_size,
                "force_refresh": force_refresh, "sort_by": sort_by,
                "sort_order": sort_order,
                "nationality_id": nationality_id,
                "min_age": min_age, "max_age": max_age,
                "min_ca": min_ca, "max_ca": max_ca,
                "min_pa": min_pa, "max_pa": max_pa,
            }
            search_kwargs = {
                key: value for key, value in search_kwargs.items()
                if key in {
                    "page", "page_size", "force_refresh", "sort_by", "sort_order",
                } or int(value or 0) > 0
            }
            if str(gender or "all").strip().lower() != "all":
                search_kwargs["gender"] = gender
            if any("\u3400" <= char <= "\u9fff" for char in str(search or "")):
                search_kwargs["candidate_uids"] = player_alias_uids_for_query(
                    scope_id, search,
                )
            if not live_summary:
                search_kwargs["live_summary"] = False
            result = search_world_players(search, **search_kwargs)
            apply_player_aliases(result, scope_id)
        return {
            "ready": True, "data_scope_id": scope_id,
            "game_date": str(output.get("game_date") or ""),
            **result,
        }

    def public_retirement_players(
        self, *, scope: str = "club", search: str = "",
    ) -> dict[str, Any]:
        """Read the native retirement-manager candidates for the activity centre."""
        resolved_scope = "world" if str(scope or "").strip().lower() == "world" else "club"
        with self.lock:
            if not self._has_verified_save():
                return {
                    "ready": False, "data_scope_id": "", "scope": resolved_scope,
                    "search": str(search or ""), "players": [], "total": 0,
                    "error": "请先连接当前存档。",
                }
            output = dict(self.output)
            scope_id = self._data_scope_id(output)
            managed = output.get("managed_team") or {}
            if not managed:
                managed = next(
                    (row for row in (output.get("managed_teams") or [])
                     if str(row.get("team_type") or "club") == "club"),
                    {},
                )
            club_team_id = int(managed.get("id") or 0)
            set_active_save_id(scope_id)
        with self.memory_lock:
            result = search_retirement_players(
                search, scope=resolved_scope, club_team_id=club_team_id,
            )
            apply_player_aliases(result, scope_id)
        return {"ready": True, "data_scope_id": scope_id, **result}

    def world_player_detail(self, player_id: int) -> dict[str, Any]:
        player_id = int(player_id)
        with self.lock:
            if not self._has_verified_save():
                raise ValueError("请先连接当前存档")
            scope_id = self._data_scope_id(self.output)
            set_active_save_id(scope_id)
        with self._timed_user_memory_operation("world_player_detail"):
            player = read_world_player_profile(player_id)
            wrapper = {"players": [player]}
            apply_player_aliases(wrapper, scope_id)
            player = wrapper["players"][0]
        return {
            "ready": True, "data_scope_id": scope_id, "player": player,
        }

    def update_world_player_name(self, payload: dict[str, Any]) -> dict[str, Any]:
        player_id = int(payload.get("player_id") or 0)
        with self.lock:
            scope_id = self._bind_current_save()
        with self._timed_user_memory_operation("world_player_alias"):
            player = read_world_player_profile(player_id)
            alias = set_player_alias(
                scope_id, player_id, str(payload.get("name") or ""),
            )
            wrapper = {"players": [player]}
            apply_player_aliases(wrapper, scope_id)
            name = str(wrapper["players"][0].get("name") or "")
            if not name:
                raise ValueError("无法恢复该球员的游戏原名")
        return {
            "player_id": player_id, "name": name, "custom_name": bool(alias),
        }

