    def public_world_nations(
        self, *, search: str = "", continent: str = "", page: int = 1,
        page_size: int = 15,
    ) -> dict[str, Any]:
        with self.lock:
            if not self._has_verified_save():
                return {
                    "ready": False, "nations": [], "facets": [],
                    "pagination": {"page": 1, "page_size": 15, "page_count": 1, "total": 0, "from": 0, "to": 0},
                    "error": "请先连接当前存档",
                    "native_scan": {"ready": False, "scanning": False, "progress": 0},
                }
            output = dict(self.output)
            save_id = str(output.get("save_instance_id") or self._data_scope_id(output))
            scope_id = self._data_scope_id(output)
        native = self._world_club_native_cache(save_id)
        result = paginate_world_nations(
            (native or {}).get("nations") or [], search=search, continent=continent,
            page=page, page_size=page_size,
        )
        page_nations = result.get("nations") or []
        pending_ids = {
            int(row.get("id") or 0)
            for row in page_nations
            if not row.get("detail_scanned")
        }
        if native and native.get("addresses_current") and pending_ids:
            pending = [row for row in page_nations if int(row.get("id") or 0) in pending_ids]
            try:
                with self.memory_lock:
                    summaries = read_native_world_nation_summaries(pending)
            except Exception:
                summaries = {}
            cached_by_id = {
                int(row.get("id") or 0): row
                for row in native.get("nations") or []
            }
            for row in page_nations:
                summary = summaries.get(int(row.get("id") or 0))
                if not summary:
                    continue
                row.update(summary)
                cached = cached_by_id.get(int(row.get("id") or 0))
                if cached is not None:
                    cached.update(summary)
        return {
            "ready": True, "data_scope_id": scope_id, **result,
            "filters": {"search": search, "continent": continent},
            "native_scan": self._world_club_scan_public(save_id),
        }

    def world_nation_detail(self, nation_id: int) -> dict[str, Any]:
        with self.lock:
            self._bind_current_save()
            output = dict(self.output)
            save_id = str(output.get("save_instance_id") or self._data_scope_id(output))
        native = self._world_club_native_cache(save_id)
        if not native or not native.get("addresses_current"):
            raise ValueError("请先扫描世界数据，或重新扫描已失效的国家地址")
        nation = next(
            (row for row in native.get("nations") or [] if int(row.get("id") or 0) == int(nation_id)),
            None,
        )
        if not nation:
            raise ValueError("未找到目标国家")
        detail = read_native_world_nation_detail(nation)
        detail["investment"] = public_purchase_quotes(detail.get("investment") or {})
        return detail

    def world_nation_players(
        self, nation_id: int, *, ranking: str = "pa", page: int = 1,
        page_size: int = 30,
    ) -> dict[str, Any]:
        ranking = str(ranking or "pa").strip().lower()
        ranking_labels = {
            "pa": "PA", "ca": "CA", "asking_price": "挂牌价",
            "world_reputation": "世界声望",
        }
        if ranking not in ranking_labels:
            raise ValueError("国家球员榜单类型无效")
        nation_id = int(nation_id)
        with self.lock:
            self._bind_current_save()
            output = dict(self.output)
            save_id = str(
                output.get("save_instance_id") or self._data_scope_id(output)
            )
            scope_id = self._data_scope_id(output)
            set_active_save_id(scope_id)
        native = self._world_club_native_cache(save_id)
        nation = next((
            row for row in (native or {}).get("nations") or []
            if int(row.get("id") or 0) == nation_id
        ), None)
        if not nation:
            raise ValueError("未找到目标国家，请先扫描世界数据")
        with self.memory_lock:
            result = search_world_players(
                "", page=max(1, int(page or 1)),
                page_size=max(1, min(30, int(page_size or 30))),
                sort_by=ranking, sort_order="desc", gender="men",
                nationality_id=nation_id,
            )
            apply_player_aliases(result, scope_id)
        return {
            "ready": True,
            "data_scope_id": scope_id,
            "nation": {
                "id": nation_id,
                "name": str(nation.get("name") or nation_id),
                "continent": nation.get("continent"),
            },
            "ranking": ranking,
            "ranking_label": ranking_labels[ranking],
            "value_field": ranking,
            "price_note": (
                "当前版本使用已验证的挂牌价；独立当前身价字段尚未验证。"
                if ranking == "asking_price" else None
            ),
            **result,
        }

    def invest_world_nation(self, payload: dict[str, Any]) -> dict[str, Any]:
        nation_id = int(payload.get("nation_id") or 0)
        expected = int(payload.get("expected_youth_rating") or 0)
        requested_increase = int(payload.get("increase") or 1)
        if requested_increase not in {-5, -1, 1, 5}:
            raise ValueError("国家青训投资只能选择 -5、-1、+1 或 +5")
        with self.lock:
            self._bind_current_save()
            output = dict(self.output)
            save_id = str(output.get("save_instance_id") or self._data_scope_id(output))
        native = self._world_club_native_cache(save_id)
        if not native or not native.get("addresses_current"):
            raise ValueError("请先扫描世界数据，或重新扫描已失效的国家地址")
        nation = next(
            (row for row in native.get("nations") or [] if int(row.get("id") or 0) == nation_id),
            None,
        )
        if not nation:
            raise ValueError("未找到目标国家")
        with self.memory_lock:
            detail = read_native_world_nation_detail(nation)
        current = int((detail.get("nation") or {}).get("youth_rating") or 0)
        if expected != current:
            raise ValueError("国家青训评分已变化，请刷新后重试")
        quote = nation_youth_investment_quote(current, requested_increase)
        if quote is None:
            raise ValueError("该国青训评分无法按所选幅度继续调整")
        price = int(quote["price"])
        increase = int(quote["increase"])
        team = (detail.get("national_team") or {}).get("name") or nation.get("name")
        payment = charge_combined_funds(
            local_purchase_price(price), "world_nation_youth_investment",
            nation_id=nation_id, nation_name=str(nation.get("name") or ""),
            youth_rating=current, increase=increase,
            requested_increase=requested_increase,
        )
        try:
            with self.memory_lock:
                native_result = invest_native_world_nation_youth(
                    nation, expected_youth_rating=current, increase=increase,
                )
        except Exception:
            refund_combined_funds(
                payment, "world_nation_youth_investment_rollback",
                nation_id=nation_id, nation_name=str(nation.get("name") or ""),
                youth_rating=current, increase=increase,
                requested_increase=requested_increase,
            )
            raise
        nation["youth_rating"] = int(native_result["after"])
        warning = None
        try:
            save_native_world_clubs(native, save_id)
        except Exception as error:
            warning = f"游戏内青训评分已修改，但国家缓存更新失败：{error}"
        with self.lock:
            self.world_club_cache = native
            self.world_club_cache_save_id = save_id
        return {
            "nation_id": nation_id, "nation_name": nation.get("name"),
            "national_team_name": team, "native": native_result,
            "payment": payment, "warning": warning,
            "economy": public_economy(),
            "investment": public_purchase_quotes({
                "price": nation_youth_investment_price(native_result["after"]),
                "increase": 1, "max_youth_rating": 200,
                "options": [
                    nation_youth_investment_quote(native_result["after"], option)
                    for option in (-5, -1, 1, 5)
                ],
            }),
        }

    def start_world_club_scan(self) -> dict[str, Any]:
        with self.lock:
            timer = getattr(self, "world_prewarm_timer", None)
            if timer is not None:
                timer.cancel()
                self.world_prewarm_timer = None
            scope_id = self._bind_current_save()
            save_id = str(self.output.get("save_instance_id") or self._data_scope_id(self.output))
            if self.world_club_scanning:
                return {"started": False, "native_scan": self._world_club_scan_public(save_id)}
            cached = self._world_club_native_cache(save_id)
            can_fast_refresh = bool(
                cached
                and cached.get("addresses_current")
                and cached.get("nations")
            )
            self.world_club_scanning = True
            self.world_club_scan_progress = 0
            self.world_club_scan_text = (
                "准备快速刷新俱乐部"
                if can_fast_refresh else "准备扫描世界数据"
            )
            self.world_club_scan_error = None
            self.world_club_scan_save_id = save_id
            team_hints = world_club_team_address_hints(self.output)
        threading.Thread(
            target=self._world_club_scan_worker,
            args=(scope_id, save_id, sorted(team_hints), cached), daemon=True,
            name="fmodd-world-club-scan",
        ).start()
        return {"started": True, "native_scan": self._world_club_scan_public(save_id)}

    def _world_club_scan_worker(
        self, scope_id: str, save_id: str, team_hints: list[int],
        cached: dict[str, Any] | None = None,
    ) -> None:
        set_active_save_id(scope_id)

        def update(progress: int, text: str) -> None:
            with self.lock:
                self.world_club_scan_progress = max(0, min(100, int(progress)))
                self.world_club_scan_text = text

        def read_world_data() -> dict[str, Any]:
            payload = None
            if cached and cached.get("addresses_current") and cached.get("nations"):
                try:
                    payload = refresh_native_world_clubs(cached, save_id, update)
                except Exception:
                    update(1, "快速刷新不可用，正在重建俱乐部索引")
            return (
                payload
                if payload is not None
                else scan_native_world_clubs(save_id, update, team_hints)
            )

        try:
            memory_lock = getattr(self, "memory_lock", None)
            if memory_lock is None:
                payload = read_world_data()
            else:
                with memory_lock:
                    payload = read_world_data()
            save_native_world_clubs(payload, save_id)
            payload["addresses_current"] = True
            with self.lock:
                self.world_club_cache = payload
                self.world_club_cache_save_id = save_id
                # The scan replaces both native addresses and nation rows.
                # Drop derived directory projections so the next request does
                # not keep serving the pre-scan snapshot.
                self.world_club_directory_cache_key = None
                self.world_club_directory_cache = None
                self.world_club_projection_cache_key = None
                self.world_club_projection_cache = None
                self.world_club_scan_progress = 100
                self.world_club_scan_text = "扫描完成"
                self.world_club_scan_error = None
                current_save_id = str(self.output.get("save_instance_id") or "")
                current_scope_id = (
                    self._data_scope_id(self.output)
                    if save_identity_matches(current_save_id, save_id) else ""
                )
            if current_scope_id == scope_id:
                with self.memory_lock:
                    self._sync_youth_generation_plans(scope_id, save_id, payload)
        except Exception as error:
            with self.lock:
                self.world_club_scan_error = str(error)
                self.world_club_scan_text = "扫描失败"
        finally:
            with self.lock:
                self.world_club_scanning = False

    def owned_world_club_metrics(
        self, team_ids: tuple[int, ...] | None = None,
    ) -> dict[str, Any]:
        with self.lock:
            scope_id = self._bind_current_save()
            output = dict(self.output)
            save_id = str(output.get("save_instance_id") or self._data_scope_id(output))
        acquired = account_acquired_clubs(scope_id, output)
        if not acquired:
            game_date = str(output.get("game_date") or "")
            result = {
                "data_scope_id": scope_id,
                "metrics": {},
                "summary": club_portfolio_summary([], {}),
            }
            if game_date:
                result["dividends"] = settle_club_dividends(game_date, [], {})
                result["economy"] = public_economy()
            return result
        acquired_ids = {int(row.get("id") or 0) for row in acquired}
        selected_ids = acquired_ids if team_ids is None else set(team_ids)
        if not selected_ids or not selected_ids.issubset(acquired_ids):
            raise ValueError("未找到目标俱乐部")
        metrics_complete = selected_ids == acquired_ids
        # A partial read must never mark a whole account's month settled.
        if not metrics_complete and (
            load_economy().get("club_dividend_last_settlement_month")
            != str(output.get("game_date") or "")[:7]
        ):
            selected_ids = acquired_ids
            metrics_complete = True
        native = self._world_club_native_cache(save_id)
        overrides = self._owned_world_club_address_overrides(save_id)
        directory = (
            merge_native_world_clubs(build_world_clubs(output), native)
            if native else {"clubs": [dict(row) for row in acquired]}
        )
        directory = self._apply_owned_world_club_addresses(directory, save_id)
        directory = apply_acquired_club_overrides(directory, acquired)
        by_id = {
            int(row.get("id") or 0): row
            for row in directory.get("clubs") or []
        }
        targets = [
            by_id.get(team_id, {**row, "address": overrides.get(team_id)})
            for row in acquired
            for team_id in [int(row.get("id") or 0)]
            if team_id > 0 and team_id in selected_ids
        ]
        with self.memory_lock:
            metrics = read_native_world_club_metrics(targets)
        comparisons = sync_acquired_club_metric_history(
            metrics,
            game_date=str(output.get("game_date") or ""),
            season_start=str(output.get("season_start") or ""),
            season_end=str(output.get("season_end") or ""),
            scope_id=scope_id,
        )
        acquired_by_id = {
            int(row.get("id") or 0): row for row in acquired
            if int(row.get("id") or 0) > 0
        }
        enriched = {
            team_id: club_investment_performance(
                {**value, **comparisons.get(team_id, {})},
                acquired_by_id.get(team_id, {}),
                current_game_date=str(output.get("game_date") or ""),
            )
            for team_id, value in metrics.items()
        }
        for team_id, value in enriched.items():
            standing = owned_club_league_standing(output, team_id)
            value["league_available"] = owned_club_finance_available(
                standing, value.get("balance"), value.get("transfer_budget"),
            )
            value["league_standing"] = standing
        game_date = str(output.get("game_date") or "")
        dividend_status = (
            settle_club_dividends(game_date, acquired, metrics)
            if metrics_complete else {"paid_count": 0, "paid_amount": 0.0, "forecasts": []}
        )
        archive_club_dividend_mail(dividend_status.get("new_payments", []))
        dividend_forecasts = {
            int(row.get("team_id") or 0): row
            for row in dividend_status.get("forecasts", [])
        }
        for team_id, value in enriched.items():
            projection = dividend_forecasts.get(team_id) or owned_club_dividend_projection(
                value, game_date, acquired_by_id.get(team_id, {}),
            )
            value["sale_price"] = owned_club_sale_price(value)
            value["dividend_forecast"] = projection
            value["estimated_dividend"] = (
                projection.get("estimated_amount") if projection else None
            )
        return {
            "data_scope_id": scope_id,
            "metrics": {
                str(team_id): value for team_id, value in enriched.items()
            },
            "summary": club_portfolio_summary(acquired, enriched) if metrics_complete else None,
            "metrics_complete": metrics_complete,
            "dividends": dividend_status,
            "economy": public_economy(),
        }

    def world_club_detail(
        self, team_id: int, *, include_related_squads: bool = True,
    ) -> dict[str, Any]:
        with self.lock:
            scope_id = self._bind_current_save()
            output = dict(self.output)
            save_id = str(output.get("save_instance_id") or self._data_scope_id(output))
        acquired = account_acquired_clubs(
            scope_id, output, include_suspended=True,
        )
        ownership = next(
            (row for row in acquired if int(row.get("id") or 0) == int(team_id)),
            None,
        )
        if ownership and ownership.get("ownership_active") is False:
            return {
                "club": dict(ownership),
                "ownership": dict(ownership),
                "portfolio_metrics": {},
                "ownership_suspended": True,
            }
        acquired = [
            row for row in acquired if row.get("ownership_active") is not False
        ]
        if ownership:
            _scope_id, _output, club = self._owned_world_club_target(team_id)
        else:
            native = self._world_club_native_cache(save_id)
            if not native:
                raise ValueError("请先扫描俱乐部")
            if not native.get("addresses_current"):
                raise ValueError("俱乐部地址已失效，请重新扫描俱乐部")
            directory = merge_native_world_clubs(build_world_clubs(output), native)
            directory = enrich_world_club_standings(directory, public_league_standings(output))
            club = next(
                (row for row in directory["clubs"] if int(row.get("id") or 0) == int(team_id)),
                None,
            )
            if not club:
                raise ValueError("未找到目标俱乐部")
        detail = read_native_world_club_detail(
            club,
            include_related_squads=bool(ownership and include_related_squads),
        )
        detail["related_squads_loaded"] = bool(
            not ownership or include_related_squads
        )
        apply_player_aliases(detail, scope_id)
        if ownership:
            generation_hook = self._persist_youth_generation_progress()
            standing = owned_club_league_standing(output, team_id)
            finances = detail.setdefault("club_information", {}).setdefault(
                "finances", {},
            )
            league_available = owned_club_finance_available(
                standing, finances.get("balance"),
                finances.get("remaining_transfer_budget", finances.get("transfer_budget")),
            )
            detail["league_available"] = league_available
            detail["league_standing"] = standing
            detail.setdefault("club", {})["league_available"] = league_available
            if standing:
                detail["club"].update(standing)
            detail["ownership"] = dict(ownership)
            detail["portfolio_metrics"] = club_investment_performance(
                detail.get("portfolio_metrics") or {}, ownership,
                current_game_date=str(output.get("game_date") or ""),
            )
            detail["portfolio_metrics"]["sale_price"] = owned_club_sale_price(
                detail["portfolio_metrics"],
            )
            projection = owned_club_dividend_projection(
                detail["portfolio_metrics"], str(output.get("game_date") or ""),
                ownership,
            )
            saved_projection = next(
                (
                    row for row in (
                        public_economy().get("dividends", {}).get("forecasts", [])
                    )
                    if int(row.get("team_id") or 0) == int(team_id)
                    and str(row.get("month") or "")
                    == str(output.get("game_date") or "")[:7]
                ),
                None,
            )
            projection = saved_projection or projection
            detail["portfolio_metrics"]["dividend_forecast"] = projection
            detail["portfolio_metrics"]["estimated_dividend"] = (
                projection.get("estimated_amount") if projection else None
            )
            detail["owned_actions"] = public_purchase_quotes(
                owned_club_action_quotes(
                    detail, ownership, str(output.get("game_date") or ""),
                ),
            )
            detail["youth_plans"] = youth_plans_for_team(scope_id, int(team_id))
            detail["golden_generation_year"] = golden_generation_year_status(
                scope_id, int(team_id), str(output.get("game_date") or ""),
            )
            detail["academy_son_assignment"] = active_academy_son_assignment(
                scope_id, acquired,
            )
            detail["generation_hook"] = generation_hook
            detail["club_vision"] = public_club_vision(
                (detail.get("club_information") or {}).get("culture"),
                club_vision_nation_options(),
                club_vision_reference_names(
                    (detail.get("club_information") or {}).get("culture"),
                ),
            )
            detail["sponsorship"] = public_sponsorship_state(
                scope_id, int(team_id), str(output.get("game_date") or ""),
            )
        return detail

    def _sponsorship_market_context(
        self, team_id: int, output: dict[str, Any], club: dict[str, Any],
    ) -> dict[str, Any]:
        """Build a complete same-league balance snapshot for one quote."""
        standing = owned_club_league_standing(output, team_id)
        if not standing or int(standing.get("competition_id") or 0) <= 0:
            raise ValueError("当前未读取到该俱乐部所属联赛，暂时无法拉取赞助")
        standings = public_league_standings(output)
        competition = next(
            (
                row for row in standings.get("competitions") or []
                if int(row.get("competition_id") or 0) == int(standing["competition_id"])
            ),
            None,
        )
        teams = list((competition or {}).get("teams") or [])
        if not teams:
            raise ValueError("当前联赛没有完整的球队列表，暂时无法计算赞助基准")
        native = self._world_club_native_cache(
            str(output.get("save_instance_id") or self._data_scope_id(output)),
        )
        directory = merge_native_world_clubs(build_world_clubs(output), native)
        directory_by_id = {
            int(row.get("id") or 0): row
            for row in directory.get("clubs") or []
            if int(row.get("id") or 0) > 0
        }
        rows: list[dict[str, Any]] = []
        known: dict[int, Any] = {}
        for team in teams:
            current_id = int(team.get("team_id") or team.get("id") or 0)
            if current_id <= 0:
                raise ValueError("当前联赛包含无效球队，无法计算赞助基准")
            source = directory_by_id.get(current_id) or {}
            address = team.get("team_address") or team.get("address") or source.get("address")
            if address:
                known[current_id] = address
            rows.append({
                "id": current_id,
                "name": str(team.get("team_name") or source.get("name") or current_id),
                "competition_id": int(standing["competition_id"]),
                "competition": str(standing.get("competition_name") or ""),
                "address": address,
            })
        addresses = resolve_native_team_addresses(
            {int(row["id"]) for row in rows},
            world_club_team_address_hints(output),
            scan_all_if_unresolved=True,
            known_addresses=known,
        )
        for row in rows:
            row["address"] = addresses.get(int(row["id"])) or row.get("address")
        if any(not row.get("address") for row in rows):
            raise ValueError("无法定位同联赛全部俱乐部，暂时不生成部分数据报价")
        balances = read_native_world_club_balances(rows)
        missing = [
            row for row in rows
            if int(row["id"]) not in balances or balances[int(row["id"])].get("balance") is None
        ]
        if missing:
            names = "、".join(str(row.get("name") or row.get("id")) for row in missing[:3])
            raise ValueError(f"同联赛仍有球队结余读取失败（{names}），暂时不生成报价")
        total = sum(int(balances[int(row["id"])]["balance"]) for row in rows)
        annual = league_quote_annual(
            balances[int(row["id"])]["balance"] for row in rows
        )
        if annual <= 0:
            raise ValueError("当前联赛平均结余不足，暂时没有可用赞助报价")
        return {
            "competition_id": int(standing["competition_id"]),
            "competition_name": str(standing.get("competition_name") or ""),
            "team_count": len(rows),
            "balance_total": total,
            "average_balance": int(total / len(rows)),
            "annual_value": annual,
            "balances": balances,
            "team": dict(club),
        }

    def owned_world_club_sponsorship_state(self, team_id: int) -> dict[str, Any]:
        scope_id, output, _club = self._owned_world_club_target(int(team_id))
        game_date = str(output.get("game_date") or "")
        return public_sponsorship_state(scope_id, int(team_id), game_date)

    def start_owned_world_club_sponsorship(self, payload: dict[str, Any]) -> dict[str, Any]:
        team_id = int(payload.get("team_id") or 0)
        candidates = payload.get("players") or payload.get("candidates") or []
        with self._timed_user_memory_operation("owned_club_sponsorship_search"):
            scope_id, output, club = self._owned_world_club_target(team_id)
            game_date = str(output.get("game_date") or "")
            context = self._sponsorship_market_context(team_id, output, club)
            result = start_sponsorship_search(
                scope_id, team_id=team_id, team_name=str(club.get("name") or team_id),
                competition_id=int(context["competition_id"]),
                competition_name=str(context["competition_name"]),
                annual_value=int(context["annual_value"]), game_date=game_date,
                candidates=candidates,
            )
            archive_sponsorship_offer_mail(result.get("mail") or {})
            result["market"] = {
                key: context[key] for key in
                ("competition_id", "competition_name", "team_count", "average_balance", "annual_value")
            }
            return result

    def continue_owned_world_club_sponsorship(self, payload: dict[str, Any]) -> dict[str, Any]:
        team_id = int(payload.get("team_id") or 0)
        candidates = payload.get("players") or payload.get("candidates") or []
        scope_id, output, _club = self._owned_world_club_target(team_id)
        game_date = str(output.get("game_date") or "")
        result = continue_sponsorship_search(
            scope_id, team_id=team_id, game_date=game_date, candidates=candidates,
        )
        archive_sponsorship_offer_mail(result.get("mail") or {})
        return result

    def accept_owned_world_club_sponsorship(self, payload: dict[str, Any]) -> dict[str, Any]:
        team_id = int(payload.get("team_id") or 0)
        offer_id = str(payload.get("offer_id") or "").strip()
        if team_id <= 0 or not offer_id:
            raise ValueError("赞助俱乐部或报价标识缺失")
        with self._timed_user_memory_operation("owned_club_sponsorship_accept"):
            scope_id, output, club = self._owned_world_club_target(team_id)
            game_date = str(output.get("game_date") or "")
            accepted = accept_sponsorship_offer(
                scope_id, team_id=team_id, offer_id=offer_id, game_date=game_date,
            )
            contract = dict(accepted.get("contract") or {})
            payment = dict(accepted.get("payment") or {})
            if not contract or not payment:
                raise RuntimeError("赞助合同付款记录不完整")
            amount = int(payment.get("amount") or 0)
            if amount <= 0:
                raise ValueError("赞助金额无效")
            if str(payment.get("status") or "") == "paid":
                update_sponsorship_offer_mail(
                    team_id=team_id, offer_id=offer_id, action_state="accepted",
                )
                return {
                    "contract": contract, "payment": payment,
                    "sponsorship": public_sponsorship_state(scope_id, team_id, game_date),
                    "idempotent": True,
                }
            payment, after = credit_sponsorship_payment(
                scope_id=scope_id, team_id=team_id, offer_id=offer_id,
                team_address=club.get("address"), payment=payment,
                io=SponsorshipPaymentIO(
                    borrow_operation=borrow_game_operation,
                    read_balance=read_club_balance,
                    write_balance=write_club_balance,
                    mark_payment=mark_sponsorship_payment,
                    rollback_acceptance=rollback_sponsorship_acceptance,
                ),
            )
            update_sponsorship_offer_mail(
                team_id=team_id, offer_id=offer_id, action_state="accepted",
            )
            archive_sponsorship_contract_mail(contract, payment)
            return {
                "contract": contract, "payment": payment,
                "sponsorship": public_sponsorship_state(scope_id, team_id, game_date),
                "club_balance": after,
            }

    def sponsorship_mail_action(self, payload: dict[str, Any]) -> dict[str, Any]:
        action = str(payload.get("action") or "").strip().lower()
        if action in {"continue", "search"}:
            return self.continue_owned_world_club_sponsorship(payload)
        if action in {"accept", "accept_offer"}:
            return self.accept_owned_world_club_sponsorship(payload)
        raise ValueError("赞助邮件操作无效")

    def update_owned_world_club_vision(
        self, payload: dict[str, Any],
    ) -> dict[str, Any]:
        team_id = int(payload.get("team_id") or 0)
        if team_id <= 0:
            raise ValueError("俱乐部 ID 无效")
        operation = str(payload.get("operation") or "update").strip().lower()
        with self._timed_user_memory_operation("owned_club_vision"):
            _scope_id, _output, club = self._owned_world_club_target(team_id)
            if operation == "create":
                with borrow_game_operation(write_memory=True, create_thread=True) as session:
                    result = create_club_vision_record(
                        club.get("address"), team_id,
                        culture_type=payload.get("type"),
                        importance=payload.get("importance"),
                        nation_id=payload.get("nation_id"),
                        value=payload.get("value"), operation=session,
                    )
                # Creation already verified this exact record by reading it
                # back. Return that receipt, not a second whole-club read and
                # repeated nation/competition directory scans after commit.
                reference_names = {
                    f"{result['reference_type']}:{result['reference_id']}": result["reference_name"],
                } if result.get("reference_name") else {}
                created = public_club_vision(
                    [{**result, "address": result["record_address"]}],
                    reference_names=reference_names,
                )["items"][0]
                return {"result": result, "created_item": created}
            elif operation == "delete":
                result = delete_club_vision_record(
                    club.get("address"), team_id,
                    payload.get("record_address"),
                    expected=payload.get("expected"),
                )
                # Deletion already validates the compacted vector. Let the
                # client remove this one row without another whole-club scan.
                return {
                    "result": result,
                    "deleted_record_address": result["record_address"],
                }
            elif operation == "update":
                expected = payload.get("expected")
                updates = payload.get("updates")
                if not isinstance(expected, dict) or not isinstance(updates, dict):
                    raise ValueError("愿景修改参数不完整")
                with borrow_game_operation(write_memory=True) as session:
                    result = update_club_vision_record(
                        club.get("address"), team_id,
                        payload.get("record_address"),
                        expected=expected, updates=updates, operation=session,
                    )
                if result.get("changed"):
                    portfolio = load_acquired_clubs(_scope_id)
                    ownership = next(
                        (
                            row for row in portfolio.get("clubs") or []
                            if int(row.get("id") or 0) == team_id
                        ),
                        None,
                    )
                    if ownership is None:
                        raise RuntimeError("俱乐部持有记录已消失，拒绝保存董事会目标修改")
                    signature_keys = (
                        "type", "importance", "source_type", "value_raw",
                        "reference_id", "reference_type",
                    )
                    expected_signature = {
                        key: int(expected[key]) if expected.get(key) is not None else -1
                        for key in signature_keys
                    }
                    overrides = [
                        item for item in ownership.get("club_vision_overrides") or []
                        if isinstance(item, dict)
                        and self._club_vision_signature(item.get("expected") or {})
                        != expected_signature
                    ]
                    overrides.append({
                        "expected": expected_signature,
                        "updates": dict(updates),
                    })
                    try:
                        update_acquired_club(
                            team_id, {"club_vision_overrides": overrides}, _scope_id,
                        )
                    except Exception as persistence_error:
                        try:
                            update_club_vision_record(
                                club.get("address"), team_id,
                                payload.get("record_address"),
                                expected=result,
                                updates={
                                    "type": expected_signature["type"],
                                    "importance": expected_signature["importance"],
                                    "source_type": expected_signature["source_type"],
                                    "value": expected_signature["value_raw"],
                                },
                            )
                        except Exception as rollback_error:
                            raise RuntimeError(
                                "董事会目标本地持久化失败，且游戏内存回滚失败"
                            ) from rollback_error
                        raise RuntimeError(
                            "董事会目标本地持久化失败，已恢复游戏内存原值"
                        ) from persistence_error
                # The write receipt was read back from the exact record. The
                # client can merge it into its existing public row without a
                # second whole-club and reference-directory scan.
                return {"result": result, "updated_item": result}
            else:
                raise ValueError("未知的愿景操作")

    def update_owned_world_club_player_name(
        self, payload: dict[str, Any],
    ) -> dict[str, Any]:
        team_id = int(payload.get("team_id") or 0)
        player_id = int(payload.get("player_id") or 0)
        if player_id <= 0:
            raise ValueError("球员 ID 无效")
        with self.memory_lock:
            scope_id, _output, club = self._owned_world_club_target(team_id)
            player = read_native_world_club_player_membership(club, player_id)
            if not player:
                raise ValueError("所选球员不属于该已收购俱乐部，请刷新后重试")
            alias = set_player_alias(
                scope_id, player_id, str(payload.get("name", "")),
            )
            wrapper = {"players": [player]}
            apply_player_aliases(wrapper, scope_id)
            if alias:
                player["name"] = alias
                player["custom_name"] = True
            name = str(wrapper["players"][0].get("name") or "")
            if not name:
                raise ValueError("无法恢复该球员的游戏原名，请刷新后重试")
        return {
            "team_id": team_id, "player_id": player_id,
            "name": name, "custom_name": bool(alias),
        }

    def transfer_owned_world_club_finance(
        self, payload: dict[str, Any],
    ) -> dict[str, Any]:
        team_id = int(payload.get("team_id") or 0)
        field = str(payload.get("field") or "").strip().lower()
        direction = str(payload.get("direction") or "").strip().lower()
        raw_amount = float(payload.get("amount", 0))
        amount = int(raw_amount)
        if field not in {"balance", "transfer_budget"}:
            raise ValueError("俱乐部资金项目无效")
        if direction not in {"in", "out"}:
            raise ValueError("俱乐部资金操作无效")
        if amount <= 0 or raw_amount != amount:
            raise ValueError("请输入大于0的整英镑金额")

        with self._timed_user_memory_operation("owned_club_finance"):
            _scope_id, output, club = self._owned_world_club_target(team_id)
            team_address = club.get("address")
            team_name = str(club.get("name") or team_id)
            locator_attempts = 2 if field == "transfer_budget" else 1
            for locator_attempt in range(locator_attempts):
                with borrow_game_operation(write_memory=True) as operation:
                    game_clock = read_game_clock_from_reader(operation.reader)
                    write_value = (
                        write_transfer_budget if field == "transfer_budget"
                        else write_club_balance
                    )
                    standing = owned_club_league_standing(output, team_id)
                    try:
                        current = read_owned_club_fund(
                            team_address, team_id, field, standing,
                            operation=operation,
                            allow_budget_scan=field != "transfer_budget",
                        )
                    except TransferBudgetLocationError:
                        if locator_attempt + 1 < locator_attempts:
                            continue
                        raise
                    before = int(current["amount"])
                    if direction == "out" and before < amount:
                        label = "转会预算" if field == "transfer_budget" else "俱乐部结余"
                        raise ValueError(f"{label}不足")
                    after = before + amount if direction == "in" else before - amount
                    written = write_value(
                        team_address, after, team_id=team_id, expected=before,
                        operation=operation,
                    )
                    source = (
                        "transfer_budget" if field == "transfer_budget" else "club_balance"
                    )
                    try:
                        details = {
                            "direction": direction,
                            "team_id": team_id,
                            "team_name": team_name,
                            "transfer_event_id": str(uuid.uuid4()),
                            "game_date": str(game_clock.get("date") or ""),
                            "game_minutes": int(game_clock.get("minutes") or 0),
                            "game_time": str(game_clock.get("time") or ""),
                            "budget_before": before,
                            "budget_after": after,
                            "source": f"owned_club_{source}",
                        }
                        economy = (
                            self._charge_bank_or_wallet(
                                amount, f"bank_to_{source}", **details,
                            )
                            if direction == "in"
                            else adjust_bank_balance(
                                amount, f"{source}_to_bank", **details,
                            )
                        )
                    except Exception:
                        write_value(
                            team_address, before, team_id=team_id, expected=after,
                            operation=operation,
                        )
                        raise
                    break
            economy["owned_club_finance"] = {
                "team_id": team_id, "team_name": team_name,
                "field": field, "direction": direction,
                "before": before, "amount": int(written["amount"]),
            }
            return self._economy_patch_response(
                economy, transient=("owned_club_finance",),
            )

    def update_owned_world_club_sugar_daddy(
        self, payload: dict[str, Any],
    ) -> dict[str, Any]:
        team_id = int(payload.get("team_id") or 0)
        try:
            target = int(payload.get("sugar_daddy"))
        except (TypeError, ValueError) as error:
            raise ValueError("俱乐部资助类型无效") from error
        expected = payload.get("expected")
        if expected is not None:
            try:
                expected = int(expected)
            except (TypeError, ValueError) as error:
                raise ValueError("俱乐部资助类型原值无效") from error
        with self._timed_user_memory_operation("owned_club_sugar_daddy"):
            scope_id, _output, club = self._owned_world_club_target(team_id)
            with borrow_game_operation(write_memory=True) as operation:
                result = update_native_club_sugar_daddy(
                    team_id, club.get("address"), target,
                    expected=expected, operation=operation,
                )
                try:
                    update_acquired_club(
                        team_id,
                        {"sugar_daddy_override": int(result["after"])},
                        scope_id,
                    )
                except Exception as persistence_error:
                    try:
                        update_native_club_sugar_daddy(
                            team_id, club.get("address"), int(result["before"]),
                            expected=int(result["after"]), operation=operation,
                        )
                    except Exception as rollback_error:
                        raise RuntimeError(
                            "资助类型本地持久化失败，且游戏内存回滚失败"
                        ) from rollback_error
                    raise RuntimeError(
                        "资助类型本地持久化失败，已恢复游戏内存原值"
                    ) from persistence_error
        return {
            "owned_club_finance": {
                "team_id": team_id,
                "field": "sugar_daddy",
                "before": result["before"],
                "after": result["after"],
                "before_name": result["before_name"],
                "after_name": result["after_name"],
            },
        }

    def quote_club_fund_transfer(self, payload: dict[str, Any]) -> dict[str, Any]:
        field = str(payload.get("field") or "").strip().lower()
        if field not in {"balance", "transfer_budget"}:
            raise ValueError("俱乐部资金项目无效")
        requested_team_id = int(payload.get("team_id") or 0)
        with self.memory_lock:
            if requested_team_id:
                scope_id, output, team = self._owned_world_club_target(
                    requested_team_id,
                )
            else:
                with self.lock:
                    scope_id = self._bind_current_save()
                    team = self._managed_club_team()
                if not team:
                    raise ValueError("尚未识别玩家执教俱乐部")
            team_id = int(team.get("id") or 0)
            owned_by_player = self._is_acquired_club(team_id, scope_id)
            team_address = team.get("address")
            standing = (
                owned_club_league_standing(output, team_id)
                if requested_team_id else {"managed_club": True}
            )
            current = read_owned_club_fund(
                team_address, team_id, field, standing,
            )
        response = {
            "available": True,
            "amount": int(current["amount"]),
            "field": field,
            "team_id": team_id,
            "team_name": team.get("name"),
        }
        if not requested_team_id:
            response["owned_by_player"] = owned_by_player
        return response

    def _owned_world_club_target(
        self, team_id: int, *, quick_rebind: bool = True,
    ) -> tuple[str, dict[str, Any], dict[str, Any]]:
        with self.lock:
            scope_id = self._bind_current_save()
            output = dict(self.output)
            save_id = str(output.get("save_instance_id") or self._data_scope_id(output))
        acquired = account_acquired_clubs(scope_id, output)
        acquired_row = next(
            (row for row in acquired if int(row.get("id") or 0) == int(team_id)),
            None,
        )
        if not acquired_row:
            suspended = next((
                row for row in account_acquired_clubs(
                    scope_id, output, include_suspended=True,
                )
                if int(row.get("id") or 0) == int(team_id)
                and row.get("ownership_active") is False
            ), None)
            if suspended:
                raise ValueError(
                    f"该俱乐部因回档暂停生效，将在 "
                    f"{suspended.get('ownership_suspended_until')} 自动恢复"
                )
            raise ValueError("该俱乐部尚未收购")
        native = self._world_club_native_cache(save_id)
        if quick_rebind:
            overrides = (
                dict(getattr(self, "owned_world_club_addresses", {}) or {})
                if getattr(self, "owned_world_club_address_save_id", None) == save_id
                else {}
            )
            cached = next(
                (
                    row for row in (native or {}).get("clubs", [])
                    if int(row.get("id") or 0) == int(team_id)
                ),
                None,
            )
            known_address = (
                overrides.get(int(team_id))
                or (cached or {}).get("address")
                or acquired_row.get("address")
            )
            addresses = resolve_native_team_addresses(
                {team_id}, world_club_team_address_hints(output),
                scan_all_if_unresolved=True,
                known_addresses={int(team_id): known_address}
                if known_address else None,
            )
            address = addresses.get(int(team_id))
            if not address:
                raise ValueError("自动定位后仍未找到目标俱乐部")
            with self.lock:
                if getattr(self, "owned_world_club_address_save_id", None) != save_id:
                    self.owned_world_club_addresses = {}
                    self.owned_world_club_address_save_id = save_id
                self.owned_world_club_addresses[int(team_id)] = str(address)
            return scope_id, output, {
                **dict(acquired_row), **dict(cached or {}),
                "id": int(team_id), "address": address,
                "address_source": "quick_rebind",
            }
        overrides = self._owned_world_club_address_overrides(save_id)
        if not (native and native.get("addresses_current")) and int(team_id) not in overrides:
            raise ValueError("俱乐部地址已失效，请刷新我的集团")
        directory = (
            merge_native_world_clubs(build_world_clubs(output), native)
            if native else {"clubs": []}
        )
        directory = self._apply_owned_world_club_addresses(directory, save_id)
        directory = apply_acquired_club_overrides(directory, acquired)
        club = next(
            (row for row in directory["clubs"] if int(row.get("id") or 0) == int(team_id)),
            None,
        )
        if not club:
            address = overrides.get(int(team_id))
            if not address:
                raise ValueError("未找到目标俱乐部")
            club = {**dict(acquired_row), "id": int(team_id), "address": address}
        return scope_id, output, club

    def _owned_world_club_targets(
        self, team_ids: tuple[int, ...], *, quick_rebind: bool = True,
    ) -> dict[int, tuple[str, dict[str, Any], dict[str, Any]]]:
        """Resolve several owned clubs with one native address lookup.

        Player movement needs two clubs at once. Resolving them independently
        can repeat the expensive private-memory fallback scan when the session
        index is cold or an address hint has gone stale.
        """
        wanted = tuple(dict.fromkeys(int(value) for value in team_ids if int(value) > 0))
        if not wanted:
            return {}
        with self.lock:
            scope_id = self._bind_current_save()
            output = dict(self.output)
            save_id = str(output.get("save_instance_id") or self._data_scope_id(output))
        acquired_rows = {
            int(row.get("id") or 0): dict(row)
            for row in account_acquired_clubs(scope_id, output)
            if int(row.get("id") or 0) > 0
        }
        for team_id in wanted:
            if team_id in acquired_rows:
                continue
            suspended = next((
                row for row in account_acquired_clubs(
                    scope_id, output, include_suspended=True,
                )
                if int(row.get("id") or 0) == team_id
                and row.get("ownership_active") is False
            ), None)
            if suspended:
                raise ValueError(
                    f"该俱乐部因回档暂停生效，将在 "
                    f"{suspended.get('ownership_suspended_until')} 自动恢复"
                )
            raise ValueError("该俱乐部尚未收购")

        native = self._world_club_native_cache(save_id) or {}
        cached_by_id = {
            int(row.get("id") or 0): dict(row)
            for row in native.get("clubs", [])
            if int(row.get("id") or 0) in wanted
        }
        known_addresses = {}
        if quick_rebind:
            overrides = (
                dict(getattr(self, "owned_world_club_addresses", {}) or {})
                if getattr(self, "owned_world_club_address_save_id", None) == save_id
                else {}
            )
            for team_id in wanted:
                candidate = (
                    overrides.get(team_id)
                    or cached_by_id.get(team_id, {}).get("address")
                    or acquired_rows[team_id].get("address")
                )
                if candidate:
                    known_addresses[team_id] = candidate
        addresses = resolve_native_team_addresses(
            set(wanted), world_club_team_address_hints(output),
            scan_all_if_unresolved=bool(quick_rebind),
            known_addresses=known_addresses or None,
        )
        unresolved = [team_id for team_id in wanted if team_id not in addresses]
        if unresolved:
            raise ValueError("自动定位后仍未找到目标俱乐部")
        if quick_rebind:
            with self.lock:
                if getattr(self, "owned_world_club_address_save_id", None) != save_id:
                    self.owned_world_club_addresses = {}
                    self.owned_world_club_address_save_id = save_id
                for team_id in wanted:
                    self.owned_world_club_addresses[team_id] = str(addresses[team_id])
        return {
            team_id: (
                scope_id, output,
                {
                    **acquired_rows[team_id], **cached_by_id.get(team_id, {}),
                    "id": team_id, "address": addresses[team_id],
                    "address_source": "quick_rebind" if quick_rebind else "native_index",
                },
            )
            for team_id in wanted
        }

    def owned_world_club_group_people(self) -> dict[str, Any]:
        with self.lock:
            scope_id = self._bind_current_save()
            output = dict(self.output)
        acquired = account_acquired_clubs(scope_id, output)
        team_ids = tuple(int(row.get("id") or 0) for row in acquired if int(row.get("id") or 0) > 0)
        targets: dict[int, tuple[str, dict[str, Any], dict[str, Any]]] = {}
        failures: dict[int, dict[str, Any]] = {}
        with self.memory_lock:
            try:
                targets = self._owned_world_club_targets(team_ids)
            except (ValueError, RuntimeError):
                # Preserve the per-club fallback when one address cannot be rebound.
                for team_id in team_ids:
                    try:
                        targets[team_id] = self._owned_world_club_target(team_id)
                    except (ValueError, RuntimeError) as error:
                        failures[team_id] = {"error": str(error)}
            people = read_native_world_club_group_people([row[2] for row in targets.values()]) if targets else {}
        people.update(failures)
        clubs: list[dict[str, Any]] = []
        for ownership in acquired:
            team_id = int(ownership.get("id") or 0)
            if team_id <= 0:
                continue
            detail = people.get(team_id) or {}
            error = detail.get("error")
            player_manager = player_manager_for_team(output, team_id) if not error else None
            manager = player_manager or detail.get("manager")
            manager_id = int((manager or {}).get("id") or 0)
            staff = [{
                **row,
                "is_manager": int(row.get("id") or 0) == manager_id,
                "coaching_license": row.get("coaching_license"),
                "coaching_license_supported": bool(row.get("coaching_license_supported")),
            } for row in detail.get("staff") or []]
            clubs.append({
                "id": team_id,
                "name": str((detail.get("club") or {}).get("name") or ownership.get("name") or team_id),
                "competition": str((detail.get("club") or {}).get("competition") or ownership.get("competition") or ""),
                "players": detail.get("players") or [], "staff": staff,
                "manager": manager, "error": error,
            })
        return {
            "data_scope_id": scope_id, "clubs": clubs,
            "player_count": sum(len(row["players"]) for row in clubs),
            "staff_count": sum(len(row["staff"]) for row in clubs),
        }

    def _owned_world_club_relation_targets(self) -> list[dict[str, Any]]:
        with self.lock:
            scope_id = self._bind_current_save()
            output = dict(self.output)
            save_id = str(
                output.get("save_instance_id") or self._data_scope_id(output)
            )
            address_overrides = (
                dict(getattr(self, "owned_world_club_addresses", {}) or {})
                if getattr(self, "owned_world_club_address_save_id", None) == save_id
                else {}
            )
        acquired = account_acquired_clubs(scope_id, output)
        owned_by_id = {
            int(row.get("id") or 0): dict(row)
            for row in acquired if int(row.get("id") or 0) > 0
        }
        team_ids = set(owned_by_id)
        if not team_ids:
            return []

        native = self._world_club_native_cache(save_id) or {}
        cached_by_id = {
            int(row.get("id") or 0): dict(row)
            for row in (native.get("clubs") or [])
            if int(row.get("id") or 0) in team_ids
        }
        hints = world_club_team_address_hints(output)
        known_addresses: dict[int, str] = {}
        for team_id in team_ids:
            candidate = (
                address_overrides.get(team_id)
                or cached_by_id.get(team_id, {}).get("address")
                or owned_by_id[team_id].get("address")
            )
            try:
                address = int(str(candidate or "0"), 0)
            except (TypeError, ValueError):
                address = 0
            if address:
                hints.add(address)
                known_addresses[team_id] = hex(address)

        addresses = resolve_native_team_addresses(
            team_ids, hints, scan_all_if_unresolved=False,
            known_addresses=known_addresses,
        )
        unresolved = team_ids.difference(addresses)
        if unresolved:
            addresses.update(resolve_native_team_addresses(
                unresolved, hints, scan_all_if_unresolved=True,
                known_addresses={
                    team_id: known_addresses[team_id]
                    for team_id in unresolved if team_id in known_addresses
                },
            ))
        if team_ids.difference(addresses):
            raise ValueError("自动定位后仍未找到目标俱乐部")

        with self.lock:
            self.owned_world_club_addresses = dict(addresses)
            self.owned_world_club_address_save_id = save_id
        return [
            {
                "id": team_id,
                "name": str(
                    cached_by_id.get(team_id, {}).get("name")
                    or owned_by_id[team_id].get("name") or team_id
                ),
                "address": addresses[team_id],
            }
            for team_id in owned_by_id
        ]

    def owned_world_club_relations(self) -> dict[str, Any]:
        with self._timed_user_memory_operation("owned_club_relations_read"):
            clubs = self._owned_world_club_relation_targets()
            overview = read_club_affiliations(clubs)
        return {"clubs": [{"id": row["id"], "name": row["name"]} for row in clubs], **overview}

    def update_owned_world_club_relation(
        self, payload: dict[str, Any],
    ) -> dict[str, Any]:
        operation = str(payload.get("operation") or "create").strip().lower()
        parent_id = int(payload.get("parent_team_id") or 0)
        feeder_id = int(payload.get("feeder_team_id") or 0)
        if parent_id <= 0 or feeder_id <= 0 or parent_id == feeder_id:
            raise ValueError("请选择两家不同的已收购俱乐部")
        with self._timed_user_memory_operation("owned_club_relations_write"):
            clubs = self._owned_world_club_relation_targets()
            parent = next((row for row in clubs if row["id"] == parent_id), None)
            feeder = next((row for row in clubs if row["id"] == feeder_id), None)
            if not parent or not feeder:
                raise ValueError("关系双方必须是当前已生效的收购俱乐部")
            if operation == "create":
                result = create_club_affiliation(
                    parent, feeder, payload.get("type"),
                    start_date=payload.get("start_date"),
                    end_date=payload.get("end_date"),
                    updates=payload,
                )
            elif operation == "update":
                result = update_club_affiliation(
                    parent, feeder, payload.get("record_address"),
                    expected_type=payload.get("expected_type"),
                    affiliation_type=payload.get("type"),
                    expected_record=payload.get("expected_record"),
                    updates=payload,
                )
            elif operation == "delete":
                result = delete_club_affiliation(
                    parent, feeder, payload.get("record_address"),
                    expected_type=payload.get("expected_type"),
                )
            else:
                raise ValueError("未知的俱乐部关系操作")
            overview = read_club_affiliations(clubs)
        return {
            "result": result,
            "clubs": [{"id": row["id"], "name": row["name"]} for row in clubs],
            **overview,
        }

    def owned_world_club_youth_overview(self) -> dict[str, Any]:
        with self.lock:
            scope_id = self._bind_current_save()
            output = dict(self.output)
        acquired = account_acquired_clubs(scope_id, output)
        return {
            "clubs": [
                {
                    "id": int(row.get("id") or 0),
                    "name": str(row.get("name") or row.get("id") or ""),
                    "plans": youth_plans_for_team(scope_id, int(row.get("id") or 0)),
                    "golden_generation_year": golden_generation_year_status(
                        scope_id, int(row.get("id") or 0),
                        str(output.get("game_date") or ""),
                    ),
                }
                for row in acquired if int(row.get("id") or 0) > 0
            ],
            "academy_son_assignment": active_academy_son_assignment(
                scope_id, acquired,
            ),
            "academy_son_year": academy_son_year_status(
                scope_id, str(output.get("game_date") or ""),
            ),
        }

    def owned_world_club_brand_quote(self, team_id: int) -> dict[str, Any]:
        _scope, _output, club = self._owned_world_club_target(
            int(team_id), quick_rebind=True,
        )
        with self.memory_lock:
            current = read_native_club_reputation(
                int(team_id), club.get("address"),
            )
        return {
            "team_id": int(team_id),
            "team_name": str(club.get("name") or team_id),
            "reputation": current,
            "quotes": public_purchase_quotes(owned_club_brand_quotes(current)),
        }

    def repay_owned_world_club_debt(self, payload: dict[str, Any]) -> dict[str, Any]:
        team_id = int(payload.get("team_id") or 0)
        expected_debt = int(payload.get("expected_debt") or 0)
        _scope, _output, club = self._owned_world_club_target(
            team_id, quick_rebind=True,
        )
        with self.memory_lock:
            total = read_native_club_debt_total(team_id, club.get("address"))
        if total <= 0:
            raise ValueError("该俱乐部当前没有需要偿还的债务")
        if expected_debt != total:
            raise ValueError("俱乐部负债已经变化，请刷新后重试")
        payment = charge_combined_funds(
            total, "world_club_debt_repayment",
            team_id=team_id, team_name=str(club.get("name") or ""),
            debt_before=total,
        )
        try:
            with self.memory_lock:
                native = repay_native_club_debts(
                    team_id, club.get("address"), expected_total=total,
                )
        except Exception:
            refund_combined_funds(
                payment, "world_club_debt_repayment_rollback",
                team_id=team_id, team_name=str(club.get("name") or ""),
            )
            raise
        return {
            "team_id": team_id, "team_name": str(club.get("name") or ""),
            "repaid_amount": total, "native": native, "payment": payment,
            "economy": public_economy(),
        }

    def promote_owned_world_club_brand(self, payload: dict[str, Any]) -> dict[str, Any]:
        team_id = int(payload.get("team_id") or 0)
        requested = int(payload.get("delta") or 0)
        scope_id, _output, club = self._owned_world_club_target(
            team_id, quick_rebind=True,
        )
        with self.memory_lock:
            current = read_native_club_reputation(team_id, club.get("address"))
        quote = owned_club_brand_quote(current, requested)
        payment = charge_combined_funds(
            local_purchase_price(quote["price"]), "world_club_brand_promotion",
            team_id=team_id, team_name=str(club.get("name") or ""),
            reputation_before=current, reputation_delta=quote["applied"],
        )
        try:
            with self.memory_lock:
                native = apply_team_reputation_delta(
                    team_id, club.get("address"), quote["applied"],
                )
        except Exception:
            refund_combined_funds(
                payment, "world_club_brand_promotion_rollback",
                team_id=team_id, team_name=str(club.get("name") or ""),
            )
            raise
        updated = update_acquired_club(
            team_id, {"reputation": int(native["after"])}, scope_id,
        )
        with self.lock:
            for row in (self.world_club_cache or {}).get("clubs", []):
                if int(row.get("id") or 0) == team_id:
                    row["reputation"] = int(native["after"])
                    break
        return {
            "club": updated, "native": native, "payment": payment,
            "quote": public_purchase_quotes(quote),
            "quotes": public_purchase_quotes(owned_club_brand_quotes(native["after"])),
            "economy": public_economy(),
        }

    def _remember_player_move_failure(
        self, payload: dict[str, Any], error: Exception,
    ) -> None:
        mode = str(payload.get("mode") or "move").strip().lower()
        detail = describe_player_movement_error(error, mode=mode)
        self.last_operation_error = str(detail["error"])
        self.last_operation_error_type = str(detail["error_type"])
        self.last_operation_error_stage = f"player_{mode}"
        self.last_operation_error_code = str(detail["error_code"])
        self.last_operation_error_phase = str(detail["error_phase"])
        self.last_operation_retryable = bool(detail["retryable"])
        self.last_operation_traceback = traceback.format_exc()[-6000:]

    def _clear_player_move_failure(self) -> None:
        self.last_operation_error = None
        self.last_operation_error_type = None
        self.last_operation_error_stage = None
        self.last_operation_error_code = None
        self.last_operation_error_phase = None
        self.last_operation_retryable = False
        self.last_operation_traceback = None

    def _rebind_player_movement_targets(
        self, team_ids: tuple[int, int],
    ) -> list[dict[str, Any]]:
        """Refresh only the two affected stable team identities after commit."""
        rebound: list[dict[str, Any]] = []
        for team_id in dict.fromkeys(int(value) for value in team_ids if int(value) > 0):
            invalidate_club_profile_cache(team_id=team_id)
            _scope_id, _output, club = self._owned_world_club_target(
                team_id, quick_rebind=True,
            )
            rebound.append({
                "id": team_id,
                "name": str(club.get("name") or team_id),
                "address": club.get("address"),
            })
        return rebound

    def move_owned_world_club_player(self, payload: dict[str, Any]) -> dict[str, Any]:
        submission_id = str(payload.get("client_submission_id") or "").strip()
        if len(submission_id) > 128:
            raise ValueError("提交标识无效")
        if not submission_id:
            try:
                result = self._execute_owned_world_club_player(payload)
            except Exception as error:
                self._remember_player_move_failure(payload, error)
                raise
            self._clear_player_move_failure()
            return result

        guard_lock = getattr(self, "_player_move_submission_lock", None)
        if guard_lock is None:
            guard_lock = threading.RLock()
            self._player_move_submission_lock = guard_lock
        with guard_lock:
            completed = getattr(self, "_player_move_submission_results", None)
            if completed is None:
                completed = {}
                self._player_move_submission_results = completed
            cached = completed.get(submission_id)
            if cached is not None:
                return deepcopy(cached)
            in_flight = getattr(self, "_player_move_submissions_in_flight", None)
            if in_flight is None:
                in_flight = set()
                self._player_move_submissions_in_flight = in_flight
            if submission_id in in_flight:
                raise RuntimeError("本次球员移动正在处理中，请勿重复点击")
            in_flight.add(submission_id)

        try:
            result = self._execute_owned_world_club_player(payload)
        except Exception as error:
            with guard_lock:
                in_flight.discard(submission_id)
            self._remember_player_move_failure(payload, error)
            raise

        self._clear_player_move_failure()
        with guard_lock:
            in_flight.discard(submission_id)
            completed[submission_id] = deepcopy(result)
            while len(completed) > 64:
                completed.pop(next(iter(completed)))
        return result

    def _execute_owned_world_club_player(self, payload: dict[str, Any]) -> dict[str, Any]:
        if not OWNED_PLAYER_MOVE_RUNTIME_ENABLED:
            raise RuntimeError("球员转会与租借的原生写入已临时停用，正在检查本次游戏错误")
        source_team_id = int(payload.get("source_team_id") or 0)
        target_team_id = int(payload.get("target_team_id") or 0)
        player_id = int(payload.get("player_id") or 0)
        source_squad_team_id = int(payload.get("source_squad_team_id") or 0)
        source_squad_team_address = payload.get("source_squad_team_address")
        mode = str(payload.get("mode") or "").strip().lower()
        if mode not in {"transfer", "loan"}:
            raise ValueError("球员移动方式无效")
        if source_team_id <= 0 or target_team_id <= 0 or player_id <= 0:
            raise ValueError("来源俱乐部、目标俱乐部或球员 ID 无效")
        if source_team_id == target_team_id:
            raise ValueError("请选择另一家已收购俱乐部")
        # Lightweight test doubles and older embedders may not initialize the
        # state lock; retain their single-target compatibility path.
        batch_target = (
            getattr(self, "_owned_world_club_targets", None)
            if getattr(self, "lock", None) is not None else None
        )
        if callable(batch_target):
            resolved = batch_target((source_team_id, target_team_id))
            source_scope, source_output, source_club = resolved[source_team_id]
            target_scope, target_output, target_club = resolved[target_team_id]
        else:
            source_scope, source_output, source_club = self._owned_world_club_target(source_team_id)
            target_scope, target_output, target_club = self._owned_world_club_target(target_team_id)
        if (
            source_scope != target_scope
            or str(source_output.get("save_instance_id") or "")
            != str(target_output.get("save_instance_id") or "")
        ):
            raise RuntimeError("当前存档身份已经变化，请重新连接后再试")
        auto_refreshed = False
        squad_kwargs = (
            {
                "source_squad_team_id": source_squad_team_id,
                "source_squad_team_address": source_squad_team_address,
            }
            if source_squad_team_id > 0 else {}
        )

        try:
            with self.memory_lock:
                result = move_owned_club_player(
                    source_team_id=source_team_id,
                    source_team_address=source_club.get("address"),
                    **squad_kwargs,
                    target_team_id=target_team_id,
                    target_team_address=target_club.get("address"),
                    player_id=player_id,
                    mode=mode,
                )
        except PlayerMovementContextChangedError as error:
            if not bool(getattr(error, "retryable", True)):
                raise
            # Re-resolve both teams from stable UIDs and retry once.
            with self.memory_lock:
                if callable(batch_target):
                    resolved = batch_target(
                        (source_team_id, target_team_id), quick_rebind=True,
                    )
                    source_scope, source_output, source_club = resolved[source_team_id]
                    target_scope, target_output, target_club = resolved[target_team_id]
                else:
                    source_scope, source_output, source_club = self._owned_world_club_target(
                        source_team_id, quick_rebind=True,
                    )
                    target_scope, target_output, target_club = self._owned_world_club_target(
                        target_team_id, quick_rebind=True,
                    )
                if (
                    source_scope != target_scope
                    or str(source_output.get("save_instance_id") or "")
                    != str(target_output.get("save_instance_id") or "")
                ):
                    raise RuntimeError("自动刷新时检测到存档身份已经变化")
                result = move_owned_club_player(
                    source_team_id=source_team_id,
                    source_team_address=source_club.get("address"),
                    **squad_kwargs,
                    target_team_id=target_team_id,
                    target_team_address=target_club.get("address"),
                    player_id=player_id,
                    mode=mode,
                )
            auto_refreshed = True
        result["auto_refreshed"] = auto_refreshed
        result["source_team_name"] = str(source_club.get("name") or source_team_id)
        result["target_team_name"] = str(target_club.get("name") or target_team_id)
        result["affected_team_ids"] = [source_team_id, target_team_id]
        try:
            with self.memory_lock:
                result["refreshed_targets"] = self._rebind_player_movement_targets(
                    (source_team_id, target_team_id),
                )
        except Exception as error:
            # The native transaction is already verified and must never be
            # reported as failed merely because the presentation refresh did.
            result["refreshed_targets"] = []
            result["refresh_warning"] = f"球员操作已完成，但俱乐部资料重新绑定失败：{error}"
        return result

    def release_owned_world_club_player(self, payload: dict[str, Any]) -> dict[str, Any]:
        if not OWNED_PLAYER_RELEASE_RUNTIME_ENABLED:
            raise RuntimeError("FM24 球员解约事务已临时停用")
        source_team_id = int(payload.get("source_team_id") or 0)
        player_id = int(payload.get("player_id") or 0)
        source_squad_team_id = int(payload.get("source_squad_team_id") or 0)
        source_squad_team_address = payload.get("source_squad_team_address")
        if source_team_id <= 0 or player_id <= 0:
            raise ValueError("来源俱乐部或球员 ID 无效")
        _scope_id, _output, source_club = self._owned_world_club_target(
            source_team_id,
        )
        with self.memory_lock:
            result = release_owned_club_player(
                source_team_id=source_team_id,
                source_team_address=source_club.get("address"),
                **({
                    "source_squad_team_id": source_squad_team_id,
                    "source_squad_team_address": source_squad_team_address,
                } if source_squad_team_id > 0 else {}),
                player_id=player_id,
            )
        result["source_team_name"] = str(
            source_club.get("name") or source_team_id
        )
        return result

    def reassign_owned_world_club_player_squad(
        self, payload: dict[str, Any],
    ) -> dict[str, Any]:
        team_id = int(payload.get("team_id") or 0)
        player_id = int(payload.get("player_id") or 0)
        source_squad_team_id = int(payload.get("source_squad_team_id") or 0)
        target_squad_team_id = int(payload.get("target_squad_team_id") or 0)
        if (
            team_id <= 0 or player_id <= 0
            or source_squad_team_id <= 0 or target_squad_team_id <= 0
        ):
            raise ValueError("俱乐部、球员、来源阵容或目标阵容 ID 无效")
        if source_squad_team_id == target_squad_team_id:
            raise ValueError("来源阵容与目标阵容不能相同")
        _scope_id, _output, club = self._owned_world_club_target(team_id)
        with self.memory_lock:
            result = reassign_owned_club_player_squad(
                club_team_id=team_id,
                club_team_address=club.get("address"),
                source_squad_team_id=source_squad_team_id,
                source_squad_team_address=payload.get("source_squad_team_address"),
                target_squad_team_id=target_squad_team_id,
                target_squad_team_address=payload.get("target_squad_team_address"),
                player_id=player_id,
            )
        result["club_name"] = str(club.get("name") or team_id)
        result["affected_team_ids"] = [team_id]
        try:
            with self.memory_lock:
                result["refreshed_targets"] = self._rebind_player_movement_targets(
                    (team_id,),
                )
        except Exception as error:
            result["refreshed_targets"] = []
            result["refresh_warning"] = (
                f"阵容调整已完成，但俱乐部资料重新绑定失败：{error}"
            )
        return result

    def release_owned_world_club_staff(self, payload: dict[str, Any]) -> dict[str, Any]:
        if not OWNED_STAFF_RELEASE_RUNTIME_ENABLED:
            raise RuntimeError("职员解雇事务已临时停用")
        source_team_id = int(payload.get("source_team_id") or 0)
        staff_id = int(payload.get("staff_id") or 0)
        if source_team_id <= 0 or staff_id <= 0:
            raise ValueError("来源俱乐部或职员 ID 无效")
        _scope_id, source_output, source_club = self._owned_world_club_target(
            source_team_id,
        )
        player_manager = player_manager_for_team(source_output, source_team_id)
        if player_manager and int(player_manager["id"]) == staff_id:
            raise ValueError("不能解雇玩家主教练")
        with self.memory_lock:
            result = release_owned_club_staff(
                source_team_id=source_team_id,
                source_team_address=source_club.get("address"),
                staff_id=staff_id,
            )
            invalidate_head_coach_search_cache()
        result["source_team_name"] = str(
            source_club.get("name") or source_team_id
        )
        return result

    def set_owned_world_club_player_listed(self, payload: dict[str, Any]) -> dict[str, Any]:
        source_team_id = int(payload.get("source_team_id") or 0)
        player_id = int(payload.get("player_id") or 0)
        source_squad_team_id = int(payload.get("source_squad_team_id") or 0)
        source_squad_team_address = payload.get("source_squad_team_address")
        listed = bool(payload.get("listed", True))
        if source_team_id <= 0 or player_id <= 0:
            raise ValueError("来源俱乐部或球员 ID 无效")
        _scope_id, _output, source_club = self._owned_world_club_target(
            source_team_id,
        )
        with self.memory_lock:
            result = set_owned_club_player_transfer_listed(
                source_team_id=source_team_id,
                source_team_address=source_club.get("address"),
                source_squad_team_id=source_squad_team_id,
                source_squad_team_address=source_squad_team_address,
                player_id=player_id,
                listed=listed,
            )
        result["source_team_name"] = str(
            source_club.get("name") or source_team_id
        )
        return result

    def move_owned_world_club_staff(self, payload: dict[str, Any]) -> dict[str, Any]:
        source_team_id = int(payload.get("source_team_id") or 0)
        target_team_id = int(payload.get("target_team_id") or 0)
        staff_id = int(payload.get("staff_id") or 0)
        if source_team_id <= 0 or target_team_id <= 0 or staff_id <= 0:
            raise ValueError("来源俱乐部、目标俱乐部或职员 ID 无效")
        if source_team_id == target_team_id:
            raise ValueError("请选择另一家已收购俱乐部")
        source_scope, source_output, source_club = self._owned_world_club_target(source_team_id)
        target_scope, target_output, target_club = self._owned_world_club_target(target_team_id)
        if (
            source_scope != target_scope
            or str(source_output.get("save_instance_id") or "")
            != str(target_output.get("save_instance_id") or "")
        ):
            raise RuntimeError("当前存档身份已经变化，请重新连接后再试")
        with self.memory_lock:
            result = move_owned_club_staff(
                source_team_id=source_team_id,
                source_team_address=source_club.get("address"),
                target_team_id=target_team_id,
                target_team_address=target_club.get("address"),
                staff_id=staff_id,
            )
        result["source_team_name"] = str(source_club.get("name") or source_team_id)
        result["target_team_name"] = str(target_club.get("name") or target_team_id)
        return result

    def search_world_head_coaches(
        self, team_id: int, query: str = "",
    ) -> dict[str, Any]:
        _scope_id, output, club = self._owned_world_club_target(int(team_id))
        manager_id = int(
            output.get("selected_manager_id")
            or (output.get("manager") or {}).get("id")
            or 0
        )
        with self.memory_lock:
            result = search_head_coaches(
                query, exclude_team_id=int(team_id), manager_id=manager_id,
            )
        result["target_team_id"] = int(team_id)
        result["target_team_name"] = str(club.get("name") or team_id)
        return result

    def extend_owned_world_club_manager_contract(
        self, payload: dict[str, Any],
    ) -> dict[str, Any]:
        team_id = int(payload.get("team_id") or 0)
        manager_id = int(payload.get("manager_id") or 0)
        if team_id <= 0 or manager_id <= 0:
            raise ValueError("俱乐部或主教练 ID 无效")
        _scope_id, output, club = self._owned_world_club_target(team_id)
        player_manager = player_manager_for_team(output, team_id)
        if player_manager and int(player_manager["id"]) == manager_id:
            raise ValueError("玩家主教练不能通过俱乐部职员合同功能续约")
        with self.memory_lock:
            result = extend_owned_club_manager_contract(
                team_id=team_id,
                team_address=club.get("address"),
                manager_id=manager_id,
                years=2,
            )
        result["team_name"] = str(club.get("name") or team_id)
        return result

    def replace_owned_world_club_manager(
        self, payload: dict[str, Any],
    ) -> dict[str, Any]:
        team_id = int(payload.get("team_id") or 0)
        current_manager_id = int(payload.get("current_manager_id") or 0)
        candidate_manager_id = int(payload.get("candidate_manager_id") or 0)
        candidate_team_id = int(payload.get("candidate_team_id") or 0)
        candidate_free_agent = bool(payload.get("candidate_free_agent"))
        if team_id <= 0 or candidate_manager_id <= 0:
            raise ValueError("主教练更换参数无效")
        if not candidate_free_agent and (
            current_manager_id <= 0 or candidate_team_id <= 0
        ):
            raise ValueError("主教练更换参数无效")
        _scope_id, output, club = self._owned_world_club_target(team_id)
        player_manager = player_manager_for_team(output, team_id)
        if player_manager:
            raise ValueError("不能通过俱乐部职员功能更换玩家主教练")
        scan_manager_id = int(
            output.get("selected_manager_id")
            or (output.get("manager") or {}).get("id")
            or 0
        )
        payment = charge_combined_funds(
            local_purchase_price(OWNED_MANAGER_REPLACE_PRICE), "world_club_manager_replace",
            team_id=team_id, team_name=str(club.get("name") or ""),
            candidate_manager_id=candidate_manager_id,
            candidate_free_agent=candidate_free_agent,
        )
        try:
            with self.memory_lock:
                if candidate_free_agent:
                    result = appoint_free_agent_manager(
                        target_team_id=team_id,
                        target_team_address=club.get("address"),
                        candidate_staff_id=candidate_manager_id,
                        candidate_name=str(payload.get("candidate_name") or ""),
                    )
                else:
                    result = replace_owned_club_manager(
                        target_team_id=team_id,
                        target_team_address=club.get("address"),
                        current_manager_id=current_manager_id,
                        candidate_manager_id=candidate_manager_id,
                        candidate_team_id=candidate_team_id,
                        scan_manager_id=scan_manager_id,
                    )
                invalidate_head_coach_search_cache()
        except Exception:
            refund_combined_funds(
                payment, "world_club_manager_replace_rollback",
                team_id=team_id, team_name=str(club.get("name") or ""),
                candidate_manager_id=candidate_manager_id,
                candidate_free_agent=candidate_free_agent,
            )
            raise
        result["target_team_name"] = str(club.get("name") or team_id)
        result["payment"] = payment
        return result

    def arm_world_club_youth_plan(self, payload: dict[str, Any]) -> dict[str, Any]:
        team_id = int(payload.get("team_id") or 0)
        kind = str(payload.get("kind") or "").strip()
        scope_id, output, club = self._owned_world_club_target(
            team_id, quick_rebind=True,
        )
        config = normalize_youth_plan_config(
            kind, payload.get("config") if isinstance(payload.get("config"), dict) else {},
        )
        existing_golden = youth_plans_for_team(scope_id, team_id).get(kind)
        if (
            kind == "golden_generation"
            and existing_golden
            and existing_golden.get("status") in {"armed", "waiting"}
        ):
            raise ValueError(
                "该俱乐部已有进行中的青训质量投资（小妖青训计划）"
            )
        if kind == "academy_son":
            assignment = active_academy_son_assignment(
                scope_id, account_acquired_clubs(scope_id, output),
            )
            if assignment:
                assigned_team_id = int(assignment.get("team_id") or 0)
                assigned_name = str(assignment.get("team_name") or assigned_team_id)
                if assigned_team_id == team_id:
                    raise ValueError("该俱乐部已有儿子历练计划，请先取消原计划")
                raise ValueError(f"儿子已在（{assigned_name}）历练，请先取消原计划")
        payment = None
        if kind in {"golden_generation", "academy_son"}:
            price = (
                golden_generation_price(config)
                if kind == "golden_generation"
                else academy_son_price(config)
            )
            operation = (
                "world_club_golden_generation"
                if kind == "golden_generation"
                else "world_club_academy_son"
            )
            payment = charge_combined_funds(
                local_purchase_price(price), operation,
                team_id=team_id, team_name=str(club.get("name") or ""),
                player_count=1 if kind == "academy_son" else int(config["count"]),
                player_name=str(config.get("name") or ""),
                primary_position=str(config.get("primary_position") or ""),
                secondary_position=str(config.get("secondary_position") or ""),
                min_ca=int(config.get("min_ca") or 0),
                max_ca=int(config.get("max_ca") or 0),
                min_pa=int(config["min_pa"]), max_pa=int(config["max_pa"]),
            )
        plan = None
        try:
            with self.memory_lock:
                plan = arm_youth_plan(
                    scope_id, team_id, club.get("address"), kind, config,
                    str(output.get("game_date") or ""), payment=payment,
                )
                hook_status = self._sync_youth_generation_plans(
                    scope_id,
                    str(output.get("save_instance_id") or self._data_scope_id(output)),
                )
                requires_generation_hook = (
                    str(plan.get("execution_mode") or "generation_hook")
                    == "generation_hook"
                )
                if requires_generation_hook and (
                    hook_status.get("error") or not hook_status.get("installed")
                ):
                    technical_error = str(
                        hook_status.get("error") or "青训生成安装失败"
                    )
                    print(
                        f"[youth-plan] activation failed: {technical_error}",
                        file=sys.stderr,
                    )
                    raise RuntimeError(
                        "青训功能暂时无法启用，本次费用已退回，"
                        "请完全重启 Football Manager 和 FMODD 后重试"
                    ) from None
        except Exception:
            if plan is not None:
                disarm_youth_plan(
                    scope_id, team_id, kind,
                    rollback_usage=True,
                )
            self._sync_youth_generation_plans(
                scope_id,
                str(output.get("save_instance_id") or self._data_scope_id(output)),
            )
            if payment:
                refund_combined_funds(
                    payment, f"world_club_{kind}_rollback",
                    team_id=team_id, team_name=str(club.get("name") or ""),
                )
            raise
        return {
            "plan": plan,
            "youth_plans": youth_plans_for_team(scope_id, team_id),
            "payment": payment,
            "generation_hook": hook_status,
            "economy": public_economy(),
        }

    def cancel_world_club_youth_plan(self, payload: dict[str, Any]) -> dict[str, Any]:
        team_id = int(payload.get("team_id") or 0)
        kind = str(payload.get("kind") or "").strip()
        if kind != "academy_son":
            raise ValueError("青训质量投资启用后不可取消")
        scope_id, output, _club = self._owned_world_club_target(
            team_id, quick_rebind=True,
        )
        with self.memory_lock:
            current_status = self.youth_generation_hook.status()
            if current_status.get("targets") or current_status.get("son_target"):
                record_youth_generation_progress(scope_id, current_status)
            disarm_youth_plan(
                scope_id, team_id, kind,
                rollback_usage=True,
            )
            hook_status = self._sync_youth_generation_plans(
                scope_id,
                str(output.get("save_instance_id") or self._data_scope_id(output)),
            )
            if hook_status.get("error"):
                print(
                    f"[youth-plan] cancellation sync failed: {hook_status['error']}",
                    file=sys.stderr,
                )
                raise RuntimeError(
                    "青训计划状态同步失败，请重启 FMODD 后重试"
                ) from None
        return {
            "cancelled": True,
            "youth_plans": youth_plans_for_team(scope_id, team_id),
            "generation_hook": hook_status,
        }

    def reopen_world_club_youth_plan(self, payload: dict[str, Any]) -> dict[str, Any]:
        team_id = int(payload.get("team_id") or 0)
        kind = str(payload.get("kind") or "").strip()
        scope_id, output, _club = self._owned_world_club_target(
            team_id, quick_rebind=True,
        )
        with self.memory_lock:
            plan = reopen_misclassified_youth_shortfall(
                scope_id, team_id, kind,
            )
            hook_status = self._sync_youth_generation_plans(
                scope_id,
                str(output.get("save_instance_id") or self._data_scope_id(output)),
            )
        return {
            "reopened": True,
            "plan": plan,
            "youth_plans": youth_plans_for_team(scope_id, team_id),
            "generation_hook": hook_status,
        }

    def apply_world_club_youth_plan(self, payload: dict[str, Any]) -> dict[str, Any]:
        team_id = int(payload.get("team_id") or 0)
        requested_kind = str(payload.get("kind") or "").strip()
        if requested_kind not in {"academy_son", "golden_generation"}:
            raise ValueError("未知的青训计划")
        if "player_id" in payload:
            raise ValueError("儿子候选由系统自动选择，不能手动指定")
        scope_id, output, club = self._owned_world_club_target(team_id)
        manager = output.get("manager") or {}
        manager_id = int(output.get("selected_manager_id") or manager.get("id") or 0)
        assignments = managed_team_rows(output)
        manager_team = next(
            (
                team for team in assignments
                if str(team.get("team_type") or "club") == "club"
            ),
            assignments[0] if assignments else {},
        )
        if manager_team:
            team_id_key = int(manager_team.get("id") or 0)
            manager_context = self.club_contexts.get(team_id_key) or {}
            if not manager_context and int(
                ((self.club_context or {}).get("team") or {}).get("id") or 0
            ) == team_id_key:
                manager_context = self.club_context or {}
            manager_team = {
                **manager_team,
                **(manager_context.get("team") or {}),
            }
        with self.memory_lock:
            plans_before = youth_plans_for_team(scope_id, team_id)
            active_kinds = [
                kind for kind in ("academy_son", "golden_generation")
                if (plans_before.get(kind) or {}).get("status")
                in {"armed", "waiting"}
            ]
            if not active_kinds:
                raise ValueError("该俱乐部当前没有待手动修正的青训计划")
            batch_results: dict[str, dict[str, Any]] = {}
            for kind in active_kinds:
                try:
                    result = apply_youth_plan(
                        scope_id, team_id, club.get("address"), kind,
                        str(output.get("game_date") or ""),
                        manager_id=manager_id,
                        manager_team_id=int(manager_team.get("id") or 0),
                        manager_team_address=manager_team.get("address"),
                        manager_address=(
                            manager.get("manager_address")
                            or manager_team.get("manager_address")
                        ),
                    )
                    if int(result.get("shortfall") or 0) > 0:
                        current_plan = (
                            result.get("plan")
                            or youth_plans_for_team(scope_id, team_id).get(kind)
                            or {}
                        )
                        if current_plan.get("roster_recovery_only"):
                            result.update({
                                "status": "insufficient",
                                "message": (
                                    "恢复计划已核验当前名单；原费用已经退回，"
                                    "不会重复退款，计划将保留以便再次核验"
                                ),
                                "plan": current_plan,
                            })
                        else:
                            settlement = self._settle_youth_plan_shortfall(
                                scope_id, output, club, kind,
                                {"team_id": team_id, **result},
                            )
                            settled_plan = settlement.get("plan") or {}
                            result.update({
                                "status": "completed_with_refund",
                                "message": str(
                                    settled_plan.get("last_result", {}).get("message")
                                    or "正式青训名单人数不足，缺少名额的费用已退款"
                                ),
                                "refund": settlement.get("refund"),
                                "mail": settlement.get("mail"),
                                "plan": settled_plan,
                            })
                    if result.get("status") == "completed":
                        completed_plan = (
                            result.get("plan")
                            or youth_plans_for_team(scope_id, team_id).get(kind)
                            or {}
                        )
                        if completed_plan.get("armed_at"):
                            try:
                                result["mail"] = archive_youth_completion_mail(
                                    armed_at=str(completed_plan.get("armed_at") or ""),
                                    kind=kind, team_id=team_id,
                                    team_name=str(club.get("name") or ""),
                                    game_date=str(output.get("game_date") or ""),
                                    player_names=_youth_plan_generated_names(
                                        kind, completed_plan,
                                    ),
                                )
                            except Exception as error:
                                result["mail_error"] = str(error)
                except Exception as error:
                    result = {
                        "status": "error",
                        "message": f"{'儿子计划' if kind == 'academy_son' else '小妖计划'}手动修正失败：{error}",
                        "applied": [],
                        "error": str(error),
                    }
                batch_results[kind] = result
                if result.get("status") == "error":
                    break
            hook_status = self._sync_youth_generation_plans(
                scope_id,
                str(output.get("save_instance_id") or self._data_scope_id(output)),
            )
        ordered_results = [batch_results[kind] for kind in active_kinds if kind in batch_results]
        statuses = {str(result.get("status") or "waiting") for result in ordered_results}
        if "error" in statuses:
            batch_status = "error"
        elif statuses & {"waiting", "insufficient"}:
            batch_status = "waiting" if "waiting" in statuses else "insufficient"
        elif "completed_with_refund" in statuses:
            batch_status = "completed_with_refund"
        else:
            batch_status = "completed"
        messages = [
            str(result.get("message") or "").strip()
            for result in ordered_results
            if str(result.get("message") or "").strip()
        ]
        applied = [
            player for result in ordered_results
            for player in result.get("applied") or []
        ]
        refunds = {
            kind: result["refund"] for kind, result in batch_results.items()
            if result.get("refund")
        }
        compatibility = dict(ordered_results[0]) if len(ordered_results) == 1 else {}
        return {
            **compatibility,
            "status": batch_status,
            "message": "；".join(messages) or "青训计划手动修正完成",
            "applied": applied,
            "plan_results": batch_results,
            "youth_plans": youth_plans_for_team(scope_id, team_id),
            "generation_hook": hook_status,
            **({"refunds": refunds, "economy": public_economy()} if refunds else {}),
        }

    def world_club_staff(self, team_id: int) -> dict[str, Any]:
        with self.lock:
            scope_id = self._bind_current_save()
            output = dict(self.output)
            save_id = str(output.get("save_instance_id") or self._data_scope_id(output))
        acquired = next(
            (
                row for row in account_acquired_clubs(scope_id, output)
                if int(row.get("id") or 0) == int(team_id)
            ),
            None,
        )
        if acquired:
            _scope_id, _output, club = self._owned_world_club_target(team_id)
        else:
            native = self._world_club_native_cache(save_id)
            if not native:
                raise ValueError("请先扫描俱乐部")
            if not native.get("addresses_current"):
                raise ValueError("俱乐部地址已失效，请重新扫描俱乐部")
            directory = merge_native_world_clubs(build_world_clubs(output), native)
            club = next(
                (row for row in directory["clubs"] if int(row.get("id") or 0) == int(team_id)),
                None,
            )
            if not club:
                raise ValueError("未找到目标俱乐部")
        result = read_native_world_club_staff(club)
        if acquired:
            player_manager = player_manager_for_team(output, int(team_id))
            if player_manager:
                result["manager"] = player_manager
            result["manager_is_player"] = bool(player_manager)
            manager_record = sync_acquired_club_manager_record(
                int(team_id), int((result.get("manager") or {}).get("id") or 0),
                list(acquired.get("club_results") or []), scope_id,
            )
            result["manager_record"] = manager_record
        return result

    def world_club_results(self, team_id: int, *, force_refresh: bool = False) -> dict[str, Any]:
        with self.lock:
            scope_id = self._bind_current_save()
            output = dict(self.output)
            save_id = str(output.get("save_instance_id") or self._data_scope_id(output))
        _scope_id, _output, club = self._owned_world_club_target(team_id)
        with self.memory_lock:
            result = read_native_world_club_results(
                club, save_identity=save_id, force_refresh=force_refresh,
            )
        cached = update_acquired_club(
            int(team_id), {
                "recent_results": result.get("recent_results") or [],
                "club_results": result.get("results") or [],
                "club_results_updated_at": result.get("updated_at"),
                "club_results_source": result.get("source"),
            }, scope_id,
        )
        record_state = cached.get("manager_record_state") or {}
        manager_record = None
        if int(record_state.get("manager_id") or 0) > 0:
            manager_record = sync_acquired_club_manager_record(
                int(team_id), int(record_state["manager_id"]),
                list(result.get("results") or []), scope_id,
            )
            cached = next(
                (
                    row for row in account_acquired_clubs(scope_id, output)
                    if int(row.get("id") or 0) == int(team_id)
                ),
                cached,
            )
        return {**result, "club": cached, "manager_record": manager_record}

    def world_club_future_transfers(self, team_id: int) -> dict[str, Any]:
        with self.lock:
            scope_id = self._bind_current_save()
            output = dict(self.output)
            save_id = str(output.get("save_instance_id") or self._data_scope_id(output))
        _scope_id, _output, club = self._owned_world_club_target(team_id)
        with self.memory_lock:
            return read_future_transfers(
                int(team_id), club.get("address"), save_identity=save_id,
            )

    def cancel_world_club_future_transfer(self, payload: dict[str, Any]) -> dict[str, Any]:
        with self.lock:
            scope_id = self._bind_current_save()
            output = dict(self.output)
            save_id = str(output.get("save_instance_id") or self._data_scope_id(output))
        team_id = int(payload.get("team_id") or 0)
        transfer_id = int(payload.get("transfer_id") or 0)
        offer_address = payload.get("offer_address")
        _scope_id, _output, club = self._owned_world_club_target(team_id)
        with self.memory_lock:
            return cancel_future_transfer(
                team_id, club.get("address"), transfer_id, offer_address,
                save_identity=save_id,
            )

    def rename_world_club(self, payload: dict[str, Any]) -> dict[str, Any]:
        with self.lock:
            scope_id = self._bind_current_save()
            output = dict(self.output)
            save_id = str(output.get("save_instance_id") or self._data_scope_id(output))
        team_id = int(payload.get("team_id") or 0)
        new_name = (
            str(payload.get("name") or "").strip()
            if "name" in payload else None
        )
        new_short_name = (
            str(payload.get("short_name") or "").strip()
            if "short_name" in payload else None
        )
        native = self._world_club_native_cache(save_id)
        _scope_id, _output, club = self._owned_world_club_target(
            team_id, quick_rebind=True,
        )
        managed_club_ids = {
            int(row.get("id") or 0)
            for row in managed_team_rows(output)
            if str(row.get("team_type") or "club") == "club"
        }
        payment = charge_combined_funds(
            local_purchase_price(OWNED_CLUB_RENAME_PRICE), "world_club_rename",
            team_id=team_id, team_name=str(club.get("name") or ""),
        )
        try:
            with self.memory_lock:
                native_result = rename_native_club(
                    team_id, club.get("address"), new_name,
                    new_short_name=new_short_name,
                    is_managed_club=team_id in managed_club_ids,
                )
        except Exception:
            refund_combined_funds(
                payment, "world_club_rename_rollback",
                team_id=team_id, team_name=str(club.get("name") or ""),
            )
            raise

        warning = None
        native_after = dict(native_result.get("after") or {})
        persisted_name = str(native_after.get("name") or club.get("name") or "")
        persisted_short_name = str(
            native_after.get("short_name") or club.get("short_name") or persisted_name
        )
        try:
            updated = update_acquired_club(
                team_id, {
                    "name": persisted_name,
                    "short_name": persisted_short_name,
                    "renamed_name": persisted_name,
                    "renamed_short_name": persisted_short_name,
                }, scope_id,
            )
            for row in (native or {}).get("clubs", []):
                if int(row.get("id") or 0) == team_id:
                    row["name"] = persisted_name
                    row["short_name"] = persisted_short_name
                    row["name_overridden"] = True
                    break
            with self.lock:
                self.world_club_cache = native
                self.world_club_cache_save_id = save_id
        except Exception as persistence_error:
            updated = {
                **club,
                "name": persisted_name,
                "short_name": persisted_short_name,
                "renamed_name": persisted_name,
                "renamed_short_name": persisted_short_name,
            }
            warning = f"游戏内名称已修改，但本地名称缓存更新失败：{persistence_error}"
        acquired_rows = account_acquired_clubs(
            scope_id, output, include_suspended=True,
        )
        if warning:
            acquired_rows = [
                ({
                    **row,
                    "name": persisted_name,
                    "short_name": persisted_short_name,
                    "renamed_name": persisted_name,
                    "renamed_short_name": persisted_short_name,
                }
                 if int(row.get("id") or 0) == team_id else row)
                for row in acquired_rows
            ]
        return {
            "club": updated, "native": native_result, "payment": payment,
            "warning": warning,
            "acquired": acquired_rows,
        }

    def upgrade_world_club_facility(self, payload: dict[str, Any]) -> dict[str, Any]:
        operation_lock = getattr(self, "owned_facility_plan_lock", None)
        if operation_lock is None:
            operation_lock = threading.RLock()
            self.owned_facility_plan_lock = operation_lock
        with operation_lock:
            return self._create_world_club_facility_plan(payload)

    def _create_world_club_facility_plan(
        self, payload: dict[str, Any],
    ) -> dict[str, Any]:
        with self.lock:
            self._bind_current_save()
        team_id = int(payload.get("team_id") or 0)
        facility = str(payload.get("facility") or "").strip().lower()
        try:
            requested_levels = int(payload.get("levels") or 1)
        except (TypeError, ValueError) as error:
            raise ValueError("升级级数无效") from error
        facility_fields = {
            "training": "training",
            "youth": "youth",
            "junior": "junior_coaching",
            "recruitment": "youth_recruitment",
        }
        if facility not in facility_fields:
            raise ValueError("不支持提高该项俱乐部设施")
        _scope_id, _output, club = self._owned_world_club_target(team_id)
        ownership = next(
            (
                row for row in account_acquired_clubs(_scope_id, _output)
                if int(row.get("id") or 0) == team_id
            ),
            club,
        )
        game_date = str(_output.get("game_date") or "")
        plan_status = owned_club_facility_upgrade_cooldowns(
            ownership, game_date,
        )[facility]
        if plan_status["active"]:
            if plan_status.get("status") in {"scheduled", "due"}:
                raise ValueError("该项设施已有进行中的升级计划")
            raise ValueError(
                f"旧版升级等待期还需 {plan_status['remaining_days']} 天；"
                f"{plan_status['until']} 可创建新计划"
            )
        try:
            current_game_date = date.fromisoformat(game_date)
        except (TypeError, ValueError) as error:
            raise RuntimeError("无法读取当前游戏日期，不能提升俱乐部设施") from error
        with self._timed_user_memory_operation("owned_club_facility_plan"):
            with borrow_game_operation() as session:
                live_levels = read_native_club_facility_levels(
                    team_id, club.get("address"), reader=session.reader,
                )
            facility_field = facility_fields[facility]
            current_level = live_levels[facility]
            saved_floors = ownership.get("facility_level_floors")
            previous_floors = (
                dict(saved_floors) if isinstance(saved_floors, dict) else {}
            )
            if facility == "recruitment" and previous_floors.get("recruitment") is not None:
                try:
                    saved_floor = int(previous_floors["recruitment"])
                except (TypeError, ValueError) as error:
                    raise RuntimeError("已保存的青训招募最低等级无效") from error
                if not 1 <= saved_floor <= 20:
                    raise RuntimeError("已保存的青训招募最低等级无效")
                if current_level is not None and int(current_level) < saved_floor:
                    repaired = set_native_club_facility_level(
                        team_id, club.get("address"), "recruitment", saved_floor,
                        expected_level=int(current_level),
                    )
                    current_level = int(repaired["after"])
                    live_levels[facility] = current_level
        try:
            quote = owned_club_facility_upgrade_quote(
                current_level, requested_levels,
            )
        except ValueError:
            if current_level == 20:
                raise ValueError("该项俱乐部设施已经达到 20 级") from None
            raise
        saved_plans = ownership.get("facility_upgrade_plans")
        previous_plans = dict(saved_plans) if isinstance(saved_plans, dict) else {}
        if isinstance(previous_plans.get(facility), dict):
            raise ValueError("该项设施已有进行中的升级计划")
        saved_cooldowns = ownership.get("facility_upgrade_cooldowns")
        previous_cooldowns = (
            dict(saved_cooldowns) if isinstance(saved_cooldowns, dict) else {}
        )
        previous_plan = previous_plans.get(facility)
        previous_cooldown = previous_cooldowns.get(facility)
        reserved_plan = {
            "status": "active",
            "facility": facility,
            "start_level": int(quote["before"]),
            "target_level": int(quote["after"]),
            "total_levels": int(quote["levels"]),
            "completed_levels": 0,
            "started_on": current_game_date.isoformat(),
            "next_due_on": (
                current_game_date
                + timedelta(days=OWNED_CLUB_FACILITY_UPGRADE_DAYS)
            ).isoformat(),
            "quoted_price": int(quote["price"]),
        }
        ownership = update_acquired_club_map_entries(
            team_id, {
                "facility_upgrade_cooldowns": {facility: None},
                "facility_upgrade_plans": {facility: reserved_plan},
            }, _scope_id,
            expected_absent=(("facility_upgrade_plans", facility),),
        )
        try:
            payment = charge_combined_funds(
                local_purchase_price(quote["price"]), "world_club_facility_upgrade",
                team_id=team_id, team_name=str(club.get("name") or ""),
                facility=facility, facility_level=int(current_level),
                target_level=int(quote["after"]), levels=int(quote["levels"]),
                facility_upgrade_mode="scheduled_12_day",
            )
        except Exception:
            update_acquired_club_map_entries(
                team_id, {
                    "facility_upgrade_cooldowns": {facility: previous_cooldown},
                    "facility_upgrade_plans": {facility: previous_plan},
                }, _scope_id,
            )
            raise
        try:
            paid_plan = dict(reserved_plan)
            paid_plan.update({
                "paid_total": payment.get("total"),
                "payment_transaction_id": str(
                    payment.get("transaction_id") or payment.get("id") or ""
                ),
            })
            ownership = update_acquired_club_map_entries(
                team_id, {"facility_upgrade_plans": {facility: paid_plan}}, _scope_id,
            )
        except Exception:
            refund_combined_funds(
                payment, "world_club_facility_upgrade_rollback",
                team_id=team_id, team_name=str(club.get("name") or ""),
                facility=facility, facility_level=int(current_level),
                target_level=int(quote["after"]), levels=int(quote["levels"]),
            )
            update_acquired_club_map_entries(
                team_id, {
                    "facility_upgrade_cooldowns": {facility: previous_cooldown},
                    "facility_upgrade_plans": {facility: previous_plan},
                }, _scope_id,
            )
            raise
        plan = owned_club_facility_upgrade_cooldowns(
            ownership, game_date,
        )[facility]
        return {
            "native": None, "payment": payment,
            "plan": plan,
            "owned_actions_patch": {
                "facility_upgrade_plans": {facility: plan},
                "facility_upgrade_cooldowns": {facility: plan},
            },
        }

    def update_world_club_stadium(self, payload: dict[str, Any]) -> dict[str, Any]:
        team_id = int(payload.get("team_id") or 0)
        action = str(payload.get("action") or "").strip().lower()
        if action not in {
            "rename", "capacity", "expansion", "state",
            "pitch_type", "pitch_condition",
        }:
            raise ValueError("不支持该球场操作")
        scope_id, output, club = self._owned_world_club_target(team_id)
        ownership = next(
            (
                row for row in account_acquired_clubs(scope_id, output)
                if int(row.get("id") or 0) == team_id
            ),
            club,
        )
        with self.memory_lock:
            action_state = read_native_stadium_action_state(
                team_id, club.get("address"),
            )
        detail = {"club_information": action_state}
        stadium = action_state["stadium"]
        game_date = str(output.get("game_date") or "")
        quotes = owned_stadium_action_quotes(
            stadium, ownership=ownership, game_date=game_date,
        )
        native_kwargs: dict[str, Any]
        previous_cooldowns: dict[str, Any] | None = None
        if action == "rename":
            new_name = str(payload.get("name") or "").strip()
            price = int(quotes["rename_price"])
            native_kwargs = {
                "name": new_name, "expected_name": stadium.get("name"),
            }
        elif action == "pitch_type":
            try:
                current_pitch_type = int(stadium.get("pitch_type"))
                target_pitch_type = int(payload.get("pitch_type"))
            except (TypeError, ValueError) as error:
                raise ValueError("草皮类型无效") from error
            if target_pitch_type not in PITCH_TYPE_NAMES:
                raise ValueError("不支持该草皮类型")
            if target_pitch_type == current_pitch_type:
                raise ValueError("球场已经使用该草皮类型")
            price = int(quotes["pitch_type_price"])
            native_kwargs = {
                "pitch_type": target_pitch_type,
                "expected_pitch_type": current_pitch_type,
            }
        else:
            if action in {"capacity", "expansion"}:
                cooldown = quotes["cooldowns"][action]
                if cooldown["active"]:
                    label = "容量" if action == "capacity" else "扩建上限"
                    raise ValueError(
                        f"球场{label}扩建冷却中，还需 {cooldown['remaining_days']} 天；"
                        f"{cooldown['until']} 可再次扩建"
                    )
                try:
                    current_game_date = date.fromisoformat(game_date)
                except (TypeError, ValueError) as error:
                    raise RuntimeError("无法读取当前游戏日期，不能开始球场扩建") from error
            quote = quotes.get(action)
            if not quote:
                if action == "capacity":
                    raise ValueError("当前容量已达到扩建上限，请先提高扩建上限")
                if action == "expansion":
                    raise ValueError("球场扩建上限已经达到 500000")
                if action == "pitch_condition":
                    raise ValueError("草皮状况已经达到 200")
                raise ValueError("球场状态已经达到非常好")
            price = int(quote["price"])
            if action == "capacity":
                native_kwargs = {
                    "current_capacity": int(quote["after"]),
                    "expected_capacity": int(quote["before"]),
                    "expected_expansion_capacity": int(stadium["expansion_capacity"]),
                }
            elif action == "expansion":
                native_kwargs = {
                    "expansion_capacity": int(quote["after"]),
                    "expected_capacity": int(stadium["capacity"]),
                    "expected_expansion_capacity": int(quote["before"]),
                }
            elif action == "pitch_condition":
                native_kwargs = {
                    "pitch_condition": int(quote["after"]),
                    "expected_pitch_condition": int(quote["before"]),
                }
            else:
                native_kwargs = {
                    "state_raw": int(quote["after"]),
                    "expected_state_raw": int(quote["before"]),
                }
        if action in {"capacity", "expansion"}:
            saved_cooldowns = ownership.get("stadium_upgrade_cooldowns")
            previous_cooldowns = (
                dict(saved_cooldowns) if isinstance(saved_cooldowns, dict) else {}
            )
            reserved_cooldowns = dict(previous_cooldowns)
            reserved_cooldowns[action] = (
                current_game_date + timedelta(days=OWNED_STADIUM_UPGRADE_COOLDOWN_DAYS)
            ).isoformat()
            ownership = update_acquired_club(
                team_id, {"stadium_upgrade_cooldowns": reserved_cooldowns}, scope_id,
            )
        try:
            payment = charge_combined_funds(
                local_purchase_price(price), f"world_club_stadium_{action}",
                team_id=team_id, team_name=str(club.get("name") or ""),
                stadium_name=str(stadium.get("name") or ""), action=action,
                **({"new_stadium_name": new_name} if action == "rename" else {}),
            )
        except Exception:
            if previous_cooldowns is not None:
                update_acquired_club(
                    team_id, {"stadium_upgrade_cooldowns": previous_cooldowns}, scope_id,
                )
            raise
        try:
            with self.memory_lock:
                native_result = update_native_stadium(
                    team_id, club.get("address"), **native_kwargs,
                )
        except Exception:
            refund_combined_funds(
                payment, f"world_club_stadium_{action}_rollback",
                team_id=team_id, team_name=str(club.get("name") or ""),
                stadium_name=str(stadium.get("name") or ""), action=action,
            )
            if previous_cooldowns is not None:
                update_acquired_club(
                    team_id, {"stadium_upgrade_cooldowns": previous_cooldowns}, scope_id,
                )
            raise
        warning = None
        stadium.update(native_result["after"])
        if action == "rename":
            persisted_stadium_name = str(
                stadium.get("name") or new_name or ""
            ).rstrip()
            try:
                ownership = update_acquired_club(
                    team_id,
                    {"renamed_stadium_name": persisted_stadium_name},
                    scope_id,
                )
            except Exception as persistence_error:
                warning = (
                    "游戏内球场名称已修改，但名称持久化失败："
                    f"{persistence_error}"
                )
        if action == "state":
            state_quote = quotes["state"]
            stadium["state_name"] = state_quote["after_name"]
            stadium["state"] = (
                1 if int(state_quote["after"]) < 5
                else 2 if int(state_quote["after"]) < 11
                else 6 if int(state_quote["after"]) < 15
                else 11 if int(state_quote["after"]) < 20 else 16
            )
        elif action == "pitch_type":
            stadium["pitch_type_name"] = PITCH_TYPE_NAMES.get(
                int(stadium.get("pitch_type") or 0),
            )
        return {
            "native": native_result, "stadium": stadium, "payment": payment,
            "warning": warning,
            "owned_actions": public_purchase_quotes(
                owned_club_action_quotes(detail, ownership, game_date),
            ),
        }

    def acquire_world_club(self, payload: dict[str, Any]) -> dict[str, Any]:
        team_id = int(payload.get("team_id") or 0)
        if team_id <= 0:
            raise ValueError("俱乐部 ID 无效")
        submission_id = str(payload.get("client_submission_id") or "").strip()
        if len(submission_id) > 128:
            raise ValueError("提交标识无效")
        with self.lock:
            scope_id = self._bind_current_save()
            output = dict(self.output)
            locks = getattr(self, "_world_club_acquisition_locks", None)
            if locks is None:
                locks = {}
                self._world_club_acquisition_locks = locks
            operation_lock = locks.setdefault(
                (str(scope_id), team_id), threading.RLock(),
            )
        with operation_lock:
            with self.lock:
                current_scope_id = self._bind_current_save()
                if str(current_scope_id) != str(scope_id):
                    raise RuntimeError("等待收购期间存档已切换，请重新操作")
                output = dict(self.output)
                completed = getattr(
                    self, "_world_club_acquisition_results", None,
                )
                if completed is None:
                    completed = {}
                    self._world_club_acquisition_results = completed
                cache_key = (str(scope_id), submission_id)
                cached = completed.get(cache_key) if submission_id else None
                if cached is not None:
                    if int(cached.get("team_id") or 0) != team_id:
                        raise ValueError("提交标识已用于其他俱乐部")
                    return deepcopy(cached["result"])
            result = LocalOddsState._execute_world_club_acquisition(
                self,
                payload, scope_id, output,
            )
            if submission_id:
                with self.lock:
                    completed[cache_key] = {
                        "team_id": team_id, "result": deepcopy(result),
                    }
                    while len(completed) > 64:
                        completed.pop(next(iter(completed)))
            return result

    def _execute_world_club_acquisition(
        self, payload: dict[str, Any], scope_id: str,
        output: dict[str, Any],
    ) -> dict[str, Any]:
        save_id = str(output.get("save_instance_id") or self._data_scope_id(output))
        native_scan = self._world_club_native_cache(save_id)
        if not native_scan or not native_scan.get("addresses_current"):
            raise ValueError("请先扫描俱乐部，或重新扫描已失效的俱乐部地址")
        directory = merge_native_world_clubs(build_world_clubs(output), native_scan)
        team_id = int(payload.get("team_id") or 0)
        submission_id = str(payload.get("client_submission_id") or "").strip()
        club = next((row for row in directory["clubs"] if int(row.get("id") or 0) == team_id), None)
        if not club:
            raise ValueError("未找到目标俱乐部")
        acquired_before = account_acquired_clubs(
            scope_id, output, include_suspended=True,
        )
        existing = next((
            row for row in acquired_before
            if int(row.get("id") or 0) == team_id
        ), None)
        if existing:
            if (
                submission_id
                and str(existing.get("client_submission_id") or "") == submission_id
            ):
                return {
                    "club": existing, "payment": None, "native": {},
                    "acquired": acquired_before, "board_listens": None,
                    "warning": None, "replayed": True,
                }
            if existing.get("ownership_active") is False:
                raise ValueError(
                    f"该俱乐部的收购将在 {existing.get('ownership_suspended_until')} 恢复生效"
                )
            raise ValueError("该俱乐部已经收购")
        quote = read_native_world_club_acquisition_quote(club)
        valuation = quote.get("acquisition") or {}
        price = int(valuation.get("price") or 0)
        if price <= 0:
            raise RuntimeError("俱乐部收购价计算失败")
        payment = charge_combined_funds(
            price, "world_club_acquisition", team_id=team_id,
            team_name=str(club.get("name") or ""),
            game_date=str(output.get("game_date") or ""),
            client_submission_id=submission_id or None,
        )
        native_result = None
        warnings: list[str] = []
        owner_name = manager_display_name(output)
        manager_id, manager_address = manager_memory_identity(output)
        try:
            try:
                with self.memory_lock:
                    native_result = acquire_native_club(
                        team_id, club.get("address"), owner_name,
                        manager_id=manager_id,
                        manager_address=manager_address,
                    )
                if native_result.get("warning"):
                    warnings.append(str(native_result["warning"]))
            except Exception as native_error:
                warnings.append(f"游戏内控制人、主席国籍或财务附加效果未完成：{native_error}")
                native_result = {
                    "team_id": team_id,
                    "requested_owner_name": owner_name,
                    "native_effects_verified": False,
                    "native_effects_applied": False,
                    "applied_fields": [],
                    "sale_restore": {
                        "schema_version": 1,
                        "modified_fields": [],
                    },
                    "warning": warnings[-1],
                    "_rollback": {},
                }
            row = acquire_club({
                **club, "manager": "待读取",
                "acquired_game_date": str(output.get("game_date") or ""),
                "balance": native_result.get("balance_after"),
                "owner_name": native_result.get("requested_owner_name"),
                "owner_job_type": native_result.get("controller_job_type"),
                "owner_role": native_result.get("controller_role"),
                "controllers": native_result.get("controllers") or [],
                "acquisition_price": price,
                "acquisition_valuation": valuation,
                "acquisition_mode": (
                    native_result.get("acquisition_mode")
                    or (
                        "native_chairman_transfer"
                        if native_result.get("native_effects_applied")
                        else "portfolio_only"
                    )
                ),
                "sale_restore": native_result.get("sale_restore"),
                "client_submission_id": submission_id or None,
            }, scope_id)
        except Exception as error:
            rollback_error = None
            refund_error = None
            try:
                if native_result and native_result.get("_rollback"):
                    with self.memory_lock:
                        rollback_native_club_acquisition(native_result.get("_rollback") or {})
            except Exception as restore_error:
                rollback_error = restore_error
            try:
                refund_combined_funds(
                    payment, "world_club_acquisition_rollback",
                    team_id=team_id, team_name=str(club.get("name") or ""),
                )
            except Exception as restore_error:
                refund_error = restore_error
            if refund_error:
                raise RuntimeError(
                    f"收购失败且退款异常：{error}；{refund_error}"
                ) from error
            if rollback_error:
                raise RuntimeError(
                    f"收购失败且游戏内存回滚异常：{error}；{rollback_error}"
                ) from error
            if isinstance(error, (ValueError, RuntimeError)):
                raise
            raise RuntimeError(
                f"俱乐部收购写入失败（{type(error).__name__}）：{error}"
            ) from error
        if native_result.get("native_effects_verified"):
            self.acquired_status_enforced.add((
                save_id, team_id, str(output.get("game_date") or ""),
            ))
        try:
            with self.memory_lock:
                board_status = self._sync_owned_club_board_hook(output)
        except Exception as board_error:
            warnings.append(f"俱乐部已收购，但董事会解锁暂未启用：{board_error}")
            board_status = {
                "supported": True, "active": False, "error": str(board_error),
                "team_ids": [team_id],
            }
        try:
            acquired_rows = account_acquired_clubs(
                scope_id, output, include_suspended=True,
            )
        except Exception as load_error:
            warnings.append(f"俱乐部已收购，但持有列表刷新失败：{load_error}")
            acquired_rows = [row]
        result = {
            "club": row, "payment": payment,
            "native": {key: value for key, value in native_result.items() if key != "_rollback"},
            "acquired": acquired_rows,
            "board_listens": board_status,
            "warning": "；".join(dict.fromkeys(warnings)) or None,
        }
        return _attach_optional_response_snapshot(
            result, "economy", public_economy,
        )

    def claim_world_club_acquisition_rebalance(
        self, payload: dict[str, Any],
    ) -> dict[str, Any]:
        team_id = int(payload.get("team_id") or 0)
        if team_id <= 0:
            raise ValueError("俱乐部 ID 无效")
        with self.lock:
            scope_id = self._bind_current_save()
            output = dict(self.output)
            acquired = account_acquired_clubs(scope_id, output)
            row = next(
                (item for item in acquired if int(item.get("id") or 0) == team_id),
                None,
            )
            if not row:
                raise ValueError("该俱乐部尚未收购")
            quote = acquisition_rebalance_quote(row)
            if quote.get("status") == "claimed":
                return {
                    "team_id": team_id,
                    "already_claimed": True,
                    "compensation": quote,
                    "acquired": acquired,
                    "economy": public_economy(),
                }
            refund = int(quote.get("refund") or 0)
            if not quote.get("eligible") or refund <= 0:
                raise ValueError("该俱乐部没有可领取的旧估值差价")

            claimed_at = datetime.now().isoformat(timespec="seconds")
            record = {
                "id": ACQUISITION_REBALANCE_ID,
                "status": "claimed",
                "refund": int(quote.get("total_refund") or refund),
                "incremental_refund": refund,
                "prior_refund": int(quote.get("claimed_refund") or 0),
                "original_price": int(quote.get("original_price") or 0),
                "fair_price": int(quote.get("fair_price") or 0),
                "claimed_at": claimed_at,
                "claimed_game_date": str(output.get("game_date") or ""),
            }
            economy = adjust_bank_balance(
                refund, "world_club_acquisition_rebalance_refund",
                team_id=team_id, team_name=str(row.get("name") or ""),
                rebalance_id=ACQUISITION_REBALANCE_ID,
                original_price=record["original_price"],
                fair_price=record["fair_price"],
                game_date=record["claimed_game_date"],
            )
            try:
                updated = update_acquired_club(
                    team_id, {"acquisition_rebalance": record}, scope_id,
                )
            except Exception as error:
                rollback_error = None
                try:
                    adjust_bank_balance(
                        -refund, "world_club_acquisition_rebalance_rollback",
                        team_id=team_id, team_name=str(row.get("name") or ""),
                        rebalance_id=ACQUISITION_REBALANCE_ID,
                    )
                except Exception as restore_error:
                    rollback_error = restore_error
                if rollback_error:
                    raise RuntimeError(
                        f"补偿记录保存失败且银行回滚异常：{error}；{rollback_error}"
                    ) from error
                raise RuntimeError(f"补偿记录保存失败，款项已回滚：{error}") from error

            compensation = acquisition_rebalance_quote(updated)
            acquired = account_acquired_clubs(scope_id, output)
            return {
                "team_id": team_id,
                "already_claimed": False,
                "compensation": compensation,
                "acquired": acquired,
                "economy": economy,
            }

    def sell_world_club(self, payload: dict[str, Any]) -> dict[str, Any]:
        team_id = int(payload.get("team_id") or 0)
        with self.lock:
            scope_id = self._bind_current_save()
            output = dict(self.output)
        acquired_rows = account_acquired_clubs(
            scope_id, output, include_suspended=True,
        )
        acquired_row = next(
            (row for row in acquired_rows if int(row.get("id") or 0) == team_id),
            None,
        )
        if not acquired_row:
            raise ValueError("该俱乐部尚未收购")
        if acquired_row.get("ownership_active") is False:
            raise ValueError(
                f"该俱乐部因回档暂停生效，将在 "
                f"{acquired_row.get('ownership_suspended_until')} 自动恢复，当前不能出售"
            )
        active_facility_plans = acquired_row.get("facility_upgrade_plans")
        if isinstance(active_facility_plans, dict) and any(
            isinstance(plan, dict)
            and str(plan.get("status") or "active") == "active"
            for plan in active_facility_plans.values()
        ):
            raise ValueError("该俱乐部还有进行中的设施升级计划，完成后才能出售")

        club = dict(acquired_row)
        metrics = owned_club_record_sale_metrics(acquired_row)
        sale_price = owned_club_sale_price(metrics)
        valuation_source = "fmodd_record"
        restore_result: dict[str, Any] = {
            "restored": False, "skipped": True, "_rollback": {},
        }
        warnings: list[str] = []
        try:
            _scope_id, live_output, live_club = self._owned_world_club_target(
                team_id, quick_rebind=True,
            )
            output = live_output
            club = {**club, **live_club}
        except Exception as error:
            live_club = None
            warnings.append(f"游戏内俱乐部定位失败，已按 FMODD 持有记录出售：{error}")

        if live_club:
            try:
                with self.memory_lock:
                    live_metrics = read_native_world_club_metrics([club]).get(team_id, {})
                live_sale_price = owned_club_sale_price(live_metrics)
                if live_sale_price is not None:
                    metrics = live_metrics
                    sale_price = live_sale_price
                    valuation_source = "live"
            except Exception as error:
                warnings.append(f"游戏内估值读取失败，已使用 FMODD 估值记录：{error}")

        if sale_price is None:
            raise RuntimeError("FMODD 持有记录中没有可用于出售的估值")

        if live_club:
            try:
                with self.memory_lock:
                    restore_result = restore_native_club_after_sale(
                        team_id, club.get("address"),
                        acquired_row.get("sale_restore") or {},
                    )
            except Exception as error:
                restore_result = {
                    "restored": False, "skipped": True,
                    "reason": str(error), "_rollback": {},
                }
                warnings.append(
                    f"游戏内所有权或主席资料已变化，未覆盖新数据：{error}"
                )

        removed = False
        credited = False
        try:
            removed = remove_acquired_club(team_id, scope_id)
            if not removed:
                raise RuntimeError("俱乐部出售记录更新失败")
            forget_club_dividend_tracking(team_id)
            economy = adjust_bank_balance(
                sale_price, "world_club_sale",
                team_id=team_id, team_name=str(club.get("name") or ""),
                game_date=str(output.get("game_date") or ""),
                valuation=int(metrics.get("current_valuation") or 0),
                sale_percent=OWNED_CLUB_SALE_PERCENT,
                valuation_source=valuation_source,
            )
            credited = True
        except Exception:
            if credited:
                try:
                    adjust_bank_balance(
                        -sale_price, "world_club_sale_rollback",
                        team_id=team_id, team_name=str(club.get("name") or ""),
                    )
                except Exception:
                    pass
            if removed:
                try:
                    acquire_club(dict(acquired_row), scope_id)
                except Exception:
                    pass
            try:
                with self.memory_lock:
                    rollback_native_club_sale(restore_result.get("_rollback") or {})
            except Exception:
                pass
            raise

        save_id = str(output.get("save_instance_id") or self._data_scope_id(output))
        self.acquired_status_enforced = {
            key for key in self.acquired_status_enforced
            if len(key) < 2 or key[0] != save_id or key[1] != team_id
        }
        with self.lock:
            self.owned_world_club_addresses.pop(team_id, None)
        try:
            with self.memory_lock:
                board_status = self._sync_owned_club_board_hook(output)
        except Exception as error:
            board_status = {
                "supported": True, "active": False, "error": str(error),
            }
            warnings.append(f"俱乐部已出售，但董事会状态同步失败：{error}")
        return {
            "sold": True,
            "team_id": team_id,
            "sale_price": sale_price,
            "restoration": {
                key: value for key, value in restore_result.items() if key != "_rollback"
            },
            "acquired": account_acquired_clubs(
                scope_id, output, include_suspended=True,
            ),
            "economy": economy,
            "board_listens": board_status,
            "valuation_source": valuation_source,
            "warning": "；".join(dict.fromkeys(warnings)) or None,
        }

    def remove_world_club(self, payload: dict[str, Any]) -> dict[str, Any]:
        return self.sell_world_club(payload)

    def refresh_club_async(self) -> bool:
        with self.lock:
            timer = getattr(self, "club_prewarm_timer", None)
            if timer is not None:
                timer.cancel()
                self.club_prewarm_timer = None
            if self.club_refreshing:
                return False
            if self.refreshing and self.refresh_reason in {"startup", "startup_odds"}:
                # A cold startup odds rebuild can take several minutes on a
                # large save. Let the explicitly requested club read take the
                # memory lock first; resume the cancelled odds job afterwards.
                self.club_refresh_pending = True
                self.club_progress = 0
                self.club_progress_text = "正在优先读取当前经理和执教队伍"
                self.club_error = None
                cancel_event = getattr(self, "refresh_cancel_event", None)
                if cancel_event is not None:
                    self.deferred_memory_job_after_club = {
                        "kind": "refresh",
                        "reason": "startup_odds",
                        "full": True,
                        "cancel_on_clock_change": False,
                    }
                    self.refresh_cancel_reason = "club_priority"
                    cancel_event.set()
                return False
            manager = self.output.get("manager") or {}
            managed_teams = self.output.get("managed_teams") or []
            if not managed_teams and self.output.get("managed_team"):
                managed_teams = [self.output["managed_team"]]
            if not manager.get("id") or not managed_teams:
                raise ValueError("尚未识别当前经理和执教队伍")
            if (
                (self.refreshing or self.reconciling)
                and self.refresh_cancel_event is not None
                and (
                    self.refresh_reason in CLUB_DEFERRED_REFRESH_REASONS
                    or self.refresh_reason == "background_reconcile"
                )
            ):
                if self.refresh_reason == "background_reconcile":
                    self.deferred_memory_job_after_club = {
                        "kind": "reconcile",
                        "cancel_on_clock_change": bool(
                            self.refresh_cancel_on_clock_change
                        ),
                    }
                else:
                    self.deferred_memory_job_after_club = {
                        "kind": "refresh",
                        "reason": str(self.refresh_reason),
                        "full": self.refresh_mode == "full",
                        "cancel_on_clock_change": bool(
                            self.refresh_cancel_on_clock_change
                        ),
                    }
                self.refresh_cancel_reason = "club_priority"
                self.refresh_cancel_event.set()
            # A manual start may consume a request queued behind startup. Clear
            # the queue marker here so completion cannot remain permanently busy.
            self.club_refresh_pending = False
            self.club_refreshing = True
            self.club_refresh_generation = int(getattr(self, "club_refresh_generation", 0)) + 1
            self.club_loading_profiles = {}
            self.club_progress = 5
            self.club_progress_text = "正在确认当前经理和执教队伍"
            self.club_error = None
        threading.Thread(target=self._club_refresh_worker, daemon=True).start()
        return True

    @contextmanager
    def _club_memory_read_lock(self):
        acquired = self.memory_lock.acquire(blocking=False)
        if not acquired:
            with self.lock:
                self.club_progress = 1
                self.club_progress_text = "等待后台盘口核对释放内存读取"
            waited = 0
            while not self.memory_lock.acquire(timeout=2.0):
                waited += 2
                with self.lock:
                    self.club_progress_text = (
                        f"等待后台盘口核对释放内存读取（已等待 {waited} 秒）"
                    )
        try:
            with self.lock:
                self.club_progress = max(5, int(self.club_progress or 0))
                self.club_progress_text = "正在确认当前经理和执教队伍"
            yield
        finally:
            self.memory_lock.release()

    def _club_refresh_worker(self) -> None:
        try:
            with self._club_memory_read_lock():
                with self.lock:
                    manager = dict(self.output.get("manager") or {})
                    managed_teams = [dict(item) for item in (self.output.get("managed_teams") or [])]
                    if not managed_teams and self.output.get("managed_team"):
                        managed_teams = [dict(self.output["managed_team"])]
                    scope_id = self._data_scope_id(self.output)
                    career_id = str(self.output.get("save_instance_id") or "")
                    game_layout = str(self.output.get("game_layout") or "")
                    season_start = str(self.output.get("season_start") or "")
                    season_end = str(self.output.get("season_end") or "")
                    context_key = self._club_legacy_context_key()
                if not scope_id:
                    raise ValueError("尚未识别当前账户")
                set_active_save_id(scope_id)
                profiles = {}
                contexts = {}
                errors = []
                team_count = max(1, len(managed_teams))
                primary_id = int((next(
                    (item for item in managed_teams if item.get("team_type") == "club"),
                    managed_teams[0],
                )).get("id") or 0)
                for index, team in enumerate(managed_teams):
                    team_id = int(team["id"])
                    with self.lock:
                        self.club_progress = 12 + round(index / team_count * 76)
                        self.club_progress_text = f"正在扫描 {team.get('name') or team.get('id')} 的球员、职员和合同"

                    def publish_players(
                        partial: dict[str, Any], *, current_team: dict[str, Any] = team,
                        current_team_id: int = team_id, current_index: int = index,
                    ) -> None:
                        partial["team"]["team_type"] = current_team.get("team_type") or "club"
                        apply_player_aliases(partial, scope_id)
                        with self.lock:
                            if context_key != self._club_legacy_context_key():
                                return
                            self.club_loading_profiles[current_team_id] = partial
                            self.club_progress = 12 + round(
                                (current_index + 0.6) / team_count * 76
                            )
                            self.club_progress_text = (
                                f"已读取 {current_team.get('name') or current_team_id} 的球员，正在读取职员资料"
                            )
                    try:
                        profile = read_club_profile(
                            int(manager["id"]), int(team["id"]), force=True,
                            team_address=team.get("address"),
                            manager_address=team.get("manager_address") or manager.get("manager_address"),
                            partial_callback=publish_players,
                        )
                        profile["team"]["team_type"] = team.get("team_type") or "club"
                        apply_player_aliases(profile, scope_id)
                        profiles[team_id] = profile
                        contexts[team_id] = {
                            key: value for key, value in profile.items()
                            if key not in {"players", "squads", "staff"}
                        }
                        with self.lock:
                            self.club_progress = 12 + round((index + 1) / team_count * 76)
                    except Exception as error:
                        errors.append(f"{team.get('name') or team.get('id')}: {error}")
                if not profiles:
                    raise RuntimeError("；".join(errors) or "无法读取当前执教队伍")
                with self.lock:
                    self.club_progress = 94
                    self.club_progress_text = "正在整理队伍资料和治疗方案"
                game_date = str((read_game_clock() or {}).get("date") or self.output.get("game_date") or "")
                if game_date:
                    welfare_snapshot = welfare_status()
                    if (welfare_snapshot.get("treatments") or {}):
                        self._process_due_medical_treatments(
                            game_date, list(profiles.values()),
                        )
                    auto_treatment_result = self._apply_default_medical_treatments(
                        game_date, list(profiles.values()),
                    )
                    self.club_progress_text = "正在结算语言学习进度"
                    self._process_language_learning(
                        game_date, list(profiles.values()),
                        welfare_snapshot=welfare_snapshot,
                    )
                else:
                    auto_treatment_result = None
            self._sync_owned_club_customizations(
                self.output,
                is_current=lambda: context_key == self._club_legacy_context_key(),
            )
            legacy_job = {
                "key": context_key, "scope_id": scope_id, "career_id": career_id,
                "game_date": game_date, "game_layout": game_layout,
                "season_start": season_start, "season_end": season_end,
                "profiles": deepcopy(profiles),
            }
            with self.lock:
                if context_key != self._club_legacy_context_key():
                    self.club_loading_profiles = {}
                    self.club_progress_text = "存档上下文已变化，请刷新队伍"
                    return
                self.club_profiles = profiles
                self.club_contexts = contexts
                self.club_profile = profiles.get(primary_id) or next(iter(profiles.values()))
                self.club_context = contexts.get(primary_id) or next(iter(contexts.values()))
                self.club_last_updated = datetime.now().isoformat(timespec="seconds")
                self.club_error = "；".join(errors) if errors else None
                self.club_progress = 100
                self.club_progress_text = "读取完成"
                self.club_medical_auto_result = auto_treatment_result
                self.club_loading_profiles = {}
                if career_id:
                    self._club_legacy_refresh().enqueue(legacy_job)
            self._cache_club_funds_from_profiles(
                profiles, primary_id, scope_id=scope_id,
            )
            with self.lock:
                retry_training_settlement = bool(
                    getattr(self, "training_settlement_roster_retry_key", None)
                )
            if retry_training_settlement:
                self._request_training_settlement(game_date)
        except Exception as error:
            with self.lock:
                if "context_key" in locals() and context_key != self._club_legacy_context_key():
                    self.club_loading_profiles = {}
                    return
                if self.club_loading_profiles and not self.club_profiles:
                    self.club_profiles = dict(self.club_loading_profiles)
                    self.club_profile = (
                        self.club_profiles.get(primary_id)
                        if "primary_id" in locals() else None
                    ) or next(iter(self.club_profiles.values()))
                    self.club_last_updated = datetime.now().isoformat(timespec="seconds")
                self.club_loading_profiles = {}
                self.club_error = str(error)
                self.club_progress_text = "读取失败"
        finally:
            deferred_job = None
            with self.lock:
                self.club_refreshing = False
                deferred_job = getattr(
                    self, "deferred_memory_job_after_club", None,
                )
                self.deferred_memory_job_after_club = None
            try:
                if deferred_job:
                    if deferred_job.get("kind") == "reconcile":
                        self._start_reconcile(
                            cancel_on_clock_change=bool(
                                deferred_job.get("cancel_on_clock_change")
                            ),
                        )
                    else:
                        self.refresh_async(
                            str(deferred_job.get("reason") or "game_clock_stable"),
                            full=bool(deferred_job.get("full")),
                            cancel_on_clock_change=bool(
                                deferred_job.get("cancel_on_clock_change")
                            ),
                        )
            finally:
                # Team readiness and deferred odds work no longer wait for archives.
                self._club_legacy_refresh().drain()

    def place_bet(self, payload: dict[str, Any]) -> dict[str, Any]:
        stake_minor = to_minor(payload.get("stake", 0))
        stake = from_minor(stake_minor)
        mode = str(payload.get("mode", "single"))
        selections = payload.get("selections")
        client_submission_id = str(payload.get("client_submission_id") or "").strip()
        if len(client_submission_id) > 128:
            raise ValueError("下注提交标识无效")
        if mode not in {"single", "parlay", "system_parlay"} or not isinstance(selections, list) or not selections:
            raise ValueError("投注单为空")
        if not math.isfinite(stake) or stake <= 0:
            raise ValueError("注额必须大于 0")
        if mode == "parlay" and len(selections) < 2:
            raise ValueError("串关至少需要两项选择")
        if mode == "parlay":
            match_keys = [(
                str(item.get("fixture_date")),
                int(item.get("competition_id")),
                int(item.get("home_id")),
                int(item.get("away_id")),
            ) for item in selections]
            if len(match_keys) != len(set(match_keys)):
                raise ValueError("同一场比赛不能加入串关两次")

        selection_groups: list[list[dict[str, Any]]] = []
        if mode == "parlay":
            selection_groups = [[item] for item in selections]
        elif mode == "system_parlay":
            grouped: dict[tuple[str, int, int, int], list[dict[str, Any]]] = {}
            for item in selections:
                key = (
                    str(item.get("fixture_date")), int(item.get("competition_id")),
                    int(item.get("home_id")), int(item.get("away_id")),
                )
                grouped.setdefault(key, []).append(item)
            selection_groups = list(grouped.values())
            if len(selection_groups) < 2:
                raise ValueError("复式串关至少需要两场比赛")
            for group in selection_groups:
                reference = group[0]
                for item in group[1:]:
                    same_market = str(item.get("market")) == str(reference.get("market"))
                    same_line = str(reference.get("market")) not in {"AH", "OU", "TEAM_OU", "HT_AH", "HT_OU", "SH_AH", "SH_OU"} or float(item.get("line")) == float(reference.get("line"))
                    if not same_market or not same_line:
                        raise ValueError("同一场复式选择必须属于同一个盘口组")

        if mode in {"parlay", "system_parlay"}:
            matchup_dates: dict[tuple[int, int, int], list[date]] = {}
            for group in selection_groups:
                item = group[0]
                matchup = (
                    int(item.get("competition_id")), int(item.get("home_id")),
                    int(item.get("away_id")),
                )
                try:
                    fixture_day = date.fromisoformat(str(item.get("fixture_date")))
                except ValueError as error:
                    raise ValueError("比赛日期无效，请刷新盘口") from error
                if any(abs((fixture_day - other).days) <= 1 for other in matchup_dates.get(matchup, [])):
                    raise ValueError("检测到重复赛程，同一场比赛不能互相串关，请刷新盘口")
                matchup_dates.setdefault(matchup, []).append(fixture_day)

        if mode in {"parlay", "system_parlay"} and len(selection_groups) > 10:
            raise ValueError("串关和复式最多选择 10 场比赛")

        with self.lock:
            if not self.cache_verified:
                raise ValueError("当前盘口缓存尚未验证，请刷新盘口后再下注")
            if self.save_change_pending:
                raise ValueError("检测到存档变化，请先在设置中点击“更换存档刷新”")
            self._assert_betting_ready()
            # A background reconcile builds the next snapshot separately. Keep
            # accepting bets against the current verified snapshot during both
            # refresh and reconcile; the replacement is published atomically.
            output = self.output
            source_path = self.output_path
            repriced = validate_bet_snapshot(
                payload, str(output.get("save_instance_id") or ""), self.data_version,
            )
            accepted_data_version = self.data_version
            confirmed_game_clock = (
                dict(self.last_connection_clock)
                if self.last_connection_clock else None
            )

        pass_code = None
        pass_sizes: tuple[int, ...] = ()
        pass_combinations: list[tuple[int, ...]] = []
        if mode in {"parlay", "system_parlay"}:
            match_count = len(selection_groups)
            try:
                pass_code, pass_sizes = pass_leg_sizes(match_count, payload.get("pass_code"))
            except (TypeError, ValueError) as error:
                raise ValueError("过关方式无效") from error
            pass_combinations = pass_subsets(match_count, pass_sizes)
            combination_count = sum(
                math.prod(len(selection_groups[index]) for index in subset)
                for subset in pass_combinations
            )
            if combination_count > MAX_PARLAY_COMBINATIONS:
                raise ValueError(f"串关最多支持 {MAX_PARLAY_COMBINATIONS} 注组合")

        if not output:
            raise ValueError("尚未读取到盘口")
        set_active_save_id(self._data_scope_id(output))
        intelligence_unlocked_fixture_keys = (
            match_intelligence_betting_unlocked_fixture_keys()
        )
        engine_restricted_selections = match_engine_restricted_legs(
            selections, intelligence_unlocked_fixture_keys,
        )
        game_clock = read_game_clock()
        god_mode = bool(load_settings().get("god_mode"))
        engine_state = (
            {
                "known": False,
                "active": False,
                "spectator": False,
                "reason": "god_mode",
            }
            if god_mode else read_betting_match_engine_state()
        )
        betting_restrictions = self._note_betting_match_engine_state(
            game_clock,
            engine_state,
            save_instance_id=str(output.get("save_instance_id") or ""),
        )
        validate_betting_clock_sync(
            confirmed_game_clock,
            game_clock,
            block_on_mismatch=bool(
                engine_restricted_selections
                and (
                    betting_restrictions["spectator_day"]
                    or betting_restrictions["current_time"]
                )
            ),
        )
        match_index = {
            (
                str(match["fixture_date"]),
                int(match["competition_id"]),
                int(match["home"]["id"]),
                int(match["away"]["id"]),
            ): match
            for match in output.get("matches", [])
        }
        score_matrix_cache: dict[tuple[float, float], list[list[float]]] = {}
        if mode in {"parlay", "system_parlay"}:
            validated_groups = [
                [
                    self._validated_leg(
                        output,
                        item,
                        game_clock,
                        match_index=match_index,
                        score_matrix_cache=score_matrix_cache,
                    )
                    for item in group
                ]
                for group in selection_groups
            ]
            legs = [leg for group in validated_groups for leg in group]
        else:
            validated_groups = []
            legs = [
                self._validated_leg(
                    output,
                    item,
                    game_clock,
                    match_index=match_index,
                    score_matrix_cache=score_matrix_cache,
                )
                for item in selections
            ]
        guarded_legs = match_engine_restricted_legs(
            legs, intelligence_unlocked_fixture_keys,
        )
        validate_permanent_spectator_locks(
            guarded_legs,
            getattr(self, "spectator_betting_locks", set()),
        )
        if betting_restrictions["spectator_day"]:
            validate_spectator_bet_times(
                game_clock, guarded_legs,
            )
        elif betting_restrictions["current_time"]:
            validate_active_match_bet_times(game_clock, guarded_legs)
        betting_settings = load_settings()
        custom_limits_enabled = bool(betting_settings.get("betting_limits_enabled"))
        unlimited_betting = custom_limits_enabled and bool(betting_settings.get("unlimited_betting"))
        single_profit_limit = float(betting_settings.get("betting_limit_single", SINGLE_MAX_PROFIT)) if custom_limits_enabled else float(betting_settings.get("default_betting_limit_single", SINGLE_MAX_PROFIT))
        parlay_profit_limit = float(betting_settings.get("betting_limit_parlay", PARLAY_MAX_PROFIT)) if custom_limits_enabled else float(betting_settings.get("default_betting_limit_parlay", PARLAY_MAX_PROFIT))
        if mode in {"parlay", "system_parlay"}:
            group_maximum_odds = [max(float(leg["odds"]) for leg in group) for group in validated_groups]
            maximum_combination_odds = max(
                math.prod(group_maximum_odds[index] for index in subset)
                for subset in pass_combinations
            )
            if not unlimited_betting:
                assert_bet_profit_limit("parlay", stake, maximum_combination_odds, parlay_profit_limit)
        elif not unlimited_betting:
            for leg in legs:
                assert_bet_profit_limit("single", stake, float(leg["odds"]), single_profit_limit)
        if not load_settings().get("disable_fa_penalties"):
            assert_integrity_bets_allowed(legs, output)
        validate_bet_times(game_clock, legs)
        game_date = game_clock["date"]
        game_datetime = f"{game_clock['date']} {game_clock['time']}"
        base = {
            "bet_id": str(uuid.uuid4()),
            "client_submission_id": client_submission_id or None,
            "placed_at": game_date,
            "placed_at_game": game_datetime,
            "recorded_at": datetime.now().isoformat(timespec="seconds"),
            "model_version": output.get("model_version"),
            "game_date": game_date,
            "stake": stake,
            "integrity_manager_name": manager_display_name(output),
            "integrity_weekly_salary": self._total_weekly_salary(self.club_contexts),
            "source_snapshot": str(source_path) if source_path else None,
            "status": "pending",
        }
        if mode == "parlay" and pass_sizes == (len(validated_groups),):
            combined = math.prod(float(leg["odds"]) for leg in legs)
            if not math.isfinite(combined):
                raise ValueError("串关赔率或预计派彩超出程序可处理范围")
            potential_return_minor = multiply_minor(stake_minor, combined)
            records = [{
                **base,
                "type": "parlay",
                "odds": round(combined, 2),
                "potential_return": from_minor(potential_return_minor),
                "potential_profit": from_minor(
                    potential_return_minor - stake_minor,
                ),
                "legs": legs,
                "match_count": len(validated_groups),
                "pass_code": pass_code,
                "pass_sizes": list(pass_sizes),
            }]
            total_stake = stake
        elif mode in {"parlay", "system_parlay"}:
            group_maximum_odds = [max(float(leg["odds"]) for leg in group) for group in validated_groups]
            combination_count = sum(
                math.prod(len(validated_groups[index]) for index in subset)
                for subset in pass_combinations
            )
            total_stake_minor = stake_minor * combination_count
            total_stake = from_minor(total_stake_minor)
            potential_return_minor = multiply_minor(
                stake_minor,
                sum(
                    math.prod(group_maximum_odds[index] for index in subset)
                    for subset in pass_combinations
                ),
            )
            potential_return = from_minor(potential_return_minor)
            records = [{
                **base,
                "type": "system_parlay",
                "selection_mode": "system" if mode == "system_parlay" else "parlay",
                "stake": total_stake,
                "unit_stake": stake,
                "combination_count": combination_count,
                "system_shape": [len(group) for group in validated_groups],
                "match_count": len(validated_groups),
                "pass_code": pass_code,
                "pass_sizes": list(pass_sizes),
                "potential_return": potential_return,
                "potential_profit": from_minor(
                    potential_return_minor - total_stake_minor,
                ),
                "legs": legs,
                "groups": [{"selections": group} for group in validated_groups],
            }]
        else:
            records = [{
                **base,
                "bet_id": str(uuid.uuid4()),
                "type": "single",
                "potential_return": from_minor(
                    multiply_minor(stake_minor, leg["odds"]),
                ),
                "potential_profit": from_minor(
                    multiply_minor(stake_minor, leg["odds"]) - stake_minor,
                ),
                **leg,
            } for leg in legs]
            total_stake = from_minor(stake_minor * len(records))
        wallet = reserve_bets(
            records, total_stake,
            single_profit_limit=None if unlimited_betting else single_profit_limit,
        )
        accepted_records = wallet.get("reserved_bets") or records
        return {
            "records": len(accepted_records),
            "balance": float(wallet["balance"]),
            "bets": accepted_records,
            "duplicate": bool(wallet.get("already_reserved")),
            "repriced": repriced,
            "data_version": accepted_data_version,
        }

    def place_championship_bet(self, payload: dict[str, Any]) -> dict[str, Any]:
        if not bool(load_settings().get("championship_enabled", True)):
            raise ValueError("冠军盘已在设置中关闭")
        try:
            stake_minor = to_minor(payload.get("stake") or 0)
            stake = from_minor(stake_minor)
        except (TypeError, ValueError) as error:
            raise ValueError("冠军盘投注参数无效") from error
        if stake_minor <= 0:
            raise ValueError("注额必须大于 0")
        client_submission_id = str(payload.get("client_submission_id") or "").strip()
        if len(client_submission_id) > 128:
            raise ValueError("下注提交标识无效")
        raw_selections = payload.get("selections")
        if raw_selections is None:
            raw_selections = [payload]
        if not isinstance(raw_selections, list) or not raw_selections or len(raw_selections) > 64:
            raise ValueError("冠军盘选择数量无效")
        selections = []
        identities = set()
        try:
            for item in raw_selections:
                if not isinstance(item, dict):
                    raise ValueError
                selection = {
                    "competition_id": int(item.get("competition_id") or 0),
                    "team_id": int(item.get("team_id") or 0),
                    "quoted_odds": float(item.get("odds") or 0),
                    "market_version": str(item.get("market_version") or ""),
                }
                identity = (selection["competition_id"], selection["team_id"])
                if not all(identity) or identity in identities:
                    raise ValueError
                if not math.isfinite(selection["quoted_odds"]) or selection["quoted_odds"] <= 1:
                    raise ValueError
                identities.add(identity)
                selections.append(selection)
        except (TypeError, ValueError) as error:
            raise ValueError("冠军盘选择或赔率无效，请刷新后重试") from error

        with self.lock:
            if not self.cache_verified or not self._has_verified_save():
                raise ValueError("当前盘口缓存尚未验证，请刷新盘口后再下注")
            if self.save_change_pending:
                raise ValueError("检测到存档变化，请先在设置中点击“更换存档刷新”")
            self._assert_betting_ready()
            set_active_save_id(self._data_scope_id(self.output))
            markets = published_championship_markets(self.output)
            if not markets:
                raise ValueError("冠军盘快照尚未发布，请刷新盘口后再下注")
            market_map = {
                int(item.get("competition_id") or 0): item
                for item in markets.get("competitions") or []
                if item.get("status") == "open"
            }
            validated = []
            repriced = False
            for selection in selections:
                competition = market_map.get(selection["competition_id"])
                if not competition:
                    raise ValueError("该赛事冠军盘当前未开放")
                team = next((
                    item for item in competition.get("teams") or []
                    if int(item.get("team_id") or 0) == selection["team_id"]
                ), None)
                current_odds = float((team or {}).get("odds") or 0)
                if not team or not math.isfinite(current_odds) or current_odds <= 1:
                    raise ValueError("冠军盘选择或赔率已经变化，请刷新后重试")
                if (
                    selection["market_version"] != str(competition.get("market_version") or "")
                    or abs(current_odds - selection["quoted_odds"]) > 0.001
                ):
                    repriced = True
                validated.append((competition, team, current_odds))
            source_path = self.output_path
            accepted_data_version = self.data_version
            output = self.output

        settings = load_settings()
        custom_limits_enabled = bool(settings.get("betting_limits_enabled"))
        unlimited_betting = custom_limits_enabled and bool(settings.get("unlimited_betting"))
        single_profit_limit = float(
            settings.get("betting_limit_single", SINGLE_MAX_PROFIT)
            if custom_limits_enabled else
            settings.get("default_betting_limit_single", SINGLE_MAX_PROFIT)
        )
        if not unlimited_betting:
            for _competition, _team, quoted_odds in validated:
                assert_bet_profit_limit("single", stake, quoted_odds, single_profit_limit)
        game_clock = read_game_clock()
        game_date = str(game_clock.get("date") or output.get("game_date") or "")
        recorded_at = datetime.now().isoformat(timespec="seconds")
        manager_name = manager_display_name(output)
        weekly_salary = self._total_weekly_salary(self.club_contexts)
        records = []
        for competition, team, quoted_odds in validated:
            cup_market = str(competition.get("market_kind") or "") == "cup"
            settlement_date = str(
                competition.get("settlement_date")
                or ("" if cup_market else competition.get("season_end") or "")
            )
            team_id = int(team["team_id"])
            potential_return_minor = multiply_minor(stake_minor, quoted_odds)
            records.append({
                "bet_id": str(uuid.uuid4()), "type": "championship",
                "client_submission_id": client_submission_id or None,
                "market": "CHAMPION", "status": "pending",
                "placed_at": game_date,
                "placed_at_game": f"{game_date} {game_clock.get('time') or '00:00'}",
                "recorded_at": recorded_at, "game_date": game_date,
                "fixture_date": settlement_date, "kickoff_time": None,
                "competition_id": int(competition["competition_id"]),
                "competition_name": str(competition["competition_name"]),
                "season_key": str(competition["season_key"]),
                "season_label": str(competition["season_label"]),
                "season_start": str(competition["season_start"]),
                "season_end": str(competition["season_end"]),
                "settlement_date": settlement_date,
                "market_kind": str(competition.get("market_kind") or "league"),
                "market_version": str(competition["market_version"]),
                "model_version": str(
                    markets.get("model_version") or CHAMPIONSHIP_MODEL_VERSION
                ),
                "team_id": team_id, "team_name": str(team["team_name"]),
                "home_id": team_id, "away_id": 0,
                "home": str(team["team_name"]), "away": "赛事冠军",
                "selection": str(team["team_name"]),
                "selection_code": str(team_id),
                "odds": round(quoted_odds, 2), "stake": stake,
                "potential_return": from_minor(potential_return_minor),
                "potential_profit": from_minor(
                    potential_return_minor - stake_minor,
                ),
                "source_snapshot": str(source_path) if source_path else None,
                "integrity_manager_name": manager_name,
                "integrity_weekly_salary": weekly_salary,
            })
        wallet = reserve_bets(records, from_minor(stake_minor * len(records)))
        accepted_records = wallet.get("reserved_bets") or records
        return {
            "records": len(accepted_records),
            "balance": float(wallet["balance"]),
            "bets": accepted_records,
            "duplicate": bool(wallet.get("already_reserved")),
            "repriced": repriced,
            "data_version": accepted_data_version,
        }

    def manual_refund_options(self) -> dict[str, Any]:
        with self.lock:
            self._bind_current_save()
            game_clock = read_game_clock()
            return manual_refund_options(
                str(game_clock.get("date") or ""),
                int(game_clock.get("minutes") or 0),
                championship_refund_settlement_dates(
                    published_championship_markets(self.output)
                ),
                refund_settlement_fixture_kickoffs(self.output),
            )

    def search_pending_bet_result(self, payload: dict[str, Any]) -> dict[str, Any]:
        bet_id = str(payload.get("bet_id") or "").strip()
        if not bet_id:
            raise ValueError("请选择需要搜索赛果的注单")
        with self.lock:
            self._bind_current_save()
            if self.refreshing or self.reconciling or self.save_change_pending:
                raise ValueError("当前正在刷新数据，请稍后再搜索赛果")
            output = dict(self.output)
        clock = read_game_clock()
        game_date = str(clock.get("date") or output.get("game_date") or "")
        request = pending_bet_result_search(bet_id, game_date)
        required_keys = set(request["keys"])
        fixture_hints = pending_result_fixture_hints(required_keys)
        with self._timed_memory_lock("manual_result_search"):
            result_kwargs = {}
            if str(output.get("game_layout") or "") == "fm24":
                result_kwargs = {
                    "preferred_save_id": str(output.get("save_instance_id") or "") or None,
                    "preferred_manager_id": _selected_manager_identity(output) or None,
                    "known_manager_sessions": list(output.get("manager_options") or []),
                }
            recovered = read_completed_results(
                required_keys, fixture_hints=fixture_hints,
                deep_recovery=True,
                **result_kwargs,
            )
        matched_by_key = {
            key: item
            for item in result_payload(output)
            if (key := self._live_result_key(item)) in required_keys
        }
        for item in recovered:
            required_key = recovered_result_required_key(item, required_keys)
            if required_key is None:
                continue
            previous = matched_by_key.get(required_key)
            if previous is not None:
                item = {**previous, **item}
                for field in (
                    "half_home_goals", "half_away_goals",
                    "first_scoring_team", "advanced_team_id", "decided_by",
                ):
                    if item.get(field) is None and previous.get(field) is not None:
                        item[field] = previous[field]
            matched_by_key[required_key] = item
        matched = list(matched_by_key.values())

        missing_details_by_key: dict[tuple[Any, ...], dict[str, Any]] = {}
        for entry in request.get("legs") or []:
            key = tuple(entry.get("key") or ())
            leg = entry.get("leg") or {}
            result = matched_by_key.get(key)
            if result is None:
                continue
            fields = missing_result_detail_fields(leg, result)
            if not fields:
                continue
            issue_key = (*key, *fields)
            issue = missing_details_by_key.setdefault(issue_key, {
                "date": str(key[0]),
                "competition_id": int(key[1]),
                "home_id": int(key[2]),
                "away_id": int(key[3]),
                "home": str((result.get("home_team") or {}).get("name") or leg.get("home") or key[2]),
                "away": str((result.get("away_team") or {}).get("name") or leg.get("away") or key[3]),
                "score": f"{int(result.get('home_goals') or 0)}-{int(result.get('away_goals') or 0)}",
                "missing_fields": list(fields),
                "markets": [],
                "selections": [],
                "result_source": str(result.get("result_source") or ""),
            })
            market = str(leg.get("market") or "")
            selection = str(leg.get("selection") or "")
            if market and market not in issue["markets"]:
                issue["markets"].append(market)
            if selection and selection not in issue["selections"]:
                issue["selections"].append(selection)
        missing_details = list(missing_details_by_key.values())
        missing_detail_message = ""
        if missing_details:
            first_issue = missing_details[0]
            if first_issue.get("missing_fields") == ["半场比分"]:
                missing_detail_message = (
                    f"{first_issue['home']} VS {first_issue['away']}比赛只有全场比分，"
                    "没有半场比分，请确认开启了对应赛事的细节。"
                )
            else:
                missing_detail_message = (
                    f"{first_issue['home']} VS {first_issue['away']}比赛只有全场赛果，"
                    f"缺少{'、'.join(first_issue.get('missing_fields') or ['结算明细'])}，"
                    "请确认开启了对应赛事的细节。"
                )
            if len(missing_details) > 1:
                missing_detail_message += f"另有 {len(missing_details) - 1} 场存在相同问题。"

        trusted_keys = {self._live_result_key(item) for item in matched}
        settlement = settle_pending_bets(
            matched, game_date,
            game_minutes=int(clock.get("minutes") or 0),
            trusted_same_day_keys=trusted_keys,
            void_missing_after_timeout=True,
        )
        self._finalize_settlement(settlement, output)
        updated, added = self._merge_light_results(output, matched)
        with self.lock:
            self.output = updated
            if added:
                self.data_version += 1
        settled_ids = {
            str(item.get("bet_id") or "")
            for item in settlement.get("settled_records") or []
        }
        found_keys = {
            required_key
            for item in matched
            if (required_key := recovered_result_required_key(
                item, required_keys,
            )) is not None
        }
        result = {
            "bet_id": bet_id,
            "found": len(found_keys),
            "settled": int(settlement.get("settled") or 0),
            "target_settled": bet_id in settled_ids,
            "remaining": (
                0 if bet_id in settled_ids else len(required_keys - found_keys)
            ),
            "returned": float(settlement.get("returned") or 0.0),
            "missing_details": missing_details,
            "message": (
                "连续3个游戏日未找到赛果，相关场次已走水并完成结算"
                if bet_id in settled_ids and not found_keys else
                f"{missing_detail_message}相关选项已按规则走水并完成结算"
                if bet_id in settled_ids and missing_details else
                "已找到赛果并完成结算"
                if bet_id in settled_ids else
                f"{missing_detail_message}可选择手动退款"
                if missing_details else
                "已找到比赛结果，但该盘口所需赛果细节仍不完整"
                if required_keys <= found_keys else
                "已找到部分赛果，注单仍需等待其他场次"
            ),
        }
        _attach_optional_response_snapshot(result, "bets", public_bet_history)
        _attach_optional_response_snapshot(result, "economy", public_economy)
        return result

    def manual_refund_bets(self, payload: dict[str, Any]) -> dict[str, Any]:
        values = payload.get("bet_ids")
        if not isinstance(values, list):
            raise ValueError("请选择需要退款的订单")
        with self.lock:
            self._bind_current_save()
            game_clock = read_game_clock()
            result = manual_refund_pending_bets(
                {str(value) for value in values},
                str(game_clock.get("date") or ""),
                int(game_clock.get("minutes") or 0),
                championship_refund_settlement_dates(
                    published_championship_markets(self.output)
                ),
                refund_settlement_fixture_kickoffs(self.output),
            )
        _attach_optional_response_snapshot(result, "bets", public_bet_history)
        _attach_optional_response_snapshot(result, "economy", public_economy)
        return result

