    def _managed_league_points_target(
        self, team_id: int = 0, competition_id: int = 0,
    ) -> tuple[dict[str, Any], dict[str, Any]]:
        managed_clubs = [
            row for row in managed_team_rows(self.output)
            if str(row.get("team_type") or "club") == "club"
            and int(row.get("id") or 0) > 0
        ]
        if team_id:
            managed_clubs = [
                row for row in managed_clubs
                if int(row.get("id") or 0) == int(team_id)
            ]
        if not managed_clubs:
            raise ValueError("当前经理没有可用的执教俱乐部")
        managed_ids = {int(row["id"]) for row in managed_clubs}
        candidates: list[tuple[dict[str, Any], dict[str, Any]]] = []
        for competition in public_league_standings(self.output).get("competitions", []):
            if competition_id and int(competition.get("competition_id") or 0) != competition_id:
                continue
            for team in competition.get("teams") or []:
                if (
                    int(team.get("team_id") or 0) in managed_ids
                    and team.get("native_standing_address")
                ):
                    candidates.append((competition, team))
        if not candidates:
            raise ValueError("当前玩家球队不在可写入的联赛积分榜中，请刷新赔率后重试")
        if len(candidates) > 1:
            raise ValueError("当前玩家球队对应多个可写入的联赛积分榜，无法自动确定使用对象")
        competition, team = candidates[0]
        return competition, team

    def inventory_use_league_points(self, payload: dict[str, Any]) -> dict[str, Any]:
        item_ids = [
            str(value) for value in
            (payload.get("item_ids") or [payload.get("item_id")]) if value
        ]
        if not item_ids or len(item_ids) > 99 or len(item_ids) != len(set(item_ids)):
            raise ValueError("批量使用的积分道具数据无效")
        with self.memory_lock:
            with self.lock:
                self._bind_current_save()
                inventory = public_economy().get("inventory", [])
                selected = [row for row in inventory if row.get("id") in item_ids]
                if (
                    len(selected) != len(item_ids)
                    or any(
                        row.get("sku") != "league_point_plus_one"
                        or row.get("status") != "available"
                        for row in selected
                    )
                ):
                    raise ValueError("部分联赛积分道具已经使用或不存在")
                competition, team = self._managed_league_points_target(
                    int(payload.get("team_id") or 0),
                    int(payload.get("competition_id") or 0),
                )
                quantity = len(item_ids)
                operation_hash = hashlib.sha256(
                    "\n".join(sorted(item_ids)).encode("utf-8")
                ).hexdigest()
                standings = add_points_adjustment(self.output, {
                    "competition_id": int(competition["competition_id"]),
                    "team_id": int(team["team_id"]),
                    "delta": quantity,
                    "reason": "联赛积分道具",
                    "source_id": f"league_points_item:{operation_hash}",
                })
                economy = consume_instant_items(
                    item_ids, "league_point_plus_one",
                    team_id=int(team["team_id"]),
                    team_name=str(team.get("team_name") or ""),
                    competition_id=int(competition["competition_id"]),
                    competition_name=str(competition.get("competition_name") or ""),
                    points_added=quantity,
                )
        return {
            "economy": economy,
            "league_standings": standings,
            "league_points": {
                "team_id": int(team["team_id"]),
                "team_name": str(team.get("team_name") or team["team_id"]),
                "competition_id": int(competition["competition_id"]),
                "competition_name": str(
                    competition.get("competition_name") or competition["competition_id"]
                ),
                "added": quantity,
            },
        }

    def _reputation_club_targets(self) -> dict[str, Any]:
        output = self.output
        targets: dict[int, dict[str, Any]] = {}
        for team in managed_team_rows(output):
            team_id = int(team.get("id") or 0)
            if (
                team_id <= 0 or not team.get("address")
                or str(team.get("team_type") or "club") == "national"
            ):
                continue
            targets[team_id] = {
                "id": team_id, "name": str(team.get("name") or team_id),
                "address": team.get("address"), "source": "managed",
                "reputation": team.get("reputation"),
            }
        acquired_ids = {
            int(row.get("id") or 0)
            for row in account_acquired_clubs(self._data_scope_id(output), output)
            if int(row.get("id") or 0) > 0
        }
        save_id = str(output.get("save_instance_id") or self._data_scope_id(output))
        native = self._world_club_native_cache(save_id)
        current_native = bool(native and native.get("addresses_current"))
        owned_addresses = self._owned_world_club_address_overrides(save_id)
        native_by_id = {
            int(row.get("id") or 0): row
            for row in (native or {}).get("clubs", [])
            if int(row.get("id") or 0) > 0
        }
        for team_id in acquired_ids:
            if team_id in targets:
                continue
            row = native_by_id.get(team_id)
            address = (
                row.get("address") if current_native and row
                else owned_addresses.get(team_id)
            )
            if not address:
                continue
            targets[team_id] = {
                "id": team_id,
                "name": str((row or {}).get("name") or team_id),
                "address": address, "source": "acquired",
                "reputation": (row or {}).get("reputation"),
            }
        resolved_acquired = sum(1 for team_id in acquired_ids if team_id in targets)
        return {
            "clubs": list(targets.values()),
            "unavailable_acquired_count": max(0, len(acquired_ids) - resolved_acquired),
        }

    def _reputation_player_targets(self) -> tuple[list[dict[str, Any]], bool]:
        managed_club_ids = {
            int(team.get("id") or 0)
            for team in managed_team_rows(self.output)
            if (
                int(team.get("id") or 0) > 0
                and str(team.get("team_type") or "club") != "national"
            )
        }
        visible_profiles = dict(self.club_profiles)
        if self.club_refreshing:
            visible_profiles.update(self.club_loading_profiles)
        if not visible_profiles and self.club_profile:
            team_id = int((self.club_profile.get("team") or {}).get("id") or 0)
            if team_id > 0:
                visible_profiles[team_id] = self.club_profile
        targets: dict[int, dict[str, Any]] = {}
        ready = False
        for profile in visible_profiles.values():
            team = profile.get("team") or {}
            team_id = int(team.get("id") or 0)
            if (
                team_id not in managed_club_ids
                or str(team.get("team_type") or "club") == "national"
            ):
                continue
            ready = True
            for player in profile.get("players") or []:
                player_id = int(player.get("id") or 0)
                if player_id <= 0:
                    continue
                targets[player_id] = {
                    "id": player_id,
                    "name": str(
                        player.get("name") or player.get("full_name")
                        or player.get("game_name") or player_id
                    ),
                    "team_id": team_id,
                    "team_name": str(team.get("name") or team_id),
                    "reputation": player.get(
                        "world_reputation",
                        player.get("international_reputation"),
                    ),
                }
        return list(targets.values()), ready

    def _reputation_league_targets(self) -> list[dict[str, Any]]:
        native_reputations: dict[int, int] = {}
        for match in self.output.get("matches", []):
            competition_id = int(match.get("competition_id") or 0)
            value = match.get("competition_reputation_native")
            if competition_id > 0 and value is not None and 0 <= int(value) <= 200:
                native_reputations[competition_id] = int(value)
        targets: dict[int, dict[str, Any]] = {}
        for row in self.output.get("competition_formats", []):
            competition_id = int(row.get("competition_id") or 0)
            season_address = str(row.get("competition_season_address") or "")
            if (
                competition_id <= 0
                or str(row.get("competition_kind") or "") != "league"
                or not season_address.startswith("0x")
            ):
                continue
            targets[competition_id] = {
                "id": competition_id,
                "name": str(row.get("competition_name") or competition_id),
                "competition_season_address": season_address,
                "reputation": native_reputations.get(competition_id),
            }
        return sorted(
            targets.values(),
            key=lambda row: (-int(row.get("reputation") or 0), str(row.get("name") or "")),
        )

    def reputation_item_targets(self) -> dict[str, Any]:
        with self.lock:
            self._bind_current_save()
            players, players_ready = self._reputation_player_targets()
            return {
                **self._reputation_club_targets(),
                "leagues": self._reputation_league_targets(),
                "players": players,
                "players_ready": players_ready,
                "players_refreshing": bool(self.club_refreshing),
                "players_error": self.club_error,
            }

    def inventory_use_reputation(self, payload: dict[str, Any]) -> dict[str, Any]:
        item_id = str(payload.get("item_id") or "")
        with self.memory_lock:
            with self.lock:
                self._bind_current_save()
                item = next(
                    (row for row in public_economy().get("inventory", []) if row.get("id") == item_id),
                    None,
                )
                if (
                    not item or item.get("status") != "available"
                    or item.get("sku") not in {
                        "club_brochure", "player_brochure", "league_brochure",
                    }
                ):
                    raise ValueError("宣传册已经使用或不存在")
                sku = str(item["sku"])
                if sku == "club_brochure":
                    team_id = int(payload.get("team_id") or 0)
                    target = next(
                        (row for row in self._reputation_club_targets()["clubs"] if int(row["id"]) == team_id),
                        None,
                    )
                    if not target:
                        raise ValueError("所选俱乐部不属于当前执教或已购买俱乐部")
                    target_address = target.get("address")
                    target_name = str(target.get("name") or team_id)
                elif sku == "league_brochure":
                    competition_id = int(payload.get("competition_id") or 0)
                    target = next(
                        (
                            row for row in self._reputation_league_targets()
                            if int(row["id"]) == competition_id
                        ),
                        None,
                    )
                    if not target:
                        raise ValueError("所选联赛不在当前存档的可用联赛列表中")
                    target_address = target.get("competition_season_address")
                    target_name = str(target.get("name") or competition_id)
                else:
                    player_id = int(payload.get("player_id") or 0)
                    team_id = int(payload.get("team_id") or 0)
                    player_target = self._live_player_effect_target(
                        player_id, team_id, allow_national=False,
                        missing_message="所选球员不属于当前执教俱乐部，请刷新我的球队",
                    )
                    player = player_target.player
                    target_address = player_target.address
                    target_name = str(player.get("name") or player_id)
            if sku == "club_brochure":
                result = apply_team_reputation_delta(team_id, target_address, 200)
                try:
                    economy = consume_instant_item(
                        item_id, sku, team_id=team_id, team_name=target_name,
                        before=result["before"], after=result["after"],
                    )
                except Exception:
                    if result["applied"]:
                        apply_team_reputation_delta(team_id, target_address, -int(result["applied"]))
                    raise
                with self.lock:
                    for team in managed_team_rows(self.output):
                        if int(team.get("id") or 0) == team_id:
                            team["reputation"] = result["after"]
                    for profile in self.club_profiles.values():
                        if int((profile.get("team") or {}).get("id") or 0) == team_id:
                            profile["team"]["reputation"] = result["after"]
                    for row in (self.world_club_cache or {}).get("clubs", []):
                        if int(row.get("id") or 0) == team_id:
                            row["reputation"] = result["after"]
                return {
                    "economy": economy,
                    "club": {"id": team_id, "name": target_name, **result},
                }
            if sku == "league_brochure":
                result = apply_competition_reputation_delta(
                    competition_id, target_address, 10,
                )
                try:
                    economy = consume_instant_item(
                        item_id, sku, competition_id=competition_id,
                        competition_name=target_name,
                        before=result["before"], after=result["after"],
                    )
                except Exception:
                    if result["applied"]:
                        apply_competition_reputation_delta(
                            competition_id, target_address, -int(result["applied"]),
                        )
                    raise
                with self.lock:
                    for competition in self.output.get("competitions", []):
                        if int(competition.get("id") or 0) == competition_id:
                            competition["reputation"] = result["after"]
                    for match in self.output.get("matches", []):
                        if int(match.get("competition_id") or 0) == competition_id:
                            match["competition_reputation"] = result["after"]
                            match["competition_reputation_native"] = result["after"]
                    for competition_format in self.output.get("competition_formats", []):
                        if int(competition_format.get("competition_id") or 0) == competition_id:
                            competition_format["competition_reputation_native"] = result["after"]
                return {
                    "economy": economy,
                    "league": {"id": competition_id, "name": target_name, **result},
                }
            transaction = commit_player_effect(
                apply_effect=lambda: apply_player_world_reputation_delta(
                    player_id, target_address, 100,
                ),
                persist_effect=lambda result: consume_instant_item(
                    item_id, sku, player_id=player_id,
                    player_name=target_name, before=result["before"],
                    after=result["after"],
                ),
                rollback_effect=lambda result: (
                    apply_player_world_reputation_delta(
                        player_id, target_address, -int(result["applied"]),
                    ) if result["applied"] else None
                ),
            )
            result = transaction.native
            economy = transaction.persisted
            with self.lock:
                player["world_reputation"] = result["after"]
                player["international_reputation"] = result["after"]
            return {
                "economy": economy,
                "player": {"id": player_id, "name": target_name, **result},
            }

    def update_salary_schedule(self, payload: dict[str, Any]) -> dict[str, Any]:
        schedule_value = payload.get("schedule")
        if schedule_value != "weekly":
            raise ValueError("工资发放方式无效")
        schedule = "weekly"
        with self.lock:
            self._bind_current_save()
            game_date = str(self.output.get("game_date") or "")
            gross_weekly = self._total_weekly_salary(self.club_contexts)
            if not game_date or gross_weekly <= 0:
                raise ValueError("尚未读取到当前执教合同")
        return set_salary_schedule(schedule, game_date, gross_weekly)

    @staticmethod
    def _total_weekly_salary(contexts: dict[int, dict[str, Any]]) -> float:
        total = 0.0
        for context in contexts.values():
            contract = (context or {}).get("contract") or {}
            if contract.get("active") is False:
                continue
            try:
                total += max(0.0, float(contract.get("gross_weekly_display") or 0.0))
            except (TypeError, ValueError):
                continue
        return canonical_money(total)

