    def inventory_reverse_player_age(self, payload: dict[str, Any]) -> dict[str, Any]:
        item_id = str(payload.get("item_id", ""))
        player_id = int(payload.get("player_id", 0))
        team_id = int(payload.get("team_id", 0))
        target_age = int(payload.get("age", 0))
        with self.memory_lock:
            with self.lock:
                self._bind_current_save()
                item = next(
                    (row for row in public_economy().get("inventory", []) if row.get("id") == item_id),
                    None,
                )
                if not item or item.get("sku") != "age_reversal_pill" or item.get("status") != "available":
                    raise ValueError("返老还童丹已经使用或不存在")
                target = self._live_player_effect_target(
                    player_id, team_id,
                    missing_message="所选球员不属于当前执教队伍，请刷新我的队伍",
                )
                player = target.player
                game_date = str((read_game_clock() or {}).get("date") or self.output.get("game_date") or "")
                if not game_date:
                    raise ValueError("尚未读取当前游戏日期")

            def apply_age_reversal() -> dict[str, Any]:
                result = set_player_age(
                    player_id, target.address, game_date, target_age,
                )
                try:
                    updated_retirement = update_retirement_plan(
                        player_id, target.address, action="cancel",
                        capture_rollback=True,
                        missing_ok=True,
                    )
                except Exception as error:
                    try:
                        restore_player_birth_date(
                            player_id, target.address, result["_original_birth_date"],
                            original_ca=result["_original_ca"],
                            original_pa=result["_original_pa"],
                        )
                    except Exception as rollback_error:
                        raise PlayerEffectRollbackError(error, rollback_error) from error
                    raise
                result["_retirement_rollback"] = updated_retirement.pop("_rollback")
                result["retirement"] = updated_retirement
                result["retirement_cleared"] = bool(result["_retirement_rollback"])
                return result

            def rollback_age_reversal(result: dict[str, Any]) -> None:
                failures: list[Exception] = []
                retirement_snapshot = result.get("_retirement_rollback")
                if retirement_snapshot:
                    try:
                        restore_retirement_plan(
                            player_id, target.address, retirement_snapshot,
                        )
                    except Exception as error:
                        failures.append(error)
                try:
                    restore_player_birth_date(
                        player_id, target.address, result["_original_birth_date"],
                        original_ca=result["_original_ca"],
                        original_pa=result["_original_pa"],
                    )
                except Exception as error:
                    failures.append(error)
                if failures:
                    raise RuntimeError("；".join(str(error) for error in failures))

            transaction = commit_player_effect(
                apply_effect=apply_age_reversal,
                persist_effect=lambda result: consume_instant_item(
                    item_id, "age_reversal_pill", player_id=player_id,
                    player_name=player.get("name"), target_age=target_age,
                    previous_birth_date=result.get("before"),
                    birth_date=result.get("after"),
                    attribute_changes=result.get("attribute_changes"),
                    retirement_cleared=result.get("retirement_cleared", False),
                ),
                rollback_effect=rollback_age_reversal,
            )
            result = transaction.native
            economy = transaction.persisted
            result.pop("_original_birth_date", None)
            result.pop("_original_ca", None)
            result.pop("_original_pa", None)
            result.pop("_retirement_rollback", None)
            with self.lock:
                player["date_of_birth"] = result["after"]
                player["age"] = target_age
                player["ca"] = result["ca_after"]
                if result.get("retirement") is not None:
                    player["retirement"] = result["retirement"]
                if result.get("training_ca") is not None:
                    player["training_ca"] = result["training_ca"]
            return {
                "economy": economy,
                "player": {"id": player_id, "name": player.get("name"), **result},
            }

