    def _probe_match_intelligence_if_idle(self, *, force: bool = False) -> bool:
        now = monotonic()
        with self.lock:
            if (
                not self._has_verified_save()
                or self.refreshing
                or self.reconciling
                or self.save_change_pending
            ):
                return False
            if (
                not force
                and now - float(self.match_intelligence_last_probe_at or 0.0)
                < MATCH_INTELLIGENCE_POLL_SECONDS
            ):
                return False
            output = dict(self.output)
            output["matches"] = [
                dict(match) for match in self.output.get("matches", [])
            ]
            clock = dict(self.last_connection_clock or {})
            scope_id = self._data_scope_id(self.output)
            self.match_intelligence_last_probe_at = now
        game_date = str(clock.get("date") or output.get("game_date") or "")
        try:
            game_minutes = int(clock.get("minutes"))
        except (TypeError, ValueError):
            return False
        if not game_date or not scope_id:
            return False
        set_active_save_id(scope_id)
        with self.lock:
            intelligence_unlocked = bool(
                self.match_intelligence_public_cache_scope_id == scope_id
                and self.match_intelligence_public_cache.get("unlocked")
            )
        if not intelligence_unlocked:
            return False
        if not self.memory_lock.acquire(blocking=False):
            return False
        try:
            probe = probe_match_intelligence_candidates(
                output.get("matches", []), game_date, game_minutes,
            )
        except Exception as error:
            with self.lock:
                self.match_intelligence_last_error = str(error).strip() or type(error).__name__
            return False
        finally:
            self.memory_lock.release()
        discovered = {
            str(item.get("fixture_id") or ""): dict(item)
            for item in (probe.get("candidates") or [])
            if item.get("fixture_id")
        }
        with self.lock:
            merged = {
                str(item.get("fixture_id") or ""): dict(item)
                for item in self.match_intelligence_results
                if item.get("fixture_id")
            }
            merged.update(discovered)
            current_candidates = current_match_intelligence_candidates(
                list(merged.values()), output.get("matches", []),
                game_date, game_minutes,
            )
            candidates = sorted(current_candidates, key=lambda item: (
                str(item.get("fixture_date") or ""),
                int(item.get("kickoff_minutes") or 24 * 60),
                str(item.get("competition_name") or ""),
                str((item.get("home") or {}).get("name") or ""),
            ))
            before = json.dumps(
                self.match_intelligence_results,
                ensure_ascii=False, sort_keys=True, default=str,
            )
            after = json.dumps(
                candidates,
                ensure_ascii=False, sort_keys=True, default=str,
            )
            self.match_intelligence_results = candidates
            self.match_intelligence_last_error = None
            if before != after:
                self.data_version += 1
        return True

    def watch_match_intelligence(self) -> None:
        while True:
            try:
                self._probe_match_intelligence_if_idle()
            except Exception as error:
                with self.lock:
                    self.match_intelligence_last_error = (
                        str(error).strip() or type(error).__name__
                    )
            sleep(1)

    def public_match_intelligence(self) -> dict[str, Any]:
        output = dict(self.output)
        if output.get("save_identity_discovery_deferred") or self.save_change_pending:
            raise ValueError("正在确认存档身份，请稍后重试")
        if not output.get("save_instance_id"):
            raise ValueError("尚未识别当前存档")
        scope_id = self._data_scope_id(output)
        if not scope_id:
            raise ValueError("尚未识别当前存档账户")
        set_active_save_id(scope_id)
        if self.match_intelligence_public_cache_scope_id != scope_id:
            return {
                "unlocked": False,
                "floor": "5F",
                "pricing_basis": "daily_entry_combined_funds_percentage",
                "pricing": {
                    "locked": False, "game_date": "",
                    "combined_funds": 0.0, "locked_at": "",
                },
                "candidates": [],
                "refreshing": True,
            }
        clock = dict(self.last_connection_clock or {})
        game_date = str(clock.get("date") or output.get("game_date") or "")
        try:
            game_minutes = int(clock["minutes"])
        except (KeyError, TypeError, ValueError):
            current_candidates = []
        else:
            current_candidates = current_match_intelligence_candidates(
                [dict(item) for item in self.match_intelligence_results],
                [dict(item) for item in output.get("matches", [])],
                game_date,
                game_minutes,
            )
        intelligence = open_match_intelligence_status(
            current_candidates, game_date,
        )
        self.match_intelligence_public_cache = deepcopy(intelligence)
        return intelligence

    def buy_match_intelligence(self, payload: dict[str, Any]) -> dict[str, Any]:
        fixture_id = str(payload.get("fixture_id") or "")
        tier = str(payload.get("tier") or "")
        random_purchase = bool(payload.get("random"))
        submission_id = str(payload.get("client_submission_id") or "").strip()
        with self.memory_lock:
            clock = read_game_clock()
        with self.lock:
            self._bind_current_save()
            current_date = str((clock or {}).get("date") or "")
            try:
                current_minutes = int((clock or {})["minutes"])
            except (KeyError, TypeError, ValueError):
                raise ValueError("无法确认当前游戏时间，请稍后重试") from None
            if not current_date:
                raise ValueError("无法确认当前游戏时间，请稍后重试")
            open_candidates = current_match_intelligence_candidates(
                [dict(item) for item in self.match_intelligence_results],
                [dict(item) for item in self.output.get("matches", [])],
                current_date,
                current_minutes,
            )
            existing_purchase = None
            if random_purchase:
                existing_purchase = next((
                    dict(purchase)
                    for purchase in dict(
                        load_economy().get("match_intelligence_purchases") or {}
                    ).values()
                    if any(
                        str(payment.get("client_submission_id") or "") == submission_id
                        for payment in purchase.get("payments") or []
                    )
                ), None)
                if existing_purchase:
                    fixture_id = str(existing_purchase.get("fixture_id") or "")
                    candidate = next((
                        dict(item) for item in self.match_intelligence_results
                        if str(item.get("fixture_id") or "") == fixture_id
                    ), existing_purchase)
                else:
                    current_status = match_intelligence_status(
                        open_candidates, pricing_date=current_date,
                    )
                    candidate = random_match_intelligence_candidate(
                        open_candidates, current_status, tier,
                    )
                    if not candidate:
                        raise ValueError("当前没有尚未获取的随机比赛情报")
                    fixture_id = str(candidate.get("fixture_id") or "")
            else:
                candidate = next((
                    dict(item) for item in open_candidates
                    if str(item.get("fixture_id") or "") == fixture_id
                ), None)
            if not candidate:
                raise ValueError("这场比赛当前没有可获取的比赛情报")
            fixture_date = str(candidate.get("fixture_date") or "")
            kickoff = candidate.get("kickoff_minutes")
            if not (random_purchase and existing_purchase) and (
                not current_date
                or fixture_date < current_date
                or (
                    fixture_date == current_date
                    and (kickoff is None or int(kickoff) < current_minutes)
                )
            ):
                raise ValueError("该场比赛的情报获取窗口已经结束")
            result = purchase_match_intelligence(
                candidate, tier, submission_id, game_date=current_date,
                purchase_mode="random" if random_purchase else "specific",
            )
            intelligence = match_intelligence_status(
                open_candidates,
                pricing_date=current_date,
            )
            self.match_intelligence_public_cache = deepcopy(intelligence)
            self.match_intelligence_public_cache_scope_id = str(
                self._data_scope_id(self.output) or ""
            )
            return {
                **result,
                "intelligence": intelligence,
                "economy": public_economy(),
                "welfare": welfare_status(),
            }

    @staticmethod
    def _language_learning_candidates(
        profiles: list[dict[str, Any]],
    ) -> list[dict[str, Any]]:
        candidates: list[dict[str, Any]] = []
        seen: set[int] = set()
        ordered = sorted(profiles, key=lambda profile: (
            str((profile.get("team") or {}).get("team_type") or "club") != "club",
        ))
        for profile in ordered:
            team = dict(profile.get("team") or {})
            for player in profile.get("players") or []:
                player_id = int(player.get("id") or 0)
                if player_id <= 0 or player_id in seen:
                    continue
                seen.add(player_id)
                player["team_id"] = int(team.get("id") or 0)
                player["team_name"] = str(team.get("name") or team.get("short_name") or "")
                player["team_type"] = str(team.get("team_type") or "club")
                candidates.append(player)
        return candidates

    @staticmethod
    def _language_learning_staff_candidates(
        profiles: list[dict[str, Any]],
    ) -> list[dict[str, Any]]:
        candidates: list[dict[str, Any]] = []
        seen: set[int] = set()
        ordered = sorted(profiles, key=lambda profile: (
            str((profile.get("team") or {}).get("team_type") or "club") != "club",
        ))
        for profile in ordered:
            team = dict(profile.get("team") or {})
            for staff in profile.get("staff") or []:
                person_id = int(staff.get("id") or 0)
                if person_id <= 0 or person_id in seen:
                    continue
                seen.add(person_id)
                person = dict(staff)
                person.update({
                    "team_id": int(team.get("id") or 0),
                    "team_name": str(team.get("name") or team.get("short_name") or ""),
                    "team_type": str(team.get("team_type") or "club"),
                })
                candidates.append(person)
        return candidates

    @staticmethod
    def _hydrate_staff_languages(
        staff: list[dict[str, Any]],
    ) -> list[dict[str, Any]]:
        hydrated: list[dict[str, Any]] = []
        for person in staff:
            row = dict(person)
            row["languages"] = read_person_languages(
                int(row.get("id") or 0), row.get("address"), person_kind="staff",
            )
            hydrated.append(row)
        return hydrated

    def activity_languages(self) -> dict[str, Any]:
        with self.memory_lock:
            with self.lock:
                self._bind_current_save()
                assert_activity_facility_unlocked("language_classroom")
            return {
                "languages": public_language_catalog(),
                "staff_language_learning": staff_language_learning_capability(),
            }

    def activity_staff_languages(self, person_ids: list[int]) -> dict[str, Any]:
        requested = {int(person_id) for person_id in person_ids if int(person_id) > 0}
        with self.memory_lock:
            with self.lock:
                self._bind_current_save()
                assert_activity_facility_unlocked("language_classroom")
                profiles = list(self.club_profiles.values()) or (
                    [self.club_profile] if self.club_profile else []
                )
            candidates = self._language_learning_staff_candidates(profiles)
            selected = [
                person for person in candidates
                if int(person.get("id") or 0) in requested
            ]
            if len(selected) != len(requested):
                raise ValueError("部分所选职员已经不属于当前执教队伍，请先刷新")
            hydrated = self._hydrate_staff_languages(selected)
            return {
                "staff": [{
                    "person_id": int(person.get("id") or 0),
                    "team_id": int(person.get("team_id") or 0),
                    "languages": list(person.get("languages") or []),
                } for person in hydrated],
                "capability": staff_language_learning_capability(),
            }

    def update_language_learning(self, payload: dict[str, Any]) -> dict[str, Any]:
        mode = str(payload.get("mode") or "")
        if mode not in {"manual", "auto", "cancel", "instant", "instant_max"}:
            raise ValueError("语言学习操作无效")
        with self.memory_lock:
            with self.lock:
                self._bind_current_save()
                assert_activity_facility_unlocked("language_classroom")
                game_date = str(
                    (read_game_clock() or {}).get("date")
                    or self.output.get("game_date") or ""
                )
                profiles = list(self.club_profiles.values()) or (
                    [self.club_profile] if self.club_profile else []
                )
            if not game_date:
                raise ValueError("尚未读取当前游戏日期")
            target_rows = payload.get("targets")
            target_kind = next((
                str(row.get("person_kind") or "").strip().lower()
                for row in target_rows or [] if isinstance(row, dict)
                and row.get("person_kind")
            ), "") if isinstance(target_rows, list) else ""
            person_kind = str(payload.get("person_kind") or target_kind or "player").strip().lower()
            if person_kind not in {"player", "staff"}:
                raise ValueError("语言学习人物类型无效")
            candidates = (
                self._language_learning_staff_candidates(profiles)
                if person_kind == "staff" else self._language_learning_candidates(profiles)
            )
            if not candidates:
                raise ValueError("请先刷新当前执教球队")
            enabled = bool(payload.get("enabled", True))
            language_id = int(payload.get("language_id") or 0)
            language_name = ""
            if mode != "auto" or enabled:
                language = next(
                    (row for row in native_language_catalog() if int(row.get("id") or 0) == language_id),
                    None,
                )
                if not language:
                    raise ValueError("请选择有效的目标语言")
                language_name = str(language["name"])
            if person_kind == "staff":
                capability = staff_language_learning_capability()
                if (mode != "cancel" and (mode != "auto" or enabled)) and not capability["write_enabled"]:
                    raise RuntimeError(str(capability["reason"]))
                if mode == "auto":
                    automatic_staff = (
                        self._hydrate_staff_languages(candidates) if enabled else candidates
                    )
                    result = configure_automatic_staff_language_learning(
                        language_id, language_name, enabled, game_date, automatic_staff,
                    )
                else:
                    requested = payload.get("targets") or payload.get("staff") or payload.get("players")
                    if not isinstance(requested, list) or not requested:
                        raise ValueError("请至少选择一名职员")
                    requested_pairs = {
                        (
                            int(row.get("staff_id") or row.get("person_id") or row.get("player_id") or 0),
                            int(row.get("team_id") or 0),
                        )
                        for row in requested if isinstance(row, dict)
                    }
                    selected_staff = [
                        person for person in candidates
                        if (
                            int(person.get("id") or 0), int(person.get("team_id") or 0)
                        ) in requested_pairs
                    ]
                    if len(selected_staff) != len({
                        person_id for person_id, _team_id in requested_pairs if person_id > 0
                    }):
                        raise ValueError("部分所选职员已经不属于当前执教队伍，请先刷新")
                    if mode == "cancel":
                        result = cancel_staff_language_learning(
                            language_id, game_date,
                            [int(person.get("id") or 0) for person in selected_staff],
                        )
                    else:
                        selected_staff = self._hydrate_staff_languages(selected_staff)
                        if mode == "manual":
                            result = enroll_staff_language_learning(
                                language_id, language_name, game_date, selected_staff,
                            )
                        else:
                            def apply_staff_level(
                                person: dict[str, Any], target_language_id: int,
                                target_level: int,
                            ) -> dict[str, Any]:
                                return apply_person_language_level(
                                    int(person.get("id") or 0), person.get("address"),
                                    int(target_language_id), int(target_level),
                                    person_kind="staff",
                                )

                            result = advance_staff_language_learning_now(
                                language_id, language_name, game_date, selected_staff,
                                apply_staff_level, restore_person_language_level,
                                to_maximum=mode == "instant_max",
                            )
            elif mode == "auto":
                result = configure_automatic_language_learning(
                    language_id, language_name, enabled, game_date, candidates,
                )
            else:
                requested = payload.get("targets") or payload.get("players")
                if not isinstance(requested, list) or not requested:
                    raise ValueError("请至少选择一名球员")
                requested_pairs = {
                    (int(row.get("player_id") or row.get("person_id") or 0), int(row.get("team_id") or 0))
                    for row in requested if isinstance(row, dict)
                }
                selected = [
                    player for player in candidates
                    if (
                        int(player.get("id") or 0), int(player.get("team_id") or 0)
                    ) in requested_pairs
                ]
                if len(selected) != len({player_id for player_id, _team_id in requested_pairs if player_id > 0}):
                    raise ValueError("部分所选球员已经不属于当前执教队伍，请先刷新")
                if mode == "manual":
                    result = enroll_language_learning(
                        language_id, language_name, game_date, selected,
                        source="manual",
                    )
                elif mode == "cancel":
                    result = cancel_language_learning(
                        language_id, game_date,
                        [int(player.get("id") or 0) for player in selected],
                    )
                else:
                    def apply_level(
                        player: dict[str, Any], target_language_id: int,
                        target_level: int,
                    ) -> dict[str, Any]:
                        return apply_player_language_level(
                            int(player.get("id") or 0), player.get("address"),
                            int(target_language_id), int(target_level),
                        )

                    result = advance_language_learning_now(
                        language_id, language_name, game_date, selected,
                        apply_level, restore_player_language_level,
                        to_maximum=mode == "instant_max",
                    )
            return {
                **result, "economy": public_economy(), "welfare": welfare_status(),
            }

    def _process_language_learning(
        self, game_date: str, profiles: list[dict[str, Any]],
        *, welfare_snapshot: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        candidates = self._language_learning_candidates(profiles)
        staff_candidates: list[dict[str, Any]] = []
        capability = staff_language_learning_capability()
        welfare = welfare_snapshot if welfare_snapshot is not None else welfare_status()
        language_state = dict(welfare.get("language_learning") or {})
        staff_course_active = bool(
            (language_state.get("auto") or {}).get("staff_enabled")
            or any(
                isinstance(plan, dict)
                and str(plan.get("person_kind") or "") == "staff"
                and plan.get("status") == "active"
                for plan in (language_state.get("plans") or {}).values()
            )
        )
        if staff_course_active:
            staff_candidates = self._language_learning_staff_candidates(profiles)
            if capability["write_enabled"]:
                staff_candidates = self._hydrate_staff_languages(staff_candidates)

        def apply_level(
            player: dict[str, Any], language_id: int, target_level: int,
        ) -> dict[str, Any]:
            return apply_player_language_level(
                int(player.get("id") or 0), player.get("address"),
                int(language_id), int(target_level),
            )

        def apply_staff_level(
            person: dict[str, Any], language_id: int, target_level: int,
        ) -> dict[str, Any]:
            return apply_person_language_level(
                int(person.get("id") or 0), person.get("address"),
                int(language_id), int(target_level), person_kind="staff",
            )

        return process_language_learning(
            game_date, candidates, apply_level, restore_player_language_level,
            staff=staff_candidates,
            apply_staff_level=apply_staff_level if capability["write_enabled"] else None,
            rollback_staff_level=(
                restore_person_language_level if capability["write_enabled"] else None
            ),
        )

    def media_activity(self, payload: dict[str, Any]) -> dict[str, Any]:
        activity = str(payload.get("activity") or "")
        target_id = int(payload.get("target_id") or 0)
        requested_team_id = int(payload.get("team_id") or 0)
        with self.memory_lock:
            with self.lock:
                self._bind_current_save()
                game_date = str((read_game_clock() or {}).get("date") or self.output.get("game_date") or "")
                if not game_date:
                    raise ValueError("尚未读取当前游戏日期")
                if activity == "club_press_conference":
                    profile = next((
                        row for row in self.club_profiles.values()
                        if str((row.get("team") or {}).get("team_type") or "club") == "club"
                        and (not target_id or int((row.get("team") or {}).get("id") or 0) == target_id)
                    ), None)
                    if not profile:
                        raise ValueError("请先刷新当前执教俱乐部")
                    team = dict(profile.get("team") or {})
                    target_id = int(team.get("id") or 0)
                    target_name = str(team.get("name") or team.get("short_name") or target_id)
                    target_address = team.get("address")
                    assert_media_activity_available(activity, target_id, game_date)
                    reputation = apply_team_reputation_delta(target_id, target_address, 50)
                    try:
                        publicity = apply_club_publicity_effect(target_id, target_address)
                    except Exception:
                        if int(reputation.get("applied") or 0):
                            apply_team_reputation_delta(
                                target_id, target_address, -int(reputation["applied"]),
                            )
                        raise
                    public_publicity = {
                        key: value for key, value in publicity.items() if not key.startswith("_")
                    }
                    result = {**reputation, "publicity": public_publicity}

                    def rollback() -> None:
                        try:
                            restore_club_publicity_effect(publicity)
                        finally:
                            if int(reputation.get("applied") or 0):
                                apply_team_reputation_delta(
                                    target_id, target_address, -int(reputation["applied"]),
                                )
                elif activity == "player_feature":
                    profile, player = self._live_player_profile(
                        target_id, requested_team_id,
                    )
                    if not profile or not player:
                        raise ValueError("所选球员不属于当前执教俱乐部，请先刷新队伍")
                    if str((profile.get("team") or {}).get("team_type") or "club") != "club":
                        raise ValueError("国家队球员不能参加俱乐部专题报道")
                    target_name = str(player.get("name") or target_id)
                    target_address = player.get("address")
                    assert_media_activity_available(activity, target_id, game_date)
                    result = apply_player_world_reputation_delta(target_id, target_address, 50)
                    def rollback() -> None:
                        if int(result.get("applied") or 0):
                            apply_player_world_reputation_delta(
                                target_id, target_address, -int(result["applied"]),
                            )
                else:
                    raise ValueError("媒体活动类型无效")
            try:
                history = record_media_activity(
                    activity, target_id, target_name, game_date, result,
                )
            except Exception:
                rollback()
                raise
            with self.lock:
                if activity == "club_press_conference":
                    profile["team"]["reputation"] = result["after"]
                    supporters = ((profile.get("club_information") or {}).get("supporters") or {})
                    publicity_result = result.get("publicity") or {}
                    follower_result = publicity_result.get("social_media_followers") or {}
                    supporter_result = publicity_result.get("supporters") or {}
                    if follower_result.get("after") is not None:
                        supporters["social_media_followers"] = follower_result["after"]
                    if isinstance(supporters.get("profile"), dict):
                        supporters["profile"]["loyalty"] = supporter_result.get(
                            "loyalty_after", supporters["profile"].get("loyalty"),
                        )
                        supporters["profile"]["passion"] = supporter_result.get(
                            "passion_after", supporters["profile"].get("passion"),
                        )
                    for team in managed_team_rows(self.output):
                        if int(team.get("id") or 0) == target_id:
                            team["reputation"] = result["after"]
                else:
                    player["world_reputation"] = result["after"]
                    player["international_reputation"] = result["after"]
            return {
                "media_activity": history, "result": result,
                "economy": public_economy(), "welfare": welfare_status(),
            }

    def international_nations(self) -> dict[str, Any]:
        with self.lock:
            self._bind_current_save()
            assert_activity_centre_unlocked("international")
            # World-nation scans are keyed by the verified save identity.  Keep
            # the lookup on that same key so an account-scoped wallet does not
            # make a completed world scan appear to be missing.
            save_id = str(self.output.get("save_instance_id") or self._data_scope_id(self.output))
        native = self._world_club_native_cache(save_id)
        if not native or not native.get("addresses_current"):
            raise ValueError("请先在世界国家页面刷新世界数据")
        nations = [
            {
                "id": int(row.get("id") or 0),
                "name": str(row.get("name") or row.get("id") or ""),
                "continent": str(row.get("continent") or "未分类"),
            }
            for row in (native.get("nations") or [])
            if int(row.get("id") or 0) > 0 and row.get("address")
        ]
        nations.sort(key=lambda row: (row["continent"], row["name"]))
        return {"nations": nations}

    def international_activity(self, payload: dict[str, Any]) -> dict[str, Any]:
        player_id = int(payload.get("player_id") or 0)
        requested_team_id = int(payload.get("team_id") or 0)
        nation_id = int(payload.get("nation_id") or 0)
        scope = "world" if str(payload.get("scope") or "club").lower() == "world" else "club"
        slot = "primary" if str(payload.get("slot") or "secondary").lower() == "primary" else "secondary"
        action = str(payload.get("action") or "set").strip().lower()
        remove_secondary = action in {"remove_secondary", "remove-second-nationality"}
        if remove_secondary:
            slot = "secondary"
        expected_nation_id = int(payload.get("expected_nation_id") or 0)
        if player_id <= 0 or nation_id <= 0:
            raise ValueError("请选择球员和目标国籍")
        with self.memory_lock:
            with self.lock:
                self._bind_current_save()
                assert_activity_centre_unlocked("international")
                profile = player = None
                if scope == "club":
                    profile, player = self._live_player_profile(player_id, requested_team_id)
                    if not profile or not player:
                        raise ValueError("所选球员不属于当前执教俱乐部，请先刷新队伍")
                    if str((profile.get("team") or {}).get("team_type") or "club") != "club":
                        raise ValueError("国家队球员不能处理国籍")
                else:
                    player = read_world_player_profile(player_id)
                # Native world scans are keyed by the verified save identity,
                # not by the account-scoped wallet/data scope.  Keep the
                # mutation path on the same key used by international_nations
                # and start_world_club_scan so a completed scan is reusable.
                save_id = str(
                    self.output.get("save_instance_id")
                    or self._data_scope_id(self.output)
                )
                native = self._world_club_native_cache(save_id)
                if not native or not native.get("addresses_current"):
                    raise ValueError("请先在世界国家页面刷新世界数据")
                nation = next(
                    (row for row in (native.get("nations") or []) if int(row.get("id") or 0) == nation_id),
                    None,
                )
                if not nation or not nation.get("address"):
                    raise ValueError("所选国家不在当前世界数据中，请重新扫描")
                player_name = str(player.get("name") or player_id)
                nation_name = str(nation.get("name") or nation_id)
                game_date = str(
                    (read_game_clock() or {}).get("date") or self.output.get("game_date") or ""
                )
                if not game_date:
                    raise ValueError("尚未读取当前游戏日期")
                price = 0.0 if remove_secondary or free_services_enabled() else local_purchase_price(
                    NATIONALITY_PROCESSING_PRICES[scope],
                )
                payment = None
                try:
                    if price > 0:
                        payment = charge_combined_funds(
                            price, "nationality_processing",
                            player_id=player_id, player_name=player_name,
                            nation_id=nation_id, nation_name=nation_name,
                            scope=scope, slot=slot, game_date=game_date,
                        )
                    if remove_secondary:
                        result = (
                            remove_player_second_nationality(
                                player_id, player.get("address"), nation_id, nation.get("address"),
                            )
                            if scope == "club" else
                            remove_world_player_second_nationality(player_id, nation_id, nation.get("address"))
                        )
                    elif slot == "primary":
                        if expected_nation_id <= 0:
                            expected_nation_id = int(player.get("nationality_id") or 0)
                        result = update_world_player_primary_nationality(
                            player_id, nation_id, expected_nation_id,
                            player_address=player.get("address") if scope == "club" else 0,
                            nation_address=nation.get("address"),
                        )
                    elif scope == "club":
                        result = apply_player_second_nationality(
                            player_id, player.get("address"), nation_id, nation.get("address"),
                            replace_existing=True,
                        )
                    else:
                        result = apply_world_player_second_nationality(
                            player_id, nation_id, nation.get("address"),
                            replace_existing=True,
                        )
                except Exception:
                    if payment:
                        refund_combined_funds(
                            payment, "nationality_processing_rollback",
                            player_id=player_id, player_name=player_name,
                            nation_id=nation_id, nation_name=nation_name,
                            scope=scope, slot=slot,
                        )
                    raise
            public_result = {key: value for key, value in result.items() if not key.startswith("_")}
            try:
                history = record_international_activity(
                    player_id, player_name, nation_id, nation_name, game_date, public_result, slot,
                )
            except Exception:
                if slot == "secondary" and result.get("_rollback"):
                    restore_player_second_nationality(result)
                    if payment:
                        refund_combined_funds(
                            payment, "nationality_processing_rollback",
                            player_id=player_id, player_name=player_name,
                            nation_id=nation_id, nation_name=nation_name,
                            scope=scope, slot=slot,
                        )
                    raise
                history = {
                    "activity": "naturalization", "activity_name": "国籍处理",
                    "target_id": player_id, "target_name": player_name,
                    "nation_id": nation_id, "nation_name": nation_name,
                    "slot": slot, "history_recorded": False,
                }
            with self.lock:
                if scope == "club" and player is not None:
                    if remove_secondary:
                        existing_nationalities = list(player.get("other_nationalities") or [])
                        if not existing_nationalities and isinstance(player.get("second_nationality"), dict):
                            existing_nationalities = [player["second_nationality"]]
                        remaining_nationalities = [
                            row for row in existing_nationalities
                            if int(row.get("id") or 0) != nation_id
                        ]
                        player["other_nationalities"] = remaining_nationalities
                        player["second_nationality"] = remaining_nationalities[0] if remaining_nationalities else None
                    elif slot == "primary":
                        player["nationality_id"] = nation_id
                        player["nationality"] = nation_name
                    else:
                        other_nationalities = list(player.get("other_nationalities") or [])
                        if not any(int(row.get("id") or 0) == nation_id for row in other_nationalities):
                            other_nationalities.append({"id": nation_id, "name": nation_name, "eligible_for_nation": True})
                        player["other_nationalities"] = other_nationalities
                        player["second_nationality"] = other_nationalities[0] if other_nationalities else None
            return {
                "international_activity": history, "result": public_result,
                "price_gbp": price, "payment": payment,
                "economy": public_economy(), "welfare": welfare_status(),
            }

    def _canteen_sea_cucumber_one(
        self, player_id: int, requested_team_id: int, *,
        manager: dict[str, Any], manager_id: int, game_date: str,
        memory_session: Any = None,
    ) -> dict[str, Any]:
        price = local_purchase_price(CANTEEN_SEA_CUCUMBER_PRICE)
        profile_kwargs = (
            {"memory_session": memory_session}
            if callable(getattr(memory_session, "resolve_roster_player", None)) else {}
        )
        target = self._live_player_effect_target(
            player_id, requested_team_id, **profile_kwargs,
            missing_message="所选球员不属于当前执教俱乐部，请先刷新队伍",
        )
        player = target.player
        team = target.team
        if str(team.get("team_type") or "club") != "club":
            raise ValueError("国家队球员不能使用球队食堂奖励")
        team_id = target.team_id
        current_intimacy = int(player.get("manager_intimacy") or 0)
        player_name = str(player.get("name") or player_id)

        payment: dict[str, Any] | None = None
        condition: dict[str, Any] | None = None
        if memory_session:
            apply_effect = lambda: memory_session.apply_effect(
                player_id, target.address,
            )
            apply_intimacy = lambda _condition: memory_session.apply_intimacy(
                player_id, target.address, manager_id, team_id,
                team_address=team.get("address"),
                manager_address=manager.get("manager_address"),
            )
            rollback_effect = memory_session.restore
        else:
            apply_effect = lambda: apply_canteen_sea_cucumber_effect(
                player_id, target.address,
            )
            apply_intimacy = lambda _condition: apply_manager_intimacy_points(
                player_id, target.address, manager_id, team_id,
                team_address=team.get("address"),
                manager_address=manager.get("manager_address"), points=1,
            )
            rollback_effect = restore_player_activity_effect
        try:
            payment = charge_combined_funds(
                price, "canteen_sea_cucumber",
                player_id=player_id, player_name=player_name,
                manager_id=manager_id, team_id=team_id, game_date=game_date,
            )
            transaction = commit_player_effect(
                apply_effect=apply_effect,
                persist_effect=apply_intimacy,
                rollback_effect=rollback_effect,
            )
            condition = transaction.native
            intimacy = transaction.persisted
        except Exception:
            try:
                if condition:
                    rollback_effect(condition)
            finally:
                if payment:
                    refund_combined_funds(
                        payment, "canteen_sea_cucumber_rollback",
                        player_id=player_id, player_name=player_name,
                    )
            raise

        public_condition = {
            key: value for key, value in condition.items() if not key.startswith("_")
        }
        with self.lock:
            player["fitness"] = 100.0
            player["sharpness"] = 100.0
            player["manager_intimacy"] = int(intimacy.get("after") or current_intimacy)
        return {
            "player_id": player_id, "player_name": player_name,
            "price_gbp": price, "payment": payment,
            "condition": public_condition,
            "fitness": public_condition["fitness"],
            "sharpness": public_condition["sharpness"],
            "intimacy": intimacy,
        }

    def _canteen_sea_cucumber_context(self) -> tuple[dict[str, Any], int, str]:
        with self.lock:
            self._bind_current_save()
            manager = dict(self.output.get("manager") or {})
            manager_id = int(
                self.output.get("selected_manager_id") or manager.get("id") or 0
            )
            fallback_date = str(self.output.get("game_date") or "")
        game_date = str((read_game_clock() or {}).get("date") or fallback_date)
        return manager, manager_id, game_date

    def canteen_sea_cucumber(self, payload: dict[str, Any]) -> dict[str, Any]:
        player_id = int(payload.get("player_id") or 0)
        requested_team_id = int(payload.get("team_id") or 0)
        if player_id <= 0:
            raise ValueError("请选择球员")
        with self.memory_lock:
            manager, manager_id, game_date = self._canteen_sea_cucumber_context()
            result = self._canteen_sea_cucumber_one(
                player_id, requested_team_id, manager=manager,
                manager_id=manager_id, game_date=game_date,
            )
        result["economy"] = public_economy()
        return result

    def canteen_sea_cucumbers(self, payload: dict[str, Any]) -> dict[str, Any]:
        raw_player_ids = payload.get("player_ids")
        if not isinstance(raw_player_ids, list):
            raise ValueError("请选择球员")
        player_ids = list(dict.fromkeys(int(value or 0) for value in raw_player_ids))
        if not player_ids or any(player_id <= 0 for player_id in player_ids):
            raise ValueError("请选择有效球员")
        if len(player_ids) > 200:
            raise ValueError("单次最多奖励 200 名球员")
        requested_team_id = int(payload.get("team_id") or 0)
        results: list[dict[str, Any]] = []
        failure: dict[str, Any] | None = None
        with self.memory_lock:
            manager, manager_id, game_date = self._canteen_sea_cucumber_context()
            with canteen_sea_cucumber_memory_session() as memory_session:
                for player_id in player_ids:
                    try:
                        results.append(self._canteen_sea_cucumber_one(
                            player_id, requested_team_id, manager=manager,
                            manager_id=manager_id, game_date=game_date,
                            memory_session=memory_session,
                        ))
                    except Exception as error:
                        failure = {
                            "player_id": player_id,
                            **describe_player_effect_error(
                                error, operation="sea_cucumber_batch",
                            ),
                        }
                        break
        return {
            "requested": len(player_ids), "completed": len(results),
            "results": results, "failure": failure,
            "economy": public_economy(),
        }

    def retirement_activity(self, payload: dict[str, Any]) -> dict[str, Any]:
        player_id = int(payload.get("player_id") or 0)
        requested_team_id = int(payload.get("team_id") or 0)
        scope = "world" if str(payload.get("scope") or "").strip().lower() == "world" else "club"
        action = str(payload.get("action") or "")
        if action not in {"cancel", "six_months", "two_years", "ten_years", "twenty_years"}:
            raise ValueError("请选择有效的退役计划交流选项")
        with self.memory_lock:
            with self.lock:
                self._bind_current_save()
                assert_activity_facility_unlocked("retirement")
                if scope == "world":
                    player = read_world_player_profile(player_id)
                    if requested_team_id and int(player.get("team_id") or 0) != requested_team_id:
                        raise ValueError("球员所属球队已变化，请刷新退役计划列表")
                    update_retirement = update_world_player_retirement
                else:
                    _profile, player = self._live_player_profile(
                        player_id, requested_team_id,
                    )
                    if not player:
                        raise ValueError("所选球员不属于当前执教球队，请先刷新队伍")
                    update_retirement = update_retirement_plan
                player_name = str(player.get("name") or player_id)
                retirement_value = player.get("retirement")
                current_retirement = dict(retirement_value or {})
                if (
                    not isinstance(retirement_value, dict)
                    or not current_retirement.get("has_plan")
                    or (
                        current_retirement.get("cancelled")
                        and (action != "cancel" or not current_retirement.get("retirement_date"))
                    )
                ):
                    raise ValueError(
                        "退役计划交流仅面向显示退役或已有退役计划的球员"
                    )
                manager = dict(self.output.get("manager") or {})
                manager_id = int(self.output.get("selected_manager_id") or manager.get("id") or 0)
                game_date = str(
                    (read_game_clock() or {}).get("date") or self.output.get("game_date") or ""
                )
                if not game_date:
                    raise ValueError("尚未读取当前游戏日期")
                assert_activity_floor_available(
                    manager_id, player_id, "talk_room", game_date,
                )
                player_address = player.get("address")
            if scope == "world":
                retirement = update_retirement(player_id, action)
            else:
                retirement = update_retirement(
                    player_id, player_address, action=action,
                )
            with self.lock:
                player["retirement"] = retirement
            record_activity_floor_cooldown(
                manager_id, player_id, "talk_room", game_date,
            )
            replies = {
                "cancel": f"{player_name}：好的老大，我会继续踢下去。",
                "six_months": f"{player_name}：好的老大，我会考虑在半年后退役。",
                "two_years": f"{player_name}：好的老大，我会考虑在两年后退役。",
                "ten_years": f"{player_name}：好的老大，我会考虑在十年后退役。",
                "twenty_years": f"{player_name}：好的老大，我会考虑在二十年后退役。",
            }
            return {
                "player_id": player_id,
                "player_name": player_name,
                "modified": True,
                "action": action,
                "reply": replies[action],
                "retirement": retirement,
                "economy": public_economy(),
                "welfare": welfare_status(),
            }

    def black_room_activity(self, payload: dict[str, Any]) -> dict[str, Any]:
        player_id = int(payload.get("player_id") or 0)
        requested_team_id = int(payload.get("team_id") or 0)
        with self.memory_lock:
            with self.lock:
                self._bind_current_save()
                assert_activity_facility_unlocked("black_room")
                profile, player = self._live_player_profile(
                    player_id, requested_team_id,
                )
                if not profile or not player:
                    raise ValueError("所选球员不属于当前执教球队，请先刷新队伍")
                manager = dict(self.output.get("manager") or {})
                manager_id = int(self.output.get("selected_manager_id") or manager.get("id") or 0)
                game_date = str(
                    (read_game_clock() or {}).get("date") or self.output.get("game_date") or ""
                )
                if not game_date:
                    raise ValueError("尚未读取当前游戏日期")
                team = dict(profile.get("team") or {})
                team_id = int(team.get("id") or 0)
                player_name = str(player.get("name") or player_id)
                player_address = player.get("address")

            reservation = reserve_activity_floor_cooldown(
                manager_id, player_id, "talk_room", game_date,
            )
            try:
                result = create_random_world_injury(
                    player_id, player_address, game_date,
                    team_id=team_id, team_address=team.get("address"),
                )
            except Exception:
                try:
                    rollback_activity_floor_cooldown(reservation)
                except Exception:
                    pass
                raise

            with self.lock:
                availability = dict(player.get("availability") or {})
                availability["injury_count"] = len(result.get("injuries") or [])
                availability["injuries"] = list(result.get("injuries") or [])
                player["availability"] = availability
            return {
                "player_id": player_id, "player_name": player_name,
                "black_room": result,
                "economy": public_economy(), "welfare": welfare_status(),
            }

    def psychological_counseling(self, payload: dict[str, Any]) -> dict[str, Any]:
        player_id = int(payload.get("player_id") or 0)
        requested_team_id = int(payload.get("team_id") or 0)
        guaranteed = bool(payload.get("guaranteed"))
        with self.memory_lock:
            with self.lock:
                self._bind_current_save()
                profile, player = self._live_player_profile(
                    player_id, requested_team_id,
                )
                if not profile or not player:
                    raise ValueError("所选球员不属于当前执教球队，请先刷新队伍")
                manager = dict(self.output.get("manager") or {})
                manager_id = int(self.output.get("selected_manager_id") or manager.get("id") or 0)
                team = dict(profile.get("team") or {})
                team_id = int(team.get("id") or 0)
                current_intimacy = int(player.get("manager_intimacy") or 0)
                game_date = str((read_game_clock() or {}).get("date") or self.output.get("game_date") or "")
                if not game_date:
                    raise ValueError("尚未读取当前游戏日期")
                player_name = str(player.get("name") or player_id)
                player_address = player.get("address")
            if not player_has_unhappiness(player_id, player_address):
                raise ValueError("该球员当前没有可清除的不满")

            payment = {"bank": 0.0, "wallet": 0.0, "total": 0.0}
            if guaranteed and not free_services_enabled():
                payment = charge_combined_funds(
                    local_purchase_price(PSYCHOLOGICAL_COUNSELING_UNLOCK_PRICE),
                    "psychological_counseling_unlock",
                    manager_id=manager_id, player_id=player_id,
                    player_name=player_name, game_date=game_date,
                )
            applied_effect: dict[str, Any] | None = None

            def apply_effects(outcome: str, points: int) -> dict[str, Any]:
                nonlocal applied_effect
                effect = apply_psychological_counseling_effect(player_id, player_address, outcome)
                applied_effect = effect
                try:
                    intimacy = adjust_manager_intimacy_points(
                        player_id, player_address, manager_id, team_id,
                        team_address=team.get("address"),
                        manager_address=manager.get("manager_address"), points=points,
                    ) if points else {
                        "before": current_intimacy, "after": current_intimacy, "applied": 0,
                    }
                except Exception:
                    restore_player_activity_effect(effect)
                    applied_effect = None
                    raise
                public_effect = {key: value for key, value in effect.items() if not key.startswith("_")}
                return {**intimacy, "effect": public_effect}

            try:
                result = perform_psychological_counseling(
                    manager_id, player_id, player_name, game_date,
                    current_intimacy, apply_effects,
                    forced_outcome="unlocked" if guaranteed else None,
                )
            except Exception:
                if guaranteed and applied_effect is not None:
                    try:
                        restore_player_activity_effect(applied_effect)
                    except Exception:
                        pass
                if float(payment.get("total") or 0) > 0:
                    refund_combined_funds(
                        payment, "psychological_counseling_unlock_rollback",
                        manager_id=manager_id, player_id=player_id,
                        player_name=player_name, game_date=game_date,
                    )
                raise
            result["guaranteed"] = guaranteed
            result["payment"] = payment
            result["relationship_archived"] = self._archive_activity_relationship(
                target=player, target_kind="player", manager=manager,
                manager_id=manager_id, result=result, game_date=game_date,
                source_key="activity:psychological_counseling",
                source_label=f"心理辅导 · {result.get('outcome_name') or '关系变化'}",
                target_role="counselee", intimacy_before=current_intimacy,
                details={
                    "event_family": "心理辅导", "outcome": result.get("outcome"),
                    "outcome_name": result.get("outcome_name"), "team_id": team_id,
                },
            )
            with self.lock:
                if int(result.get("integer_applied") or 0):
                    player["manager_intimacy"] = int(float(result["intimacy"]))
                for change in (result.get("effect") or {}).get("effects") or []:
                    if change.get("field") == "morale":
                        player["morale"] = change.get("after")
                    if change.get("field") == "unhappiness" and change.get("after") is False:
                        player["has_unhappiness"] = False
            return {
                "counseling": result,
                "economy": public_economy(),
                "welfare": welfare_status(),
            }

    def update_medical_treatment(self, payload: dict[str, Any]) -> dict[str, Any]:
        player_id = int(payload.get("player_id") or 0)
        requested_team_id = int(payload.get("team_id") or 0)
        mode = str(payload.get("mode") or "none")
        with self.memory_lock:
            with self.lock:
                self._bind_current_save()
                profile, player = self._live_player_profile(
                    player_id, requested_team_id,
                )
                if not profile or not player:
                    raise ValueError("所选球员不属于当前执教球队，请先刷新队伍")
                game_date = str((read_game_clock() or {}).get("date") or self.output.get("game_date") or "")
                team_id = int((profile.get("team") or {}).get("id") or 0)
                player_address = str(player.get("address") or "")
                if not game_date:
                    raise ValueError("尚未读取当前游戏日期")

            previous = dict((welfare_status().get("treatments") or {}).get(str(player_id)) or {})
            old_factor = float(previous.get("factor") or 1.0)

            def transform(from_factor: float, to_factor: float) -> dict[str, Any]:
                return update_player_injury_treatment(
                    player_id, player_address, game_date, from_factor, to_factor,
                )

            result = set_medical_treatment(
                player_id, str(player.get("name") or player_id), team_id,
                player_address, mode, game_date, transform,
            )
            with self.lock:
                if result.get("injuries") is not None:
                    availability = dict(player.get("availability") or {})
                    availability["injuries"] = list(result.get("injuries") or [])
                    availability["injury_count"] = len(availability["injuries"])
                    player["availability"] = availability
            return {"treatment": result, "economy": public_economy(), "welfare": welfare_status()}

    def update_default_medical_treatment(self, payload: dict[str, Any]) -> dict[str, Any]:
        mode = str(payload.get("mode") or "manual")
        with self.memory_lock:
            with self.lock:
                self._bind_current_save()
                profiles = list(self.club_profiles.values()) or (
                    [self.club_profile] if self.club_profile else []
                )
                game_date = str(
                    (read_game_clock() or {}).get("date")
                    or self.output.get("game_date") or ""
                )
            medical_snapshot = set_default_medical_treatment(mode)
            auto_result = (
                self._apply_default_medical_treatments(
                    game_date, profiles, status=medical_snapshot,
                )
                if game_date and profiles else None
            )
            with self.lock:
                self.club_medical_auto_result = auto_result
        return {
            "economy": public_economy(), "welfare": welfare_status(),
            "auto_treatment": auto_result,
        }

    def _process_due_medical_treatments(
        self, game_date: str, profiles: list[dict[str, Any]],
    ) -> dict[str, Any]:
        players = {
            int(player.get("id") or 0): player
            for profile in profiles for player in (profile.get("players") or [])
            if int(player.get("id") or 0) > 0
        }
        injured_ids = {
            player_id for player_id, player in players.items()
            if int((player.get("availability") or {}).get("injury_count") or 0) > 0
        }

        def cancel(state: dict[str, Any]) -> None:
            player_id = int(state.get("player_id") or 0)
            player = players.get(player_id)
            address = (player or {}).get("address") or state.get("player_address")
            result = update_player_injury_treatment(
                player_id, address, game_date, float(state.get("factor") or 1.0), 1.0,
            )
            if player is not None:
                availability = dict(player.get("availability") or {})
                availability["injuries"] = list(result.get("injuries") or [])
                availability["injury_count"] = len(availability["injuries"])
                player["availability"] = availability

        def complete(state: dict[str, Any]) -> None:
            player_id = int(state.get("player_id") or 0)
            player = players.get(player_id)
            address = (player or {}).get("address") or state.get("player_address")
            complete_player_medical_treatment(
                player_id, address, game_date,
                list(state.get("injury_start_dates") or []),
            )

        return process_medical_treatments(
            game_date, injured_ids, cancel, complete,
            resolved_player_ids=set(players),
        )

    def _apply_default_medical_treatments(
        self, game_date: str, profiles: list[dict[str, Any]],
        *, status: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        candidates = []
        for profile in profiles:
            team_id = int((profile.get("team") or {}).get("id") or 0)
            for player in profile.get("players") or []:
                candidate = dict(player)
                candidate["team_id"] = team_id
                candidate["_profile_player"] = player
                candidates.append(candidate)

        def transform(
            candidate: dict[str, Any], from_factor: float, to_factor: float,
        ) -> dict[str, Any]:
            player_id = int(candidate.get("id") or 0)
            result = update_player_injury_treatment(
                player_id, candidate.get("address"), game_date,
                from_factor, to_factor,
            )
            player = candidate.get("_profile_player")
            if isinstance(player, dict):
                availability = dict(player.get("availability") or {})
                availability["injuries"] = list(result.get("injuries") or [])
                availability["injury_count"] = len(availability["injuries"])
                player["availability"] = availability
            return result

        return apply_default_medical_treatments(
            game_date, candidates, transform, status=status,
        )

    def _team_context(self, team_id: int) -> dict[str, Any]:
        return self.club_contexts.get(int(team_id)) or self.club_context or {}

    def _active_referee_context(
        self, contexts: dict[int, dict[str, Any]] | None = None,
        output: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        active = [
            item for item in public_economy().get("inventory", [])
            if item.get("status") == "active"
            and item.get("sku") in {"referee", "referee_level2", "referee_level3"}
        ]
        active.sort(key=lambda item: int(item.get("referee_level") or 0), reverse=True)
        return self._referee_item_context(active[0] if active else None, contexts, output)

    def _referee_item_context(
        self, item: dict[str, Any] | None,
        contexts: dict[int, dict[str, Any]] | None = None,
        output: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        explicit_contexts = contexts is not None
        contexts = contexts if explicit_contexts else self.club_contexts
        current_output = output if output is not None else self.output
        team_id = int((item or {}).get("managed_team_id") or 0)
        if item and not team_id:
            try:
                parts = str(item.get("fixture_key") or "").split("|")
                participants = {int(parts[-2]), int(parts[-1])}
                managed = {
                    int(team.get("id") or 0)
                    for team in (current_output.get("managed_teams") or [])
                }
                eligible = participants & managed
                team_id = next(iter(eligible)) if len(eligible) == 1 else 0
            except (TypeError, ValueError, IndexError):
                team_id = 0
        if explicit_contexts:
            return contexts.get(int(team_id)) or {}
        return contexts.get(int(team_id)) or self._team_context(team_id)

    def _sync_referee_fixture_hook(
        self, game_date: str,
        contexts: dict[int, dict[str, Any]] | None = None,
        output: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        """Arm the Hook before committing a scheduled referee item as active."""
        candidate = referee_hook_candidate(game_date) if REFEREE_EFFECT_ENABLED else None
        context = self._referee_item_context(candidate, contexts, output) if candidate else {}
        hook = self.referee_hook.sync(
            int((candidate or {}).get("referee_level") or 0),
            self._club_team_address(context),
            self._club_address(context),
        )
        result = {
            "state": "inactive",
            "item_id": str((candidate or {}).get("id") or "") or None,
            "hook": hook,
        }
        if not candidate:
            return result
        ready = bool(
            hook.get("installed") and hook.get("armed") and not hook.get("error")
        )
        if not ready:
            result["state"] = "pending"
            return result
        if candidate.get("status") == "scheduled":
            try:
                activate_scheduled_referee_item(str(candidate.get("id") or ""), game_date)
            except Exception:
                self.referee_hook.sync(0, 0, 0)
                raise
        result["state"] = "active"
        return result

    def fixture_opponent_players(self, payload: dict[str, Any]) -> dict[str, Any]:
        with self.lock:
            self._bind_current_save()
            output = self.output
        fixture_key = str(payload.get("fixture_key") or "")
        team_id = int(payload.get("team_id") or 0)
        managed_ids = {
            int(team.get("id") or 0)
            for team in (output.get("managed_teams") or [])
        }
        if not managed_ids and output.get("managed_team"):
            managed_ids.add(int(output["managed_team"].get("id") or 0))
        if team_id not in managed_ids:
            raise ValueError("所选队伍不是当前执教球队")
        opponent = None
        for match in output.get("matches", []):
            key = "|".join(map(str, (
                match.get("fixture_date"), match.get("competition_id"),
                match.get("home", {}).get("id"), match.get("away", {}).get("id"),
            )))
            participant_ids = {
                int(match.get("home", {}).get("id") or 0),
                int(match.get("away", {}).get("id") or 0),
            }
            if key == fixture_key and team_id in participant_ids:
                opponent = match["away"] if int(match["home"]["id"]) == team_id else match["home"]
                break
        if not opponent:
            raise ValueError("无法定位所选比赛的对手球队")
        address = opponent.get("address")
        if not address:
            raise RuntimeError("尚未读取到对手球队地址")
        players = read_team_roster(address)
        result = {
            "team": {"id": int(opponent.get("id") or 0), "name": str(opponent.get("name") or "")},
            "players": players,
        }
        apply_player_aliases(result, self._data_scope_id(output))
        return result

    def match_markets(self, payload: dict[str, Any]) -> dict[str, Any]:
        fixture_key = str(payload.get("fixture_key") or "")
        if not fixture_key:
            raise ValueError("缺少赛事标识")
        with self.lock:
            match = next(
                (
                    item for item in self.output.get("matches", [])
                    if "|".join(map(str, (
                        item.get("fixture_date"), item.get("competition_id"),
                        item.get("home", {}).get("id"), item.get("away", {}).get("id"),
                    ))) == fixture_key
                ),
                None,
            )
            if not match:
                raise ValueError("赛事盘口已刷新，请重新选择")
            if (
                normalize_match_market_catalog_state(match) != "full"
                and not ensure_match_market_catalog(match)
            ):
                raise ValueError("当前赛事盘口暂时无法生成")
            match_snapshot = dict(match)
            game_clock = dict(self.last_connection_clock or {})
            data_version = self.data_version
        quote = live_market_quote(
            match_snapshot, game_clock, include_catalog=True,
        )
        return {
            "match": apply_live_market_quote(match_snapshot, quote),
            "data_version": data_version,
        }

    def inventory_use(self, payload: dict[str, Any]) -> dict[str, Any]:
        with self.lock:
            self._bind_current_save()
            profiles = dict(self.club_profiles)
            if not profiles and self.club_profile:
                profiles[int((self.club_profile.get("team") or {}).get("id") or 0)] = self.club_profile
            output = self.output
        item_id = str(payload.get("item_id", ""))
        item = next((row for row in public_economy().get("inventory", []) if row.get("id") == item_id), None)
        if not item or item.get("sku") not in {"red_bull", "team_red_bull", "doping", "team_doping", "bribed_goalkeeper", "opponent_flu", "referee", "referee_level2", "referee_level3"}:
            raise ValueError("所选物品不能安排到比赛")
        if item.get("sku") == "opponent_flu" and not OPPONENT_VIRUS_EFFECT_ENABLED:
            raise ValueError("病毒包裹已暂时停用：FM 伤病对象生命周期尚未安全适配")
        select_process_layout()
        if item.get("sku") in {"referee", "referee_level2", "referee_level3"} and not REFEREE_EFFECT_ENABLED:
            raise ValueError("黑哨比赛已因实战崩溃停用，物品保留且当前不能再次使用")
        fixture_key = str(payload.get("fixture_key", ""))
        managed_teams = managed_team_rows(output)
        managed_by_id = {int(team.get("id") or 0): team for team in managed_teams}
        requested_team_id = int(payload.get("team_id") or 0)
        fixture = None
        selected_team = None
        for match in output.get("matches", []):
            key = "|".join(map(str, (match.get("fixture_date"), match.get("competition_id"), match.get("home", {}).get("id"), match.get("away", {}).get("id"))))
            participant_ids = {int(match["home"]["id"]), int(match["away"]["id"])}
            eligible_ids = participant_ids & set(managed_by_id)
            target_id = requested_team_id if requested_team_id in eligible_ids else (next(iter(eligible_ids)) if len(eligible_ids) == 1 else 0)
            if key == fixture_key and target_id:
                selected_team = managed_by_id[target_id]
                opponent = match["away"] if int(match["home"]["id"]) == target_id else match["home"]
                fixture = {
                    "key": key, "date": match["fixture_date"],
                    "name": f"{match['home']['name']} VS {match['away']['name']}",
                    "kickoff_minutes": match.get("kickoff_minutes"),
                    "kickoff_time": match.get("kickoff_time"),
                    "managed_team_id": target_id,
                    "managed_team_name": selected_team.get("name") or str(target_id),
                    "managed_team_address": str(selected_team.get("address") or ""),
                    "opponent_team_id": int(opponent.get("id") or 0),
                    "opponent_team_name": str(opponent.get("name") or ""),
                    "opponent_team_address": str(opponent.get("address") or ""),
                    "competition_reputation_native": match.get("competition_reputation_native"),
                    "competition_id": int(match.get("competition_id") or 0),
                    "competition_name": match.get("competition_name"),
                    "competition_kind": match.get("competition_kind"),
                    "home_name": match.get("home", {}).get("name"),
                    "away_name": match.get("away", {}).get("name"),
                    "manager_name": manager_display_name(output),
                    "referee_name": str(match.get("referee_name") or ""),
                }
                break
        if not fixture:
            raise ValueError("所选比赛不属于当前执教队伍或已失效")
        game_clock = read_game_clock()
        current_date = str(game_clock.get("date") or "")
        current_minutes = int(game_clock.get("minutes") or 0)
        fixture_date = str(fixture.get("date") or "")
        kickoff_minutes = fixture.get("kickoff_minutes")
        already_started = bool(
            fixture_date and current_date > fixture_date
            or fixture_date and current_date == fixture_date
            and kickoff_minutes is not None
            and current_minutes >= int(kickoff_minutes)
        )
        if already_started:
            raise ValueError("比赛已经开始，不能再使用比赛类道具")
        selected_profile = profiles.get(int(fixture["managed_team_id"])) or {}
        player = None
        if item.get("sku") in {"red_bull", "doping"}:
            player_id = int(payload.get("player_id", 0))
            with self.memory_lock:
                selected_profile, player = self._live_player_profile(
                    player_id, int(fixture["managed_team_id"]),
                )
            selected_team_id = int(((selected_profile or {}).get("team") or {}).get("id") or 0)
            if selected_team_id != int(fixture["managed_team_id"]):
                player = None
            if not player:
                raise ValueError("所选球员不属于该场比赛对应的执教队伍")
        elif item.get("sku") == "opponent_flu":
            player_id = int(payload.get("player_id", 0))
            opponent_players = read_team_roster(fixture.get("opponent_team_address"))
            player = next(
                (row for row in opponent_players if int(row.get("id") or 0) == player_id),
                None,
            )
            if not player:
                raise ValueError("所选球员不属于该场比赛的对手一线队")
            availability = player.get("availability") or {}
            if int(availability.get("injury_count") or 0) > 0 or availability.get("injuries"):
                raise ValueError("该球员已有伤病，不能使用病毒包裹")
        if item.get("sku") in {"team_red_bull", "team_doping"}:
            if not selected_profile:
                with self.memory_lock:
                    self._reload_player_profile(
                        0, int(fixture["managed_team_id"]),
                    )
                    with self.lock:
                        selected_profile = self.club_profiles.get(
                            int(fixture["managed_team_id"]),
                        ) or {}
            if not selected_profile:
                raise ValueError("尚未读取该场比赛对应执教队伍的一线队名单")
            assign_team_item(item_id, list(selected_profile.get("players", [])), fixture)
        elif item.get("sku") in {"bribed_goalkeeper", "referee", "referee_level2", "referee_level3"}:
            assign_fixture_item(item_id, fixture)
        else:
            assign_item(item_id, player, fixture)
        game_date = current_date
        reconcile_inventory(
            game_date, self._fixture_index(output), activate_referee=False,
        )
        self._sync_opponent_flu_items(game_date)
        doping_status = sync_doping_effects(active_doping_items())
        if doping_status.get("errors") and item.get("sku") in {"doping", "team_doping"}:
            raise ValueError("兴奋剂效果暂未附加：" + "; ".join(doping_status["errors"]))
        bribe_status = sync_goalkeeper_bribes(active_goalkeeper_bribes())
        if bribe_status.get("errors") and item.get("sku") == "bribed_goalkeeper":
            raise ValueError("买通门将效果暂未附加：" + "; ".join(bribe_status["errors"]))
        hook_status = self.redbull_hook.sync(
            active_player_ids(), bribe_status.get("player_ids", []),
        )
        if bribe_status.get("player_ids") and hook_status.get("error"):
            bribe_status.setdefault("errors", []).append(str(hook_status["error"]))
        self._remember_fixture_effect_status(doping_status, bribe_status)
        if hook_status.get("error"):
            refund_active_sku("red_bull", str(hook_status["error"]))
            refund_active_sku("team_red_bull", str(hook_status["error"]))
            self.redbull_hook.sync([], bribe_status.get("player_ids", []))
            if (
                item.get("sku") == "bribed_goalkeeper"
                and bribe_status.get("player_ids")
            ):
                raise ValueError(
                    f"买通门将比赛属性模块未能安全启用：{hook_status['error']}；比赛安排已保留"
                )
            if item.get("sku") in {"red_bull", "team_red_bull"}:
                raise ValueError(
                    f"功能饮料体力模块未能安全启用：{hook_status['error']}，物品已退回"
                )
        referee_activation = self._sync_referee_fixture_hook(game_date, output=output)
        result = public_economy()
        if item.get("sku") in {"referee", "referee_level2", "referee_level3"}:
            result["referee_activation"] = referee_activation
        return result

