API_ROUTES = build_api_routes()


class Handler(BaseHTTPRequestHandler):
    state: LocalOddsState

    @staticmethod
    def _post_error_payload(path: str, error: Exception) -> dict[str, Any]:
        normalized = normalize_error(error, operation=path)
        payload = normalized.payload()
        if path.startswith(("/api/canteen/", "/api/inventory/", "/api/training/")):
            specialized = describe_player_effect_error(
                error, operation=path.rsplit("/", 1)[-1],
            )
            payload.update(specialized)
        # Legacy business validation already carries a deliberately authored,
        # user-facing reason.  Keep the generic semantic message for clients
        # that need it, while explicitly allowing the desktop UI to show the
        # preserved detail.  Never opt in arbitrary TypeError/KeyError/runtime
        # failures, whose text may contain implementation-only information.
        if (
            not isinstance(error, DomainError)
            and isinstance(error, (InvalidMoney, ValueError))
            and not isinstance(error, json.JSONDecodeError)
        ):
            payload["error_detail_safe"] = True
        return payload

    def _request_locale(self) -> str | None:
        headers = getattr(self, "headers", None)
        getter = getattr(headers, "get", None)
        if not callable(getter):
            return None
        return str(
            getter("X-FMODD-Locale")
            or getter("Accept-Language")
            or ""
        )

    def _localized_error_payload(
        self, error: Exception, *, operation: str,
    ) -> dict[str, Any]:
        """Keep legacy diagnostics while adding safe, semantic API messages."""
        payload = self._post_error_payload(operation, error)
        return localized_error_payload(
            payload,
            locale=self._request_locale(),
            message_key=getattr(error, "message_key", None),
            message_params=getattr(error, "message_params", None),
        )

    def _domain_error(self, error: Exception, *, operation: str) -> None:
        normalized = normalize_error(error, operation=operation)
        return self._json(
            normalized.status,
            self._localized_error_payload(error, operation=operation),
        )

    def log_message(self, _format: str, *_args: Any) -> None:
        return

    def do_GET(self) -> None:
        try:
            self._bind_request_scope()
            self._do_GET()
        except (BrokenPipeError, ConnectionAbortedError, ConnectionResetError):
            # The client no longer accepts a response. A second write would
            # only obscure the original disconnect.
            return
        except Exception as error:
            try:
                operation = urlparse(getattr(self, "path", "")).path or "GET"
                normalized = normalize_error(error, operation=operation)
                return self._json(
                    normalized.status,
                    self._localized_error_payload(error, operation=operation),
                )
            except (BrokenPipeError, ConnectionAbortedError, ConnectionResetError):
                return

    def _do_GET(self) -> None:
        parsed = urlparse(self.path)
        path = parsed.path
        query = parse_qs(parsed.query)
        if path == "/api/player-avatar":
            try:
                player_id = int((query.get("player_id") or ["0"])[0])
            except (TypeError, ValueError):
                return self._json(HTTPStatus.BAD_REQUEST, {"error": "球员 UID 无效"})
            portrait = portrait_path(player_id)
            if portrait is None:
                return self._json(HTTPStatus.NOT_FOUND, {"error": "未找到球员头像"})
            try:
                content = portrait.read_bytes()
            except OSError:
                return self._json(HTTPStatus.NOT_FOUND, {"error": "球员头像不可读取"})
            if len(content) > 8 * 1024 * 1024:
                return self._json(HTTPStatus.REQUEST_ENTITY_TOO_LARGE, {"error": "球员头像过大"})
            content_type = mimetypes.guess_type(portrait.name)[0] or "application/octet-stream"
            self.send_response(HTTPStatus.OK)
            self.send_header("Content-Type", content_type)
            self.send_header("Cache-Control", "no-store, max-age=0")
            self.send_header("X-FMODD-Asset-Source", "fm-graphics")
            self.send_header("Content-Length", str(len(content)))
            self.end_headers()
            self.wfile.write(content)
            return
        route_result = API_ROUTES.dispatch(
            "GET", path, self, query=query,
        )
        if route_result is not None:
            return self._json(route_result.status, route_result.payload)
        if path.startswith("/api/"):
            return self._domain_error(
                NotFoundError("接口不存在", details={"path": path}),
                operation=path,
            )
        self._static(path)

    def _bind_request_scope(self) -> str | None:
        path = urlparse(str(getattr(self, "path", "") or "")).path
        if not path.startswith("/api/"):
            set_active_save_id(None)
            return None
        state = getattr(self, "state", None)
        binder = getattr(state, "_bind_request_scope", None)
        if not callable(binder):
            set_active_save_id(None)
            return None
        return binder()

    def do_POST(self) -> None:
        path = urlparse(self.path).path
        self._http_mutation_context = None
        try:
            self._bind_request_scope()
            capture = getattr(getattr(self, "state", None), "_capture_mutation_context", None)
            if callable(capture):
                self._http_mutation_context = capture()
            length = int(self.headers.get("Content-Length", "0"))
            payload = json.loads(self.rfile.read(length) or b"{}")
            if not isinstance(payload, dict):
                raise ValidationError("请求正文必须是 JSON 对象")
            memory_lock = getattr(getattr(self, "state", None), "memory_lock", None)
            foreground_request = getattr(memory_lock, "foreground_request", None)
            request_context = foreground_request() if callable(foreground_request) else nullcontext()
            with request_context:
                route_result = API_ROUTES.dispatch(
                    "POST", path, self, payload=payload,
                )
            if route_result is not None:
                return self._json(route_result.status, route_result.payload)
            raise NotFoundError("接口不存在", details={"path": path})
        except DomainError as error:
            return self._domain_error(error, operation=path)
        except (ValueError, KeyError, TypeError, json.JSONDecodeError) as error:
            return self._domain_error(error, operation=path)
        except OverflowError as error:
            normalized = ValidationError(
                f"金额或赔率超出程序可处理范围：{error}",
                code="numeric_overflow", phase="validate_number",
                details={"operation": path},
            )
            return self._domain_error(normalized, operation=path)
        except RuntimeError as error:
            return self._domain_error(error, operation=path)
        except Exception as error:
            # Keep an unexpected request-side failure visible to the client.
            # Without a JSON response, fetch reports only the misleading
            # network-level "Failed to fetch" message.
            return self._domain_error(error, operation=path)

    def _json(self, status: HTTPStatus, payload: dict[str, Any]) -> None:
        if int(status) >= 400 and "error" in payload and "message" not in payload:
            payload = localized_error_payload(
                payload,
                locale=self._request_locale(),
                message_key=message_key_for_status(int(status)),
            )
        if (
            getattr(self, "command", "") == "POST"
            and int(status) < 400
            and hasattr(self, "state")
            and getattr(self, "_http_mutation_context", None) is not None
        ):
            # State patches only avoid a follow-up /api/state read.  A failure
            # here happens after the route has already committed, so it must
            # never turn that successful operation into a misleading 4xx.
            # Returning the original response makes existing clients reload.
            original_payload = payload
            try:
                payload = self.state._mutation_patch_response(
                    payload, origin=self._http_mutation_context,
                )
            except Exception:
                payload = original_payload
        body = json.dumps(
            payload, ensure_ascii=False, separators=(",", ":"),
        ).encode("utf-8")
        content_encoding = ""
        accepted_encodings = str(self.headers.get("Accept-Encoding") or "").lower()
        if len(body) >= 1024 and "gzip" in accepted_encodings:
            # Responses stay on loopback. Level 1 preserves most of the size
            # reduction without making every click wait on heavier compression.
            compressed = gzip.compress(body, compresslevel=1, mtime=0)
            if len(compressed) < len(body):
                body = compressed
                content_encoding = "gzip"
        self.send_response(status)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        if content_encoding:
            self.send_header("Content-Encoding", content_encoding)
            self.send_header("Vary", "Accept-Encoding")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def _static(self, requested: str) -> None:
        relative = "index.html" if requested in {"", "/"} else requested.lstrip("/")
        path = (WEB_ROOT / relative).resolve()
        content: bytes | None = None
        source = "embedded"
        if path == WEB_ROOT or WEB_ROOT in path.parents:
            try:
                if path.is_file():
                    content = path.read_bytes()
                    source = "filesystem"
            except OSError:
                content = None
        if content is None:
            content = read_embedded_web_asset(relative)
        if content is None:
            return self.send_error(HTTPStatus.NOT_FOUND)
        content_type = mimetypes.guess_type(relative)[0] or "application/octet-stream"
        self.send_response(HTTPStatus.OK)
        self.send_header("Content-Type", f"{content_type}; charset=utf-8" if content_type.startswith("text/") else content_type)
        self.send_header("X-FMODD-Asset-Source", source)
        self.send_header("Cache-Control", "no-store, max-age=0")
        self.send_header("Pragma", "no-cache")
        self.send_header("Expires", "0")
        self.send_header("Content-Length", str(len(content)))
        self.end_headers()
        self.wfile.write(content)


def show_startup_error(message: str) -> None:
    if sys.platform == "win32" and getattr(sys, "frozen", False):
        ctypes.windll.user32.MessageBoxW(None, message, "FMODD", 0x10)
    else:
        print(message)


def watch_fm_process(server: ThreadingHTTPServer) -> None:
    while True:
        sleep(2)
        try:
            select_process()
        except RuntimeError:
            server.shutdown()
            return


def start_local_runtime(state: LocalOddsState) -> None:
    """Start idle monitors; only an explicit connect request reads the live save."""
    if FROZEN:
        try:
            reward_result = process_version_update_rewards(APP_VERSION)
            if reward_result["failures"]:
                print(f"更新奖励有 {len(reward_result['failures'])} 个账户待重试")
        except Exception as error:
            print(f"更新奖励检测失败，将在下次启动重试：{error}")
    threading.Thread(target=state.watch_game_date, daemon=True).start()
    threading.Thread(target=state.watch_match_intelligence, daemon=True).start()
    threading.Thread(target=state.watch_live_result_capture, daemon=True).start()
    threading.Thread(target=state.watch_live_settlement, daemon=True).start()
    with state.lock:
        state.status = "等待连接 Football Manager 存档"
        state.error = None


def main() -> int:
    parser = argparse.ArgumentParser(description="FM Odds local web preview")
    parser.add_argument("--port", type=int, default=7856)
    parser.add_argument("--no-browser", action="store_true")
    parser.add_argument("--save-id", help="load a confirmed save cache when the current FM screen hides manager identity")
    parser.add_argument(
        "--exit-with-fm", action="store_true", default=bool(getattr(sys, "frozen", False)),
        help="close the web service when the live FM process exits (enabled by default in packaged builds)",
    )
    parser.add_argument("--keep-alive", action="store_true", help="keep the service running without FM")
    args = parser.parse_args()
    configure_activity_centre_development_unlocks(not FROZEN)
    exit_with_fm = bool(args.exit_with_fm and not args.keep_alive)
    if args.save_id:
        set_active_save_id(args.save_id)
    if exit_with_fm:
        try:
            select_process()
        except RuntimeError:
            show_startup_error("未检测到正在运行的 Football Manager，请先启动游戏并进入存档。")
            return 1
    ensure_data_directories()
    if FROZEN:
        enforce_storage_budget()
    state = LocalOddsState()
    Handler.state = state
    try:
        server = ThreadingHTTPServer(("127.0.0.1", args.port), Handler)
    except OSError as error:
        show_startup_error(f"无法启动本地服务端口 {args.port}：{error}")
        return 1
    start_local_runtime(state)
    if exit_with_fm:
        threading.Thread(target=watch_fm_process, args=(server,), daemon=True).start()
    address = f"http://127.0.0.1:{args.port}"
    if not args.no_browser:
        webbrowser.open(address)
    print(f"FM Odds web preview: {address}")
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        state.redbull_hook.close()
        state.referee_hook.close()
        state.ca_growth_hook.close()
        state.attribute_growth_hook.close()
        state.team_nuclear_hooks.close()
        state.club_policy_hooks.close()
        state.board_listens_hook.close()
        state._close_youth_generation_hook()
        state.simple_effects.close()
        server.server_close()
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
